const { PrismaClient } = require("@prisma/client");
const prisma = new PrismaClient();

async function main() {
    // 1. Get a user
    const user = await prisma.user.findFirst();

    if (!user) {
        console.log("No users found. Please sign in first to create a user record.");
        return;
    }

    console.log(`Creating pending loans for user: ${user.email}`);

    // 2. Create some pending loans
    await prisma.loan.createMany({
        data: [
            {
                userId: user.id,
                issuedAmount: 50000,
                remainingPrincipal: 50000,
                gracePeriodMonths: 6,
                totalMonths: 12,
                status: "PENDING",
            },
            {
                userId: user.id,
                issuedAmount: 120000,
                remainingPrincipal: 120000,
                gracePeriodMonths: 3,
                totalMonths: 24,
                status: "PENDING",
            },
        ],
    });

    console.log("Seed successful!");
}

main()
    .catch((e) => {
        console.error(e);
        process.exit(1);
    })
    .finally(async () => {
        await prisma.$disconnect();
    });

"use server";

import { prisma } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import { UserStatus, EmployeeStatus, SalaryChangeReason } from "@prisma/client";
import { clerkClient } from "@clerk/nextjs/server";
import { getDbUser } from "./user.actions";
import { createAdminNotification } from "./notification.actions";
import { logManagerEmployeeEditAction } from "./manager-employee-edit.actions";

async function logManagerEmployeeRejectionAction(params: {
    actorId: string;
    actorName: string;
    employeeId: string;
    employeeName: string;
}) {
    try {
        await prisma.auditLog.create({
            data: {
                userId: params.actorId,
                oldEmi: null,
                newEmi: null,
                changeReason: `Manager rejected employee account: ${params.employeeName} (${params.employeeId})`,
            },
        });

        await createAdminNotification({
            type: "SYSTEM_ALERT",
            title: "Manager Rejected Employee Account",
            message: `${params.actorName} rejected the employee account for ${params.employeeName}`,
            metadata: {
                actorId: params.actorId,
                actorName: params.actorName,
                action: "REJECTED",
                employeeId: params.employeeId,
                employeeName: params.employeeName,
                source: "employee_account_approval",
            },
        });
    } catch (error) {
        console.error("Failed to log manager employee rejection action:", error);
    }
}

export async function getActiveEmployees() {
    return await prisma.user.findMany({
        where: { 
            isArchived: false,
            role: { not: "SUPERADMIN" }
        },
        include: { 
            branch: true,
            department: true,
            designation: true
        },
        orderBy: { createdAt: "desc" },
    });
}

export async function getPendingEmployees() {
    return await prisma.user.findMany({
        where: { 
            status: "PENDING",
            isArchived: false,
            role: { not: "SUPERADMIN" }
        },
        include: { 
            branch: true,
            department: true,
            designation: true
        },
        orderBy: { createdAt: "desc" },
    });
}

export async function getArchivedEmployees(fromDate?: string, toDate?: string) {
    const whereClause: any = { 
        isArchived: true,
        role: { not: "SUPERADMIN" }
    };

    if (fromDate || toDate) {
        whereClause.updatedAt = {};
        if (fromDate) whereClause.updatedAt.gte = new Date(fromDate);
        if (toDate) whereClause.updatedAt.lte = new Date(toDate);
    }

    return await prisma.user.findMany({
        where: whereClause,
        include: { 
            branch: true,
            department: true,
            designation: true
        },
        orderBy: { updatedAt: "desc" },
    });
}

export async function approveEmployeeWithDetails(userId: string, branchId: string, baseSalary: number) {
    try {
        if (!branchId) {
            return { success: false, error: "Branch is required to approve employee" };
        }
        if (!baseSalary || baseSalary <= 0) {
            return { success: false, error: "Base salary is required to approve employee" };
        }

        const user = await prisma.$transaction(async (tx) => {
            const updatedUser = await tx.user.update({
                where: { id: userId },
                data: { 
                    status: "APPROVED",
                    employeeStatus: "ACTIVE",
                    branchId,
                    baseSalary
                },
            });

            // Create salary history entry for joining
            await tx.baseSalary.create({
                data: {
                    userId,
                    amount: baseSalary,
                    reason: SalaryChangeReason.JOINING,
                    effectiveFrom: new Date()
                }
            });

            // Create medical entitlement for approved employee
            const settings = await tx.systemSettings.findUnique({ where: { id: "global" } });
            const limit = settings?.medicalClaimLimit ?? 500;
            const year = new Date().getFullYear();

            await tx.medicalEntitlement.upsert({
                where: { userId_year: { userId, year } },
                update: {}, // Don't overwrite if already exists
                create: {
                    userId,
                    year,
                    totalLimit: limit,
                    remainingBalance: limit,
                },
            });

            return updatedUser;
        });

        revalidatePath("/admin/employees");
        return { success: true, user };
    } catch (error) {
        console.error("Error approving employee:", error);
        return { success: false, error: "Failed to approve employee" };
    }
}

export async function approveEmployee(userId: string) {
    try {
        const user = await prisma.user.findUnique({
            where: { id: userId },
            select: { branchId: true, baseSalary: true }
        });

        if (!user?.branchId || !user.baseSalary || user.baseSalary <= 0) {
            return { success: false, error: "Branch and base salary are required before approval" };
        }

        return await approveEmployeeWithDetails(userId, user.branchId, user.baseSalary);
    } catch (error) {
        console.error("Error approving employee:", error);
        return { success: false, error: "Failed to approve employee" };
    }
}

export async function rejectEmployee(userId: string) {
    try {
        const actor = await getDbUser();

        // Get user details before deletion
        const user = await prisma.user.findUnique({
            where: { id: userId },
        });

        if (!user) {
            return { success: false, error: "Employee not found" };
        }

        // Delete from database
        await prisma.user.delete({
            where: { id: userId },
        });

        // Try to delete from Clerk (optional, if it fails we continue)
        try {
            const clerk = await clerkClient();
            await clerk.users.deleteUser(user.clerkId);
        } catch (clerkError) {
            console.warn("Could not delete user from Clerk:", clerkError);
        }

        if (actor && actor.role === "EMPLOYEE" && actor.isManager) {
            const actorName = [actor.firstName, actor.lastName].filter(Boolean).join(" ") || actor.email;
            const employeeName = [user.firstName, user.lastName].filter(Boolean).join(" ") || user.email;

            await logManagerEmployeeRejectionAction({
                actorId: actor.id,
                actorName,
                employeeId: user.id,
                employeeName,
            });
        }

        revalidatePath("/admin/employees");
        revalidatePath("/manager/employees");
        return { success: true };
    } catch (error) {
        console.error("Error rejecting employee:", error);
        return { success: false, error: "Failed to reject employee" };
    }
}

export async function updateEmployeeStatus(userId: string, employeeStatus: EmployeeStatus) {
    try {
        const updateData: any = { employeeStatus };

        // If status is RESIGNED or TERMINATED, archive the employee
        if (employeeStatus === "RESIGNED" || employeeStatus === "TERMINATED") {
            updateData.isArchived = true;
        }

        const user = await prisma.user.update({
            where: { id: userId },
            data: updateData,
        });

        revalidatePath("/admin/employees");
        revalidatePath("/admin/archived-employees");
        return { success: true, user };
    } catch (error) {
        console.error("Error updating employee status:", error);
        return { success: false, error: "Failed to update employee status" };
    }
}

export async function assignBranch(userId: string, branchId: string | null) {
    try {
        const user = await prisma.user.update({
            where: { id: userId },
            data: { branchId },
        });
        revalidatePath("/admin/employees");
        return { success: true, user };
    } catch (error) {
        console.error("Error assigning branch:", error);
        return { success: false, error: "Failed to assign branch" };
    }
}

export async function updateWorkingDaysInMonth(userId: string, workingDaysInMonth: number) {
    try {
        const normalizedWorkingDays = Math.max(0, Math.min(31, Math.floor(workingDaysInMonth)));
        const user = await prisma.user.update({
            where: { id: userId },
            data: { workingDaysInMonth: normalizedWorkingDays }
        });
        revalidatePath(`/admin/employees/${userId}`);
        return { success: true, user };
    } catch (error) {
        console.error("Error updating working days in month:", error);
        return { success: false, error: "Failed to update working days" };
    }
}

export async function updateEmployeeDocumentLinks(
    userId: string,
    links: {
        loanPapersLink?: string | null;
        nomineesPapersLink?: string | null;
        emergencyContactLink?: string | null;
        personalInfoLink?: string | null;
    }
) {
    try {
        const actor = await getDbUser();
        const isAuthorized = !!actor && (
            actor.role === "SUPERADMIN" ||
            (actor.role === "EMPLOYEE" && actor.isManager)
        );

        if (!isAuthorized) {
            return { success: false, error: "Unauthorized" };
        }

        const user = await prisma.user.update({
            where: { id: userId },
            data: {
                loanPapersLink: links.loanPapersLink ?? null,
                nomineesPapersLink: links.nomineesPapersLink ?? null,
                emergencyContactLink: links.emergencyContactLink ?? null,
                personalInfoLink: links.personalInfoLink ?? null,
            },
        });

        revalidatePath(`/admin/employees/${userId}`);
        revalidatePath(`/admin/admin/employees/${userId}`);
        revalidatePath(`/manager/employees/${userId}`);
        revalidatePath(`/manager/manager/employees/${userId}`);

        return { success: true, user };
    } catch (error) {
        console.error("Error updating employee document links:", error);
        return { success: false, error: "Failed to update document links" };
    }
}

export async function updateEmployeeProfile(userId: string, data: {
    role?: any;
    branchId?: string | null;
    departmentId?: string | null;
    designationId?: string | null;
}) {
    try {
        const actor = await getDbUser();
        const isAuthorized = !!actor && (["SUPERADMIN", "HR"].includes(actor.role) || (actor.role === "EMPLOYEE" && actor.isManager));

        if (!isAuthorized) {
            return { success: false, error: "Unauthorized" };
        }

        const employee = await prisma.user.findUnique({
            where: { id: userId },
            select: { id: true, firstName: true, lastName: true, email: true },
        });

        if (!employee) {
            return { success: false, error: "Employee not found" };
        }

        const user = await prisma.user.update({
            where: { id: userId },
            data,
        });

        if (actor.role === "EMPLOYEE" && actor.isManager) {
            const actorName = [actor.firstName, actor.lastName].filter(Boolean).join(" ") || actor.email;
            const employeeName = [employee.firstName, employee.lastName].filter(Boolean).join(" ") || employee.email;
            const changeKeys = Object.keys(data).join(", ");

            await logManagerEmployeeEditAction({
                actorId: actor.id,
                actorName,
                action: "UPDATED",
                area: "employee_employment",
                employeeId: employee.id,
                employeeName,
                details: changeKeys ? `fields=${changeKeys}` : undefined,
            });
        }

        revalidatePath("/admin/employees");
        revalidatePath(`/admin/employees/${userId}`);
        revalidatePath("/manager/employees");
        revalidatePath(`/manager/employees/${userId}`);
        return { success: true, user };
    } catch (error) {
        console.error("Error updating employee profile:", error);
        return { success: false, error: "Failed to update profile" };
    }
}

// Legacy function - kept for backward compatibility
export async function updateUserStatus(userId: string, status: UserStatus) {
    if (status === "APPROVED") {
        return { success: false, error: "Approval requires branch and base salary" };
    }

    try {
        const user = await prisma.user.update({
            where: { id: userId },
            data: { status },
        });
        revalidatePath("/admin/employees");
        return { success: true, user };
    } catch (error) {
        console.error("Error updating user status:", error);
        return { success: false, error: "Failed to update status" };
    }
}

"use server";

import { prisma } from "@/lib/prisma";
import { startOfDay, endOfDay, format, subDays } from "date-fns";

function getMidnightDate(date: Date) {
    const midnight = new Date(date);
    midnight.setHours(0, 0, 0, 0);
    return midnight;
}

function isFilledString(value?: string | null) {
    return Boolean(value && value.trim().length > 0);
}

function isNonZeroTime(value?: Date | null) {
    if (!value) return false;
    return value.getHours() !== 0 || value.getMinutes() !== 0 || value.getSeconds() !== 0;
}

function timeStringToMinutes(timeStr?: string | null) {
    if (!timeStr) return 0;
    const [hours, minutes] = timeStr.split(':').map(Number);
    return (hours * 60) + minutes;
}

function getRequiredActiveMinutes(existingRecord: any, requiredCheckIn: Date, requiredCheckOut: Date, requiredBreakTime: string) {
    if (existingRecord?.requiredActiveTime) {
        const minutes = timeStringToMinutes(existingRecord.requiredActiveTime);
        if (minutes > 0) return minutes;
    }

    const totalMinutes = Math.max(0, Math.floor((requiredCheckOut.getTime() - requiredCheckIn.getTime()) / (1000 * 60)));
    const breakMinutes = timeStringToMinutes(requiredBreakTime);
    return Math.max(0, totalMinutes - breakMinutes);
}

function isSameDay(a: Date, b: Date) {
    return a.getFullYear() === b.getFullYear()
        && a.getMonth() === b.getMonth()
        && a.getDate() === b.getDate();
}

function isWithinRequiredWindow(employee: any, processDate: Date, now: Date) {
    if (!isSameDay(processDate, now)) return false;

    const checkInTime = employee.branch?.checkInTime || "09:00";
    const checkOutTime = employee.branch?.checkOutTime || "18:00";

    const requiredCheckIn = new Date(processDate);
    const [checkInHour, checkInMinute] = checkInTime.split(':');
    requiredCheckIn.setHours(parseInt(checkInHour), parseInt(checkInMinute), 0, 0);

    const requiredCheckOut = new Date(processDate);
    const [checkOutHour, checkOutMinute] = checkOutTime.split(':');
    requiredCheckOut.setHours(parseInt(checkOutHour), parseInt(checkOutMinute), 0, 0);

    return now >= requiredCheckIn && now <= requiredCheckOut;
}

/**
 * Process all unprocessed dates (including today and any dates with null values)
 * This is the main function called by the cron job at 23:00
 */
export async function processAllUnprocessedDates() {
    console.log("Starting comprehensive leave automation processing...");
    
    try {
        const today = startOfDay(new Date());
        const now = new Date();
        
        // Get dates to process: yesterday, today, and any dates with unprocessed records
        const datesToProcess = new Set<string>();
        
        // Add yesterday (default processing)
        datesToProcess.add(format(subDays(today, 1), 'yyyy-MM-dd'));
        
        // Add today (for current day processing)
        datesToProcess.add(format(today, 'yyyy-MM-dd'));
        
        // Find dates with incomplete processing
        const unprocessedRecords = await prisma.dailyTimeRecord.groupBy({
            by: ['date'],
            where: {
                isProcessed: {
                    not: true
                }
            },
            orderBy: {
                date: 'asc'
            }
        });
        
        // Add all dates with unprocessed records
        unprocessedRecords.forEach(record => {
            datesToProcess.add(format(record.date, 'yyyy-MM-dd'));
        });

        let totalProcessed = 0;
        const results: any[] = [];

        // Process each unique date
        for (const dateStr of Array.from(datesToProcess).sort()) {
            const processDate = startOfDay(new Date(dateStr));
            const isToday = isSameDay(processDate, today);
            
            console.log(`Processing leave automation for date: ${dateStr}`);
            
            const result = await processDailyLeaveAutomation(processDate, {
                skipIfWithinWindow: isToday,
                now: isToday ? now : undefined
            });
            
            if (result.success) {
                totalProcessed += result.processedEmployees || 0;
            }
            
            results.push({ date: dateStr, ...result });
        }

        console.log(`Completed processing ${datesToProcess.size} dates, ${totalProcessed} total employee records`);
        return { 
            success: true, 
            datesProcessed: datesToProcess.size,
            totalProcessed,
            results 
        };
    } catch (error) {
        console.error("Error processing all unprocessed dates:", error);
        return { success: false, error: "Failed to process automation" };
    }
}

/**
 * Main function to process daily leave automation for a specific date
 * Should be called every day at 23:00 (11 PM)
 */
export async function processDailyLeaveAutomation(
    targetDate?: Date,
    options?: { skipIfWithinWindow?: boolean; now?: Date }
) {
    const processDate = targetDate ? startOfDay(targetDate) : startOfDay(subDays(new Date(), 1)); // Yesterday by default
    
    try {
        // Get all active employees
        const activeEmployees = await prisma.user.findMany({
            where: {
                employeeStatus: "ACTIVE",
                isArchived: false,
                branchId: { not: null }
            },
            include: {
                branch: true,
                leaveEntitlements: {
                    where: {
                        year: new Date().getFullYear(),
                        leaveType: {
                            isActive: true,
                            leaveResetPolicy: "ROSTER_EVERY_YEAR"
                        }
                    },
                    include: {
                        leaveType: true
                    },
                    orderBy: {
                        createdAt: 'asc' // First created will be used first
                    }
                }
            }
        });

        for (const employee of activeEmployees) {
            await processEmployeeDailyRecord(employee, processDate, options);
        }

        return { success: true, processedEmployees: activeEmployees.length };
    } catch (error) {
        console.error("Error processing daily leave automation:", error);
        return { success: false, error: "Failed to process daily automation" };
    }
}

/**
 * Process daily record for a single employee
 */
async function processEmployeeDailyRecord(employee: any, processDate: Date, options?: { skipIfWithinWindow?: boolean; now?: Date }) {
    const dateStr = format(processDate, 'yyyy-MM-dd');
    
    // Check if already processed
    const existingRecord = await prisma.dailyTimeRecord.findUnique({
        where: {
            userId_date: {
                userId: employee.id,
                date: processDate
            }
        }
    });

    const hasRequiredFilled = Boolean(
        isNonZeroTime(existingRecord?.requiredCheckIn) &&
        isNonZeroTime(existingRecord?.requiredCheckOut) &&
        isFilledString(existingRecord?.requiredBreakTime)
    );

    const hasActualFilled = Boolean(
        isNonZeroTime(existingRecord?.actualCheckIn) &&
        isNonZeroTime(existingRecord?.actualCheckOut) &&
        isFilledString(existingRecord?.actualBreakTime)
    );

    const isFullyFilled = hasRequiredFilled && hasActualFilled;

    // If record exists, is already processed, and fully filled, skip
    if (existingRecord?.isProcessed && isFullyFilled) {
        return;
    }

    const dayOfWeek = format(processDate, 'EEEE').toUpperCase();
    const isWeeklyOff = employee.branch?.weeklyOffDays?.includes(dayOfWeek);

    if (options?.skipIfWithinWindow && options?.now && isWithinRequiredWindow(employee, processDate, options.now)) {
        return;
    }

    if (isWeeklyOff) {
        await handleWeeklyOffDay(employee, processDate, existingRecord);
    } else {
        await handleWorkDay(employee, processDate, existingRecord);
    }
}

/**
 * Handle weekly off day processing
 */
async function handleWeeklyOffDay(employee: any, processDate: Date, existingRecord: any) {
    const recordData = {
        userId: employee.id,
        date: processDate,
        status: "WEEKLY_OFF" as const,
        requiredCheckIn: null,
        requiredCheckOut: null,
        requiredBreakTime: "00:00",
        actualCheckIn: null,
        actualCheckOut: null,
        actualBreakTime: "00:00",
        requiredActiveTime: "00:00",
        actualActiveTime: "00:00",
        officialOvertimeundertime: "00:00",
        requestedOvertime: "00:00",
        overtimeUndertime: "00:00",
        isProcessed: true
    };

    if (existingRecord) {
        await prisma.dailyTimeRecord.update({
            where: { id: existingRecord.id },
            data: recordData
        });
    } else {
        await prisma.dailyTimeRecord.create({
            data: recordData
        });
    }

    // Create audit log
    await prisma.leaveAuditLog.create({
        data: {
            userId: employee.id,
            action: "WEEKLY_OFF_SET",
            description: `Weekly off day automatically set for ${format(processDate, 'EEEE, MMMM d, yyyy')}`,
            affectedDate: processDate,
            processingSource: "SYSTEM"
        }
    });

    // Create notification
    await prisma.employeeNotification.create({
        data: {
            userId: employee.id,
            type: "WEEKLY_OFF_SET",
            title: "Weekly Off Day",
            message: `${format(processDate, 'EEEE, MMMM d, yyyy')} has been set as your weekly off day.`,
            relatedDate: processDate
        }
    });
}

/**
 * Handle work day processing
 */
async function handleWorkDay(employee: any, processDate: Date, existingRecord: any) {
    const hasRequiredFilled = Boolean(
        isNonZeroTime(existingRecord?.requiredCheckIn) &&
        isNonZeroTime(existingRecord?.requiredCheckOut) &&
        isFilledString(existingRecord?.requiredBreakTime)
    );

    const hasActualFilled = Boolean(
        isNonZeroTime(existingRecord?.actualCheckIn) &&
        isNonZeroTime(existingRecord?.actualCheckOut) &&
        isFilledString(existingRecord?.actualBreakTime)
    );

    if (existingRecord && hasRequiredFilled && hasActualFilled) {
        const requiredCheckIn = existingRecord.requiredCheckIn as Date;
        const requiredCheckOut = existingRecord.requiredCheckOut as Date;
        const requiredBreakTime = existingRecord.requiredBreakTime || "00:00";

        const actualCheckIn = existingRecord.actualCheckIn as Date;
        const lateMinutes = Math.max(0, Math.floor((actualCheckIn.getTime() - requiredCheckIn.getTime()) / (1000 * 60)));
        const requiredActiveMinutes = getRequiredActiveMinutes(
            existingRecord,
            requiredCheckIn,
            requiredCheckOut,
            requiredBreakTime
        );

        const workingDaysInMonth = employee.workingDaysInMonth || 22;
        const dailySalary = workingDaysInMonth > 0 ? (employee.baseSalary / workingDaysInMonth) : 0;
        const perMinuteRate = requiredActiveMinutes > 0 ? (dailySalary / requiredActiveMinutes) : 0;
        const penaltyAmount = lateMinutes > 0 ? Number((perMinuteRate * lateMinutes).toFixed(2)) : 0;

        await prisma.dailyTimeRecord.update({
            where: { id: existingRecord.id },
            data: {
                status: "PRESENT",
                isProcessed: true,
                lateCheckInMinutes: lateMinutes,
                lateCheckInPenalty: penaltyAmount
            }
        });

        if (penaltyAmount > 0 && (existingRecord.lateCheckInPenalty || 0) <= 0) {
            await prisma.$transaction(async (tx) => {
                await tx.user.update({
                    where: { id: employee.id },
                    data: { walletBalance: { increment: -penaltyAmount } }
                });

                await tx.walletTransaction.create({
                    data: {
                        userId: employee.id,
                        amount: -penaltyAmount,
                        type: "ADJUSTMENT",
                        description: `Late check-in penalty for ${format(processDate, 'yyyy-MM-dd')} (${lateMinutes} min)`
                    }
                });
            });

            await prisma.employeeNotification.create({
                data: {
                    userId: employee.id,
                    type: "LATE_CHECKIN_PENALTY",
                    title: "Late Check-in Penalty",
                    message: `A penalty of αº│${penaltyAmount.toFixed(2)} was applied for ${lateMinutes} minutes late on ${format(processDate, 'MMMM d, yyyy')}.`,
                    relatedDate: processDate
                }
            });
        }
        return;
    }

    // Employee is absent - check for available leaves
    const availableLeaveEntitlements = employee.leaveEntitlements.filter((entitlement: any) => 
        (entitlement.allocatedDays - entitlement.usedDays) > 0
    );

    if (availableLeaveEntitlements.length > 0) {
        await handleAutoLeaveDeduction(employee, processDate, existingRecord, availableLeaveEntitlements[0]);
    } else {
        await handleAbsentWithoutLeave(employee, processDate, existingRecord);
    }
}

/**
 * Handle automatic leave deduction
 */
async function handleAutoLeaveDeduction(employee: any, processDate: Date, existingRecord: any, leaveEntitlement: any) {
    // Deduct one day from leave entitlement
    await prisma.userLeaveEntitlement.update({
        where: { id: leaveEntitlement.id },
        data: {
            usedDays: leaveEntitlement.usedDays + 1
        }
    });

    const midnight = getMidnightDate(processDate);
    const recordData = {
        userId: employee.id,
        date: processDate,
        status: "ON_LEAVE" as const,
        requiredCheckIn: midnight,
        requiredCheckOut: midnight,
        requiredBreakTime: "00:00",
        actualCheckIn: midnight,
        actualCheckOut: midnight,
        actualBreakTime: "00:00",
        requiredActiveTime: "00:00",
        actualActiveTime: "00:00",
        officialOvertimeundertime: "00:00",
        requestedOvertime: "00:00",
        overtimeUndertime: "00:00",
        autoDeductedLeaveType: leaveEntitlement.leaveType.name,
        isProcessed: true
    };

    if (existingRecord) {
        await prisma.dailyTimeRecord.update({
            where: { id: existingRecord.id },
            data: recordData
        });
    } else {
        await prisma.dailyTimeRecord.create({
            data: recordData
        });
    }

    const newBalance = leaveEntitlement.allocatedDays - (leaveEntitlement.usedDays + 1);

    // Create audit log
    await prisma.leaveAuditLog.create({
        data: {
            userId: employee.id,
            action: "AUTO_LEAVE_DEDUCTION",
            description: `Auto-deducted 1 day from ${leaveEntitlement.leaveType.name} due to absence on ${format(processDate, 'MMMM d, yyyy')}`,
            affectedDate: processDate,
            leaveTypeId: leaveEntitlement.leaveTypeId,
            previousBalance: leaveEntitlement.allocatedDays - leaveEntitlement.usedDays,
            newBalance: newBalance,
            deductedDays: 1,
            processingSource: "SYSTEM"
        }
    });

    // Create notification
    await prisma.employeeNotification.create({
        data: {
            userId: employee.id,
            type: "AUTO_LEAVE_DEDUCTION",
            title: "Leave Auto-Deducted",
            message: `1 day has been automatically deducted from your ${leaveEntitlement.leaveType.name} for absence on ${format(processDate, 'MMMM d, yyyy')}. Remaining balance: ${newBalance} days.`,
            relatedDate: processDate
        }
    });
}

/**
 * Handle absent without leave
 */
async function handleAbsentWithoutLeave(employee: any, processDate: Date, existingRecord: any) {
    const midnight = getMidnightDate(processDate);
    const recordData = {
        userId: employee.id,
        date: processDate,
        status: "ABSENT" as const,
        requiredCheckIn: midnight,
        requiredCheckOut: midnight,
        requiredBreakTime: "00:00",
        actualCheckIn: midnight,
        actualCheckOut: midnight,
        actualBreakTime: "00:00",
        requiredActiveTime: "00:00",
        actualActiveTime: "00:00",
        officialOvertimeundertime: "00:00",
        requestedOvertime: "00:00",
        overtimeUndertime: "00:00",
        isProcessed: true
    };

    if (existingRecord) {
        await prisma.dailyTimeRecord.update({
            where: { id: existingRecord.id },
            data: recordData
        });
    } else {
        await prisma.dailyTimeRecord.create({
            data: recordData
        });
    }

    // Create audit log
    await prisma.leaveAuditLog.create({
        data: {
            userId: employee.id,
            action: "ABSENT_WITHOUT_LEAVE",
            description: `Employee marked absent on ${format(processDate, 'MMMM d, yyyy')} - no available leave balance for auto-deduction`,
            affectedDate: processDate,
            processingSource: "SYSTEM"
        }
    });

    // Create notification
    await prisma.employeeNotification.create({
        data: {
            userId: employee.id,
            type: "ABSENT_WITHOUT_LEAVE",
            title: "Absent Without Leave",
            message: `You were marked absent on ${format(processDate, 'MMMM d, yyyy')}. No available leave balance for auto-deduction.`,
            relatedDate: processDate
        }
    });
}

/**
 * Process past dates that haven't been processed yet
 */
export async function processBackfillLeaveAutomation(
    fromDate: Date,
    toDate?: Date,
    options?: { includeToday?: boolean; skipIfWithinWindow?: boolean; now?: Date }
) {
    const today = startOfDay(new Date());
    const endDate = toDate ? startOfDay(toDate) : (options?.includeToday ? today : subDays(today, 1));
    const currentDate = startOfDay(new Date(fromDate));
    
    console.log(`Processing backfill from ${format(fromDate, 'yyyy-MM-dd')} to ${format(endDate, 'yyyy-MM-dd')}`);
    
    let processedDates = 0;
    
    while (currentDate <= endDate) {
        const isCurrentDay = isSameDay(currentDate, today);
        await processDailyLeaveAutomation(new Date(currentDate), {
            skipIfWithinWindow: isCurrentDay ? options?.skipIfWithinWindow : false,
            now: isCurrentDay ? options?.now : undefined
        });
        currentDate.setDate(currentDate.getDate() + 1);
        processedDates++;
    }
    
    console.log(`Completed backfill processing for ${processedDates} dates`);
    return { success: true, processedDates };
}

