export async function approveLeaveApplication(applicationId: string, approvedBy: string = "SYSTEM", adminNote?: string) {
    try {
        const application = await prisma.leaveApplication.findUnique({
            where: { id: applicationId },
            include: {
                user: true,
                leaveType: true
            }
        });
        
        if (!application) {
            return { success: false, error: "Leave application not found" };
        }
        
        if (application.status !== "PENDING") {
            return { success: false, error: "Leave application is not pending" };
        }
        
        // Find user's entitlement
        const entitlement = await prisma.userLeaveEntitlement.findUnique({
            where: {
                userId_leaveTypeId_year: {
                    userId: application.userId,
                    leaveTypeId: application.leaveTypeId,
                    year: application.leaveDate.getFullYear()
                }
            }
        });
        
        if (!entitlement) {
            return { success: false, error: "User doesn't have entitlement for this leave type" };
        }
        
        const remainingDays = entitlement.allocatedDays - entitlement.usedDays;
        if (remainingDays <= 0) {
            return { success: false, error: "User has no remaining leave days" };
        }
        
        // Approve application and deduct from balance
        await prisma.$transaction([
            prisma.leaveApplication.update({
                where: { id: applicationId },
                data: {
                    status: "APPROVED",
                    approvedBy,
                    approvedAt: new Date()
                }
            }),
            prisma.userLeaveEntitlement.update({
                where: { id: entitlement.id },
                data: { usedDays: entitlement.usedDays + 1 }
            })
        ]);
        
        revalidatePath("/admin/leave-applications");
        revalidatePath("/leaves");
        
        return { success: true };
    } catch (error) {
        console.error("Error approving leave application:", error);
        return { success: false, error: "Failed to approve leave application" };
    }
}

export async function rejectLeaveApplication(applicationId: string, approvedBy: string = "SYSTEM", adminNote?: string) {
    try {
        const application = await prisma.leaveApplication.findUnique({
            where: { id: applicationId }
        });
        
        if (!application) {
            return { success: false, error: "Leave application not found" };
        }
        
        if (application.status !== "PENDING") {
            return { success: false, error: "Leave application is not pending" };
        }
        
        await prisma.leaveApplication.update({
            where: { id: applicationId },
            data: {
                status: "REJECTED",
                approvedBy,
                approvedAt: new Date()
            }
        });
        
        revalidatePath("/admin/leave-applications");
        revalidatePath("/leaves");
        
        return { success: true };
    } catch (error) {
        console.error("Error rejecting leave application:", error);
        return { success: false, error: "Failed to reject leave application" };
    }
}

// Utility function to reset leave balances for new year
export async function resetLeaveBalancesForNewYear() {
    try {
        const currentYear = new Date().getFullYear();
        
        // Get all users with their current entitlements
        const users = await prisma.user.findMany({
            where: { 
                status: "APPROVED",
                isArchived: false 
            },
            include: {
                leaveEntitlements: {
                    where: { year: currentYear - 1 },
                    include: { leaveType: true }
                }
            }
        });
        
        // Create new year entitlements based on previous year's assignments
        const newEntitlements = [];
        for (const user of users) {
            for (const entitlement of user.leaveEntitlements) {
                if (entitlement.leaveType.isActive) {
                    newEntitlements.push({
                        userId: user.id,
                        leaveTypeId: entitlement.leaveTypeId,
                        year: currentYear,
                        allocatedDays: entitlement.leaveType.allocatedDays,
                        usedDays: 0
                    });
                }
            }
        }
        
        if (newEntitlements.length > 0) {
            await prisma.userLeaveEntitlement.createMany({
                data: newEntitlements,
                skipDuplicates: true
            });
        }
        
        return { success: true, created: newEntitlements.length };
    } catch (error) {
        console.error("Error resetting leave balances:", error);
        return { success: false, error: "Failed to reset leave balances" };
    }
}

// Holiday Management Functions
export async function createPublicHoliday(data: {
    name: string;
    date: string; // YYYY-MM-DD format
    description?: string;
    isRecurring?: boolean;
    appliesToAllBranches?: boolean;
    applicableBranchIds?: string[];
}) {
    try {
        const holidayDate = new Date(data.date);
        const appliesToAllBranches = data.appliesToAllBranches !== false;
        const applicableBranchIds = appliesToAllBranches
            ? []
            : [...new Set((data.applicableBranchIds || []).filter(Boolean))];

        if (!appliesToAllBranches && applicableBranchIds.length === 0) {
            return { success: false, error: "Select at least one branch or choose all branches" };
        }
        
        // Check conflicting holiday scope on this date
        const existingHolidays = await prisma.publicHoliday.findMany({
            where: {
                date: {
                    gte: new Date(holidayDate.getFullYear(), holidayDate.getMonth(), holidayDate.getDate()),
                    lt: new Date(holidayDate.getFullYear(), holidayDate.getMonth(), holidayDate.getDate() + 1)
                }
            }
        });
        
        const hasScopeConflict = existingHolidays.some((holiday) => {
            if (holiday.appliesToAllBranches || appliesToAllBranches) {
                return true;
            }

            return holiday.applicableBranchIds.some((branchId) => applicableBranchIds.includes(branchId));
        });

        if (hasScopeConflict) {
            return { success: false, error: "A holiday already exists on this date for one or more selected branches" };
        }
        
        const holiday = await prisma.publicHoliday.create({
            data: {
                name: data.name,
                date: holidayDate,
                description: data.description,
                isRecurring: data.isRecurring || false,
                appliesToAllBranches,
                applicableBranchIds
            }
        });

        const actor = await getDbUser();
        if (actor?.role === "EMPLOYEE" && actor.isManager) {
            const actorName = [actor.firstName, actor.lastName].filter(Boolean).join(" ") || actor.email;
            await logManagerHolidayAction({
                actorId: actor.id,
                actorName,
                action: "CREATE",
                holidayName: holiday.name,
                holidayDate: holiday.date,
                holidayId: holiday.id,
            });
        }
        
        revalidatePath("/admin/holidays");
        return { success: true, holiday };
    } catch (error) {
        console.error("Error creating holiday:", error);
        return { success: false, error: "Failed to create holiday" };
    }
}

export async function getPublicHolidays(year?: number) {
    try {
        const currentYear = year || new Date().getFullYear();
        const startDate = new Date(currentYear, 0, 1);
        const endDate = new Date(currentYear + 1, 0, 1);
        
        return await prisma.publicHoliday.findMany({
            where: {
                date: {
                    gte: startDate,
                    lt: endDate
                },
                isActive: true
            },
            orderBy: { date: "asc" }
        });
    } catch (error) {
        console.error("Error fetching holidays:", error);
        return [];
    }
}

export async function updatePublicHoliday(id: string, data: {
    name?: string;
    date?: string;
    description?: string;
    isRecurring?: boolean;
    isActive?: boolean;
    appliesToAllBranches?: boolean;
    applicableBranchIds?: string[];
}) {
    try {
        const existingHoliday = await prisma.publicHoliday.findUnique({ where: { id } });
        if (!existingHoliday) {
            return { success: false, error: "Holiday not found" };
        }

        const appliesToAllBranches = data.appliesToAllBranches ?? existingHoliday.appliesToAllBranches;
        const applicableBranchIds = appliesToAllBranches
            ? []
            : [...new Set((data.applicableBranchIds ?? existingHoliday.applicableBranchIds).filter(Boolean))];

        if (!appliesToAllBranches && applicableBranchIds.length === 0) {
            return { success: false, error: "Select at least one branch or choose all branches" };
        }

        const updateData: Prisma.PublicHolidayUpdateInput = {};
        
        if (data.name) updateData.name = data.name;
        if (data.date) updateData.date = new Date(data.date);
        if (data.description !== undefined) updateData.description = data.description;
        if (data.isRecurring !== undefined) updateData.isRecurring = data.isRecurring;
        if (data.isActive !== undefined) updateData.isActive = data.isActive;
        updateData.appliesToAllBranches = appliesToAllBranches;
        updateData.applicableBranchIds = applicableBranchIds;

        const targetDate = data.date ? new Date(data.date) : existingHoliday.date;
        const existingHolidays = await prisma.publicHoliday.findMany({
            where: {
                id: { not: id },
                date: {
                    gte: new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate()),
                    lt: new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate() + 1)
                }
            }
        });

        const hasScopeConflict = existingHolidays.some((holiday) => {
            if (holiday.appliesToAllBranches || appliesToAllBranches) {
                return true;
            }

            return holiday.applicableBranchIds.some((branchId) => applicableBranchIds.includes(branchId));
        });

        if (hasScopeConflict) {
            return { success: false, error: "A holiday already exists on this date for one or more selected branches" };
        }
        
        const holiday = await prisma.publicHoliday.update({
            where: { id },
            data: updateData
        });

        const actor = await getDbUser();
        if (actor?.role === "EMPLOYEE" && actor.isManager) {
            const actorName = [actor.firstName, actor.lastName].filter(Boolean).join(" ") || actor.email;
            await logManagerHolidayAction({
                actorId: actor.id,
                actorName,
                action: "UPDATE",
                holidayName: holiday.name,
                holidayDate: holiday.date,
                holidayId: holiday.id,
            });
        }
        
        revalidatePath("/admin/holidays");
        return { success: true, holiday };
    } catch (error) {
        console.error("Error updating holiday:", error);
        return { success: false, error: "Failed to update holiday" };
    }
}

export async function deletePublicHoliday(id: string) {
    try {
        const existingHoliday = await prisma.publicHoliday.findUnique({ where: { id } });
        if (!existingHoliday) {
            return { success: false, error: "Holiday not found" };
        }

        await prisma.publicHoliday.delete({
            where: { id }
        });

        const actor = await getDbUser();
        if (actor?.role === "EMPLOYEE" && actor.isManager) {
            const actorName = [actor.firstName, actor.lastName].filter(Boolean).join(" ") || actor.email;
            await logManagerHolidayAction({
                actorId: actor.id,
                actorName,
                action: "DELETE",
                holidayName: existingHoliday.name,
                holidayDate: existingHoliday.date,
                holidayId: existingHoliday.id,
            });
        }
        
        revalidatePath("/admin/holidays");
        return { success: true };
    } catch (error) {
        console.error("Error deleting holiday:", error);
        return { success: false, error: "Failed to delete holiday" };
    }
}

export async function checkIfHoliday(date: string, branchId?: string | null) {
    try {
        const targetDate = new Date(date);
        const whereClause: Prisma.PublicHolidayWhereInput = {
            date: {
                gte: new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate()),
                lt: new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate() + 1)
            },
            isActive: true
        };

        if (branchId) {
            whereClause.OR = [
                { appliesToAllBranches: true },
                { applicableBranchIds: { has: branchId } }
            ];
        }

        const holiday = await prisma.publicHoliday.findFirst({
            where: whereClause
        });
        
        return {
            isHoliday: !!holiday,
            holidayName: holiday?.name,
            holidayDescription: holiday?.description
        };
    } catch (error) {
        console.error("Error checking holiday:", error);
        return { isHoliday: false };
    }
}

export async function checkIfWeeklyHoliday(userId: string, date: string) {
    try {
        const user = await prisma.user.findUnique({
            where: { id: userId },
            include: { branch: true }
        });
        
        if (!user || !user.branch) {
            return { isWeeklyHoliday: false };
        }
        
        const targetDate = new Date(date);
        const dayOfWeek = targetDate.getDay(); // 0=Sunday, 6=Saturday
        const dayNames = ['SUNDAY', 'MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY'];
        const currentDayName = dayNames[dayOfWeek];
        
        const isWeeklyHoliday = user.branch.weeklyOffDays?.includes(currentDayName) || false;
        
        return {
            isWeeklyHoliday,
            weeklyHolidayDay: isWeeklyHoliday ? currentDayName : undefined,
            branchName: user.branch.name
        };
    } catch (error) {
        console.error("Error checking weekly holiday:", error);
        return { isWeeklyHoliday: false };
    }
}

export async function checkAllHolidays(userId: string, date: string) {
    try {
        const user = await prisma.user.findUnique({
            where: { id: userId },
            select: { branchId: true }
        });

        const [publicHolidayResult, weeklyHolidayResult] = await Promise.all([
            checkIfHoliday(date, user?.branchId),
            checkIfWeeklyHoliday(userId, date)
        ]);
        
        return {
            isPublicHoliday: publicHolidayResult.isHoliday,
            publicHolidayName: publicHolidayResult.holidayName,
            publicHolidayDescription: publicHolidayResult.holidayDescription,
            isWeeklyHoliday: weeklyHolidayResult.isWeeklyHoliday,
            weeklyHolidayDay: weeklyHolidayResult.weeklyHolidayDay,
            branchName: weeklyHolidayResult.branchName,
            hasAnyHoliday: publicHolidayResult.isHoliday || weeklyHolidayResult.isWeeklyHoliday
        };
    } catch (error) {
        console.error("Error checking all holidays:", error);
        return { hasAnyHoliday: false, isPublicHoliday: false, isWeeklyHoliday: false };
    }
}

"use server";

import { prisma } from "@/lib/prisma";
import { LoanStatus, Role, TransactionType } from "@prisma/client";
import { revalidatePath } from "next/cache";
import { calculateEMI, checkLoanEligibility, processLoanPayment } from "@/lib/services/loan.service";
import { getDbUser } from "./user.actions";

/**
 * Fetch all loans for admin review (Pending & Active).
 * Enhanced to include comprehensive employee financial context.
 */
export async function getAllLoans() {
    const user = await getDbUser();

    // Security Check: Only Admin/HR can see this
    if (!user || (user.role !== "SUPERADMIN" && user.role !== "HR")) {
        throw new Error("Unauthorized access to loan management");
    }

    return await prisma.loan.findMany({
        orderBy: {
            createdAt: 'desc'
        },
        include: {
            user: {
                select: {
                    id: true,
                    firstName: true,
                    lastName: true,
                    email: true,
                    phoneNumber: true,
                    baseSalary: true,
                    walletBalance: true,
                    dateOfJoining: true,
                    department: {
                        select: {
                            name: true
                        }
                    },
                    designation: {
                        select: {
                            name: true
                        }
                    },
                    branch: {
                        select: {
                            name: true
                        }
                    }
                }
            },
            emiState: true
        }
    });
}

/**
 * Get detailed loan information for admin approval with financial context
 */
export async function getLoanDetailsForApproval(loanId: string) {
    const user = await getDbUser();
    
    if (!user || (user.role !== "SUPERADMIN" && user.role !== "HR")) {
        throw new Error("Unauthorized");
    }
    
    const loan = await prisma.loan.findUnique({
        where: { id: loanId },
        include: {
            user: {
                select: {
                    id: true,
                    firstName: true,
                    lastName: true,
                    email: true,
                    phoneNumber: true,
                    baseSalary: true,
                    walletBalance: true,
                    dateOfJoining: true,
                    department: {
                        select: {
                            name: true
                        }
                    },
                    designation: {
                        select: {
                            name: true
                        }
                    },
                    branch: {
                        select: {
                            name: true
                        }
                    }
                }
            }
        }
    });
    
    if (!loan) {
        throw new Error("Loan not found");
    }
    
    // Get existing loans for debt calculation
    const existingLoans = await prisma.loan.findMany({
        where: {
            userId: loan.userId,
            id: { not: loanId }, // Exclude current loan
            status: { in: ["ACTIVE", "APPROVED"] }
        },
        include: {
            emiState: true
        }
    });
    
    // Get recent payment history
    const recentPayments = await prisma.payment.findMany({
        where: {
            loan: {
                userId: loan.userId
            }
        },
        orderBy: {
            createdAt: 'desc'
        },
        take: 5,
        include: {
            loan: {
                select: {
                    id: true,
                    issuedAmount: true
                }
            }
        }
    });
    
    // Calculate financial metrics
    const totalExistingDebt = existingLoans.reduce((sum, loan) => sum + loan.remainingPrincipal, 0);
    const totalIssuedAmount = existingLoans.reduce((sum, loan) => sum + loan.issuedAmount, 0);
    const totalRepaidAmount = totalIssuedAmount - totalExistingDebt;
    const repaymentRatio = totalIssuedAmount > 0 ? (totalRepaidAmount / totalIssuedAmount) : 1;
    
    // Calculate exact loan limits using same employee-side logic
    const financialMetrics = {
        totalExistingDebt,
        totalIssuedAmount,
        totalRepaidAmount,
        repaymentRatio,
        salaryCap: loan.user.baseSalary * 0.5,  // 50% of salary (employee-side logic)
        globalCap: 300000,                      // Hard limit (employee-side logic)
        remainingSalaryCap: Math.max(0, (loan.user.baseSalary * 0.5) - totalExistingDebt),
        remainingGlobalCap: Math.max(0, 300000 - totalExistingDebt),
        maxAllowedLoan: Math.min(
            Math.max(0, (loan.user.baseSalary * 0.5) - totalExistingDebt),
            Math.max(0, 300000 - totalExistingDebt)
        ),
        meetsRepaymentRequirement: repaymentRatio >= 0.75
    };
    
    return {
        loan,
        financialMetrics,
        existingLoans,
        recentPayments
    };
}

/**
 * Approve a loan request.
 * Sets values, creates EmiState, and logs to AuditLog.
 */
export async function approveLoan(
    loanId: string,
    data: {
        issuedAmount: number;
        gracePeriodMonths: number;
        totalMonths: number;
        adminComments?: string;
    }
) {
    const user = await getDbUser();

    if (!user || (user.role !== "SUPERADMIN" && user.role !== "HR")) {
        throw new Error("Unauthorized");
    }

    // 1. Validation Logic
    const loan = await prisma.loan.findUnique({ where: { id: loanId } });
    if (!loan) throw new Error("Loan not found");
    // Allow approval for manager-verified loans or pending loans
    if (loan.status !== LoanStatus.PENDING && loan.status !== LoanStatus.MANAGER_VERIFIED) {
        throw new Error("Only pending or manager-verified loans can be approved");
    }

    // Skip eligibility check for manager-verified loans (manager already verified)
    if (loan.status === LoanStatus.PENDING) {
        const eligibility = await checkLoanEligibility(loan.userId, data.issuedAmount);
        if (!eligibility.eligible) {
            throw new Error(eligibility.reason);
        }
    }

    return await prisma.$transaction(async (tx) => {
        // Calculate Schedule
        const now = new Date();
        const startMonthDate = new Date(now.getFullYear(), now.getMonth() + data.gracePeriodMonths + 1, 1);

        // 2. Update the Loan record
        const updatedLoan = await tx.loan.update({
            where: { id: loanId },
            data: {
                issuedAmount: data.issuedAmount,
                remainingPrincipal: data.issuedAmount,
                gracePeriodMonths: data.gracePeriodMonths,
                totalMonths: data.totalMonths,
                status: LoanStatus.ACTIVE,
                emiStartMonth: startMonthDate.getMonth() + 1,
                emiStartYear: startMonthDate.getFullYear(),
                approvedBy: user.id,
                adminComments: data.adminComments
            }
        });

        // 3. Create the initial EmiState record
        const emiMonths = data.totalMonths - data.gracePeriodMonths;
        const initialEmi = data.gracePeriodMonths > 0 ? 0 : calculateEMI(data.issuedAmount, emiMonths);

        await tx.emiState.create({
            data: {
                loanId: updatedLoan.id,
                currentEmi: initialEmi,
                carryForward: 0
            }
        });

        // 4. Log the initial EMI in AuditLog
        await tx.auditLog.create({
            data: {
                loanId: updatedLoan.id,
                oldEmi: 0,
                newEmi: initialEmi,
                changeReason: `Loan approved by ${user.id}. EMI starts ${startMonthDate.toLocaleDateString()}.`
            }
        });

        // 5. Credit Wallet
        await tx.user.update({
            where: { id: loan.userId },
            data: {
                walletBalance: { increment: data.issuedAmount }
            }
        });

        await tx.walletTransaction.create({
            data: {
                userId: loan.userId,
                amount: data.issuedAmount,
                type: "ADJUSTMENT",
                description: `Loan Disbursement - Loan #${loan.id.slice(-6)}`
            }
        });

        // 6. Notify manager if this was a manager-verified loan
        if (loan.managerVerifiedById) {
            const manager = await tx.user.findUnique({
                where: { id: loan.managerVerifiedById },
                select: { id: true }
            });

            if (manager) {
                const employee = await tx.user.findUnique({
                    where: { id: loan.userId },
                    select: { firstName: true, lastName: true }
                });

                await tx.employeeNotification.create({
                    data: {
                        userId: loan.managerVerifiedById,
                        type: "LOAN_APPLICATION_APPROVED",
                        title: "Loan Approved by Admin",
                        message: `The loan request you verified for ${employee?.firstName} ${employee?.lastName} (αº│${data.issuedAmount.toLocaleString()}) has been approved by Admin ${user.firstName} ${user.lastName}.`,
                        relatedEntityId: loan.id,
                    }
                });
            }
        }

        revalidatePath("/admin/loans");
        return updatedLoan;
    });
}

/**
 * EMI Management Functions for Admin
 */

// Toggle EMI collection for a specific loan
export async function toggleEmiCollection(loanId: string, enabled: boolean, reason?: string) {
    const user = await getDbUser();
    
    if (!user || (user.role !== "SUPERADMIN" && user.role !== "HR")) {
        throw new Error("Unauthorized");
    }
    
    return await prisma.$transaction(async (tx) => {
        const loan = await tx.loan.findUnique({
            where: { id: loanId },
            include: { emiState: true }
        });
        
        if (!loan || !loan.emiState) {
            throw new Error("Loan or EMI state not found");
        }
        
        // Create audit log
        await tx.auditLog.create({
            data: {
                loanId,
                oldEmi: loan.emiState.currentEmi,
                newEmi: enabled ? loan.emiState.currentEmi : 0,
                changeReason: `EMI collection ${enabled ? 'enabled' : 'disabled'} by admin ${user.id}${reason ? '. Reason: ' + reason : ''}`
            }
        });
        
        // Update EMI state
        if (!enabled) {
            // When disabling EMI, set currentEmi to 0 and add to carryForward
            await tx.emiState.update({
                where: { loanId },
                data: {
                    carryForward: loan.emiState.carryForward + loan.emiState.currentEmi,
                    currentEmi: 0
                }
            });
        } else {
            // When enabling EMI, recalculate and redistribute across remaining months
            const newEmi = await recalculateEMI(loanId, tx);
            
            // Log the EMI change
            await tx.auditLog.create({
                data: {
                    loanId,
                    oldEmi: 0,
                    newEmi: newEmi,
                    changeReason: `EMI enabled with redistribution by admin ${user.id}${reason ? '. Reason: ' + reason : ''}`
                }
            });
        }
        
        revalidatePath("/admin/loans");
        return { success: true };
    });
}

// Skip EMI for specific month
export async function skipEmiForMonth(loanId: string, month: string, reason: string) {
    const user = await getDbUser();
    
    if (!user || (user.role !== "SUPERADMIN" && user.role !== "HR")) {
        throw new Error("Unauthorized");
    }
    
    return await prisma.$transaction(async (tx) => {
        const loan = await tx.loan.findUnique({
            where: { id: loanId },
            include: { emiState: true }
        });
        
        if (!loan || !loan.emiState) {
            throw new Error("Loan not found");
        }
        
        // Check if EMI already processed for this month
        const existingPayment = await tx.payment.findFirst({
            where: {
                loanId,
                payrollMonth: month,
                type: 'EMI'
            }
        });
        
        if (existingPayment) {
            throw new Error("EMI already processed for this month");
        }
        
        // Create a skip record (payment with 0 amount)
        await tx.payment.create({
            data: {
                loanId,
                amount: 0,
                type: 'EMI',
                payrollMonth: month,
            }
        });
        
        // Add carry forward for skipped EMI and recalculate
        await tx.emiState.update({
            where: { loanId },
            data: {
                carryForward: loan.emiState.carryForward + loan.emiState.currentEmi
            }
        });
        
        // Recalculate and redistribute EMI across remaining months
        const newEmi = await recalculateEMI(loanId, tx);
        
        // Create audit log
        await tx.auditLog.create({
            data: {
                loanId,
                oldEmi: loan.emiState.currentEmi,
                newEmi: newEmi,
                changeReason: `EMI skipped for ${month} and redistributed by admin ${user.id}. Reason: ${reason}`
            }
        });
        
        revalidatePath("/admin/loans");
        return { success: true };
    });
}

// Manual payment recording
export async function recordManualPayment(loanId: string, amount: number, reason: string) {
    const user = await getDbUser();
    
    if (!user || (user.role !== "SUPERADMIN" && user.role !== "HR")) {
        throw new Error("Unauthorized");
    }
    
    if (amount <= 0) {
        throw new Error("Payment amount must be positive");
    }
    
    // Use existing loan service for payment processing
    const result = await processLoanPayment(loanId, amount, 'MANUAL');
    
    // Create audit log for manual payment
    await prisma.auditLog.create({
        data: {
