            oldEmi: 0, // Not EMI related
            newEmi: 0,
            changeReason: `Manual payment of αº│${amount} recorded by admin ${user.id}. Reason: ${reason}`
        }
    });
    
    revalidatePath("/admin/loans");
    return result;
}

