        return {
            success: true,
            message: `Successfully ${user.isManager ? 'removed manager status from' : 'made'} ${user.firstName} ${user.lastName} ${user.isManager ? '' : 'a manager'}`,
            isManager: updatedUser.isManager
        };
    } catch (error) {
        console.error("Error toggling manager status:", error);
        return { success: false, error: "Failed to update manager status" };
    }
}

/**
 * Get role statistics
 */
export async function getRoleStatistics() {
    const admin = await getDbUser();
    if (!admin || admin.role !== "SUPERADMIN") {
        throw new Error("Unauthorized");
    }

    try {
        const stats = await prisma.user.groupBy({
            by: ['role'],
            _count: {
                _all: true,
            },
            where: {
                isArchived: false,
            },
        });

        const totalUsers = await prisma.user.count({
            where: { isArchived: false }
        });

        const archivedUsers = await prisma.user.count({
            where: { isArchived: true }
        });

        const pendingUsers = await prisma.user.count({
            where: { 
                status: UserStatus.PENDING,
                isArchived: false 
            }
        });

        return {
            roleBreakdown: stats.reduce((acc, stat) => {
                acc[stat.role] = stat._count._all;
                return acc;
            }, {} as Record<Role, number>),
            totalUsers,
            archivedUsers,
            pendingUsers,
        };
    } catch (error) {
        console.error("Error fetching role statistics:", error);
        throw new Error("Failed to fetch role statistics");
    }
}

