"use server";

import { prisma } from "@/lib/prisma";
import { zkTecoService } from "@/lib/services/zkteco.service";
import { subDays, format, startOfDay } from "date-fns";
import { revalidatePath } from "next/cache";

export interface SyncResult {
  success: boolean;
  message: string;
  syncedRecords: number;
  skippedRecords: number;
  errors: string[];
}

/**
 * Sync ZKTeco data for a specific employee on a specific date
 */
export async function syncEmployeeTimeData(userId: string, date: Date): Promise<SyncResult> {
  const result: SyncResult = {
    success: false,
    message: "",
    syncedRecords: 0,
    skippedRecords: 0,
    errors: [],
  };

  try {
    console.log(`Syncing employee ${userId} for date ${date.toISOString().split('T')[0]}`);
    
    // Check if ZKTeco service is configured
    if (!zkTecoService.isConfigured()) {
      result.message = "ZKTeco service is not properly configured";
      result.errors.push("Missing environment variables: ZKTECO_BASE_URL, ZKTECO_USERNAME, or ZKTECO_PASSWORD");
      console.log(`Sync failed for ${userId}: ZKTeco not configured`);
      return result;
    }

    // Get user with attendanceId
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        attendanceId: true,
        firstName: true,
        lastName: true,
      },
    });

    if (!user) {
      result.message = "User not found";
      result.errors.push(`User with ID ${userId} not found`);
      console.log(`Sync failed: User ${userId} not found`);
      return result;
    }

    if (!user.attendanceId) {
      result.message = `Employee ${user.firstName} ${user.lastName} has no attendance ID`;
      result.errors.push("AttendanceId is required for ZKTeco sync");
      console.log(`Sync failed: ${user.firstName} ${user.lastName} has no attendanceId`);
      return result;
    }

    console.log(`Found employee: ${user.firstName} ${user.lastName} with attendanceId: ${user.attendanceId}`);

    // Get or create daily time record for the date
    const timeRecord = await prisma.dailyTimeRecord.findUnique({
      where: {
        userId_date: {
          userId: userId,
          date: date,
        },
      },
    });

    // If no time record exists for this date, skip (since we only want to fill existing records)
    if (!timeRecord) {
      result.message = `No time record found for ${user.firstName} ${user.lastName} on ${format(date, "yyyy-MM-dd")}`;
      result.skippedRecords = 1;
      console.log(`Sync skipped: No time record for ${user.firstName} ${user.lastName} on ${format(date, "yyyy-MM-dd")}`);
      return result;
    }

    console.log(`Found time record for ${format(date, "yyyy-MM-dd")}:`, {
      status: timeRecord.status,
      hasCheckIn: !!timeRecord.actualCheckIn,
      hasCheckOut: !!timeRecord.actualCheckOut,
      hasBreakTime: !!timeRecord.actualBreakTime
    });

    // Check if the record already has all the data (skip if all fields are filled)
    const hasAllData = timeRecord.actualCheckIn && timeRecord.actualCheckOut && timeRecord.actualBreakTime;
    if (hasAllData) {
      result.message = `Time record for ${user.firstName} ${user.lastName} on ${format(date, "yyyy-MM-dd")} already has complete data`;
      result.skippedRecords = 1;
      console.log(`Sync skipped: Record already complete for ${user.firstName} ${user.lastName} on ${format(date, "yyyy-MM-dd")}`);
      return result;
    }

    console.log(`Fetching ZKTeco data for employee code: ${user.attendanceId} on ${format(date, "yyyy-MM-dd")}`);
    console.log(`Database date being passed to ZKTeco service: ${date.toISOString()}`);

    // Fetch data from ZKTeco API
    const timeData = await zkTecoService.getEmployeeTimeData(user.attendanceId, date);
    
    console.log(`ZKTeco response for ${user.attendanceId}:`, {
      hasCheckIn: !!timeData.actualCheckIn,
      hasCheckOut: !!timeData.actualCheckOut,  
      hasBreakTime: !!timeData.actualBreakTime,
      checkIn: timeData.actualCheckIn?.toISOString(),
      checkOut: timeData.actualCheckOut?.toISOString(),
      breakTime: timeData.actualBreakTime
    });

    // Prepare update data (only update empty fields)
    const updateData: any = {};
    let hasUpdates = false;

    if (!timeRecord.actualCheckIn && timeData.actualCheckIn) {
      updateData.actualCheckIn = timeData.actualCheckIn;
      hasUpdates = true;
      console.log(`Will update checkIn: ${timeData.actualCheckIn.toISOString()}`);
    }

    if (!timeRecord.actualCheckOut && timeData.actualCheckOut) {
      updateData.actualCheckOut = timeData.actualCheckOut;
      hasUpdates = true;
      console.log(`Will update checkOut: ${timeData.actualCheckOut.toISOString()}`);
    }

    if (!timeRecord.actualBreakTime && timeData.actualBreakTime) {
      updateData.actualBreakTime = timeData.actualBreakTime;
      hasUpdates = true;
      console.log(`Will update breakTime: ${timeData.actualBreakTime}`);
    }

    if (!hasUpdates) {
      result.message = `No new data available for ${user.firstName} ${user.lastName} on ${format(date, "yyyy-MM-dd")}`;
      result.skippedRecords = 1;
      console.log(`Sync skipped: No new data available for ${user.firstName} ${user.lastName} on ${format(date, "yyyy-MM-dd")}`);
      return result;
    }

    console.log(`Updating database for ${user.firstName} ${user.lastName} with:`, updateData);

    // Update the time record
    await prisma.dailyTimeRecord.update({
      where: {
        userId_date: {
          userId: userId,
          date: date,
        },
      },
      data: updateData,
    });

    result.success = true;
    result.syncedRecords = 1;
    result.message = `Successfully synced time data for ${user.firstName} ${user.lastName} on ${format(date, "yyyy-MM-dd")}`;
    console.log(`Sync successful: Updated ${user.firstName} ${user.lastName} for ${format(date, "yyyy-MM-dd")}`);
  } catch (error) {
    console.error("Error syncing employee time data:", error);
    result.message = "An error occurred while syncing time data";
    result.errors.push(error instanceof Error ? error.message : "Unknown error");
  }

  return result;
}

/**
 * Sync ZKTeco data for a specific employee for the last N days
 */
export async function syncEmployeeTimeDataRange(userId: string, days: number = 4): Promise<SyncResult> {
  const result: SyncResult = {
    success: true,
    message: "",
    syncedRecords: 0,
    skippedRecords: 0,
    errors: [],
  };

  try {
    console.log(`Starting sync range for user ${userId}, ${days} days`);
    
    const today = new Date();
    // Generate dates array using startOfDay to handle Bangladesh timezone correctly
    const dates = Array.from({ length: days }, (_, i) => {
      const date = subDays(today, i);  
      const startOfDayDate = startOfDay(date); // This handles timezone correctly
      console.log(`Date ${i}: ${date.toISOString()} -> startOfDay: ${startOfDayDate.toISOString()}`);
      return startOfDayDate;
    });

    console.log(`Processing ${dates.length} dates for user ${userId}`);

    for (const date of dates) {
      console.log(`\n=== Processing date: ${date.toISOString()} ===`);
      const dayResult = await syncEmployeeTimeData(userId, date);
      
      result.syncedRecords += dayResult.syncedRecords;
      result.skippedRecords += dayResult.skippedRecords;
      result.errors.push(...dayResult.errors);

      if (!dayResult.success && dayResult.errors.length > 0) {
        result.success = false;
      }
      
      console.log(`Date ${date.toISOString().split('T')[0]} result:`, {
        success: dayResult.success,
        synced: dayResult.syncedRecords,
        skipped: dayResult.skippedRecords,
        message: dayResult.message
      });
    }

    if (result.syncedRecords === 0 && result.skippedRecords === 0) {
      result.message = "No records processed";
    } else if (result.syncedRecords > 0) {
      result.message = `Successfully synced ${result.syncedRecords} record(s), skipped ${result.skippedRecords} record(s)`;
    } else {
      result.message = `Skipped ${result.skippedRecords} record(s) (already complete or no data available)`;
    }
    
    console.log(`\nSync Range Summary:`, {
      totalSynced: result.syncedRecords,
      totalSkipped: result.skippedRecords,
      success: result.success,
      message: result.message
    });
    
  } catch (error) {
    console.error("Error syncing employee time data range:", error);
    result.success = false;
    result.message = "An error occurred while syncing time data range";
    result.errors.push(error instanceof Error ? error.message : "Unknown error");
  }

  return result;
}

/**
 * Sync ZKTeco data for all employees with attendance IDs for the last N days
 */
export async function syncAllEmployeesTimeData(days: number = 4): Promise<SyncResult> {
  const result: SyncResult = {
    success: true,
    message: "",
    syncedRecords: 0,
    skippedRecords: 0,
    errors: [],
  };

  try {
    // Check if ZKTeco service is configured
    if (!zkTecoService.isConfigured()) {
      result.success = false;
      result.message = "ZKTeco service is not properly configured";
      result.errors.push("Missing environment variables: ZKTECO_BASE_URL, ZKTECO_USERNAME, or ZKTECO_PASSWORD");
      return result;
    }

    // Get all users with attendance IDs
    const users = await prisma.user.findMany({
      where: {
        attendanceId: {
          not: null,
        },
        isArchived: false,
        employeeStatus: "ACTIVE",
      },
      select: {
        id: true,
        attendanceId: true,
        firstName: true,
        lastName: true,
      },
    });

    if (users.length === 0) {
      result.message = "No active employees with attendance IDs found";
      result.skippedRecords = 0;
      return result;
    }

    console.log(`Starting ZKTeco sync for ${users.length} employees for last ${days} days`);

    // Process each employee
    for (const user of users) {
      try {
        const userResult = await syncEmployeeTimeDataRange(user.id!, days);
        
        result.syncedRecords += userResult.syncedRecords;
        result.skippedRecords += userResult.skippedRecords;
        result.errors.push(...userResult.errors);

        if (!userResult.success && userResult.errors.length > 0) {
          console.log(`Error syncing data for ${user.firstName} ${user.lastName}:`, userResult.errors);
        }
      } catch (error) {
        console.error(`Error processing user ${user.firstName} ${user.lastName}:`, error);
        result.errors.push(`${user.firstName} ${user.lastName}: ${error instanceof Error ? error.message : "Unknown error"}`);
      }
    }

    result.message = `Processed ${users.length} employee(s): synced ${result.syncedRecords} record(s), skipped ${result.skippedRecords} record(s)`;
    
    if (result.errors.length > 0) {
      console.log(`ZKTeco sync completed with ${result.errors.length} error(s)`);
    } else {
      console.log("ZKTeco sync completed successfully");
    }
  } catch (error) {
    console.error("Error in bulk sync:", error);
    result.success = false;
    result.message = "An error occurred during bulk sync";
    result.errors.push(error instanceof Error ? error.message : "Unknown error");
  }

  return result;
}

/**
 * Manual sync function for UI - syncs specific user for today and past 3 days
 */
export async function manualSyncEmployee(userId: string): Promise<SyncResult> {
  console.log(`Starting manual sync for user: ${userId}`);
  
  try {
    const result = await syncEmployeeTimeDataRange(userId, 4); // Today + 3 days back
    
    console.log(`Manual sync completed for user: ${userId}`, {
      success: result.success,
      syncedRecords: result.syncedRecords,
      skippedRecords: result.skippedRecords,
      message: result.message,
      errors: result.errors
    });
    
    // Revalidate the timeline page to show updated data
    revalidatePath("/admin/timeline");
    
    return result;
  } catch (error) {
    console.error(`Manual sync failed for user: ${userId}`, error);
    return {
      success: false,
      message: `Manual sync failed: ${error instanceof Error ? error.message : 'Unknown error'}`,
      syncedRecords: 0,
      skippedRecords: 0,
      errors: [error instanceof Error ? error.message : 'Unknown error']
    };
  }
}

"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ProfileView } from "@/components/employee/ProfileView";
import { ProfileEditFormTabbed as ProfileEditForm } from "@/components/employee/ProfileEditFormTabbed";
import { getUserProfileById } from "@/actions/profile.actions";
import { User } from "@prisma/client";
import { Loader2, ArrowLeft, Wallet } from "lucide-react";
import { toast } from "sonner";
import Link from "next/link";
import { getActiveBranches } from "@/actions/branch.actions";

type UserWithBranch = User & {
  branch?: {
    id: string;
    name: string;
    location: string;
  } | null;
  department?: {
    id: string;
    name: string;
  } | null;
  designation?: {
    id: string;
    name: string;
  } | null;
};

export default function AdminEmployeeDetailPage() {
  const params = useParams();
  const router = useRouter();
  const userId = params.id as string;
  
  const [user, setUser] = useState<UserWithBranch | null>(null);
  const [branches, setBranches] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("view");

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [result, branchesResult] = await Promise.all([
        getUserProfileById(userId),
        getActiveBranches(),
      ]);

      if (result.success && result.data) {
        setUser(result.data as UserWithBranch);
      } else {
        toast.error(result.error || "Failed to load employee profile");
      }
      
      setBranches(branchesResult);
    } catch (error) {
      console.error(error);
      toast.error("Failed to load data");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [userId]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!user) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <p className="text-muted-foreground mb-4">Employee not found</p>
          <Button onClick={() => router.back()}>Go Back</Button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Link href="/admin/employees">
            <Button variant="outline" size="icon">
              <ArrowLeft className="h-4 w-4" />
            </Button>
          </Link>
          <div>
            <h1 className="text-3xl font-bold tracking-tight">
              {user.firstName} {user.lastName}
            </h1>
            <p className="text-muted-foreground">{user.email}</p>
          </div>
        </div>
      </div>

      {/* Wallet & Salary Quick Info */}
      <div className="grid gap-4 md:grid-cols-2">
        <Link href={`/employees/${userId}/wallet`}>
          <Card className="bg-primary/5 border-primary/20 hover:bg-primary/10 transition-colors cursor-pointer">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Wallet className="h-5 w-5" />
                Wallet Balance
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-3xl font-bold text-primary">
                αº│{user.walletBalance.toLocaleString("en-BD")}
              </div>
            </CardContent>
          </Card>
        </Link>

        <Link href={`/employees/${userId}/salary`}>
          <Card className="hover:bg-muted/50 transition-colors cursor-pointer">
            <CardHeader>
              <CardTitle>Base Salary</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-3xl font-bold">
                αº│{user.baseSalary.toLocaleString("en-BD")}
              </div>
            </CardContent>
          </Card>
        </Link>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="view">View Profile</TabsTrigger>
          <TabsTrigger value="edit">Edit Profile</TabsTrigger>
        </TabsList>

        <TabsContent value="view" className="space-y-6 mt-6">
          <ProfileView
            user={user}
            canEdit={true}
            onEdit={() => setActiveTab("edit")}
          />
        </TabsContent>

        <TabsContent value="edit" className="mt-6">
          <ProfileEditForm
            user={user}
            branches={branches}
            isAdmin={true}
            onSuccess={() => {
              setActiveTab("view");
              fetchData();
            }}
            onCancel={() => setActiveTab("view")}
          />
        </TabsContent>
      </Tabs>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { getUserProfileById } from "@/actions/profile.actions";
import { getWalletTransactionsForUser, getWalletRequestsForUser, updateWalletRequestStatus } from "@/actions/wallet.actions";
import { User, WalletTransaction, WalletRequest } from "@prisma/client";
import { 
  ArrowLeft, 
  Wallet, 
  TrendingUp, 
  TrendingDown, 
  Clock, 
  DollarSign,
  Plus,
  Minus,
  CreditCard,
  AlertCircle,
  Loader2
} from "lucide-react";
import { toast } from "sonner";
import Link from "next/link";
import { WalletAdjustmentDialog } from "@/components/admin/WalletAdjustmentDialog";

type UserWithWallet = User & {
  branch?: {
    id: string;
    name: string;
    location: string;
  } | null;
  department?: {
    id: string;
    name: string;
  } | null;
  designation?: {
    id: string;
    name: string;
  } | null;
};

export default function EmployeeWalletPage() {
  const params = useParams();
  const router = useRouter();
  const userId = params.id as string;
  
  const [user, setUser] = useState<UserWithWallet | null>(null);
  const [transactions, setTransactions] = useState<WalletTransaction[]>([]);
  const [walletRequests, setWalletRequests] = useState<WalletRequest[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isApproving, setIsApproving] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("overview");

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [userResult, transactionsResult, requestsResult] = await Promise.all([
        getUserProfileById(userId),
        getWalletTransactionsForUser(userId),
        getWalletRequestsForUser(userId)
      ]);

      if (userResult.success && userResult.data) {
        setUser(userResult.data as UserWithWallet);
      } else {
        toast.error(userResult.error || "Failed to load employee profile");
      }

      setTransactions(transactionsResult);
      setWalletRequests(requestsResult);
    } catch (error) {
      console.error(error);
      toast.error("Failed to load data");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [userId]);

  // Calculate monthly totals
  const thisMonthTransactions = transactions.filter(t => {
    const transactionDate = new Date(t.createdAt);
    const currentDate = new Date();
    return transactionDate.getMonth() === currentDate.getMonth() && 
           transactionDate.getFullYear() === currentDate.getFullYear();
  });

  const monthlyCredits = thisMonthTransactions
    .filter(t => t.amount > 0)
    .reduce((sum, t) => sum + t.amount, 0);

  const monthlyDebits = thisMonthTransactions
    .filter(t => t.amount < 0)
    .reduce((sum, t) => sum + Math.abs(t.amount), 0);

  const netMonthlyAmount = monthlyCredits - monthlyDebits;

  // Get pending requests
  const pendingRequests = walletRequests.filter(r => r.status === "PENDING");

  // Format transaction type for display
  const getTransactionType = (amount: number, type: string) => {
    if (amount > 0) return "CREDIT";
    if (amount < 0) return "DEBIT";
    return type.toUpperCase();
  };

  const handleApproveRequest = async (requestId: string) => {
    setIsApproving(requestId);
    try {
      await updateWalletRequestStatus(requestId, "APPROVED");
      toast.success("Request approved successfully");
      fetchData(); // Refresh data
    } catch (error) {
      console.error(error);
      toast.error("Failed to approve request");
    } finally {
      setIsApproving(null);
    }
  };

  const handleRejectRequest = async (requestId: string) => {
    setIsApproving(requestId);
    try {
      await updateWalletRequestStatus(requestId, "REJECTED");
      toast.success("Request rejected successfully");
      fetchData(); // Refresh data
    } catch (error) {
      console.error(error);
      toast.error("Failed to reject request");
    } finally {
      setIsApproving(null);
    }
  };

  if (isLoading || !user) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <p className="text-muted-foreground mb-4">Loading...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Link href={`/admin/employees/${userId}`}>
            <Button variant="outline" size="icon">
              <ArrowLeft className="h-4 w-4" />
            </Button>
          </Link>
          <div>
            <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2">
              <Wallet className="h-8 w-8" />
              {user.firstName} {user.lastName} - Wallet
            </h1>
            <p className="text-muted-foreground">Manage wallet transactions and adjustments</p>
          </div>
        </div>
        <WalletAdjustmentDialog
          userId={user.id}
          currentBalance={user.walletBalance}
          onSuccess={fetchData}
        />
      </div>

      {/* Wallet Overview Cards */}
      <div className="grid gap-4 md:grid-cols-3">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Current Balance</CardTitle>
            <Wallet className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-primary">αº│{user.walletBalance.toLocaleString("en-BD")}</div>
            <p className="text-xs text-muted-foreground">Available balance</p>
          </CardContent>
        </Card>
        
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">This Month</CardTitle>
            <TrendingUp className="h-4 w-4 text-green-600" />
          </CardHeader>
          <CardContent>
            <div className={`text-2xl font-bold ${netMonthlyAmount >= 0 ? 'text-green-600' : 'text-red-600'}`}>
              {netMonthlyAmount >= 0 ? '+' : ''}αº│{netMonthlyAmount.toLocaleString("en-BD")}
            </div>
            <p className="text-xs text-muted-foreground">Net amount this month</p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Pending</CardTitle>
            <Clock className="h-4 w-4 text-yellow-600" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-yellow-600">{pendingRequests.length}</div>
            <p className="text-xs text-muted-foreground">Pending requests</p>
          </CardContent>
        </Card>
      </div>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="transactions">All Transactions</TabsTrigger>
          <TabsTrigger value="requests">Pending Requests</TabsTrigger>
        </TabsList>

        <TabsContent value="overview" className="space-y-6 mt-6">
          {/* Recent Transactions */}
          <Card>
            <CardHeader>
              <CardTitle>Recent Transactions</CardTitle>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Type</TableHead>
                    <TableHead>Description</TableHead>
                    <TableHead>Amount</TableHead>
                    <TableHead>Date</TableHead>
                    <TableHead>Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {transactions.slice(0, 5).map((transaction) => {
                    const transactionType = getTransactionType(transaction.amount, transaction.type);
                    return (
                      <TableRow key={transaction.id}>
                        <TableCell>
                          <div className="flex items-center gap-2">
                            {transactionType === "CREDIT" ? (
                              <TrendingUp className="h-4 w-4 text-green-600" />
                            ) : transactionType === "DEBIT" ? (
                              <TrendingDown className="h-4 w-4 text-red-600" />
                            ) : (
                              <DollarSign className="h-4 w-4 text-blue-600" />
                            )}
                            <span className="capitalize">{transactionType.toLowerCase()}</span>
                          </div>
                        </TableCell>
                        <TableCell>{transaction.description}</TableCell>
                        <TableCell className={`font-medium ${
                          transactionType === "CREDIT" ? "text-green-600" : 
                          transactionType === "DEBIT" ? "text-red-600" : "text-blue-600"
                        }`}>
                          {transactionType === "CREDIT" ? "+" : transactionType === "DEBIT" ? "-" : "┬▒"}
                          αº│{Math.abs(transaction.amount).toLocaleString("en-BD")}
                        </TableCell>
                        <TableCell>{new Date(transaction.createdAt).toLocaleDateString()}</TableCell>
                        <TableCell>
                          <Badge variant="default">COMPLETED</Badge>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                  {transactions.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={5} className="text-center py-8 text-muted-foreground">
                        No transactions found
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>

          {/* Pending Requests */}
          {pendingRequests.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <AlertCircle className="h-5 w-5 text-yellow-600" />
                  Pending Approval Requests
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {pendingRequests.map((request) => (
                    <div key={request.id} className="flex items-center justify-between p-4 border rounded-lg">
                      <div>
                        <div className="font-medium">Wallet Request</div>
                        <div className="text-sm text-muted-foreground">{request.description}</div>
                        <div className="text-sm text-muted-foreground">
                          Amount: αº│{request.amount.toLocaleString("en-BD")} ΓÇó 
                          {new Date(request.createdAt).toLocaleDateString()}
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          variant="outline"
                          className="text-green-600 border-green-600 hover:bg-green-50"
                          onClick={() => handleApproveRequest(request.id)}
                          disabled={isApproving === request.id}
                        >
                          {isApproving === request.id ? (
                            <>
                              <Loader2 className="mr-2 h-3 w-3 animate-spin" />
                              Approving...
                            </>
                          ) : (
                            "Approve"
                          )}
                        </Button>
                        <Button
                          size="sm" 
                          variant="outline"
                          className="text-red-600 border-red-600 hover:bg-red-50"
                          onClick={() => handleRejectRequest(request.id)}
                          disabled={isApproving === request.id}
                        >
                          {isApproving === request.id ? (
                            <>
                              <Loader2 className="mr-2 h-3 w-3 animate-spin" />
                              Rejecting...
                            </>
                          ) : (
                            "Reject"
                          )}
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}
        </TabsContent>

        <TabsContent value="transactions" className="space-y-6 mt-6">
          <Card>
            <CardHeader>
              <CardTitle>All Transactions</CardTitle>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Reference</TableHead>
                    <TableHead>Type</TableHead>
                    <TableHead>Description</TableHead>
                    <TableHead>Amount</TableHead>
                    <TableHead>Date</TableHead>
                    <TableHead>Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {transactions.map((transaction) => {
                    const transactionType = getTransactionType(transaction.amount, transaction.type);
                    return (
                      <TableRow key={transaction.id}>
                        <TableCell className="font-mono text-sm">{transaction.id.slice(-8).toUpperCase()}</TableCell>
                        <TableCell>
                          <div className="flex items-center gap-2">
                            {transactionType === "CREDIT" ? (
                              <TrendingUp className="h-4 w-4 text-green-600" />
                            ) : transactionType === "DEBIT" ? (
                              <TrendingDown className="h-4 w-4 text-red-600" />
                            ) : (
                              <DollarSign className="h-4 w-4 text-blue-600" />
                            )}
                            <span className="capitalize">{transactionType.toLowerCase()}</span>
                          </div>
                        </TableCell>
                        <TableCell>{transaction.description}</TableCell>
                        <TableCell className={`font-medium ${
                          transactionType === "CREDIT" ? "text-green-600" : 
                          transactionType === "DEBIT" ? "text-red-600" : "text-blue-600"
                        }`}>
                          {transactionType === "CREDIT" ? "+" : transactionType === "DEBIT" ? "-" : "┬▒"}
                          αº│{Math.abs(transaction.amount).toLocaleString("en-BD")}
                        </TableCell>
                        <TableCell>{new Date(transaction.createdAt).toLocaleString()}</TableCell>
                        <TableCell>
                          <Badge variant="default">COMPLETED</Badge>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                  {transactions.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={6} className="text-center py-8 text-muted-foreground">
                        No transactions found
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="requests" className="space-y-6 mt-6">
          <Card>
            <CardHeader>
              <CardTitle>Pending Approval Requests</CardTitle>
            </CardHeader>
            <CardContent>
              {pendingRequests.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground">
                  <AlertCircle className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
                  <p>No pending requests</p>
                </div>
              ) : (
                <div className="space-y-4">
                  {pendingRequests.map((request) => (
                    <Card key={request.id}>
                      <CardContent className="pt-6">
                        <div className="flex items-center justify-between">
                          <div className="space-y-2">
                            <div className="flex items-center gap-2">
                              <Badge variant="outline">WALLET REQUEST</Badge>
                              <span className="font-medium">αº│{request.amount.toLocaleString("en-BD")}</span>
                            </div>
                            <div className="text-sm text-muted-foreground">{request.description}</div>
                            <div className="text-xs text-muted-foreground">
                              Requested on {new Date(request.createdAt).toLocaleString()}
                            </div>
                          </div>
                          <div className="flex gap-2">
                            <Button
                              size="sm"
                              className="bg-green-600 hover:bg-green-700"
                              onClick={() => handleApproveRequest(request.id)}
                              disabled={isApproving === request.id}
                            >
                              {isApproving === request.id ? (
                                <>
                                  <Loader2 className="mr-2 h-3 w-3 animate-spin" />
                                  Approving...
                                </>
                              ) : (
                                "Approve"
                              )}
                            </Button>
                            <Button
                              size="sm" 
                              variant="outline"
                              className="text-red-600 border-red-600 hover:bg-red-50"
                              onClick={() => handleRejectRequest(request.id)}
                              disabled={isApproving === request.id}
                            >
                              {isApproving === request.id ? (
                                <>
                                  <Loader2 className="mr-2 h-3 w-3 animate-spin" />
                                  Rejecting...
                                </>
                              ) : (
                                "Reject"
                              )}
                            </Button>
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { getActiveEmployees, getPendingEmployees } from "@/actions/employee.actions";
import { getActiveBranches } from "@/actions/branch.actions";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { EmployeeActionButtons } from "@/components/admin/EmployeeActionButtons";
import { AssignBranchSelect } from "@/components/admin/AssignBranchSelect";
import { EditEmployeeDialog } from "@/components/admin/EditEmployeeDialog";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Users } from "lucide-react";
import { ApprovalButtons } from "@/components/admin/ApprovalButtons";
import { EmployeeStatusSelect } from "@/components/admin/EmployeeStatusSelect";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

export default async function EmployeesPage() {
    const [activeEmployees, pendingEmployees] = await Promise.all([
        getActiveEmployees(),
        getPendingEmployees()
    ]);
    const branches = await getActiveBranches();

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-3xl font-bold tracking-tight">Employee Management</h1>
                <p className="text-muted-foreground">Manage active and pending employees</p>
            </div>

            {/* Pending Employees Section */}
            {pendingEmployees.length > 0 && (
                <Card>
                    <CardHeader>
                        <CardTitle className="text-lg">Pending Approvals ({pendingEmployees.length})</CardTitle>
