                                <div key={employee.id} className="flex items-center justify-between p-3 border rounded-lg bg-yellow-50">
                                    <div className="flex items-center gap-3">
                                        <div>
                                            <p className="font-medium">
                                                {employee.firstName && employee.lastName 
                                                    ? `${employee.firstName} ${employee.lastName}`
                                                    : employee.email
