            {/* Active Employees Section */}
            <Card>
                <CardHeader className="flex flex-row items-center justify-between">
                    <CardTitle className="text-lg">Active Employees ({activeEmployees.length})</CardTitle>
                    <Link href="/admin/archived-employees">
                        <Button variant="outline">View Archived</Button>
                    </Link>
                </CardHeader>
                <CardContent>
                    {activeEmployees.length === 0 ? (
                        <div className="text-center py-8 text-muted-foreground">
                            No active employees found
                        </div>
                    ) : (
                        <div className="space-y-3">
                            {activeEmployees.map((employee) => (
                                <div key={employee.id} className="flex items-center justify-between p-3 border rounded-lg hover:bg-gray-50 transition-colors">
                                    <div className="flex items-center gap-3">
                                        <Link 
                                            href={`/admin/employees/${employee.id}`}
                                            className="flex-1 hover:text-blue-600 transition-colors"
                                        >
                                            <p className="font-medium">
                                                {employee.firstName && employee.lastName 
                                                    ? `${employee.firstName} ${employee.lastName}`
                                                    : employee.email
                                                }
                                            </p>
                                            <p className="text-sm text-muted-foreground">{employee.email}</p>
                                            <div className="flex gap-2 mt-1">
                                                {employee.branch && (
                                                    <Badge variant="outline" className="text-xs">{employee.branch.name}</Badge>
                                                )}
                                                {employee.department && (
                                                    <Badge variant="secondary" className="text-xs">{employee.department.name}</Badge>
                                                )}
                                                {employee.designation && (
                                                    <Badge variant="secondary" className="text-xs">{employee.designation.name}</Badge>
                                                )}
                                                {employee.employeeStatus && (
                                                    <Badge 
                                                        variant={
                                                            employee.employeeStatus === "ACTIVE" ? "default" :
                                                            employee.employeeStatus === "PROBATION" ? "secondary" :
                                                            "destructive"
                                                        }
                                                        className="text-xs"
                                                    >
                                                        {employee.employeeStatus}
                                                    </Badge>
                                                )}
                                            </div>
                                        </Link>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <EmployeeStatusSelect 
                                            employeeId={employee.id} 
                                            currentStatus={employee.employeeStatus} 
                                        />
                                        <EditEmployeeDialog
                                            user={{
                                                id: employee.id,
                                                email: employee.email,
                                                role: employee.role,
                                                branchId: employee.branchId,
                                                departmentId: employee.departmentId,
                                                designationId: employee.designationId,
                                            }}
                                            branches={branches}
                                        />
                                        <Link href={`/admin/employees/${employee.id}`}>
                                            <Button variant="outline" size="sm">View Profile</Button>
                                        </Link>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Calendar, Clock, Play, RotateCcw } from "lucide-react";
import { toast } from "sonner";

export default function LeaveAutomationAdmin() {
    const [isProcessing, setIsProcessing] = useState(false);
    const [backfillDays, setBackfillDays] = useState("7");

    const handleDailyProcess = async () => {
        setIsProcessing(true);
        try {
            const response = await fetch('/api/leave-automation', {
                method: 'POST',
            });
            const result = await response.json();
            
            if (result.success) {
                toast.success(`Daily automation completed. Processed ${result.data.processedEmployees} employees.`);
            } else {
                toast.error(result.error || "Failed to process daily automation");
            }
        } catch (error) {
            console.error("Error:", error);
            toast.error("Failed to process daily automation");
        } finally {
            setIsProcessing(false);
        }
    };

    const handleBackfillProcess = async () => {
        if (!backfillDays || parseInt(backfillDays) <= 0) {
            toast.error("Please enter a valid number of days");
            return;
        }

        setIsProcessing(true);
        try {
            const response = await fetch(`/api/leave-automation?backfill=${backfillDays}`, {
                method: 'POST',
            });
            const result = await response.json();
            
            if (result.success) {
                toast.success(`Backfill automation completed. Processed ${result.data.processedDates} dates.`);
            } else {
                toast.error(result.error || "Failed to process backfill automation");
            }
        } catch (error) {
            console.error("Error:", error);
            toast.error("Failed to process backfill automation");
        } finally {
            setIsProcessing(false);
        }
    };

    return (
        <div className="max-w-4xl mx-auto space-y-6">
            <div>
                <h1 className="text-3xl font-bold tracking-tight">Leave Automation Management</h1>
                <p className="text-muted-foreground">Manage automatic leave processing and weekly off day settings</p>
            </div>

            {/* System Status */}
            <Card>
                <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                        <Clock className="h-5 w-5" />
                        Automation Schedule
                    </CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="grid gap-4 md:grid-cols-2">
                        <div className="flex items-center justify-between p-4 border rounded-lg">
                            <div>
                                <p className="font-medium">Daily Processing</p>
                                <p className="text-sm text-muted-foreground">Runs every day at 22:00 (10 PM)</p>
                            </div>
                            <Badge variant="default">Active</Badge>
                        </div>
                        <div className="flex items-center justify-between p-4 border rounded-lg">
                            <div>
                                <p className="font-medium">Auto Leave Deduction</p>
                                <p className="text-sm text-muted-foreground">For "Roster Every Year" leave types only</p>
                            </div>
                            <Badge variant="default">Enabled</Badge>
                        </div>
                    </div>
                </CardContent>
            </Card>

            {/* Manual Controls */}
            <div className="grid gap-6 md:grid-cols-2">
                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <Play className="h-5 w-5" />
                            Manual Daily Process
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <p className="text-sm text-muted-foreground">
                            Manually trigger the daily leave automation process for yesterday's records.
                        </p>
                        <Button 
                            onClick={handleDailyProcess}
                            disabled={isProcessing}
                            className="w-full"
                        >
                            {isProcessing ? "Processing..." : "Process Yesterday"}
                        </Button>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <RotateCcw className="h-5 w-5" />
                            Backfill Processing
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <p className="text-sm text-muted-foreground">
                            Process past dates that haven't been processed yet.
                        </p>
                        <div className="grid gap-2">
                            <Label htmlFor="backfillDays">Number of days to backfill</Label>
                            <Input
                                id="backfillDays"
                                type="number"
                                min="1"
                                max="365"
                                value={backfillDays}
                                onChange={(e) => setBackfillDays(e.target.value)}
                                placeholder="Enter number of days"
                            />
                        </div>
                        <Button 
                            onClick={handleBackfillProcess}
                            disabled={isProcessing}
                            variant="outline"
                            className="w-full"
                        >
                            {isProcessing ? "Processing..." : "Start Backfill"}
                        </Button>
                    </CardContent>
                </Card>
            </div>

            {/* Information Cards */}
            <div className="grid gap-6 md:grid-cols-3">
                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2 text-green-600">
                            <Calendar className="h-5 w-5" />
                            Weekly Off Days
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <p className="text-sm text-muted-foreground">
                            System automatically sets required and actual times to 0 for weekly off days based on branch settings.
                        </p>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2 text-orange-600">
                            <Calendar className="h-5 w-5" />
                            Auto Leave Deduction
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <p className="text-sm text-muted-foreground">
                            Automatically deducts from "Roster Every Year" leave types when employee is absent and has available balance.
                        </p>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2 text-red-600">
                            <Calendar className="h-5 w-5" />
                            No Leave Balance
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <p className="text-sm text-muted-foreground">
                            When no leaves available, sets required times as per branch settings and actual times to 0.
                        </p>
                    </CardContent>
                </Card>
            </div>
        </div>
    );
}

import { getAllLeaveTypes } from "@/actions/leave.actions";
import { getActiveBranches } from "@/actions/branch.actions";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { AddLeaveTypeDialog } from "@/components/admin/AddLeaveTypeDialog";
import { EditLeaveTypeDialog } from "@/components/admin/EditLeaveTypeDialog";
import { LeaveTypeToggle } from "@/components/admin/LeaveTypeToggle";
import { CalendarDays } from "lucide-react";

export default async function AdminLeaveTypesPage() {
    const [leaveTypes, branches] = await Promise.all([
        getAllLeaveTypes(),
        getActiveBranches()
    ]);

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Leave Types</h1>
                    <p className="text-muted-foreground">Manage different types of leaves and their allocations</p>
                </div>
                <AddLeaveTypeDialog branches={branches} />
            </div>

            <Card>
                <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                        <CalendarDays className="h-5 w-5" />
                        All Leave Types ({leaveTypes.length})
                    </CardTitle>
                </CardHeader>
                <CardContent>
                    {leaveTypes.length === 0 ? (
                        <div className="text-center py-8 text-muted-foreground">
                            <CalendarDays className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
                            <p>No leave types found</p>
                            <p className="text-sm">Add your first leave type to get started</p>
                        </div>
                    ) : (
                        <div className="overflow-x-auto">
                            <Table>
                                <TableHeader>
                                    <TableRow>
                                        <TableHead>Leave Type</TableHead>
                                        <TableHead>Days per Year</TableHead>
                                        <TableHead>Requires Approval</TableHead>
                                        <TableHead>Applicable Branches</TableHead>
                                        <TableHead>Status</TableHead>
                                        <TableHead className="text-right">Actions</TableHead>
                                    </TableRow>
                                </TableHeader>
                                <TableBody>
                                    {leaveTypes.map((leaveType) => {
                                        const applicableBranchIds = JSON.parse(leaveType.applicableBranches || '[]');
                                        const applicableBranches = branches.filter(branch => 
                                            applicableBranchIds.includes(branch.id)
                                        );

                                        return (
                                            <TableRow key={leaveType.id}>
                                                <TableCell>
                                                    <div className="font-medium">{leaveType.name}</div>
                                                </TableCell>
                                                <TableCell>
                                                    <div className="font-semibold text-blue-600">
                                                        {leaveType.allocatedDays} days
                                                    </div>
                                                </TableCell>
                                                <TableCell>
                                                    <Badge 
                                                        variant={leaveType.requiresApproval ? "destructive" : "secondary"}
                                                    >
                                                        {leaveType.requiresApproval ? "Yes" : "No"}
                                                    </Badge>
                                                </TableCell>
                                                <TableCell>
                                                    <div className="flex flex-wrap gap-1">
                                                        {applicableBranches.length === 0 ? (
                                                            <Badge variant="outline" className="text-xs">None</Badge>
                                                        ) : applicableBranches.length === branches.length ? (
                                                            <Badge variant="outline" className="text-xs">All Branches</Badge>
                                                        ) : (
                                                            applicableBranches.slice(0, 2).map(branch => (
                                                                <Badge key={branch.id} variant="outline" className="text-xs">
                                                                    {branch.name}
                                                                </Badge>
                                                            ))
                                                        )}
                                                        {applicableBranches.length > 2 && (
                                                            <Badge variant="outline" className="text-xs">
                                                                +{applicableBranches.length - 2} more
                                                            </Badge>
                                                        )}
                                                    </div>
                                                </TableCell>
                                                <TableCell>
                                                    <LeaveTypeToggle 
                                                        leaveTypeId={leaveType.id} 
                                                        isActive={leaveType.isActive} 
                                                    />
                                                </TableCell>
                                                <TableCell className="text-right">
                                                    <EditLeaveTypeDialog 
                                                        leaveType={leaveType} 
                                                        branches={branches}
                                                    />
                                                </TableCell>
                                            </TableRow>
                                        );
                                    })}
                                </TableBody>
                            </Table>
                        </div>
                    )}
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { getAllLoansWithManagerInfo } from "@/actions/manager-verification.actions";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { ApproveLoanDialog } from "@/components/admin/ApproveLoanDialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { RefreshCw } from "lucide-react";
import { ProcessEMIButton } from "@/components/admin/loans/ProcessEMIButton";
import { EmiManageDialog } from "@/components/admin/EmiManageDialog";

interface Loan {
    id: string;
    issuedAmount: number;
    remainingPrincipal: number;
    totalMonths: number;
    gracePeriodMonths: number;
    emiStartMonth: number | null;
    emiStartYear: number | null;
    reason: string;
    status: string;
    createdAt: Date;
    userId: string;
    declineReason?: string | null;
    adminComments?: string | null; // Temporary field for decline reason
    user: {
        id: string;
        firstName: string;
        lastName: string;
        email: string;
        phoneNumber: string;
        baseSalary: number;
        walletBalance: number;
        dateOfJoining: Date;
        department: { name: string } | null;
        designation: { name: string } | null;
        branch: { name: string } | null;
    };
        managerVerifiedAt?: Date | null;
        managerVerifiedBy?: {
            id: string;
            firstName: string | null;
            lastName: string | null;
        } | null;
        managerComments?: string | null;
        managerRejectionReason?: string | null;
        adminDeclinedReason?: string | null;
    emiState: {
        currentEmi: number;
        carryForward: number;
    } | null;
}

export default function AdminLoansPage() {
    const [allLoans, setAllLoans] = useState<Loan[]>([]);
    const [loading, setLoading] = useState(true);
    const [refreshing, setRefreshing] = useState(false);

    const loadLoans = async () => {
        try {
            setRefreshing(true);
            const loans = await getAllLoansWithManagerInfo();
            setAllLoans(loans as Loan[]);
        } catch (error) {
            console.error("Failed to load loans:", error);
        } finally {
            setLoading(false);
            setRefreshing(false);
        }
    };

    useEffect(() => {
        loadLoans();
    }, []);

    const handleApprovalSuccess = () => {
        loadLoans();
    };

    const getEmployeeName = (user: any) => {
        return `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email;
    };

    // Helper function to extract decline reason from adminComments (temporary)
    const getDeclineReason = (loan: Loan) => {
        if (loan.declineReason) return loan.declineReason;
        if (loan.adminDeclinedReason) return loan.adminDeclinedReason;
        if (loan.adminComments && loan.adminComments.startsWith('DECLINED:')) {
            return loan.adminComments.replace(/^DECLINED:\s*/, '').replace(/\s*\(Declined by:.*\)$/, '');
        }
        return null;
    };

    // Filter loans for tabs
    const pendingLoans = allLoans.filter(l => l.status === "PENDING");
    const managerVerifiedLoans = allLoans.filter(l => l.status === "MANAGER_VERIFIED");
    const activeLoans = allLoans.filter(l => l.status === "ACTIVE" || l.status === "CLOSED");
    const declinedLoans = allLoans.filter(l => l.status === "DECLINED");

    if (loading) {
        return (
            <div className="container mx-auto py-10 px-4">
                <div className="flex items-center justify-center min-h-100">
                    <div className="text-center">
                        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto"></div>
                        <p className="mt-2 text-sm text-muted-foreground">Loading loans...</p>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="container mx-auto py-10 px-4">
            <div className="flex justify-between items-center mb-8">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Loan Management</h1>
                    <p className="text-muted-foreground mt-1">
                        Review pending requests and monitor active loan portfolios.
                    </p>
                </div>
                <div className="flex items-center gap-2">
                    <Button
                        variant="outline"
                        size="sm"
                        onClick={loadLoans}
                        disabled={refreshing}
                    >
                        <RefreshCw className={`h-4 w-4 mr-2 ${refreshing ? 'animate-spin' : ''}`} />
                        Refresh
                    </Button>
                    <ProcessEMIButton />
                </div>
            </div>

            <Tabs defaultValue="pending" className="space-y-4">
                <TabsList>
                    <TabsTrigger value="pending">Awaiting Manager ({pendingLoans.length})</TabsTrigger>
                    <TabsTrigger value="manager-verified">Manager Verified ({managerVerifiedLoans.length})</TabsTrigger>
                    <TabsTrigger value="active">Active Portfolio ({activeLoans.length})</TabsTrigger>
                    <TabsTrigger value="declined">Declined ({declinedLoans.length})</TabsTrigger>
                </TabsList>

                <TabsContent value="pending">
                    <div className="border rounded-lg bg-card shadow-sm overflow-hidden">
                        <Table>
                            <TableHeader>
                                <TableRow className="bg-muted/50">
                                    <TableHead className="font-semibold">Employee</TableHead>
                                    <TableHead className="font-semibold">Department</TableHead>
                                    <TableHead className="font-semibold text-right">Requested Amount</TableHead>
                                    <TableHead className="font-semibold text-right">Base Salary</TableHead>
                                    <TableHead className="font-semibold text-center">Date Requested</TableHead>
                                    <TableHead className="font-semibold text-right pr-6">Action</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {pendingLoans.length === 0 ? (
                                    <TableRow>
                                        <TableCell colSpan={6} className="h-32 text-center text-muted-foreground">
                                            No pending loan requests found.
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    pendingLoans.map((loan) => (
                                        <TableRow key={loan.id} className="hover:bg-muted/30 transition-colors">
                                            <TableCell className="font-medium">
                                                <div className="flex flex-col">
                                                    <span>{getEmployeeName(loan.user)}</span>
                                                    <span className="text-xs text-muted-foreground">{loan.user.email}</span>
                                                </div>
                                            </TableCell>
                                            <TableCell>
                                                <div className="text-sm">
                                                    <div>{loan.user.department?.name || 'N/A'}</div>
                                                    <div className="text-xs text-muted-foreground">
                                                        {loan.user.designation?.name || 'N/A'}
                                                    </div>
                                                </div>
                                            </TableCell>
                                            <TableCell className="text-right tabular-nums font-medium">
                                                αº│{loan.issuedAmount.toLocaleString("en-BD")}
                                            </TableCell>
                                            <TableCell className="text-right tabular-nums">
                                                αº│{loan.user.baseSalary.toLocaleString("en-BD")}
                                            </TableCell>
                                            <TableCell className="text-center text-muted-foreground text-sm">
                                                {new Date(loan.createdAt).toLocaleDateString('en-US', {
                                                    year: 'numeric',
                                                    month: 'short',
                                                    day: 'numeric'
                                                })}
                                            </TableCell>
                                            <TableCell className="text-right pr-6">
                                                {loan.status === "DECLINED" ? (
                                                    <div className="text-sm text-red-600">
                                                        <div className="font-medium">Declined</div>
                                                        {getDeclineReason(loan) && (
                                                            <div className="text-xs text-muted-foreground mt-1">
                                                                {getDeclineReason(loan)}
                                                            </div>
                                                        )}
                                                    </div>
                                                ) : (
                                                    <Badge variant="secondary" className="text-xs">
                                                        Awaiting manager verification
                                                    </Badge>
                                                )}
                                            </TableCell>
                                        </TableRow>
                                    ))
                                )}
                            </TableBody>
                        </Table>
                    </div>
                </TabsContent>

                <TabsContent value="manager-verified">
                    <div className="border rounded-lg bg-card shadow-sm overflow-hidden">
                        <Table>
                            <TableHeader>
                                <TableRow className="bg-muted/50">
                                    <TableHead className="font-semibold">Employee</TableHead>
                                    <TableHead className="font-semibold">Verified By</TableHead>
                                    <TableHead className="font-semibold text-right">Requested Amount</TableHead>
                                    <TableHead className="font-semibold text-center">Verification Notes</TableHead>
                                    <TableHead className="font-semibold text-center">Date Verified</TableHead>
                                    <TableHead className="font-semibold text-right pr-6">Action</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {managerVerifiedLoans.length === 0 ? (
                                    <TableRow>
                                        <TableCell colSpan={6} className="h-32 text-center text-muted-foreground">
                                            No manager-verified loan requests found.
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    managerVerifiedLoans.map((loan) => (
                                        <TableRow key={loan.id} className="hover:bg-muted/30 transition-colors">
                                            <TableCell className="font-medium">
                                                <div className="flex flex-col">
                                                    <span>{getEmployeeName(loan.user)}</span>
                                                    <span className="text-xs text-muted-foreground">{loan.user.email}</span>
                                                </div>
                                            </TableCell>
                                            <TableCell>
                                                <div className="text-sm">
                                                    <div>{loan.managerVerifiedBy?.firstName} {loan.managerVerifiedBy?.lastName}</div>
                                                </div>
                                            </TableCell>
                                            <TableCell className="text-right tabular-nums font-medium">
                                                αº│{loan.issuedAmount.toLocaleString("en-BD")}
                                            </TableCell>
                                            <TableCell className="text-center text-sm text-muted-foreground max-w-xs truncate">
                                                {loan.managerComments || "No notes"}
                                            </TableCell>
                                            <TableCell className="text-center text-muted-foreground text-sm">
                                                {loan.managerVerifiedAt ? new Date(loan.managerVerifiedAt).toLocaleDateString('en-US', {
                                                    year: 'numeric',
                                                    month: 'short',
                                                    day: 'numeric'
                                                }) : 'N/A'}
                                            </TableCell>
                                            <TableCell className="text-right pr-6">
                                                <ApproveLoanDialog 
                                                    loan={loan as any} 
                                                    onApprovalSuccess={handleApprovalSuccess}
                                                />
                                            </TableCell>
                                        </TableRow>
                                    ))
                                )}
                            </TableBody>
                        </Table>
                    </div>
                </TabsContent>

                <TabsContent value="active">
                    <div className="border rounded-lg bg-card shadow-sm overflow-hidden">
                        <Table>
                            <TableHeader>
                                <TableRow className="bg-muted/50">
                                    <TableHead className="font-semibold">Employee</TableHead>
                                    <TableHead className="font-semibold">Department</TableHead>
                                    <TableHead className="font-semibold text-right">Principal</TableHead>
                                    <TableHead className="font-semibold text-right">Remaining</TableHead>
                                    <TableHead className="font-semibold text-right">Current EMI</TableHead>
                                    <TableHead className="font-semibold text-center">Status</TableHead>
                                    <TableHead className="font-semibold text-right">Actions</TableHead>
