"use client";

import { useState, useEffect } from "react";
import {
  Bell,
  Check,
  X,
  Eye,
  EyeOff,
  Trash2,
  MoreHorizontal,
  Loader2,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Card, CardContent } from "@/components/ui/card";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import type { AdminNotification } from "@prisma/client";
import { NotificationStatus } from "@prisma/client";
import {
  getAllNotifications,
  getUnreadCount,
  deleteNotification,
  markNotificationAsRead,
  markNotificationAsUnread,
  markAllNotificationsAsRead,
  handleNotificationAction,
} from "@/actions/notification.actions";

/* ===============================
   Γ£à Proper Metadata Type
================================ */
type NotificationMetadata = {
  processed?: boolean;
  status?: string;
  action?: "approve" | "decline";
  adminNote?: string;
  processedAt?: string | Date;
};

export default function NotificationsPage() {
  const [unreadCount, setUnreadCount] = useState(0);
  const [notifications, setNotifications] = useState<AdminNotification[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedNotification, setSelectedNotification] =
    useState<AdminNotification | null>(null);
  const [actionLoading, setActionLoading] = useState(false);

  /* ===============================
     Fetch Functions
  ================================ */

  const fetchUnreadCount = async () => {
    const result = await getUnreadCount();
    if (result.success) {
      setUnreadCount(result.count);
    }
  };

  const fetchNotifications = async () => {
    setLoading(true);
    const result = await getAllNotifications(1, 50);
    if (result.success) {
      setNotifications(result.notifications);
      setUnreadCount(
        result.notifications.filter(
          (n) => n.status === NotificationStatus.UNREAD
        ).length
      );
    }
    setLoading(false);
  };

  /* ===============================
     Actions
  ================================ */

  const toggleReadStatus = async (
    notificationId: string,
    currentStatus: NotificationStatus
  ) => {
    const action =
      currentStatus === NotificationStatus.UNREAD
        ? markNotificationAsRead
        : markNotificationAsUnread;

    const result = await action(notificationId);

    if (result.success) {
      await fetchNotifications();
      await fetchUnreadCount();
      toast.success(
        `Marked as ${
          currentStatus === NotificationStatus.UNREAD ? "read" : "unread"
        }`
      );
    } else {
      toast.error("Failed to update notification");
    }
  };

  const markAllAsRead = async () => {
    const result = await markAllNotificationsAsRead();
    if (result.success) {
      await fetchNotifications();
      await fetchUnreadCount();
      toast.success("All notifications marked as read");
    } else {
      toast.error("Failed to mark all notifications as read");
    }
  };

  const handleDelete = async (notificationId: string) => {
    const result = await deleteNotification(notificationId);
    if (result.success) {
      await fetchNotifications();
      await fetchUnreadCount();
      toast.success("Notification deleted");
    } else {
      toast.error("Failed to delete notification");
    }
  };

  const handleAction = async (
    notificationId: string,
    action: "approve" | "decline",
    adminNote: string = ""
  ) => {
    setActionLoading(true);

    const result = await handleNotificationAction(
      notificationId,
      action,
      adminNote
    );

    if (result.success) {
      await fetchNotifications();
      await fetchUnreadCount();
      setSelectedNotification(null);
      toast.success(`Request ${action}d successfully`);
    } else {
      toast.error(result.error || `Failed to ${action} request`);
    }

    setActionLoading(false);
  };

  /* ===============================
     Effects
  ================================ */

  useEffect(() => {
    fetchNotifications();
    fetchUnreadCount();
    const interval = setInterval(fetchUnreadCount, 30000);
    return () => clearInterval(interval);
  }, []);

  /* ===============================
     Helpers
  ================================ */

  const allowsActions = (notification: AdminNotification) => {
    const actionableTypes = [
      "PROFILE_UPDATE_REQUEST",
      "LEAVE_APPLICATION_PENDING",
      "LOAN_APPLICATION_PENDING",
      "WALLET_REQUEST_PENDING",
    ];

    const metadata =
      notification.metadata as NotificationMetadata | null;

    if (!actionableTypes.includes(notification.type as string)) return false;

    if (
      metadata?.processed === true ||
      metadata?.status === "PROCESSED"
    )
      return false;

    return true;
  };

  /* ===============================
     UI
  ================================ */

  return (
    <div className="p-6 max-w-6xl mx-auto">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-4">
          <Bell className="h-8 w-8" />
          <div>
            <h1 className="text-3xl font-bold">Notifications</h1>
            <p className="text-muted-foreground">
              {unreadCount > 0
                ? `${unreadCount} unread notification${
                    unreadCount > 1 ? "s" : ""
                  }`
                : "All caught up!"}
            </p>
          </div>
        </div>

        {unreadCount > 0 && (
          <Button onClick={markAllAsRead} variant="outline" size="sm">
            <Check className="h-4 w-4 mr-2" />
            Mark All as Read
          </Button>
        )}
      </div>

      <div className="space-y-3">
        {notifications.map((notification) => {
          const metadata =
            notification.metadata as NotificationMetadata | null;

          const isProcessed = metadata?.processed === true;

          return (
            <Card
              key={notification.id}
              className={`transition-all ${
                notification.status === NotificationStatus.UNREAD
                  ? "bg-blue-50 border-blue-200"
                  : ""
              } ${isProcessed ? "opacity-75" : ""}`}
            >
              <CardContent className="p-4">
                <div className="flex items-start justify-between gap-3">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <h3 className="font-semibold text-sm truncate">
                        {notification.title}
                      </h3>

                      {notification.status ===
                        NotificationStatus.UNREAD && (
                        <Badge className="bg-blue-100 text-blue-800 text-xs">
                          New
                        </Badge>
                      )}

                      {isProcessed && (
                        <Badge className="text-xs bg-green-50 border-green-200 text-green-700">
                          {metadata?.action === "approve"
                            ? "Approved"
                            : "Declined"}
                        </Badge>
                      )}
                    </div>

                    <p className="text-sm text-muted-foreground mb-2">
                      {notification.message}
                    </p>

                    {metadata?.adminNote && (
                      <p className="text-xs italic bg-gray-50 p-2 rounded">
                        Admin note: {metadata.adminNote}
                      </p>
                    )}

                    <p className="text-xs text-muted-foreground">
                      {new Date(
                        notification.createdAt
                      ).toLocaleString()}

                      {metadata?.processedAt && (
                        <span className="ml-2">
                          ΓÇó Processed:{" "}
                          {new Date(
                            metadata.processedAt
                          ).toLocaleString()}
                        </span>
                      )}
                    </p>
                  </div>

                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" size="sm">
                        <MoreHorizontal className="h-4 w-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <DropdownMenuItem
                        onClick={() =>
                          toggleReadStatus(
                            notification.id,
                            notification.status
                          )
                        }
                      >
                        {notification.status ===
                        NotificationStatus.UNREAD ? (
                          <>
                            <Eye className="mr-2 h-4 w-4" />
                            Mark as read
                          </>
                        ) : (
                          <>
                            <EyeOff className="mr-2 h-4 w-4" />
                            Mark as unread
                          </>
                        )}
                      </DropdownMenuItem>

                      <Separator className="my-1" />

                      <DropdownMenuItem
                        onClick={() =>
                          handleDelete(notification.id)
                        }
                        className="text-red-600"
                      >
                        <Trash2 className="mr-2 h-4 w-4" />
                        Delete
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
}

import { getAdminDashboardData, getAllBranches } from "@/actions/dashboard.actions";
import { EnhancedDashboard } from "@/components/admin/EnhancedDashboard";

export default async function AdminDashboard({
    searchParams
}: {
    searchParams: { branch?: string, from?: string, to?: string }
}) {
    const params = await searchParams;
    
    const branchId = params.branch;
    const fromDate = params.from;
    const toDate = params.to;

    const [data, branches] = await Promise.all([
        getAdminDashboardData(branchId, fromDate, toDate),
        getAllBranches()
    ]);

    return (
        <div className="container mx-auto space-y-6 p-6">
            <EnhancedDashboard 
                initialData={data as any} 
                branches={branches} 
            />
        </div>
    );
}

import { getPayrollAggregation } from "@/actions/payroll.actions";
import { PayrollClient } from "@/components/admin/PayrollClient";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue
} from "@/components/ui/select";
import { PayrollSelectors } from "@/components/admin/PayrollSelectors";

export default async function PayrollPage({
    searchParams
}: {
    searchParams: { month?: string, year?: string }
}) {
    const params = await searchParams;

    // Logic: Starting from Jan 2026.
    const selectedYear = params.year ? parseInt(params.year) : 2026;
    const selectedMonth = params.month ? parseInt(params.month) : 1;

    const payrollData = await getPayrollAggregation(selectedMonth, selectedYear);

    return (
        <div className="container mx-auto space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Payroll Management</h1>
                    <p className="text-muted-foreground text-sm">Review and process organization payroll for future periods.</p>
                </div>
                <PayrollSelectors
                    currentMonth={selectedMonth}
                    currentYear={selectedYear}
                />
            </div>

            <PayrollClient
                initialData={payrollData as any}
                month={selectedMonth}
                year={selectedYear}
            />
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ProfileUpdateRequestsList } from "@/components/admin/ProfileUpdateRequestsList";
import { getPendingProfileUpdateRequests } from "@/actions/profile.actions";
import { Loader2, Bell } from "lucide-react";
import { toast } from "sonner";

export default function ProfileRequestsPage() {
  const [requests, setRequests] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const fetchRequests = async () => {
    setIsLoading(true);
    try {
      const result = await getPendingProfileUpdateRequests();
      if (result.success && result.data) {
        setRequests(result.data);
      } else {
        toast.error(result.error || "Failed to load requests");
      }
    } catch (error) {
      console.error(error);
      toast.error("Failed to load requests");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, []);

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Profile Update Requests</h1>
        <p className="text-muted-foreground">
          Review and approve employee profile update requests
        </p>
      </div>

      <Card className="bg-blue-50 dark:bg-blue-950/20 border-blue-200">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-blue-700 dark:text-blue-400">
            <Bell className="h-5 w-5" />
            Pending Requests
          </CardTitle>
          <CardDescription>
            {isLoading
              ? "Loading..."
              : `${requests.length} pending request${requests.length !== 1 ? "s" : ""}`}
          </CardDescription>
        </CardHeader>
      </Card>

      {isLoading ? (
        <div className="flex items-center justify-center min-h-[400px]">
          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        </div>
      ) : (
        <ProfileUpdateRequestsList requests={requests} onUpdate={fetchRequests} />
      )}
    </div>
  );
}

import { getUserLeaveEntitlements, getUserLeaveApplications } from "@/actions/leave.actions";
import { getDbUser } from "@/actions/user.actions";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ApplyLeaveDialog } from "@/components/employee/ApplyLeaveDialog";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { CalendarDays, Clock, CheckCircle, XCircle, Calendar } from "lucide-react";
import { redirect } from "next/navigation";

export default async function EmployeeLeavePage() {
    const user = await getDbUser();
    
    if (!user) {
        redirect("/sign-in");
    }

    const currentYear = new Date().getFullYear();
    const [entitlements, applications] = await Promise.all([
        getUserLeaveEntitlements(user.id, currentYear),
        getUserLeaveApplications(user.id, currentYear)
    ]);

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">My Leaves</h1>
                    <p className="text-muted-foreground">Track your leave balance and apply for time off</p>
                </div>
                {entitlements.length > 0 && <ApplyLeaveDialog entitlements={entitlements} userId={user.id} />}
            </div>

            {/* Leave Entitlements Summary */}
            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                {entitlements.length === 0 ? (
                    <Card className="col-span-full">
                        <CardContent className="pt-6">
                            <div className="text-center">
                                <CalendarDays className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
                                <p className="text-muted-foreground">No leave types assigned</p>
                                <p className="text-sm text-muted-foreground">
                                    Contact HR to get leave types assigned to your account
                                </p>
                            </div>
                        </CardContent>
                    </Card>
                ) : (
                    entitlements.map((entitlement: any) => {
                        const remainingDays = entitlement.allocatedDays - entitlement.usedDays;
                        const usagePercentage = (entitlement.usedDays / entitlement.allocatedDays) * 100;
                        
                        return (
                            <Card key={entitlement.id} className="hover:shadow-md transition-shadow">
                                <CardHeader className="pb-2">
                                    <CardTitle className="text-lg flex items-center justify-between">
                                        {entitlement.leaveType.name}
                                        <Badge variant={entitlement.leaveType.requiresApproval ? "destructive" : "secondary"}>
                                            {entitlement.leaveType.requiresApproval ? "Approval Required" : "Auto Approve"}
                                        </Badge>
                                    </CardTitle>
                                </CardHeader>
                                <CardContent className="space-y-3">
                                    <div className="flex justify-between items-center">
                                        <span className="text-sm text-muted-foreground">Total Allocated:</span>
                                        <span className="font-semibold">{entitlement.allocatedDays} days</span>
                                    </div>
                                    <div className="flex justify-between items-center">
                                        <span className="text-sm text-muted-foreground">Used:</span>
                                        <span className="font-semibold text-red-600">{entitlement.usedDays} days</span>
                                    </div>
                                    <div className="flex justify-between items-center">
                                        <span className="text-sm text-muted-foreground">Remaining:</span>
                                        <span className={`font-semibold ${remainingDays > 0 ? 'text-green-600' : 'text-red-600'}`}>
                                            {remainingDays} days
                                        </span>
                                    </div>
                                    
                                    {/* Progress Bar */}
                                    <div className="w-full bg-gray-200 rounded-full h-2">
                                        <div 
                                            className={`h-2 rounded-full transition-all duration-300 ${
                                                usagePercentage >= 100 ? 'bg-red-500' :
                                                usagePercentage >= 80 ? 'bg-orange-500' :
                                                'bg-green-500'
                                            }`}
                                            style={{ width: `${Math.min(usagePercentage, 100)}%` }}
                                        />
                                    </div>
                                    <p className="text-xs text-center text-muted-foreground">
                                        {usagePercentage.toFixed(1)}% used
                                    </p>
                                </CardContent>
                            </Card>
                        );
                    })
                )}
            </div>

            {/* Recent Leave Applications */}
            <Card>
                <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                        <Calendar className="h-5 w-5" />
                        Recent Leave Applications
                    </CardTitle>
                </CardHeader>
                <CardContent>
                    {applications.length === 0 ? (
                        <div className="text-center py-8 text-muted-foreground">
                            <Clock className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
                            <p>No leave applications found</p>
                            <p className="text-sm">Your leave applications will appear here</p>
                        </div>
                    ) : (
                        <div className="overflow-x-auto">
                            <Table>
                                <TableHeader>
                                    <TableRow>
                                        <TableHead>Leave Type</TableHead>
                                        <TableHead>Date</TableHead>
                                        <TableHead>Reason</TableHead>
                                        <TableHead>Status</TableHead>
                                        <TableHead>Applied On</TableHead>
                                        <TableHead>Approved By</TableHead>
                                    </TableRow>
                                </TableHeader>
                                <TableBody>
                                    {applications.map((application: any) => (
                                        <TableRow key={application.id}>
                                            <TableCell className="font-medium">
                                                {application.leaveType.name}
                                            </TableCell>
                                            <TableCell>
                                                {new Date(application.leaveDate).toLocaleDateString()}
                                            </TableCell>
                                            <TableCell>
                                                {application.reason || "No reason provided"}
                                            </TableCell>
                                            <TableCell>
                                                <Badge 
                                                    variant={
                                                        application.status === "APPROVED" ? "default" :
                                                        application.status === "REJECTED" ? "destructive" :
                                                        "secondary"
                                                    }
                                                    className="flex items-center gap-1 w-fit"
                                                >
                                                    {application.status === "APPROVED" && <CheckCircle className="h-3 w-3" />}
                                                    {application.status === "REJECTED" && <XCircle className="h-3 w-3" />}
                                                    {application.status === "PENDING" && <Clock className="h-3 w-3" />}
                                                    {application.status}
                                                </Badge>
                                            </TableCell>
                                            <TableCell className="text-muted-foreground">
                                                {new Date(application.createdAt).toLocaleDateString()}
                                            </TableCell>
                                            <TableCell className="text-muted-foreground">
