"use client";

import { useEffect, useState } from "react";
import {
    getMedicalEntitlement,
    submitMedicalClaim,
    getMyMedicalClaims
} from "@/actions/medical.actions";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Textarea } from "@/components/ui/textarea";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import Link from "next/link";
import { History } from "lucide-react";

export default function EmployeeMedicalPage() {
    const [entitlement, setEntitlement] = useState<any>(null);
    const [claims, setClaims] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [formData, setFormData] = useState({
        amount: "",
        description: "",
        attachmentUrl: "",
    });

    const loadData = async () => {
        try {
            const [e, c] = await Promise.all([
                getMedicalEntitlement(),
                getMyMedicalClaims(),
            ]);
            setEntitlement(e);
            setClaims(c);
        } catch (error) {
            console.error("Error loading medical data:", error);
        }
    };

    useEffect(() => {
        loadData();
    }, []);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.amount || !formData.description) {
            toast.error("Please fill in required fields");
            return;
        }

        const amount = Number(formData.amount);
        if (amount > entitlement.remainingBalance) {
            toast.error(`Amount exceeds remaining balance of αº│${entitlement.remainingBalance}`);
            return;
        }

        setLoading(true);
        const res = await submitMedicalClaim({
            amount,
            description: formData.description,
            attachmentUrl: formData.attachmentUrl || undefined,
        });

        if (res.success) {
            toast.success("Claim submitted successfully");
            setFormData({ amount: "", description: "", attachmentUrl: "" });
            loadData();
        } else {
            toast.error(res.error || "Failed to submit claim");
        }
        setLoading(false);
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Medical Reimbursement</h1>
                    <p className="text-muted-foreground">Submit and track your medical claims for the current year.</p>
                </div>
                <Link href="/medical/history">
                    <Button variant="outline">
                        <History className="mr-2 h-4 w-4" />
                        View History
                    </Button>
                </Link>
            </div>

            <div className="grid gap-6 md:grid-cols-3">
                <Card className="md:col-span-1">
                    <CardHeader>
                        <CardTitle>Entitlement Summary</CardTitle>
                        <CardDescription>Current year: {new Date().getFullYear()}</CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-4">
                        <div className="flex justify-between items-center">
                            <span className="text-sm text-muted-foreground">Total Limit:</span>
                            <span className="font-bold">αº│{entitlement?.totalLimit.toLocaleString("en-BD") || "..."}</span>
                        </div>
                        <div className="flex justify-between items-center">
                            <span className="text-sm text-muted-foreground">Remaining:</span>
                            <span className="font-bold text-green-600">αº│{entitlement?.remainingBalance.toLocaleString("en-BD") || "..."}</span>
                        </div>
                        {entitlement && (
                            <div className="w-full bg-secondary h-2 rounded-full overflow-hidden">
                                <div
                                    className="bg-green-500 h-full transition-all duration-500"
                                    style={{ width: `${(entitlement.remainingBalance / entitlement.totalLimit) * 100}%` }}
                                />
                            </div>
                        )}
                    </CardContent>
                </Card>

                <Card className="md:col-span-2">
                    <CardHeader>
                        <CardTitle>New Claim Request</CardTitle>
                    </CardHeader>
                    <CardContent>
                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div className="grid gap-4 md:grid-cols-2">
                                <div className="space-y-2">
                                    <Label htmlFor="amount">Amount (αº│)</Label>
                                    <Input
                                        id="amount"
                                        type="number"
                                        placeholder="Enter amount"
                                        value={formData.amount}
                                        onChange={(e) => setFormData({ ...formData, amount: e.target.value })}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <Label htmlFor="attachment">Attachment URL (Optional)</Label>
                                    <Input
                                        id="attachment"
                                        placeholder="https://link-to-receipt.com"
                                        value={formData.attachmentUrl}
                                        onChange={(e) => setFormData({ ...formData, attachmentUrl: e.target.value })}
                                    />
                                </div>
                            </div>
                            <div className="space-y-2">
                                <Label htmlFor="description">Description</Label>
                                <Textarea
                                    id="description"
                                    placeholder="Describe the nature of the claim (e.g. Consultation fee, Medicine...)"
                                    className="min-h-[100px]"
                                    value={formData.description}
                                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                />
                            </div>
                            <Button type="submit" disabled={loading} className="w-full md:w-auto">
                                {loading ? "Submitting..." : "Submit Claim"}
                            </Button>
                        </form>
                    </CardContent>
                </Card>
            </div>

            <Card>
                <CardHeader>
                    <CardTitle>Claim History</CardTitle>
                </CardHeader>
                <CardContent>
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead>Date</TableHead>
                                <TableHead>Description</TableHead>
                                <TableHead className="text-right">Amount</TableHead>
                                <TableHead className="text-center">Status</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {claims.length === 0 ? (
                                <TableRow>
                                    <TableCell colSpan={4} className="h-24 text-center text-muted-foreground">
                                        No claims found.
                                    </TableCell>
                                </TableRow>
                            ) : (
                                claims.map((claim) => (
                                    <TableRow key={claim.id}>
                                        <TableCell className="text-sm">
                                            {new Date(claim.createdAt).toLocaleDateString()}
                                        </TableCell>
                                        <TableCell className="max-w-[300px] truncate">
                                            {claim.description}
                                        </TableCell>
                                        <TableCell className="text-right tabular-nums">
                                            αº│{claim.amount.toLocaleString("en-BD")}
                                        </TableCell>
                                        <TableCell className="text-center">
                                            <Badge
                                                variant={
                                                    claim.status === "APPROVED" ? "default" :
                                                        claim.status === "PENDING" ? "secondary" :
                                                            claim.status === "PAID" ? "outline" : "destructive"
                                                }
                                                className={
                                                    claim.status === "APPROVED" ? "bg-green-100 text-green-800 hover:bg-green-100 border-green-200" :
                                                        claim.status === "PENDING" ? "bg-yellow-100 text-yellow-800 hover:bg-yellow-100 border-yellow-200" : ""
                                                }
                                            >
                                                {claim.status}
                                            </Badge>
                                        </TableCell>
                                    </TableRow>
                                ))
                            )}
                        </TableBody>
                    </Table>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ProfileView } from "@/components/employee/ProfileView";
import { ProfileEditFormTabbed as ProfileEditForm } from "@/components/employee/ProfileEditFormTabbed";
import { NotificationPanel } from "@/components/employee/NotificationPanel";
import { getCurrentUserProfile, getMyProfileUpdateRequests } from "@/actions/profile.actions";
import { User } from "@prisma/client";
import { Loader2, Clock, CheckCircle, XCircle } from "lucide-react";
import { format } from "date-fns";
import { toast } from "sonner";

type UserWithBranch = User & {
  branch?: {
    id: string;
    name: string;
    location: string;
  } | null;
  department?: {
    id: string;
    name: string;
  } | null;
  designation?: {
    id: string;
    name: string;
  } | null;
};

export default function ProfilePage() {
  const [user, setUser] = useState<UserWithBranch | null>(null);
  const [updateRequests, setUpdateRequests] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("view");

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [userResult, requestsResult] = await Promise.all([
        getCurrentUserProfile(),
        getMyProfileUpdateRequests(),
      ]);

      if (userResult.success && userResult.data) {
        setUser(userResult.data as UserWithBranch);
      } else {
        toast.error(userResult.error || "Failed to load profile");
      }

      if (requestsResult.success && requestsResult.data) {
        setUpdateRequests(requestsResult.data);
      }
    } catch (error) {
      console.error(error);
      toast.error("Failed to load data");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!user) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <p className="text-muted-foreground">Failed to load profile</p>
      </div>
    );
  }

  const pendingRequests = updateRequests.filter((r) => r.status === "PENDING");

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">My Profile</h1>
        <p className="text-muted-foreground">View and manage your personal information</p>
      </div>

      {pendingRequests.length > 0 && (
        <Card className="border-orange-200 bg-orange-50 dark:bg-orange-950/20">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-orange-700 dark:text-orange-400">
              <Clock className="h-5 w-5" />
              Pending Update Request
            </CardTitle>
            <CardDescription>
              You have {pendingRequests.length} pending profile update request(s) awaiting admin approval
            </CardDescription>
          </CardHeader>
        </Card>
      )}

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="view">View Profile</TabsTrigger>
          <TabsTrigger value="edit">Edit Profile</TabsTrigger>
          <TabsTrigger value="notifications">Notifications</TabsTrigger>
          <TabsTrigger value="requests">
            Update History
            {pendingRequests.length > 0 && (
              <Badge variant="secondary" className="ml-2">
                {pendingRequests.length}
              </Badge>
            )}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="view" className="space-y-6 mt-6">
          <ProfileView
            user={user}
            canEdit={true}
            onEdit={() => setActiveTab("edit")}
          />
        </TabsContent>

        <TabsContent value="edit" className="mt-6">
          <ProfileEditForm
            user={user}
            isAdmin={false}
            onSuccess={() => {
              setActiveTab("view");
              fetchData();
            }}
            onCancel={() => setActiveTab("view")}
          />
        </TabsContent>
        <TabsContent value="notifications" className="mt-6">
          <NotificationPanel userId={user.id} />
        </TabsContent>
        <TabsContent value="requests" className="mt-6">
          <div className="space-y-4">
            {updateRequests.length === 0 ? (
              <Card>
                <CardContent className="py-10">
                  <div className="text-center text-muted-foreground">
                    <Clock className="h-12 w-12 mx-auto mb-4 opacity-50" />
                    <p>No profile update requests yet</p>
                  </div>
                </CardContent>
              </Card>
            ) : (
              updateRequests.map((request) => (
                <Card key={request.id}>
                  <CardHeader>
                    <div className="flex items-center justify-between">
                      <CardTitle className="text-lg">
                        Profile Update Request
                      </CardTitle>
                      <Badge
                        variant={
                          request.status === "APPROVED"
                            ? "default"
                            : request.status === "PENDING"
                            ? "secondary"
                            : "destructive"
                        }
                      >
                        {request.status === "APPROVED" && (
                          <CheckCircle className="h-3 w-3 mr-1" />
                        )}
                        {request.status === "REJECTED" && (
                          <XCircle className="h-3 w-3 mr-1" />
                        )}
                        {request.status === "PENDING" && (
                          <Clock className="h-3 w-3 mr-1" />
                        )}
                        {request.status}
                      </Badge>
                    </div>
                    <CardDescription>
                      Submitted on {format(new Date(request.createdAt), "PPP 'at' p")}
                      {request.reviewedAt && (
                        <> ΓÇó Reviewed on {format(new Date(request.reviewedAt), "PPP 'at' p")}</>
                      )}
                    </CardDescription>
                  </CardHeader>
                  {request.reviewNotes && (
                    <CardContent>
                      <div className="rounded-lg bg-muted p-4">
                        <p className="text-sm font-semibold mb-1">Admin Notes:</p>
                        <p className="text-sm text-muted-foreground">{request.reviewNotes}</p>
                      </div>
                    </CardContent>
                  )}
                </Card>
              ))
            )}
          </div>
        </TabsContent>
      </Tabs>
    </div>
  );
}

