                                onValueChange={(value: ValueType) =>
                                    setFormData({ ...formData, type: value })
                                }
                            >
                                <SelectTrigger>
                                    <SelectValue placeholder="Select type" />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="FIXED">Fixed Amount</SelectItem>
                                    <SelectItem value="PERCENTAGE">Percentage of Salary</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                        <div className="grid gap-2">
                            <Label htmlFor="value">Value</Label>
                            <Input
                                id="value"
                                type="number"
                                placeholder="e.g. 5000"
                                value={formData.value}
                                onChange={(e) =>
                                    setFormData({ ...formData, value: Number(e.target.value) })
                                }
                            />
                        </div>
                    </div>

                    <div className="space-y-3">
                        <Label>Target Branches</Label>
                        <p className="text-[10px] text-muted-foreground uppercase tracking-wider">
                            If none selected, it applies to ALL branches.
                        </p>
                        <div className="grid grid-cols-2 gap-3 border rounded-lg p-4 bg-muted/30">
                            {branches.map((branch) => (
                                <div key={branch.id} className="flex items-center space-x-2">
                                    <Checkbox
                                        id={`bonus-branch-${branch.id}`}
                                        checked={formData.branchIds.includes(branch.id)}
                                        onCheckedChange={() => toggleBranch(branch.id)}
                                    />
                                    <label
                                        htmlFor={`bonus-branch-${branch.id}`}
                                        className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
                                    >
                                        {branch.name}
                                    </label>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
                <DialogFooter>
                    <Button variant="outline" onClick={() => setIsOpen(false)}>
                        Cancel
                    </Button>
                    <Button onClick={handleSubmit} disabled={loading}>
                        {loading ? "Creating..." : "Create Bonus"}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState } from "react";
import { createLeaveType } from "@/actions/leave.actions";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Plus } from "lucide-react";

interface Branch {
    id: string;
    name: string;
}

interface AddLeaveTypeDialogProps {
    branches: Branch[];
}

export function AddLeaveTypeDialog({ branches }: AddLeaveTypeDialogProps) {
    const [isOpen, setIsOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [formData, setFormData] = useState({
        name: "",
        allocatedDays: "",
        requiresApproval: true,
        leaveResetPolicy: "ROSTER_EVERY_YEAR",
        selectedBranches: [] as string[]
    });

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        
        if (!formData.name.trim()) {
            toast.error("Leave type name is required");
            return;
        }
        
        if (!formData.allocatedDays || parseInt(formData.allocatedDays) <= 0) {
            toast.error("Please enter a valid number of days");
            return;
        }

        setLoading(true);
        
        try {
            const result = await createLeaveType({
                name: formData.name.trim(),
                allocatedDays: parseInt(formData.allocatedDays),
                requiresApproval: formData.requiresApproval,
                leaveResetPolicy: formData.leaveResetPolicy as "ROSTER_EVERY_YEAR" | "FIXED",
                applicableBranches: formData.selectedBranches
            });
            
            if (result.success) {
                toast.success("Leave type created successfully");
                setIsOpen(false);
                setFormData({
                    name: "",
                    allocatedDays: "",
                    requiresApproval: true,
                    leaveResetPolicy: "ROSTER_EVERY_YEAR",
                    selectedBranches: []
                });
            } else {
                toast.error(result.error || "Failed to create leave type");
            }
        } catch {
            toast.error("An error occurred while creating leave type");
        } finally {
            setLoading(false);
        }
    };

    const handleBranchToggle = (branchId: string) => {
        setFormData(prev => ({
            ...prev,
            selectedBranches: prev.selectedBranches.includes(branchId)
                ? prev.selectedBranches.filter(id => id !== branchId)
                : [...prev.selectedBranches, branchId]
        }));
    };

    const selectAllBranches = () => {
        setFormData(prev => ({
            ...prev,
            selectedBranches: branches.map(branch => branch.id)
        }));
    };

    const clearAllBranches = () => {
        setFormData(prev => ({
            ...prev,
            selectedBranches: []
        }));
    };

    return (
        <Dialog open={isOpen} onOpenChange={setIsOpen}>
            <DialogTrigger asChild>
                <Button>
                    <Plus className="mr-2 h-4 w-4" />
                    Add Leave Type
                </Button>
            </DialogTrigger>
            <DialogContent className="sm:max-w-150">
                <DialogHeader>
                    <DialogTitle>Add New Leave Type</DialogTitle>
                </DialogHeader>
                
                <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="grid gap-4">
                        <div className="grid gap-2">
                            <Label htmlFor="name">Leave Type Name</Label>
                            <Input
                                id="name"
                                value={formData.name}
                                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                placeholder="e.g., Annual Leave, Sick Leave"
                                required
                            />
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="allocatedDays">Days per Year</Label>
                            <Input
                                id="allocatedDays"
                                type="number"
                                min="1"
                                max="365"
                                value={formData.allocatedDays}
                                onChange={(e) => setFormData({ ...formData, allocatedDays: e.target.value })}
                                placeholder="Enter number of days"
                                required
                            />
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="leaveResetPolicy">Leave Reset Policy</Label>
                            <Select
                                value={formData.leaveResetPolicy}
                                onValueChange={(value) => setFormData({ ...formData, leaveResetPolicy: value })}
                            >
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="ROSTER_EVERY_YEAR">
                                        Reset Every Year (Auto-deduction eligible)
                                    </SelectItem>
                                    <SelectItem value="FIXED">
                                        Fixed Balance (No auto-deduction)
                                    </SelectItem>
                                </SelectContent>
                            </Select>
                            <p className="text-xs text-muted-foreground">
                                "Reset Every Year" leaves will be auto-deducted for absences. "Fixed" leaves will not be auto-deducted.
                            </p>
                        </div>

                        <div className="flex items-center space-x-2">
                            <Checkbox
                                id="requiresApproval"
                                checked={formData.requiresApproval}
                                onCheckedChange={(checked) => 
                                    setFormData({ ...formData, requiresApproval: !!checked })
                                }
                            />
                            <Label htmlFor="requiresApproval" className="text-sm">
                                Requires admin approval
                            </Label>
                        </div>

                        <div className="grid gap-2">
                            <Label>Applicable Branches</Label>
                            <div className="flex gap-2 mb-2">
                                <Button 
                                    type="button" 
                                    variant="outline" 
                                    size="sm" 
                                    onClick={selectAllBranches}
                                >
                                    Select All
                                </Button>
                                <Button 
                                    type="button" 
                                    variant="outline" 
                                    size="sm" 
                                    onClick={clearAllBranches}
                                >
                                    Clear All
                                </Button>
                            </div>
                            <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto border rounded p-2">
                                {branches.map((branch) => (
                                    <div key={branch.id} className="flex items-center space-x-2">
                                        <Checkbox
                                            id={`branch-${branch.id}`}
                                            checked={formData.selectedBranches.includes(branch.id)}
                                            onCheckedChange={() => handleBranchToggle(branch.id)}
                                        />
                                        <Label htmlFor={`branch-${branch.id}`} className="text-sm">
                                            {branch.name}
                                        </Label>
                                    </div>
                                ))}
                            </div>
                            <p className="text-xs text-muted-foreground">
                                Select which branches can use this leave type. Leave empty for no restrictions.
                            </p>
                        </div>
                    </div>

                    <div className="flex justify-end gap-2">
                        <Button 
                            type="button" 
                            variant="outline" 
                            onClick={() => setIsOpen(false)}
                            disabled={loading}
                        >
                            Cancel
                        </Button>
                        <Button type="submit" disabled={loading}>
                            {loading ? "Creating..." : "Create Leave Type"}
                        </Button>
                    </div>
                </form>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState } from "react";
import { toggleAllowanceStatus } from "@/actions/settings.actions";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";

export function AllowanceToggle({
    allowanceId,
    initialStatus
}: {
    allowanceId: string;
    initialStatus: boolean
}) {
    const [isActive, setIsActive] = useState(initialStatus);
    const [loading, setLoading] = useState(false);

    const handleToggle = async (checked: boolean) => {
        setLoading(true);
        try {
            const res = await toggleAllowanceStatus(allowanceId, checked);
            if (res.success) {
                setIsActive(checked);
                toast.success(`Allowance ${checked ? "activated" : "deactivated"} successfully`);
            }
        } catch (error) {
            toast.error("Failed to update status");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex items-center justify-end gap-2">
            <Switch
                checked={isActive}
                onCheckedChange={handleToggle}
                disabled={loading}
            />
        </div>
    );
}

"use client";

import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { approveEmployeeWithDetails, rejectEmployee } from "@/actions/employee.actions";
import { getActiveBranches } from "@/actions/branch.actions";
import { toast } from "sonner";
import { useEffect, useState } from "react";
import { Check, X, Loader2 } from "lucide-react";

interface ApprovalButtonsProps {
    employeeId: string;
}

interface Branch {
    id: string;
    name: string;
}

export function ApprovalButtons({ employeeId }: ApprovalButtonsProps) {
    const [branches, setBranches] = useState<Branch[]>([]);
    const [branchId, setBranchId] = useState<string>("");
    const [baseSalary, setBaseSalary] = useState<string>("");
    const [open, setOpen] = useState(false);
    const [approving, setApproving] = useState(false);
    const [rejecting, setRejecting] = useState(false);

    useEffect(() => {
        const loadBranches = async () => {
            const data = await getActiveBranches();
            setBranches(data);
        };
        loadBranches();
    }, []);

    const handleApprove = async () => {
        if (!branchId) {
            toast.error("Please select a branch");
            return;
        }
        if (!baseSalary || Number(baseSalary) <= 0) {
            toast.error("Please enter a valid base salary");
            return;
        }

        setApproving(true);
        try {
            const result = await approveEmployeeWithDetails(employeeId, branchId, Number(baseSalary));
            if (result.success) {
                toast.success("Employee approved successfully");
                setOpen(false);
                setBranchId("");
                setBaseSalary("");
            } else {
                toast.error(result.error || "Failed to approve employee");
            }
        } catch (error) {
            toast.error("Failed to approve employee");
        } finally {
            setApproving(false);
        }
    };

    const handleReject = async () => {
        if (!confirm("Are you sure you want to reject this employee? This action cannot be undone.")) {
            return;
        }

        setRejecting(true);
        try {
            const result = await rejectEmployee(employeeId);
            if (result.success) {
                toast.success("Employee rejected and removed");
            } else {
                toast.error(result.error || "Failed to reject employee");
            }
        } catch (error) {
            toast.error("Failed to reject employee");
        } finally {
            setRejecting(false);
        }
    };

    return (
        <div className="flex gap-2">
            <Dialog open={open} onOpenChange={setOpen}>
                <DialogTrigger asChild>
                    <Button 
                        size="sm" 
                        disabled={rejecting}
                        className="bg-green-600 hover:bg-green-700"
                    >
                        <Check className="h-4 w-4" />
                        Accept
                    </Button>
                </DialogTrigger>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>Approve Employee</DialogTitle>
                    </DialogHeader>
                    <div className="space-y-4">
                        <div className="space-y-2">
                            <Label htmlFor="branch">Branch <span className="text-red-500">*</span></Label>
                            <Select value={branchId} onValueChange={setBranchId}>
                                <SelectTrigger id="branch">
                                    <SelectValue placeholder="Select branch" />
                                </SelectTrigger>
                                <SelectContent>
                                    {branches.map(branch => (
                                        <SelectItem key={branch.id} value={branch.id}>
                                            {branch.name}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>

                        <div className="space-y-2">
                            <Label htmlFor="baseSalary">Base Salary <span className="text-red-500">*</span></Label>
                            <Input
                                id="baseSalary"
                                type="number"
                                min="0"
                                step="0.01"
                                placeholder="Enter base salary"
                                value={baseSalary}
                                onChange={(e) => setBaseSalary(e.target.value)}
                            />
                        </div>

                        <div className="flex justify-end gap-2">
                            <Button 
                                variant="outline" 
                                onClick={() => setOpen(false)}
                                disabled={approving}
                            >
                                Cancel
                            </Button>
                            <Button 
                                onClick={handleApprove} 
                                disabled={approving}
                                className="bg-green-600 hover:bg-green-700"
                            >
                                {approving ? (
                                    <>
                                        <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                        Approving...
                                    </>
                                ) : (
                                    "Approve"
                                )}
                            </Button>
                        </div>
                    </div>
                </DialogContent>
            </Dialog>
            
            <Button 
                size="sm" 
                variant="destructive"
                onClick={handleReject}
                disabled={approving || rejecting}
            >
                {rejecting ? <Loader2 className="h-4 w-4 animate-spin" /> : <X className="h-4 w-4" />}
                Reject
            </Button>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { approveLoan, getLoanDetailsForApproval, declineLoan } from "@/actions/loan.actions";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
    AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { ScrollArea } from "@/components/ui/scroll-area";
import { 
    User, 
    DollarSign, 
    Calendar, 
    Building, 
    Phone, 
    Mail,
    TrendingUp,
    AlertTriangle,
    CheckCircle,
    Clock,
    CreditCard,
    XCircle
} from "lucide-react";
import { format } from "date-fns";

interface LoanDetailsData {
    loan: {
        id: string;
        issuedAmount: number;
        gracePeriodMonths: number;
        totalMonths: number;
        reason: string;
        status: string;
        createdAt: Date;
        user: {
            id: string;
            firstName: string | null;
            lastName: string | null;
            email: string;
            phoneNumber: string | null;
            baseSalary: number;
            walletBalance: number;
            dateOfJoining: Date | null;
            department: { name: string } | null;
            designation: { name: string } | null;
            branch: { name: string } | null;
        };
    };
    existingLoans: any[];
    recentPayments: any[];
    financialMetrics: {
        totalExistingDebt: number;
        totalIssuedAmount: number;
        totalRepaidAmount: number;
        repaymentRatio: number;
        salaryCap: number;
        globalCap: number;
        remainingSalaryCap: number;
        remainingGlobalCap: number;
        maxAllowedLoan: number;
        meetsRepaymentRequirement: boolean;
    };
}

interface ApproveLoanDialogProps {
    loan: {
        id: string;
        issuedAmount: number;
        user: {
            email: string;
        };
    };
    onApprovalSuccess?: () => void;
}

export function ApproveLoanDialog({ loan, onApprovalSuccess }: ApproveLoanDialogProps) {
    const [isOpen, setIsOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [detailsLoading, setDetailsLoading] = useState(false);
    const [loanDetails, setLoanDetails] = useState<LoanDetailsData | null>(null);
    const [isDeclineDialogOpen, setIsDeclineDialogOpen] = useState(false);
    const [declineReason, setDeclineReason] = useState('');
    const [formData, setFormData] = useState({
        issuedAmount: loan.issuedAmount,
        gracePeriodMonths: 6,
        totalMonths: 12,
        adminComments: '',
    });

    // Load detailed loan information when dialog opens
    useEffect(() => {
        if (isOpen && !loanDetails) {
            loadLoanDetails();
        }
    }, [isOpen]);

    const loadLoanDetails = async () => {
        setDetailsLoading(true);
        try {
            const details = await getLoanDetailsForApproval(loan.id);
            setLoanDetails(details);
            
            // Pre-populate form with employee's original request
            setFormData({
                issuedAmount: details.loan.issuedAmount,
                gracePeriodMonths: details.loan.gracePeriodMonths,
                totalMonths: details.loan.totalMonths,
                adminComments: '',
            });
        } catch (error) {
            console.error("Failed to load loan details:", error);
            const errorMessage = error instanceof Error ? error.message : "Failed to load loan details. Please try again.";
            toast.error(errorMessage);
        } finally {
            setDetailsLoading(false);
        }
    };

    const handleApprove = async () => {
        if (!loanDetails) return;
        
        setLoading(true);
        try {
            await approveLoan(loan.id, formData);
            toast.success("Loan approved and initialized successfully");
            setIsOpen(false);
            onApprovalSuccess?.();
        } catch (error) {
            console.error("Failed to approve loan:", error);
            const errorMessage = error instanceof Error ? error.message : "Failed to approve loan. Please try again.";
            toast.error(errorMessage);
        } finally {
            setLoading(false);
        }
    };

    const handleDecline = async () => {
        if (!declineReason.trim()) {
            toast.error("Please provide a reason for declining the loan");
            return;
        }
        
        setLoading(true);
        try {
            await declineLoan(loan.id, declineReason);
            toast.success("Loan declined successfully");
            setIsOpen(false);
            setIsDeclineDialogOpen(false);
            setDeclineReason('');
            onApprovalSuccess?.();
        } catch (error) {
            console.error("Failed to decline loan:", error);
            const errorMessage = error instanceof Error ? error.message : "Failed to decline loan. Please try again.";
            toast.error(errorMessage);
        } finally {
            setLoading(false);
        }
    };

    const getEmployeeName = (user: any) => {
        return `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email;
    };

    const calculateEMI = () => {
        if (formData.totalMonths <= formData.gracePeriodMonths) return 0;
        const emiMonths = formData.totalMonths - formData.gracePeriodMonths;
        return Math.round(formData.issuedAmount / emiMonths);
    };

    const isValidApproval = () => {
        if (!loanDetails) return false;
        
        const { financialMetrics } = loanDetails;
        return formData.issuedAmount <= financialMetrics.maxAllowedLoan &&
               financialMetrics.meetsRepaymentRequirement;
    };

    return (
        <Dialog open={isOpen} onOpenChange={setIsOpen}>
            <DialogTrigger asChild>
                <Button size="sm">Review & Approve</Button>
            </DialogTrigger>
            <DialogContent className="max-w-5xl max-h-[90vh]">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                        <CreditCard className="h-5 w-5" />
                        Loan Approval Review
                    </DialogTitle>
                </DialogHeader>
                
                {detailsLoading ? (
                    <div className="flex items-center justify-center py-8">
                        <div className="text-center">
                            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto"></div>
                            <p className="mt-2 text-sm text-muted-foreground">Loading employee details...</p>
                        </div>
                    </div>
                ) : loanDetails ? (
                    <ScrollArea className="max-h-[calc(90vh-120px)]">
                        <div className="grid gap-6 p-1">
                            {/* Employee Information */}
                            <Card>
                                <CardHeader>
                                    <CardTitle className="flex items-center gap-2">
                                        <User className="h-4 w-4" />
                                        Employee Information
                                    </CardTitle>
                                </CardHeader>
                                <CardContent>
                                    <div className="grid gap-4 md:grid-cols-2">
                                        <div className="space-y-3">
                                            <div className="flex items-center gap-2">
                                                <User className="h-4 w-4 text-muted-foreground" />
                                                <span className="font-medium">{getEmployeeName(loanDetails.loan.user)}</span>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <Mail className="h-4 w-4 text-muted-foreground" />
                                                <span className="text-sm">{loanDetails.loan.user.email}</span>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <Phone className="h-4 w-4 text-muted-foreground" />
                                                <span className="text-sm">{loanDetails.loan.user.phoneNumber || 'N/A'}</span>
                                            </div>
                                        </div>
                                        <div className="space-y-3">
                                            <div className="flex items-center gap-2">
                                                <Building className="h-4 w-4 text-muted-foreground" />
                                                <span className="text-sm">{loanDetails.loan.user.department?.name || 'N/A'} - {loanDetails.loan.user.designation?.name || 'N/A'}</span>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <Calendar className="h-4 w-4 text-muted-foreground" />
                                                <span className="text-sm">
                                                    Joined: {loanDetails.loan.user.dateOfJoining 
                                                        ? format(new Date(loanDetails.loan.user.dateOfJoining), 'MMM dd, yyyy') 
                                                        : 'Not set'
                                                    }
                                                </span>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <DollarSign className="h-4 w-4 text-muted-foreground" />
                                                <span className="text-sm">Branch: {loanDetails.loan.user.branch?.name || 'N/A'}</span>
                                            </div>
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>

                            <div className="grid gap-6 md:grid-cols-2">
                                {/* Employee's Original Request */}
                                <Card>
                                    <CardHeader>
                                        <CardTitle className="flex items-center gap-2">
                                            <Clock className="h-4 w-4" />
                                            Employee's Request
                                        </CardTitle>
                                    </CardHeader>
                                    <CardContent>
                                        <div className="space-y-4">
                                            <div className="grid grid-cols-2 gap-4">
                                                <div>
                                                    <Label className="text-xs text-muted-foreground">Requested Amount</Label>
                                                    <div className="text-lg font-semibold text-primary">
