                                                    Max allowed: αº│{loanDetails.financialMetrics.maxAllowedLoan.toLocaleString('en-BD')}
                                                </div>
                                            </div>
                                            <div className="grid gap-2">
                                                <Label htmlFor="gracePeriodMonths">Grace Period (Months)</Label>
                                                <Input
                                                    id="gracePeriodMonths"
                                                    type="number"
                                                    min="0"
                                                    max="12"
                                                    value={formData.gracePeriodMonths}
                                                    onChange={(e) =>
                                                        setFormData({
                                                            ...formData,
                                                            gracePeriodMonths: Number(e.target.value),
                                                        })
                                                    }
                                                />
                                            </div>
                                            <div className="grid gap-2">
                                                <Label htmlFor="totalMonths">Total Duration (Months)</Label>
                                                <Input
                                                    id="totalMonths"
                                                    type="number"
                                                    min="1"
                                                    max="60"
                                                    value={formData.totalMonths}
                                                    onChange={(e) =>
                                                        setFormData({ ...formData, totalMonths: Number(e.target.value) })
                                                    }
                                                />
                                            </div>
                                            <div className="grid gap-2">
                                                <Label htmlFor="adminComments">Admin Comments (Optional)</Label>
                                                <Input
                                                    id="adminComments"
                                                    placeholder="Add notes about this approval..."
                                                    value={formData.adminComments}
                                                    onChange={(e) =>
                                                        setFormData({ ...formData, adminComments: e.target.value })
                                                    }
                                                />
                                                <div className="text-xs text-muted-foreground">
                                                    Notes visible to other admins for audit purposes
                                                </div>
                                            </div>
                                        </div>
                                        
                                        <div className="space-y-4">
                                            <div className="p-4 bg-muted/50 rounded-lg">
                                                <h4 className="font-medium mb-3">Loan Preview</h4>
                                                <div className="space-y-2 text-sm">
                                                    <div className="flex justify-between">
                                                        <span>Monthly EMI:</span>
                                                        <span className="font-medium">αº│{calculateEMI().toLocaleString('en-BD')}</span>
                                                    </div>
                                                    <div className="flex justify-between">
                                                        <span>Payment starts after:</span>
                                                        <span className="font-medium">{formData.gracePeriodMonths} months</span>
                                                    </div>
                                                    <div className="flex justify-between">
                                                        <span>EMI months:</span>
                                                        <span className="font-medium">{Math.max(0, formData.totalMonths - formData.gracePeriodMonths)}</span>
                                                    </div>
                                                </div>
                                            </div>
                                            
                                            {!isValidApproval() && (
                                                <div className="p-4 bg-red-50 border border-red-200 rounded-lg">
                                                    <div className="flex items-center gap-2 text-red-600">
                                                        <AlertTriangle className="h-4 w-4" />
                                                        <span className="font-medium">Validation Issues</span>
                                                    </div>
                                                    <ul className="mt-2 text-xs text-red-600 list-disc list-inside space-y-1">
                                                        {formData.issuedAmount > loanDetails.financialMetrics.maxAllowedLoan && (
                                                            <li>Amount exceeds maximum allowed limit</li>
                                                        )}
                                                        {!loanDetails.financialMetrics.meetsRepaymentRequirement && (
                                                            <li>Employee hasn't repaid 75% of existing loans</li>
                                                        )}
                                                    </ul>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                    
                                    <div className="flex justify-end gap-3 mt-6">
                                        <Button variant="outline" onClick={() => setIsOpen(false)}>
                                            Cancel
                                        </Button>
                                        <AlertDialog>
                                            <AlertDialogTrigger asChild>
                                                <Button variant="destructive">
                                                    <XCircle className="mr-2 h-4 w-4" />
                                                    Decline Loan
                                                </Button>
                                            </AlertDialogTrigger>
                                            <AlertDialogContent>
                                                <AlertDialogHeader>
                                                    <AlertDialogTitle>Decline Loan Application</AlertDialogTitle>
                                                    <AlertDialogDescription>
                                                        Please provide a reason for declining this loan application. This will be communicated to the employee.
                                                    </AlertDialogDescription>
                                                </AlertDialogHeader>
                                                <div className="grid gap-2 py-4">
                                                    <Label htmlFor="decline-reason">Decline Reason</Label>
                                                    <Textarea
                                                        id="decline-reason"
                                                        placeholder="Enter reason for declining the loan..."
                                                        value={declineReason}
                                                        onChange={(e) => setDeclineReason(e.target.value)}
                                                        rows={4}
                                                    />
                                                </div>
                                                <AlertDialogFooter>
                                                    <AlertDialogCancel onClick={() => setDeclineReason('')}>
                                                        Cancel
                                                    </AlertDialogCancel>
                                                    <AlertDialogAction 
                                                        onClick={handleDecline}
                                                        disabled={loading || !declineReason.trim()}
                                                        className="bg-destructive hover:bg-destructive/90"
                                                    >
                                                        {loading ? "Declining..." : "Decline Loan"}
                                                    </AlertDialogAction>
                                                </AlertDialogFooter>
                                            </AlertDialogContent>
                                        </AlertDialog>
                                        <Button 
                                            onClick={handleApprove} 
                                            disabled={loading || !isValidApproval()}
                                            className="min-w-32"
                                        >
                                            {loading ? "Approving..." : "Approve Loan"}
                                        </Button>
                                    </div>
                                </CardContent>
                            </Card>
                        </div>
                    </ScrollArea>
                ) : (
                    <div className="text-center py-8 text-muted-foreground">
                        Failed to load loan details. Please try again.
                    </div>
                )}
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useEffect } from "react";
import { updateBranch } from "@/actions/branch.actions";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
    DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Edit2, Clock } from "lucide-react";

type Branch = {
    id: string;
    name: string;
    location: string;
    checkInTime: string;
    checkOutTime: string;
    breakDuration: string;
    weeklyOffDays: string[];
    isActive: boolean;
};

interface EditBranchDialogProps {
    branch: Branch;
}

export function EditBranchDialog({ branch }: EditBranchDialogProps) {
    const [isOpen, setIsOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [formData, setFormData] = useState({
        name: "",
        location: "",
        checkInTime: "09:00",
        checkOutTime: "18:00",
        breakDuration: "01:00",
        weeklyOffDays: ["SUNDAY"] as string[]
    });

    const weekDays = [
        { value: "MONDAY", label: "Monday" },
        { value: "TUESDAY", label: "Tuesday" },
        { value: "WEDNESDAY", label: "Wednesday" },
        { value: "THURSDAY", label: "Thursday" },
        { value: "FRIDAY", label: "Friday" },
        { value: "SATURDAY", label: "Saturday" },
        { value: "SUNDAY", label: "Sunday" }
    ];

    // Initialize form with branch data when dialog opens
    useEffect(() => {
        if (isOpen) {
            setFormData({
                name: branch.name,
                location: branch.location,
                checkInTime: branch.checkInTime || "09:00",
                checkOutTime: branch.checkOutTime || "18:00",
                breakDuration: branch.breakDuration || "01:00",
                weeklyOffDays: branch.weeklyOffDays || ["SUNDAY"]
            });
        }
    }, [isOpen, branch]);

    const handleWeeklyOffChange = (day: string, checked: boolean) => {
        if (checked) {
            setFormData({
                ...formData,
                weeklyOffDays: [...formData.weeklyOffDays, day]
            });
        } else {
            setFormData({
                ...formData,
                weeklyOffDays: formData.weeklyOffDays.filter(d => d !== day)
            });
        }
    };

    const handleSubmit = async () => {
        if (!formData.name || !formData.location) {
            toast.error("Please fill in all fields");
            return;
        }

        setLoading(true);
        const res = await updateBranch(branch.id, formData);
        if (res.success) {
            toast.success("Branch updated successfully");
            setIsOpen(false);
        } else {
            toast.error(res.error || "Failed to update branch");
        }
        setLoading(false);
    };

    return (
        <Dialog open={isOpen} onOpenChange={setIsOpen}>
            <DialogTrigger asChild>
                <Button variant="ghost" size="sm">
                    <Edit2 className="h-4 w-4" />
                </Button>
            </DialogTrigger>
            <DialogContent className="sm:max-w-150 max-h-screen overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>Edit Branch</DialogTitle>
                </DialogHeader>
                <div className="space-y-6 py-4">
                    {/* Basic Information */}
                    <Card>
                        <CardHeader className="pb-4">
                            <CardTitle className="text-base">Basic Information</CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <div className="grid gap-2">
                                <Label htmlFor="edit-name">Branch Name</Label>
                                <Input
                                    id="edit-name"
                                    placeholder="e.g. Mumbai HQ"
                                    value={formData.name}
                                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                />
                            </div>
                            <div className="grid gap-2">
                                <Label htmlFor="edit-location">Location</Label>
                                <Input
                                    id="edit-location"
                                    placeholder="e.g. Mumbai, Maharashtra"
                                    value={formData.location}
                                    onChange={(e) => setFormData({ ...formData, location: e.target.value })}
                                />
                            </div>
                        </CardContent>
                    </Card>

                    {/* Timeline Settings */}
                    <Card>
                        <CardHeader className="pb-4">
                            <CardTitle className="text-base flex items-center gap-2">
                                <Clock className="h-4 w-4" />
                                Timeline Settings
                            </CardTitle>
                            <CardDescription>
                                Configure working hours and off days for this branch
                            </CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="grid gap-2">
                                    <Label htmlFor="edit-checkInTime">Check-in Time</Label>
                                    <Input
                                        id="edit-checkInTime"
                                        type="time"
                                        value={formData.checkInTime}
                                        onChange={(e) => setFormData({ ...formData, checkInTime: e.target.value })}
                                    />
                                </div>
                                <div className="grid gap-2">
                                    <Label htmlFor="edit-checkOutTime">Check-out Time</Label>
                                    <Input
                                        id="edit-checkOutTime"
                                        type="time"
                                        value={formData.checkOutTime}
                                        onChange={(e) => setFormData({ ...formData, checkOutTime: e.target.value })}
                                    />
                                </div>
                            </div>
                            
                            <div className="grid gap-2">
                                <Label htmlFor="edit-breakDuration">Break Duration (HH:MM)</Label>
                                <Input
                                    id="edit-breakDuration"
                                    type="time"
                                    value={formData.breakDuration}
                                    onChange={(e) => setFormData({ ...formData, breakDuration: e.target.value })}
                                />
                            </div>

                            <div className="grid gap-3">
                                <Label>Weekly Off Days</Label>
                                <div className="grid grid-cols-2 gap-2">
                                    {weekDays.map((day) => (
                                        <div key={day.value} className="flex items-center space-x-2">
                                            <Checkbox
                                                id={`edit-${day.value}`}
                                                checked={formData.weeklyOffDays.includes(day.value)}
                                                onCheckedChange={(checked) => 
                                                    handleWeeklyOffChange(day.value, checked as boolean)
                                                }
                                            />
                                            <Label
                                                htmlFor={`edit-${day.value}`}
                                                className="text-sm font-normal cursor-pointer"
                                            >
                                                {day.label}
                                            </Label>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                </div>
                <DialogFooter>
                    <Button variant="outline" onClick={() => setIsOpen(false)}>
                        Cancel
                    </Button>
                    <Button onClick={handleSubmit} disabled={loading}>
                        {loading ? "Updating..." : "Update Branch"}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Calendar, Clock, Settings, AlertCircle, CheckCircle2, XCircle, FileText, Info } from "lucide-react";
import { toggleEmiCollection, skipEmiForMonth, recordManualPayment, getLoanActivityHistory } from "@/actions/loan.actions";
import { toast } from "sonner";
import { formatCurrency } from "@/lib/utils";

interface EmiManageDialogProps {
  loan: {
    id: string;
    issuedAmount: number;
    remainingPrincipal: number;
    totalMonths: number;
    gracePeriodMonths: number;
    emiStartMonth: number | null;
    emiStartYear: number | null;
    reason: string;
    adminComments?: string | null | undefined;
    status: string;
    createdAt: Date;
    emiState: {
      currentEmi: number;
      carryForward: number;
    } | null;
    user: {
      firstName: string;
      lastName: string;
    };
  };
}

export function EmiManageDialog({ loan }: EmiManageDialogProps) {
  const [open, setOpen] = useState(false);
  const [skipMonth, setSkipMonth] = useState("");
  const [skipReason, setSkipReason] = useState("");
  const [manualAmount, setManualAmount] = useState("");
  const [manualReason, setManualReason] = useState("");
  const [emiEnabled, setEmiEnabled] = useState(true);
  const [disableReason, setDisableReason] = useState("");
  const [activityHistory, setActivityHistory] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  // Calculate loan timeline information
  const loanStartDate = new Date(loan.createdAt);
  const loanEndDate = new Date(loanStartDate);
  loanEndDate.setMonth(loanEndDate.getMonth() + loan.totalMonths);
  
  const graceEndDate = new Date(loanStartDate);
  graceEndDate.setMonth(graceEndDate.getMonth() + loan.gracePeriodMonths);
  
  const emiStartDate = loan.emiStartMonth && loan.emiStartYear 
    ? new Date(loan.emiStartYear, loan.emiStartMonth - 1, 1)
    : graceEndDate;
  
  const currentDate = new Date();
  const isInGracePeriod = currentDate <= graceEndDate;
  
  // Calculate progress and remaining time
  const monthsPassed = Math.max(0, Math.floor(
    (currentDate.getTime() - loanStartDate.getTime()) / (30.44 * 24 * 60 * 60 * 1000)
  ));
  const remainingMonths = Math.max(0, loan.totalMonths - monthsPassed);
  const progressPercentage = Math.min(100, (monthsPassed / loan.totalMonths) * 100);
  
  // Calculate total paid amount
  const totalPaidAmount = loan.issuedAmount - loan.remainingPrincipal;
  const repaymentPercentage = loan.issuedAmount > 0 ? (totalPaidAmount / loan.issuedAmount) * 100 : 0;

  const handleToggleEmi = async () => {
    if (loading) return;
    
    setLoading(true);
    try {
      await toggleEmiCollection(loan.id, emiEnabled, disableReason);
      toast.success(
        emiEnabled ? "EMI collection enabled" : "EMI collection disabled"
      );
      setOpen(false);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Failed to update EMI");
    } finally {
      setLoading(false);
    }
  };

  const handleSkipEmi = async () => {
    if (!skipMonth || !skipReason || loading) return;
    
    setLoading(true);
    try {
      await skipEmiForMonth(loan.id, skipMonth, skipReason);
      toast.success("EMI skipped successfully");
      setSkipMonth("");
      setSkipReason("");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Failed to skip EMI");
    } finally {
      setLoading(false);
    }
  };

  const handleManualPayment = async () => {
    if (!manualAmount || !manualReason || loading) return;
    
    const amount = parseFloat(manualAmount);
    if (isNaN(amount) || amount <= 0) {
      toast.error("Please enter a valid amount");
      return;
    }
    
    setLoading(true);
    try {
      await recordManualPayment(loan.id, amount, manualReason);
      toast.success("Manual payment recorded successfully");
      setManualAmount("");
      setManualReason("");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Failed to record payment");
    } finally {
      setLoading(false);
    }
  };

  const loadActivityHistory = async () => {
    if (activityHistory) {
      setActivityHistory(null);
      return;
    }
    
    setLoading(true);
    try {
      const history = await getLoanActivityHistory(loan.id);
      setActivityHistory(history);
    } catch (error) {
      toast.error("Failed to load activity history");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm">
          <Settings className="w-4 h-4 mr-2" />
          EMI Controls
        </Button>
      </DialogTrigger>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Settings className="w-5 h-5" />
            EMI Management - {loan.user.firstName} {loan.user.lastName}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-6">
          {/* Loan Timeline & Information */}
          <Card>
            <CardHeader>
              <CardTitle className="text-lg flex items-center gap-2">
                <Info className="w-5 h-5 text-blue-600" />
                Loan Timeline & Details
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-6">
              {/* Basic Loan Info */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">Loan Reason</Label>
                  <p className="font-medium">{loan.reason || "Personal"}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">Total Duration</Label>
                  <p className="font-medium">{loan.totalMonths} months</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">Grace Period</Label>
                  <p className="font-medium">{loan.gracePeriodMonths} months</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">Remaining Months</Label>
                  <p className="font-medium text-blue-600">{remainingMonths} months</p>
                </div>
              </div>
              
              {/* Progress Indicators */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <Label className="text-sm text-muted-foreground">Loan Timeline Progress</Label>
                  <div className="flex items-center gap-2">
                    <div className="flex-1 bg-muted rounded-full h-3">
                      <div 
                        className="bg-blue-600 h-3 rounded-full transition-all" 
                        style={{ width: `${progressPercentage}%` }}
                      />
                    </div>
                    <span className="text-sm font-medium">{Math.round(progressPercentage)}%</span>
                  </div>
                  <p className="text-xs text-muted-foreground">{monthsPassed} of {loan.totalMonths} months elapsed</p>
                </div>
                <div className="space-y-2">
                  <Label className="text-sm text-muted-foreground">Repayment Progress</Label>
                  <div className="flex items-center gap-2">
                    <div className="flex-1 bg-muted rounded-full h-3">
                      <div 
                        className="bg-green-600 h-3 rounded-full transition-all" 
                        style={{ width: `${repaymentPercentage}%` }}
                      />
                    </div>
                    <span className="text-sm font-medium">{Math.round(repaymentPercentage)}%</span>
                  </div>
                  <p className="text-xs text-muted-foreground">{formatCurrency(totalPaidAmount)} of {formatCurrency(loan.issuedAmount)} repaid</p>
                </div>
              </div>
              
              {/* Timeline Dates */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">Loan Start Date</Label>
                  <p className="font-medium">{loanStartDate.toLocaleDateString()}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">EMI Start Date</Label>
                  <div className="flex items-center gap-2">
                    <p className="font-medium">{emiStartDate.toLocaleDateString()}</p>
                    {isInGracePeriod && (
                      <Badge variant="outline" className="text-xs">Grace Period</Badge>
                    )}
                  </div>
                </div>
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">Expected End Date</Label>
                  <p className="font-medium">{loanEndDate.toLocaleDateString()}</p>
                </div>
              </div>
              
              {/* Financial Summary */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-4 bg-muted/50 rounded-lg">
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">Total Loan</Label>
                  <p className="font-semibold text-lg">{formatCurrency(loan.issuedAmount)}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">Total Paid</Label>
                  <p className="font-semibold text-lg text-green-600">{formatCurrency(totalPaidAmount)}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">Remaining</Label>
                  <p className="font-semibold text-lg text-blue-600">{formatCurrency(loan.remainingPrincipal)}</p>
                </div>
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">Current EMI</Label>
                  <p className="font-semibold text-lg">{formatCurrency(loan.emiState?.currentEmi || 0)}</p>
                </div>
              </div>
              
              {/* Admin Comments */}
              {loan.adminComments && (
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">Admin Comments</Label>
                  <p className="text-sm p-3 bg-muted rounded-lg">{loan.adminComments}</p>
                </div>
              )}
              
              {/* Grace Period Status */}
              {isInGracePeriod && (
                <div className="flex items-center gap-2 p-3 bg-blue-50 border border-blue-200 rounded-lg">
                  <AlertCircle className="w-4 h-4 text-blue-600" />
                  <span className="text-sm text-blue-800">
                    This loan is currently in grace period. EMI deductions will start on {emiStartDate.toLocaleDateString()}
                  </span>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Current EMI Status */}
          <Card>
            <CardHeader>
              <CardTitle className="text-lg flex items-center gap-2">
                <CheckCircle2 className="w-5 h-5 text-green-600" />
                EMI Status & Controls
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">Carry Forward Amount</Label>
                  <p className="font-medium text-red-600">{formatCurrency(loan.emiState?.carryForward || 0)}</p>
                  {(loan.emiState?.carryForward || 0) > 0 && (
                    <p className="text-xs text-red-500">Will be added to next EMI deduction</p>
                  )}
                </div>
                <div className="space-y-1">
                  <Label className="text-sm text-muted-foreground">Loan Status</Label>
                  <Badge variant={loan.status === "ACTIVE" ? "default" : "secondary"} className="w-fit">
                    {loan.status}
                  </Badge>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* EMI Controls */}
          <div className="grid md:grid-cols-2 gap-6">
            {/* Toggle EMI Collection */}
            <Card>
              <CardHeader>
                <CardTitle className="text-lg flex items-center gap-2">
                  <AlertCircle className="w-5 h-5 text-orange-500" />
                  EMI Collection Control
                </CardTitle>
                <CardDescription>
                  Enable or disable EMI collection for this loan
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex items-center space-x-2">
                  <Switch
                    id="emi-toggle"
                    checked={emiEnabled}
                    onCheckedChange={setEmiEnabled}
                  />
                  <Label htmlFor="emi-toggle">
                    {emiEnabled ? "Enable EMI Collection" : "Disable EMI Collection"}
                  </Label>
                </div>
                {!emiEnabled && (
                  <div className="space-y-2">
                    <Label htmlFor="disable-reason">Reason for disabling</Label>
                    <Input
                      id="disable-reason"
                      placeholder="Enter reason..."
                      value={disableReason}
                      onChange={(e) => setDisableReason(e.target.value)}
                    />
                  </div>
                )}
                <Button 
                  onClick={handleToggleEmi} 
                  disabled={loading || (!emiEnabled && !disableReason)}
                  className="w-full"
                >
                  {loading ? "Processing..." : (emiEnabled ? "Enable EMI" : "Disable EMI")}
                </Button>
              </CardContent>
            </Card>

            {/* Skip EMI for Specific Month */}
            <Card>
              <CardHeader>
                <CardTitle className="text-lg flex items-center gap-2">
                  <Calendar className="w-5 h-5 text-blue-500" />
                  Skip EMI for Month
                </CardTitle>
                <CardDescription>
                  Skip EMI collection for a specific month
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="skip-month">Month (YYYY-MM)</Label>
                  <Input
                    id="skip-month"
                    placeholder="e.g., 2024-12"
                    value={skipMonth}
                    onChange={(e) => setSkipMonth(e.target.value)}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="skip-reason">Reason</Label>
                  <Textarea
                    id="skip-reason"
                    placeholder="Enter reason for skipping EMI..."
                    value={skipReason}
                    onChange={(e) => setSkipReason(e.target.value)}
                    rows={3}
                  />
                </div>
                <Button 
                  onClick={handleSkipEmi}
                  disabled={loading || !skipMonth || !skipReason}
                  className="w-full"
                >
                  {loading ? "Processing..." : "Skip EMI"}
                </Button>
              </CardContent>
            </Card>
          </div>

          {/* Manual Payment Recording */}
          <Card>
            <CardHeader>
              <CardTitle className="text-lg flex items-center gap-2">
                <Clock className="w-5 h-5 text-green-500" />
                Record Manual Payment
              </CardTitle>
              <CardDescription>
                Record a manual payment made outside of regular EMI
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="grid md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="manual-amount">Payment Amount (αº│)</Label>
                  <Input
                    id="manual-amount"
                    type="number"
                    placeholder="0.00"
                    value={manualAmount}
                    onChange={(e) => setManualAmount(e.target.value)}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="manual-reason">Payment Reason</Label>
                  <Textarea
                    id="manual-reason"
                    placeholder="Enter reason for manual payment..."
                    value={manualReason}
                    onChange={(e) => setManualReason(e.target.value)}
                    rows={2}
                  />
                </div>
              </div>
              <Button 
                onClick={handleManualPayment}
                disabled={loading || !manualAmount || !manualReason}
                className="w-full mt-4"
              >
                {loading ? "Processing..." : "Record Payment"}
              </Button>
            </CardContent>
          </Card>

          {/* Activity History */}
          <Card>
            <CardHeader>
              <CardTitle className="text-lg flex items-center gap-2">
                <FileText className="w-5 h-5 text-purple-500" />
                Loan Activity History
              </CardTitle>
              <CardDescription>
                View payment history and admin actions for this loan
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Button
                onClick={loadActivityHistory}
                disabled={loading}
                variant="outline"
                className="w-full"
              >
                {loading ? "Loading..." : activityHistory ? "Hide History" : "Show History"}
              </Button>
              
              {activityHistory && (
                <div className="mt-4 space-y-4">
                  {/* Recent Payments */}
                  {activityHistory.payments.length > 0 && (
                    <div>
                      <h4 className="font-medium mb-2">Recent Payments</h4>
                      <div className="space-y-2">
                        {activityHistory.payments.slice(0, 5).map((payment: any) => (
                          <div key={payment.id} className="flex justify-between p-2 bg-muted rounded">
                            <div>
                              <span className="font-medium">{formatCurrency(payment.amount)}</span>
                              <Badge variant="outline" className="ml-2">{payment.type}</Badge>
                            </div>
                            <span className="text-sm text-muted-foreground">
                              {payment.payrollMonth}
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                  
                  {/* Admin Actions */}
                  {activityHistory.auditLogs.length > 0 && (
                    <div>
                      <h4 className="font-medium mb-2">Admin Actions</h4>
                      <div className="space-y-2">
                        {activityHistory.auditLogs.slice(0, 5).map((log: any) => (
                          <div key={log.id} className="p-2 bg-muted rounded">
                            <p className="text-sm">{log.changeReason}</p>
                            <span className="text-xs text-muted-foreground">
                              {new Date(log.createdAt).toLocaleString()}
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useEffect } from "react";
import { 
    getEmployeeAllowances, 
    getCustomAllowancesForEmployee, 
    assignEmployeeAllowance, 
    removeEmployeeAllowance 
} from "@/actions/settings.actions";
import { toast } from "sonner";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Plus, X, DollarSign } from "lucide-react";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";

interface EmployeeAllowanceManagerProps {
    userId: string;
    userName: string;
}

type EmployeeAllowance = {
    id: string;
    isActive: boolean;
    allowance: {
        id: string;
        name: string;
        amount: number;
        valueType: string;
        scope: string;
    };
};

type CustomAllowance = {
    id: string;
    name: string;
    amount: number;
    valueType: string;
};

export function EmployeeAllowanceManager({ userId, userName }: EmployeeAllowanceManagerProps) {
    const [employeeAllowances, setEmployeeAllowances] = useState<EmployeeAllowance[]>([]);
    const [availableAllowances, setAvailableAllowances] = useState<CustomAllowance[]>([]);
    const [selectedAllowanceId, setSelectedAllowanceId] = useState<string>("");
    const [loading, setLoading] = useState(false);
    const [adding, setAdding] = useState(false);

    const loadData = async () => {
        setLoading(true);
        try {
            const [employeeAlloData, customAlloData] = await Promise.all([
                getEmployeeAllowances(userId),
                getCustomAllowancesForEmployee(userId)
            ]);
            
            setEmployeeAllowances(employeeAlloData);
            setAvailableAllowances(customAlloData);
        } catch (error) {
            toast.error("Failed to load allowance data");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadData();
    }, [userId]);

    const handleAssignAllowance = async () => {
        if (!selectedAllowanceId) {
            toast.error("Please select an allowance to assign");
            return;
        }

        setAdding(true);
        try {
            const res = await assignEmployeeAllowance(userId, selectedAllowanceId);
            if (res.success) {
                toast.success("Allowance assigned successfully");
                setSelectedAllowanceId("");
                await loadData();
            } else {
                toast.error(res.error || "Failed to assign allowance");
            }
        } catch (error) {
            toast.error("An error occurred");
        } finally {
            setAdding(false);
        }
    };

    const handleRemoveAllowance = async (allowanceId: string, allowanceName: string) => {
        if (!confirm(`Remove ${allowanceName} allowance from ${userName}?`)) return;

        try {
            const res = await removeEmployeeAllowance(userId, allowanceId);
            if (res.success) {
                toast.success("Allowance removed successfully");
                await loadData();
            } else {
                toast.error(res.error || "Failed to remove allowance");
            }
        } catch (error) {
            toast.error("An error occurred");
        }
    };

    const assignedAllowanceIds = employeeAllowances
        .filter(ea => ea.isActive)
        .map(ea => ea.allowance.id);
    
    const unassignedAllowances = availableAllowances.filter(
        allowance => !assignedAllowanceIds.includes(allowance.id)
    );

    if (loading) return <div>Loading allowances...</div>;

    return (
        <Card>
            <CardHeader>
                <div className="flex items-center gap-2">
                    <DollarSign className="h-5 w-5 text-primary" />
                    <div>
                        <CardTitle>Custom Allowances</CardTitle>
                        <CardDescription>
                            Individual allowances assigned to {userName}
                        </CardDescription>
                    </div>
                </div>
            </CardHeader>
            <CardContent className="space-y-4">
                {/* Add New Allowance */}
                {unassignedAllowances.length > 0 && (
                    <div className="flex gap-2">
                        <Select value={selectedAllowanceId} onValueChange={setSelectedAllowanceId}>
                            <SelectTrigger className="flex-1">
                                <SelectValue placeholder="Select allowance to assign" />
                            </SelectTrigger>
                            <SelectContent>
                                {unassignedAllowances.map((allowance) => (
                                    <SelectItem key={allowance.id} value={allowance.id}>
                                        {allowance.name} ({allowance.valueType === "FIXED" 
                                            ? `αº│${allowance.amount.toLocaleString("en-BD")}`
                                            : `${allowance.amount}%`})
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                        <Button 
                            onClick={handleAssignAllowance} 
                            disabled={adding || !selectedAllowanceId}
                        >
                            <Plus className="h-4 w-4" />
                            {adding ? "Adding..." : "Assign"}
                        </Button>
                    </div>
                )}

                {/* Current Allowances */}
                <div className="space-y-2">
                    {employeeAllowances.length === 0 ? (
                        <p className="text-sm text-muted-foreground text-center py-4">
                            No custom allowances assigned
                        </p>
                    ) : (
                        employeeAllowances
                            .filter(ea => ea.isActive)
                            .map((employeeAllowance) => (
                                <div
                                    key={employeeAllowance.id}
                                    className="flex items-center justify-between p-3 bg-muted/30 rounded-lg"
                                >
                                    <div className="flex items-center gap-3">
                                        <div>
                                            <p className="font-medium">{employeeAllowance.allowance.name}</p>
                                            <p className="text-sm text-muted-foreground">
                                                {employeeAllowance.allowance.valueType === "FIXED"
                                                    ? `αº│${employeeAllowance.allowance.amount.toLocaleString("en-BD")}`
                                                    : `${employeeAllowance.allowance.amount}% of salary`}
                                            </p>
                                        </div>
                                    </div>
                                    <Button
                                        variant="ghost"
                                        size="sm"
                                        onClick={() => handleRemoveAllowance(
                                            employeeAllowance.allowance.id,
                                            employeeAllowance.allowance.name
                                        )}
                                    >
                                        <X className="h-4 w-4" />
                                    </Button>
                                </div>
                            ))
                    )}
                </div>

                {unassignedAllowances.length === 0 && employeeAllowances.length === 0 && (
                    <p className="text-sm text-muted-foreground text-center py-4">
                        No custom allowance types available. Create some in Organization ΓåÆ Allowances.
                    </p>
                )}
            </CardContent>
        </Card>
    );
}

"use client";

import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { updateEmployeeStatus } from "@/actions/employee.actions";
import { EmployeeStatus } from "@prisma/client";
import { toast } from "sonner";
import { useState } from "react";

interface EmployeeStatusSelectProps {
    employeeId: string;
    currentStatus: EmployeeStatus | null;
}

export function EmployeeStatusSelect({ employeeId, currentStatus }: EmployeeStatusSelectProps) {
    const [isUpdating, setIsUpdating] = useState(false);

    const handleStatusChange = async (newStatus: EmployeeStatus) => {
        if (newStatus === currentStatus) return;

        if (newStatus === "RESIGNED" || newStatus === "TERMINATED") {
            if (!confirm(`Are you sure you want to change status to ${newStatus}? This will archive the employee.`)) {
                return;
            }
        }

        setIsUpdating(true);
        try {
            const result = await updateEmployeeStatus(employeeId, newStatus);
            if (result.success) {
                toast.success(`Employee status updated to ${newStatus}`);
                if (newStatus === "RESIGNED" || newStatus === "TERMINATED") {
                    toast.info("Employee has been moved to archive");
                }
            } else {
                toast.error(result.error || "Failed to update status");
            }
        } catch (error) {
            toast.error("Failed to update status");
        } finally {
            setIsUpdating(false);
        }
    };

    return (
        <Select 
            value={currentStatus || "ACTIVE"} 
            onValueChange={handleStatusChange}
            disabled={isUpdating}
        >
            <SelectTrigger className="w-32">
                <SelectValue />
            </SelectTrigger>
            <SelectContent>
                <SelectItem value="ACTIVE">Active</SelectItem>
                <SelectItem value="PROBATION">Probation</SelectItem>
                <SelectItem value="RESIGNED">Resigned</SelectItem>
                <SelectItem value="TERMINATED">Terminated</SelectItem>
            </SelectContent>
        </Select>
    );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { CalendarIcon, Filter, TrendingUp, Users, Building, Gift, UserCheck, ClipboardList, Banknote } from "lucide-react";
import { cn } from "@/lib/utils";
import { 
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
    PieChart, Pie, Cell, LineChart, Line
} from "recharts";

interface Branch {
    id: string;
    name: string;
}

interface DashboardData {
    totalEmployees: number;
    pendingEmployees: number;
    activeLoanAmount: number;
    activeLoanCount: number;
    activeBranches: number;
    activeBonuses: number;
    monthlyPayrollAmount: number;
    monthlyPayrollCount: number;
    totalMedicalClaimsAmount: number;
    totalMedicalClaimsCount: number;
    departmentDistribution: { department: string; count: number }[];
    monthlyPayrollTrends: { month: string; amount: number; count: number }[];
    medicalClaimsVsEntitlements: any;
    loanRepaymentData: any[];
    leaveUtilization: any[];
    weeklyAttendanceData: any[];
    lateCheckInPenalties: any[];
    branchComparison: any[];
}

interface EnhancedDashboardProps {
    initialData: DashboardData;
    branches: Branch[];
}

const COLORS = ['#1f2937', '#374151', '#6b7280', '#9ca3af', '#d1d5db', '#e5e7eb'];

export function EnhancedDashboard({ initialData, branches }: EnhancedDashboardProps) {
    const [selectedBranch, setSelectedBranch] = useState<string>('all');
    const [fromDate, setFromDate] = useState<string>(new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0]);
    const [toDate, setToDate] = useState<string>(new Date(new Date().getFullYear(), 11, 31).toISOString().split('T')[0]);
    const [data] = useState(initialData);
    const [loading, setLoading] = useState(false);
    const [attendanceView, setAttendanceView] = useState<'current' | 'trends'>('current');

    const handleFilterChange = async () => {
        setLoading(true);
        try {
            const params = new URLSearchParams({
                branch: selectedBranch,
                from: fromDate,
                to: toDate
            });
            
            window.location.href = `/admin?${params}`;
        } catch (error) {
            console.error('Filter change failed:', error);
        } finally {
            setLoading(false);
        }
    };

    const stats = [
        { 
            title: "Total Employees", 
            value: data.totalEmployees.toString(), 
            icon: Users, 
            description: data.pendingEmployees > 0 ? `${data.pendingEmployees} pending approval` : "All employees active",
            change: "+12%",
            trend: "up" as const
        },
        { 
            title: "Active Loans", 
            value: `αº│${data.activeLoanAmount.toLocaleString("en-BD")}`, 
            icon: Banknote, 
            description: `${data.activeLoanCount} loans active`,
            change: "-8%",
            trend: "down" as const
        },
        { 
            title: "Active Branches", 
            value: data.activeBranches.toString(), 
            icon: Building, 
            description: "All operational",
            change: "0%",
            trend: "neutral" as const
        },
        { 
            title: "Active Bonuses", 
            value: data.activeBonuses.toString(), 
            icon: Gift, 
            description: "Performance bonuses",
            change: "+5%",
            trend: "up" as const
        },
        { 
            title: "Monthly Payroll", 
            value: `αº│${data.monthlyPayrollAmount.toLocaleString("en-BD")}`, 
            icon: UserCheck, 
            description: `${data.monthlyPayrollCount} employees paid this month`,
            change: "+15%",
            trend: "up" as const
        },
        { 
            title: "Medical Claims", 
            value: `αº│${data.totalMedicalClaimsAmount.toLocaleString("en-BD")}`, 
            icon: ClipboardList, 
            description: `${data.totalMedicalClaimsCount} claims this year`,
            change: "+3%",
            trend: "up" as const
        },
    ];

    // Process weekly attendance data
    const processWeeklyAttendance = () => {
        const daysOfWeek = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
        return daysOfWeek.map(day => {
            const dayRecords = data.weeklyAttendanceData?.filter(record => {
                const recordDate = new Date(record.date);
                return daysOfWeek[recordDate.getDay() - 1] === day;
            }) || [];

            const totalHours = dayRecords.reduce((sum, record) => {
                if (record.actualActiveTime) {
                    const [hours, minutes] = record.actualActiveTime.split(':').map(Number);
                    return sum + hours + (minutes / 60);
                }
                return sum;
            }, 0);

            const overtimeHours = dayRecords.reduce((sum, record) => {
                if (record.overtimeUndertime && record.overtimeUndertime.startsWith('+')) {
                    const timeStr = record.overtimeUndertime.slice(1);
                    const [hours, minutes] = timeStr.split(':').map(Number);
                    return sum + hours + (minutes / 60);
                }
                return sum;
            }, 0);

            const undertimeHours = dayRecords.reduce((sum, record) => {
                if (record.overtimeUndertime && record.overtimeUndertime.startsWith('-')) {
                    const timeStr = record.overtimeUndertime.slice(1);
                    const [hours, minutes] = timeStr.split(':').map(Number);
                    return sum + hours + (minutes / 60);
                }
                return sum;
            }, 0);

            return {
                day,
                totalHours: Math.round(totalHours * 100) / 100,
                overtimeHours: Math.round(overtimeHours * 100) / 100,
                undertimeHours: Math.round(undertimeHours * 100) / 100,
                employees: dayRecords.length
            };
        });
    };

    const weeklyData = processWeeklyAttendance();
    // Process attendance trends data (past weeks)
    const processAttendanceTrends = () => {
        if (!data.weeklyAttendanceData || data.weeklyAttendanceData.length === 0) {
            return [];
        }

        // Group by week
        const weeklyGroups: Record<string, any[]> = {};
        data.weeklyAttendanceData.forEach(record => {
            const date = new Date(record.date);
            const weekStart = new Date(date);
            weekStart.setDate(date.getDate() - date.getDay() + 1); // Monday
            const weekKey = weekStart.toISOString().split('T')[0];
            
            if (!weeklyGroups[weekKey]) {
                weeklyGroups[weekKey] = [];
            }
            weeklyGroups[weekKey].push(record);
        });

        // Calculate metrics for each week
        return Object.entries(weeklyGroups)
            .map(([weekKey, records]) => {
                const presentCount = records.filter(r => r.status === 'PRESENT').length;
                const totalCount = records.length;
                const attendanceRate = totalCount > 0 ? Math.round((presentCount / totalCount) * 100) : 0;
                
                const weekDate = new Date(weekKey);
                const weekLabel = `Week ${Math.ceil(weekDate.getDate() / 7)} - ${weekDate.toLocaleDateString('en-US', { month: 'short' })}`;
                
                return {
                    week: weekLabel,
                    attendanceRate,
                    presentCount,
                    totalCount
                };
            })
            .sort((a, b) => a.week.localeCompare(b.week))
            .slice(-8); // Last 8 weeks
    };

    const attendanceTrendsData = processAttendanceTrends();
    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex flex-col space-y-4">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight"> Admin Dashboard</h1>
                    <p className="text-muted-foreground">Comprehensive analytics and insights for your organization</p>
                </div>

                {/* Filters */}
                <div className="flex flex-wrap items-center gap-4 p-4 bg-gray-50 rounded-lg border border-gray-200">
                    <div className="flex items-center gap-2">
                        <Filter className="h-4 w-4 text-gray-600" />
                        <span className="text-sm font-medium text-gray-700">Filters:</span>
                    </div>
                    
                    {/* Branch Filter */}
                    <Select value={selectedBranch} onValueChange={setSelectedBranch}>
                        <SelectTrigger className="w-[180px]">
                            <SelectValue placeholder="Select Branch" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="all">All Branches</SelectItem>
                            {branches.map((branch) => (
                                <SelectItem key={branch.id} value={branch.id}>
                                    {branch.name}
                                </SelectItem>
                            ))}
                        </SelectContent>
                    </Select>

                    {/* Date Range Filter */}
                    <div className="flex items-center gap-2">
                        <CalendarIcon className="h-4 w-4 text-gray-600" />
                        <Input
                            type="date"
                            value={fromDate}
                            onChange={(e) => setFromDate(e.target.value)}
                            className="w-auto"
                        />
                        <span className="text-gray-600">to</span>
                        <Input
                            type="date"
                            value={toDate}
                            onChange={(e) => setToDate(e.target.value)}
                            className="w-auto"
                        />
                    </div>

                    <Button onClick={handleFilterChange} disabled={loading}>
                        {loading ? "Applying..." : "Apply Filters"}
                    </Button>
                </div>
            </div>

            {/* Quick Stats */}
            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                {stats.map((stat) => (
                    <Card key={stat.title} className="hover:shadow-md transition-shadow">
                        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                            <CardTitle className="text-sm font-medium text-gray-700">{stat.title}</CardTitle>
                            <stat.icon className="h-4 w-4 text-gray-600" />
                        </CardHeader>
                        <CardContent>
                            <div className="text-2xl font-bold text-gray-900">{stat.value}</div>
                            <div className="flex items-center justify-between mt-1">
                                <p className="text-xs text-gray-600">{stat.description}</p>
                                <span className={cn(
                                    "text-xs font-medium",
                                    stat.trend === 'up' && "text-green-600",
                                    stat.trend === 'down' && "text-red-600",
                                    stat.trend === 'neutral' && "text-gray-600"
                                )}>
                                    {stat.change}
                                </span>
                            </div>
                        </CardContent>
                    </Card>
                ))}
            </div>

            {/* Department Distribution */}
            <div className="grid gap-6 lg:grid-cols-2">
                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <Users className="h-5 w-5" />
                            Department Distribution
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <ResponsiveContainer width="100%" height={300}>
                            <PieChart>
                                <Pie
                                    data={data.departmentDistribution}
                                    cx="50%"
                                    cy="50%"
                                    labelLine={false}
                                    label={(props) => {
                                        const { payload } = props;
                                        return `${payload.department}: ${payload.count}`;
                                    }}
                                    outerRadius={80}
                                    fill="#8884d8"
                                    dataKey="count"
                                    >

                                    {data.departmentDistribution?.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip />
                            </PieChart>
                        </ResponsiveContainer>
                    </CardContent>
                </Card>

                {/* Monthly Payroll Trends */}
                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <TrendingUp className="h-5 w-5" />
                            Monthly Payroll Trends
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <ResponsiveContainer width="100%" height={300}>
                            <LineChart data={data.monthlyPayrollTrends}>
                                <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
                                <XAxis dataKey="month" stroke="#6b7280" />
                                <YAxis stroke="#6b7280" />
                                <Tooltip 
                                    formatter={(value: number | undefined) => [`αº│${(value || 0).toLocaleString()}`, 'Amount']}
                                    labelStyle={{ color: '#1f2937' }}
                                />
                                <Line 
                                    type="monotone" 
                                    dataKey="amount" 
                                    stroke="#1f2937" 
                                    strokeWidth={3}
                                    dot={{ fill: '#1f2937', strokeWidth: 2, r: 4 }}
                                />
                            </LineChart>
                        </ResponsiveContainer>
                    </CardContent>
                </Card>
            </div>

            {/* Weekly Attendance Analysis */}
            <Card>
                <CardHeader>
                    <div className="flex items-center justify-between">
                        <CardTitle className="flex items-center gap-2">
                            <UserCheck className="h-5 w-5" />
                            Weekly Attendance Analysis
                        </CardTitle>
                        <div className="flex gap-2">
                            <Button 
                                variant={attendanceView === 'current' ? 'default' : 'outline'}
                                size="sm"
                                onClick={() => setAttendanceView('current')}
                            >
                                Current Week
                            </Button>
                            <Button 
                                variant={attendanceView === 'trends' ? 'default' : 'outline'}
                                size="sm"
                                onClick={() => setAttendanceView('trends')}
                            >
                                Trends
                            </Button>
                        </div>
                    </div>
                </CardHeader>
                <CardContent>
                    <div className="h-80 w-full">
                        {attendanceView === 'current' ? (
                            <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={weeklyData}>
                                    <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
                                    <XAxis dataKey="day" stroke="#6b7280" />
                                    <YAxis stroke="#6b7280" />
                                    <Tooltip 
                                        formatter={(value: number | undefined, name: string | undefined) => [
                                            `${value || 0} hours`,
                                            name === 'totalHours' ? 'Total Hours' : 
                                            name === 'overtimeHours' ? 'Overtime' : 'Undertime'
                                        ]}
                                        labelStyle={{ color: '#1f2937' }}
                                    />
                                    <Legend />
                                    <Bar dataKey="totalHours" fill="#1f2937" name="Total Hours" />
                                    <Bar dataKey="overtimeHours" fill="#16a34a" name="Overtime" />
                                    <Bar dataKey="undertimeHours" fill="#dc2626" name="Undertime" />
                                </BarChart>
                            </ResponsiveContainer>
                        ) : (
                            <ResponsiveContainer width="100%" height="100%">
                                <LineChart data={attendanceTrendsData}>
                                    <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
                                    <XAxis dataKey="week" stroke="#6b7280" />
                                    <YAxis stroke="#6b7280" domain={[0, 100]} />
                                    <Tooltip 
                                        formatter={(value: number | undefined, name: string | undefined) => [
                                            `${value || 0}%`,
                                            name === 'attendanceRate' ? 'Attendance Rate' : name
                                        ]}
                                        labelStyle={{ color: '#1f2937' }}
                                    />
                                    <Legend />
                                    <Line 
                                        type="monotone" 
                                        dataKey="attendanceRate" 
                                        stroke="#1f2937" 
                                        strokeWidth={2}
                                        name="Attendance Rate (%)"
                                        dot={{ fill: '#1f2937', strokeWidth: 2, r: 4 }}
                                    />
                                </LineChart>
                            </ResponsiveContainer>
                        )}
                    </div>
                </CardContent>
            </Card>

            {/* Branch Comparison */}
            {data.branchComparison && data.branchComparison.length > 0 && (
                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <Building className="h-5 w-5" />
                            Branch Comparison
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <ResponsiveContainer width="100%" height={400}>
                            <BarChart data={data.branchComparison}>
                                <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
                                <XAxis dataKey="branch" stroke="#6b7280" />
                                <YAxis yAxisId="left" stroke="#6b7280" />
                                <YAxis yAxisId="right" orientation="right" stroke="#6b7280" />
                                <Tooltip />
                                <Legend />
                                <Bar 
                                    yAxisId="left" 
                                    dataKey="employees" 
                                    fill="#1f2937" 
                                    name="Employees"
                                />
                                <Bar 
                                    yAxisId="right" 
                                    dataKey="monthlyPayroll" 
                                    fill="#6b7280" 
                                    name="Monthly Payroll (αº│)"
                                />
                            </BarChart>
                        </ResponsiveContainer>
                    </CardContent>
                </Card>
            )}

            {/* Loan Progress */}
            {data.loanRepaymentData && data.loanRepaymentData.length > 0 && (
                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2">
                            <Banknote className="h-5 w-5" />
                            Loan Repayment Progress
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <div className="space-y-4">
                            {data.loanRepaymentData.slice(0, 5).map((loan) => (
                                <div key={loan.id} className="space-y-2">
                                    <div className="flex justify-between text-sm">
                                        <span className="font-medium">{loan.employee}</span>
                                        <span className="text-gray-600">
                                            αº│{(loan.totalAmount - loan.remaining).toLocaleString()} / αº│{loan.totalAmount.toLocaleString()}
                                        </span>
                                    </div>
                                    <div className="w-full bg-gray-200 rounded-full h-2">
                                        <div 
                                            className="bg-gray-800 h-2 rounded-full transition-all duration-300" 
                                            style={{ width: `${loan.progressPercent}%` }}
                                        />
                                    </div>
                                    <div className="flex justify-between text-xs text-gray-500">
                                        <span>{loan.progressPercent}% completed</span>
                                        <span>{loan.monthsPassed} / {loan.totalMonths} months</span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </CardContent>
                </Card>
            )}

            {/* Late Check-ins */}
            {data.lateCheckInPenalties && data.lateCheckInPenalties.length > 0 && (
                <Card>
                    <CardHeader>
                        <CardTitle>Late Check-in Penalties</CardTitle> 
                    </CardHeader>
                    <CardContent>
                        <ResponsiveContainer width="100%" height={300}>
                            <BarChart data={data.lateCheckInPenalties.slice(0, 5)}>
                                <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
                                <XAxis 
                                    dataKey="employee" 
                                    stroke="#6b7280" 
                                    angle={-45}
                                    textAnchor="end"
                                    height={80}
                                />
                                <YAxis stroke="#6b7280" />
                                <Tooltip 
                                    formatter={(value: number | undefined) => [`αº│${value || 0}`, 'Penalty']}
                                />
                                <Bar dataKey="totalPenalty" fill="#dc2626" />
                            </BarChart>
                        </ResponsiveContainer>
                    </CardContent>
                </Card>
            )}
        </div>
    );
}

"use client";

import { useState } from "react";
import { updateSystemSettings } from "@/actions/settings.actions";
import { toast } from "sonner";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Loader2, Save } from "lucide-react";

interface GlobalSettingsFormProps {
    initialData: {
        medicalClaimLimit: number;
    };
}

export function GlobalSettingsForm({ initialData }: GlobalSettingsFormProps) {
    const [formData, setFormData] = useState(initialData);
    const [saving, setSaving] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);
        try {
            const res = await updateSystemSettings(formData);
            if (res.success) {
                toast.success("Global configurations saved successfully");
            }
        } catch (error: any) {
            toast.error(error.message || "Failed to update settings");
        } finally {
            setSaving(false);
        }
    };

    return (
        <form onSubmit={handleSubmit}>
            <Card>
                <CardHeader>
                    <CardTitle className="text-xl">Medical Settings</CardTitle>
                    <CardDescription>
                        Default medical claim limit for all employees.
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-6">
                    <div className="space-y-4">
                        <div className="space-y-2">
                            <Label htmlFor="medicalLimit">Annual Medical Limit (αº│)</Label>
                            <Input
                                id="medicalLimit"
                                type="number"
                                value={formData.medicalClaimLimit}
                                onChange={(e) => setFormData({ ...formData, medicalClaimLimit: Number(e.target.value) })}
                            />
                        </div>
                    </div>

                    <Button type="submit" className="w-full" disabled={saving}>
                        {saving ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Save className="mr-2 h-4 w-4" />}
                        Save Medical Settings
                    </Button>
                </CardContent>
            </Card>
        </form>
    );
}

"use client";

import { useState } from "react";
import { approveLeaveApplication, rejectLeaveApplication } from "@/actions/leave.actions";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { CheckCircle, XCircle } from "lucide-react";

interface ApprovalButtonsProps {
    applicationId: string;
}

export function ApprovalButtons({ applicationId }: ApprovalButtonsProps) {
    const [loading, setLoading] = useState(false);

    const handleApprove = async () => {
        setLoading(true);
        
        try {
            const result = await approveLeaveApplication(applicationId, "admin");
            
            if (result.success) {
                toast.success("Leave application approved successfully");
                // Refresh the page to update the list
                window.location.reload();
            } else {
                toast.error(result.error || "Failed to approve application");
            }
        } catch (error) {
            toast.error("An error occurred while approving");
        } finally {
            setLoading(false);
        }
    };

    const handleReject = async () => {
        if (!confirm("Are you sure you want to reject this leave application?")) {
            return;
        }

        setLoading(true);
        
        try {
            const result = await rejectLeaveApplication(applicationId, "admin");
            
            if (result.success) {
                toast.success("Leave application rejected");
                // Refresh the page to update the list
                window.location.reload();
            } else {
                toast.error(result.error || "Failed to reject application");
            }
        } catch (error) {
            toast.error("An error occurred while rejecting");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex gap-2">
            <Button
                size="sm"
                variant="outline"
                onClick={handleReject}
                disabled={loading}
                className="text-red-600 hover:bg-red-50"
            >
                <XCircle className="h-4 w-4 mr-1" />
                Reject
            </Button>
            <Button
                size="sm"
                onClick={handleApprove}
                disabled={loading}
                className="bg-green-600 hover:bg-green-700"
            >
                <CheckCircle className="h-4 w-4 mr-1" />
                Approve
            </Button>
        </div>
    );
}

"use client";

import { useState } from "react";
import { toggleLeaveTypeStatus } from "@/actions/leave.actions";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";

interface LeaveTypeToggleProps {
    leaveTypeId: string;
    isActive: boolean;
}

export function LeaveTypeToggle({ leaveTypeId, isActive }: LeaveTypeToggleProps) {
    const [loading, setLoading] = useState(false);

    const handleToggle = async (checked: boolean) => {
        setLoading(true);
        
        try {
            const result = await toggleLeaveTypeStatus(leaveTypeId);
            
            if (result.success) {
                toast.success(`Leave type ${checked ? 'activated' : 'deactivated'} successfully`);
            } else {
                toast.error(result.error || "Failed to update leave type status");
            }
        } catch (error) {
            toast.error("An error occurred while updating status");
        } finally {
            setLoading(false);
        }
    };

    return (
        <Switch
            checked={isActive}
            onCheckedChange={handleToggle}
            disabled={loading}
        />
    );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Settings, Crown } from "lucide-react";
import { toast } from "sonner";
import { toggleManagerStatus } from "@/actions/user.actions";

interface ManagerToggleProps {
    userId: string;
    isManager: boolean;
    userRole: string;
    userName: string;
}

export function ManagerToggle({ userId, isManager, userRole, userName }: ManagerToggleProps) {
    const [currentManagerStatus, setCurrentManagerStatus] = useState(isManager);
    const [isLoading, setIsLoading] = useState(false);

    const handleToggleManager = async () => {
        if (userRole !== "EMPLOYEE") {
            toast.error("Manager status can only be set for employees");
            return;
        }

        setIsLoading(true);
        try {
            const result = await toggleManagerStatus(userId);
            if (result.success) {
                setCurrentManagerStatus(result.isManager ?? currentManagerStatus);
                toast.success(result.message);
            } else {
                toast.error(result.error || "Failed to update manager status");
            }
        } catch (error) {
            toast.error("An unexpected error occurred");
        } finally {
            setIsLoading(false);
        }
    };

    if (userRole !== "EMPLOYEE") {
        return (
            <div className="flex items-center gap-2">
                <Badge variant="outline">Not applicable</Badge>
                <span className="text-xs text-muted-foreground">
                    (Only employees can be managers)
                </span>
            </div>
        );
    }

    return (
        <div className="flex items-center gap-2">
            {currentManagerStatus ? (
                <Badge variant="default" className="gap-1">
                    <Crown className="h-3 w-3" />
                    Manager
                </Badge>
            ) : (
                <Badge variant="outline">Regular Employee</Badge>
            )}
            <Button
                variant={currentManagerStatus ? "destructive" : "default"}
                size="sm"
                onClick={handleToggleManager}
                disabled={isLoading}
                className="gap-1"
            >
                <Settings className="h-3 w-3" />
                {currentManagerStatus ? "Remove Manager" : "Make Manager"}
            </Button>
        </div>
    );
}

