"use client";

import { useState, useEffect } from "react";
import { Bell, Check, X, Eye, EyeOff, Trash2, MoreHorizontal } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area"; 
import { Separator } from "@/components/ui/separator";
import type { AdminNotification } from "@prisma/client";
import { NotificationStatus } from "@prisma/client";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { toast } from "sonner";
import { 
  getUnreadCount, 
  getAllNotifications, 
  markNotificationAsRead,
  markNotificationAsUnread,
  markAllNotificationsAsRead,
  deleteNotification,
  handleNotificationAction
} from "@/actions/notification.actions";

type NotificationType = 'TIMELINE_GENERATION_FAILED' | 'TIMELINE_BACKFILL_COMPLETED' | 'PROFILE_UPDATE_REQUEST' | 'LEAVE_APPLICATION_PENDING' | 'INCREMENT_REMINDER' | 'WALLET_REQUEST_PENDING' | 'LOAN_APPLICATION_PENDING' | 'EMPLOYEE_REGISTRATION_PENDING' | 'PAYROLL_NOTIFICATION' | 'SYSTEM_ALERT' | 'DEADLINE_REMINDER' | 'OVERTIME_REQUEST_PENDING';


export function NotificationBell() {
  const [unreadCount, setUnreadCount] = useState(0);
  const [notifications, setNotifications] = useState<AdminNotification[]>([]);
  const [loading, setLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const [selectedNotification, setSelectedNotification] = useState<AdminNotification | null>(null);
  const [actionLoading, setActionLoading] = useState(false);

  // Fetch unread count
  const fetchUnreadCount = async () => {
    const result = await getUnreadCount();
    if (result.success) {
      setUnreadCount(result.count);
    }
  };

  // Fetch all notifications
  const fetchNotifications = async () => {
    setLoading(true);
    const result = await getAllNotifications(1, 50);
    if (result.success) {
      setNotifications(result.notifications);
    }
    setLoading(false);
  };

  // Handle notification actions
  const handleAction = async (notificationId: string, action: 'approve' | 'decline') => {
    setActionLoading(true);
    const result = await handleNotificationAction(notificationId, action);
    
    if (result.success) {
      toast.success(`Request ${action}d successfully`);
      await fetchNotifications();
      await fetchUnreadCount();
    } else {
      toast.error(result.error || `Failed to ${action} request`);
    }
    setActionLoading(false);
  };

  // Mark as read/unread
  const toggleReadStatus = async (notificationId: string, currentStatus: NotificationStatus) => {
    const action = currentStatus === NotificationStatus.UNREAD ? markNotificationAsRead : markNotificationAsUnread;
    const result = await action(notificationId);
    
    if (result.success) {
      await fetchNotifications();
      await fetchUnreadCount();
      toast.success(`Marked as ${currentStatus === NotificationStatus.UNREAD ? 'read' : 'unread'}`);
    } else {
      toast.error('Failed to update notification');
    }
  };

  // Mark all as read
  const handleMarkAllRead = async () => {
    const result = await markAllNotificationsAsRead();
    if (result.success) {
      await fetchNotifications();
      await fetchUnreadCount();
      toast.success('All notifications marked as read');
    } else {
      toast.error('Failed to mark all as read');
    }
  };

  // Delete notification
  const handleDelete = async (notificationId: string) => {
    const result = await deleteNotification(notificationId);
    if (result.success) {
      await fetchNotifications();
      await fetchUnreadCount();
      toast.success('Notification deleted');
    } else {
      toast.error('Failed to delete notification');
    }
  };

  // Get notification icon and color
  const getNotificationIcon = (type: NotificationType) => {
    const iconMap = {
      PROFILE_UPDATE_REQUEST: '≡ƒæñ',
      LEAVE_APPLICATION_PENDING: '≡ƒôà', 
      INCREMENT_REMINDER: '≡ƒÄë',
      WALLET_REQUEST_PENDING: '≡ƒÆ░',
      LOAN_APPLICATION_PENDING: '≡ƒÅª',
      EMPLOYEE_REGISTRATION_PENDING: '≡ƒæÑ',
      PAYROLL_NOTIFICATION: '≡ƒÆ╕',
      SYSTEM_ALERT: 'ΓÜá∩╕Å',
      DEADLINE_REMINDER: 'ΓÅ░',
      TIMELINE_GENERATION_FAILED: 'Γ¥î',
      TIMELINE_BACKFILL_COMPLETED: 'Γ£à',
      OVERTIME_REQUEST_PENDING: 'ΓÅ▒∩╕Å'
    };
    return iconMap[type] || '≡ƒôó';
  };

  // Auto refresh every 30 seconds
  useEffect(() => {
    fetchUnreadCount();
    const interval = setInterval(fetchUnreadCount, 30000);
    return () => clearInterval(interval);
  }, []);

  // Fetch notifications when sheet opens
  useEffect(() => {
    if (isOpen) {
      fetchNotifications();
    }
  }, [isOpen]);

  // Check if notification allows actions
  const allowsActions = (type: NotificationType) => {
    return ['PROFILE_UPDATE_REQUEST', 'LEAVE_APPLICATION_PENDING', 'LOAN_APPLICATION_PENDING', 'WALLET_REQUEST_PENDING'].includes(type);
  };

  return (
    <>
      <Sheet open={isOpen} onOpenChange={setIsOpen}>
        <SheetTrigger asChild>
          <Button variant="ghost" size="sm" className="relative">
            <Bell className="h-5 w-5" />
            {unreadCount > 0 && (
              <Badge 
                variant="destructive" 
                className="absolute -top-2 -right-2 h-5 w-5 flex items-center justify-center p-0 text-xs"
              >
                {unreadCount > 99 ? '99+' : unreadCount}
              </Badge>
            )}
          </Button>
        </SheetTrigger>
        
        <SheetContent className="w-[400px] sm:w-[540px]">
          <SheetHeader>
            <div className="flex items-center justify-between">
              <SheetTitle>Notifications</SheetTitle>
              {notifications.length > 0 && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleMarkAllRead}
                  disabled={loading}
                >
                  Mark all read
                </Button>
              )}
            </div>
            <SheetDescription>
              Manage requests and system alerts
            </SheetDescription>
          </SheetHeader>

          <div className="mt-6">
            {loading ? (
              <div className="flex items-center justify-center py-4">
                <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-primary"></div>
              </div>
            ) : notifications.length === 0 ? (
              <div className="text-center py-8">
                <Bell className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
                <p className="text-muted-foreground">No notifications</p>
              </div>
            ) : (
              <ScrollArea className="h-[calc(100vh-200px)]">
                <div className="space-y-4">
                  {notifications.map((notification) => (
                    <Card key={notification.id} className={notification.status === NotificationStatus.UNREAD ? 'bg-blue-50 border-blue-200' : ''}>
                      <CardHeader className="pb-2">
                        <div className="flex items-start justify-between">
                          <div className="flex items-start gap-2">
                            <span className="text-lg">{getNotificationIcon(notification.type)}</span>
                            <div className="flex-1">
                              <CardTitle className="text-sm">{notification.title}</CardTitle>
                              <CardDescription className="text-xs">
                                {new Date(notification.createdAt).toLocaleDateString()} at {new Date(notification.createdAt).toLocaleTimeString()}
                              </CardDescription>
                            </div>
                          </div>
                          
                          <div className="flex items-center gap-1">
                            {notification.status === NotificationStatus.UNREAD && (
                              <Badge variant="secondary" className="text-xs">New</Badge>
                            )}
                            
                            <DropdownMenu>
                              <DropdownMenuTrigger asChild>
                                <Button variant="ghost" size="sm">
                                  <MoreHorizontal className="h-4 w-4" />
                                </Button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end">
                                <DropdownMenuItem 
                                  onClick={() => toggleReadStatus(notification.id, notification.status)}
                                >
                                  {notification.status === NotificationStatus.UNREAD ? (
                                    <>
                                      <Eye className="mr-2 h-4 w-4" />
                                      Mark as read
                                    </>
                                  ) : (
                                    <>
                                      <EyeOff className="mr-2 h-4 w-4" />
                                      Mark as unread
                                    </>
                                  )}
                                </DropdownMenuItem>
                                <DropdownMenuSeparator />
                                <DropdownMenuItem 
                                  onClick={() => handleDelete(notification.id)}
                                  className="text-destructive"
                                >
                                  <Trash2 className="mr-2 h-4 w-4" />
                                  Delete
                                </DropdownMenuItem>
                              </DropdownMenuContent>
                            </DropdownMenu>
                          </div>
                        </div>
                      </CardHeader>
                      
                      <CardContent className="pt-0">
                        <p className="text-sm text-muted-foreground mb-3">
                          {notification.message}
                        </p>
                        
                        {allowsActions(notification.type) && (
                          <div className="flex gap-2">
                            <Button
                              size="sm"
                              onClick={() => handleAction(notification.id, 'approve')}
                              disabled={actionLoading}
                              className="bg-green-600 hover:bg-green-700"
                            >
                              <Check className="mr-1 h-3 w-3" />
                              Approve
                            </Button>
                            <Button
                              size="sm"
                              variant="destructive"
                              onClick={() => handleAction(notification.id, 'decline')}
                              disabled={actionLoading}
                            >
                              <X className="mr-1 h-3 w-3" />
                              Decline
                            </Button>
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => setSelectedNotification(notification)}
                            >
                              View Details
                            </Button>
                          </div>
                        )}
                        
                        {!allowsActions(notification.type) && (
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => setSelectedNotification(notification)}
                          >
                            View Details
                          </Button>
                        )}
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </ScrollArea>
            )}
          </div>
        </SheetContent>
      </Sheet>

      {/* Notification Details Dialog */}
      {selectedNotification && (
        <Dialog open={!!selectedNotification} onOpenChange={() => setSelectedNotification(null)}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle className="flex items-center gap-2">
                <span>{getNotificationIcon(selectedNotification.type)}</span>
                {selectedNotification.title}
              </DialogTitle>
              <DialogDescription>
                {selectedNotification.message}
              </DialogDescription>
            </DialogHeader>
            
            {selectedNotification.metadata && (
              <div className="py-4">
                <h4 className="text-sm font-semibold mb-2">Additional Information:</h4>
                <pre className="text-xs bg-muted p-2 rounded overflow-auto">
                  {JSON.stringify(selectedNotification.metadata, null, 2)}
                </pre>
              </div>
            )}
            
            <DialogFooter>
              <Button variant="outline" onClick={() => setSelectedNotification(null)}>
                Close
              </Button>
              {allowsActions(selectedNotification.type) && (
                <>
                  <Button
                    onClick={() => {
                      handleAction(selectedNotification.id, 'approve');
                      setSelectedNotification(null);
                    }}
                    className="bg-green-600 hover:bg-green-700"
                  >
                    Approve
                  </Button>
                  <Button
                    onClick={() => {
                      handleAction(selectedNotification.id, 'decline');
                      setSelectedNotification(null);
                    }}
                    variant="destructive"
                  >
                    Decline
                  </Button>
                </>
              )}
            </DialogFooter>
          </DialogContent>
        </Dialog>
      )}
    </>
  );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { 
    Bell, 
    CheckCircle, 
    AlertTriangle, 
    Info, 
    X,
    Clock,
    User,
    FileText
} from "lucide-react";

interface Notification {
    id: string;
    type: string;
    title: string;
    message: string;
    status: "READ" | "UNREAD";
    createdAt: Date | string;
    metadata?: any;
}

interface NotificationListProps {
    notifications: Notification[];
    markAsReadAction: (notificationId: string) => Promise<any>;
    markAllAsReadAction: () => Promise<any>;
}

export function NotificationList({ 
    notifications, 
    markAsReadAction, 
    markAllAsReadAction 
}: NotificationListProps) {
    const [isMarkingAllRead, setIsMarkingAllRead] = useState(false);
    const [markingReadIds, setMarkingReadIds] = useState<Set<string>>(new Set());

    const unreadCount = notifications.filter(n => n.status === "UNREAD").length;

    const handleMarkAsRead = async (notificationId: string) => {
        setMarkingReadIds(prev => new Set([...prev, notificationId]));
        try {
            await markAsReadAction(notificationId);
        } catch (error) {
            console.error("Failed to mark notification as read:", error);
        } finally {
            setMarkingReadIds(prev => {
                const newSet = new Set(prev);
                newSet.delete(notificationId);
                return newSet;
            });
        }
    };

    const handleMarkAllAsRead = async () => {
        setIsMarkingAllRead(true);
        try {
            await markAllAsReadAction();
        } catch (error) {
            console.error("Failed to mark all notifications as read:", error);
        } finally {
            setIsMarkingAllRead(false);
        }
    };

    const getNotificationIcon = (type: string) => {
        switch (type) {
            case 'TIMELINE_GENERATION_FAILED':
            case 'SYSTEM_ALERT':
                return <AlertTriangle className="h-4 w-4 text-red-600" />;
            case 'TIMELINE_BACKFILL_COMPLETED':
            case 'PAYROLL_NOTIFICATION':
                return <CheckCircle className="h-4 w-4 text-green-600" />;
            case 'PROFILE_UPDATE_REQUEST':
            case 'EMPLOYEE_REGISTRATION_PENDING':
                return <User className="h-4 w-4 text-blue-600" />;
            case 'LEAVE_APPLICATION_PENDING':
            case 'LOAN_APPLICATION_PENDING':
            case 'WALLET_REQUEST_PENDING':
                return <FileText className="h-4 w-4 text-orange-600" />;
            case 'INCREMENT_REMINDER':
            case 'DEADLINE_REMINDER':
                return <Clock className="h-4 w-4 text-purple-600" />;
            default:
                return <Info className="h-4 w-4 text-gray-600" />;
        }
    };

    const getNotificationTypeBadge = (type: string) => {
        const typeMap: Record<string, { label: string; variant: "default" | "secondary" | "destructive" | "outline" }> = {
            'TIMELINE_GENERATION_FAILED': { label: 'Timeline Error', variant: 'destructive' },
            'TIMELINE_BACKFILL_COMPLETED': { label: 'Timeline Complete', variant: 'default' },
            'PROFILE_UPDATE_REQUEST': { label: 'Profile Request', variant: 'secondary' },
            'LEAVE_APPLICATION_PENDING': { label: 'Leave Pending', variant: 'outline' },
            'INCREMENT_REMINDER': { label: 'Reminder', variant: 'secondary' },
            'WALLET_REQUEST_PENDING': { label: 'Wallet Request', variant: 'outline' },
            'LOAN_APPLICATION_PENDING': { label: 'Loan Request', variant: 'outline' },
            'EMPLOYEE_REGISTRATION_PENDING': { label: 'New Employee', variant: 'secondary' },
            'PAYROLL_NOTIFICATION': { label: 'Payroll', variant: 'default' },
            'SYSTEM_ALERT': { label: 'System Alert', variant: 'destructive' },
            'DEADLINE_REMINDER': { label: 'Deadline', variant: 'outline' },
        };

        const config = typeMap[type] || { label: type, variant: 'outline' as const };
        return <Badge variant={config.variant}>{config.label}</Badge>;
    };

    const formatDate = (dateInput: Date | string) => {
        const date = typeof dateInput === 'string' ? new Date(dateInput) : dateInput;
        const now = new Date();
        const diffInHours = Math.floor((now.getTime() - date.getTime()) / (1000 * 60 * 60));

        if (diffInHours < 1) {
            return 'Just now';
        } else if (diffInHours < 24) {
            return `${diffInHours}h ago`;
        } else {
            return date.toLocaleDateString();
        }
    };

    return (
        <div className="space-y-4">
            {/* Header with stats and actions */}
            <Card>
                <CardHeader className="pb-3">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <Bell className="h-5 w-5" />
                            <div>
                                <CardTitle>Notifications</CardTitle>
                                <p className="text-sm text-muted-foreground">
                                    {unreadCount} unread of {notifications.length} total
                                </p>
                            </div>
                        </div>
                        {unreadCount > 0 && (
                            <Button
                                variant="outline"
                                size="sm"
                                onClick={handleMarkAllAsRead}
                                disabled={isMarkingAllRead}
                            >
                                {isMarkingAllRead ? "Marking..." : "Mark All Read"}
                            </Button>
                        )}
                    </div>
                </CardHeader>
            </Card>

            {/* Notifications List */}
            <Card>
                <CardContent className="p-0">
                    <ScrollArea className="h-[600px]">
                        {notifications.length === 0 ? (
                            <div className="flex flex-col items-center justify-center py-12">
                                <Bell className="h-12 w-12 text-muted-foreground mb-4" />
                                <h3 className="text-lg font-semibold">No notifications</h3>
                                <p className="text-muted-foreground">
                                    You&apos;re all caught up! No new notifications at this time.
                                </p>
                            </div>
                        ) : (
                            <div className="divide-y">
                                {notifications.map((notification, index) => (
                                    <div
                                        key={notification.id}
                                        className={`p-4 transition-colors hover:bg-muted/50 ${
                                            notification.status === "UNREAD" ? "bg-blue-50/50 border-l-4 border-l-blue-500" : ""
                                        }`}
                                    >
                                        <div className="flex items-start justify-between gap-3">
                                            <div className="flex-1 space-y-2">
                                                <div className="flex items-center gap-2">
                                                    {getNotificationIcon(notification.type)}
                                                    <h4 className="font-medium text-sm">{notification.title}</h4>
                                                    {getNotificationTypeBadge(notification.type)}
                                                    {notification.status === "UNREAD" && (
                                                        <Badge variant="secondary" className="text-xs">
                                                            New
                                                        </Badge>
                                                    )}
                                                </div>
                                                <p className="text-sm text-muted-foreground">
                                                    {notification.message}
                                                </p>
                                                <div className="flex items-center justify-between">
                                                    <span className="text-xs text-muted-foreground">
                                                        {formatDate(notification.createdAt)}
                                                    </span>
                                                    {notification.status === "UNREAD" && (
                                                        <Button
                                                            variant="ghost"
                                                            size="sm"
                                                            onClick={() => handleMarkAsRead(notification.id)}
                                                            disabled={markingReadIds.has(notification.id)}
                                                            className="text-xs"
                                                        >
                                                            {markingReadIds.has(notification.id) ? (
                                                                "Marking..."
                                                            ) : (
                                                                <>
                                                                    <CheckCircle className="h-3 w-3 mr-1" />
                                                                    Mark as Read
                                                                </>
                                                            )}
                                                        </Button>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </ScrollArea>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState } from "react";
import { toggleEmiCarryForward, processPayroll, generatePayrollCSVData, getFailedEmployees } from "@/actions/payroll.actions";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import { Loader2, DollarSign, Gift } from "lucide-react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import { Checkbox } from "@/components/ui/checkbox";

interface EligibleBonus {
    id: string;
    name: string;
    type: "FIXED" | "PERCENTAGE";
    value: number;
    amount: number;
}

interface PayrollAggregation {
    userId: string;
    email: string;
    firstName?: string;
    lastName?: string;
    bankAccountNumber?: string;
    baseSalary: number;
    walletBalance: number;
    eligibleBonuses: EligibleBonus[];
    totalAllowances: number;
    totalMedical: number;
    activeLoans: {
        id: string;
        currentEmi: number;
        carryForward: number;
        remainingPrincipal: number;
    }[];
    totalLoanDeduction: number;
    netPay: number; // Base net pay without bonuses
}

export function PayrollClient({
    initialData,
    month,
    year
}: {
    initialData: PayrollAggregation[],
    month: number,
    year: number
}) {
    const data = initialData;
    const [selectedBonuses, setSelectedBonuses] = useState<Record<string, string[]>>({});
    const [emiDisabledUsers, setEmiDisabledUsers] = useState<Set<string>>(new Set());
    const [processing, setProcessing] = useState(false);

    const handleToggleEmployeeEmi = (userId: string, enabled: boolean) => {
        setEmiDisabledUsers(prev => {
            const newSet = new Set(prev);
            if (enabled) {
                newSet.delete(userId); // EMI enabled, remove from disabled set
            } else {
                newSet.add(userId); // EMI disabled, add to disabled set
            }
            return newSet;
        });
    };

    const toggleBonus = (userId: string, bonusId: string) => {
        setSelectedBonuses(prev => {
            const userBonuses = prev[userId] || [];
            if (userBonuses.includes(bonusId)) {
                return { ...prev, [userId]: userBonuses.filter(id => id !== bonusId) };
            } else {
                return { ...prev, [userId]: [...userBonuses, bonusId] };
            }
        });
    };

    const calculateUserNetPay = (emp: PayrollAggregation) => {
        const bonusAmount = (selectedBonuses[emp.userId] || []).reduce((sum, bid) => {
            const b = emp.eligibleBonuses.find(eb => eb.id === bid);
            return sum + (b?.amount || 0);
        }, 0);
        
        // If EMI is disabled for this user, don't deduct EMI from net pay display
        const emiDeduction = emiDisabledUsers.has(emp.userId) ? 0 : emp.totalLoanDeduction;
        const adjustedNetPay = emp.baseSalary + emp.totalAllowances + emp.totalMedical - emiDeduction;
        
        return adjustedNetPay + bonusAmount + emp.walletBalance;
    };

    const generateAndDownloadCSV = (csvData: any[], filename: string) => {
        const headers = ['Employee Name', 'Account Number', 'Net Pay Amount'];
        const csvContent = [
            headers.join(','),
            ...csvData.map(row => [
                `"${row.employeeName}"`,
                `"${row.accountNumber}"`,
                row.netPayAmount
            ].join(','))
        ].join('\n');

        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        const url = URL.createObjectURL(blob);
        link.setAttribute('href', url);
        link.setAttribute('download', filename);
        link.style.visibility = 'hidden';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const handleProcessPayroll = async () => {
        const payrollMonth = `${year}-${month.toString().padStart(2, '0')}`;
        setProcessing(true);
        try {
            // 1. Generate CSV data BEFORE processing (when all employee data is available)
            const initialCsvData = await generatePayrollCSVData(data, selectedBonuses, Array.from(emiDisabledUsers));
            
            // 2. Process payroll with EMI disabled users info
            await processPayroll(payrollMonth, selectedBonuses, Array.from(emiDisabledUsers));
            
            // 3. Check for failed employees (employees still left after processing)
            const failedEmployeeIds = await getFailedEmployees(payrollMonth);
            
            // 4. Remove failed employees from CSV data (keep only successfully processed employees)
            const finalCsvData = initialCsvData.filter(row => !failedEmployeeIds.includes(row.userId));
            
            // 5. Download CSV file with only successfully processed employees
            const fileName = `payroll-${payrollMonth}-${new Date().toISOString().split('T')[0]}.csv`;
            generateAndDownloadCSV(finalCsvData, fileName);
            
            const processedCount = finalCsvData.length;
            const failedCount = failedEmployeeIds.length;
            
            if (failedCount > 0) {
                toast.success(`Payroll processed: ${processedCount} successful, ${failedCount} failed. CSV contains only successful employees.`);
            } else {
                toast.success(`Payroll for ${payrollMonth} processed successfully. CSV file downloaded.`);
            }
        } catch (error: unknown) {
            toast.error((error instanceof Error) ? error.message : "Failed to process payroll");
        } finally {
            setProcessing(false);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center bg-white p-4 rounded-lg border shadow-sm">
                <div>
                    <h2 className="text-xl font-bold">Review for {month}/{year}</h2>
                    <p className="text-sm text-muted-foreground">Adjust bonuses and EMI states before final commit.</p>
                </div>
                <Button
                    size="lg"
                    onClick={handleProcessPayroll}
                    disabled={processing || data.length === 0}
                    className="bg-green-600 hover:bg-green-700"
                >
                    {processing ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <DollarSign className="mr-2 h-4 w-4" />}
                    Finalize & Process
                </Button>
            </div>

            <div className="border rounded-lg bg-white shadow-sm overflow-hidden text-sm">
                <Table>
                    <TableHeader>
                        <TableRow className="bg-muted/50">
                            <TableHead className="font-semibold">Employee</TableHead>
                            <TableHead className="font-semibold text-right">Base</TableHead>
                            <TableHead className="font-semibold text-right">Allowances</TableHead>
                            <TableHead className="font-semibold text-right">Medical</TableHead>
                            <TableHead className="font-semibold text-right">Bonuses</TableHead>
                            <TableHead className="font-semibold text-right">Deductions</TableHead>
                            <TableHead className="font-semibold text-right">Wallet</TableHead>
                            <TableHead className="font-semibold">EMI Ctrl</TableHead>
                            <TableHead className="font-semibold text-right text-green-700">Net Pay</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {data.length === 0 ? (
                            <TableRow>
                                <TableCell colSpan={9} className="h-32 text-center text-muted-foreground italic">
                                    No approved employees found for this period.
                                </TableCell>
                            </TableRow>
                        ) : (
                            data.map((emp) => (
                                <TableRow key={emp.userId} className="hover:bg-muted/30 transition-colors">
                                    <TableCell className="font-medium">{emp.email}</TableCell>
                                    <TableCell className="text-right tabular-nums">αº│{emp.baseSalary.toLocaleString("en-BD")}</TableCell>
                                    <TableCell className="text-right tabular-nums text-blue-600">
                                        +αº│{emp.totalAllowances.toLocaleString("en-BD")}
                                    </TableCell>
                                    <TableCell className="text-right tabular-nums text-indigo-600">
                                        +αº│{emp.totalMedical.toLocaleString("en-BD")}
                                    </TableCell>
                                    <TableCell className="text-right">
                                        <Dialog>
                                            <DialogTrigger asChild>
                                                <Button variant="outline" size="sm" className="h-7 text-[11px] px-2">
                                                    <Gift className="mr-1 h-3 w-3" />
                                                    Manage ({selectedBonuses[emp.userId]?.length || 0})
                                                </Button>
                                            </DialogTrigger>
                                            <DialogContent>
                                                <DialogHeader>
                                                    <DialogTitle>Bonuses for {emp.email}</DialogTitle>
                                                </DialogHeader>
                                                <div className="space-y-4 py-4">
                                                    {emp.eligibleBonuses.length === 0 ? (
                                                        <p className="text-center text-muted-foreground italic py-4">No eligible bonuses found for this branch.</p>
                                                    ) : (
                                                        emp.eligibleBonuses.map(bonus => (
                                                            <div key={bonus.id} className="flex items-center justify-between p-3 border rounded-lg hover:bg-muted/50 transition-colors">
                                                                <div className="flex items-center gap-3">
                                                                    <Checkbox
                                                                        id={`bonus-${emp.userId}-${bonus.id}`}
                                                                        checked={(selectedBonuses[emp.userId] || []).includes(bonus.id)}
                                                                        onCheckedChange={() => toggleBonus(emp.userId, bonus.id)}
                                                                    />
                                                                    <label htmlFor={`bonus-${emp.userId}-${bonus.id}`} className="flex flex-col cursor-pointer">
                                                                        <span className="font-semibold text-sm">{bonus.name}</span>
                                                                        <span className="text-[10px] text-muted-foreground">{bonus.type} ({bonus.value}{bonus.type === "PERCENTAGE" ? "%" : " FIXED"})</span>
                                                                    </label>
                                                                </div>
                                                                <div className="font-bold text-green-600">
                                                                    αº│{bonus.amount.toLocaleString("en-BD")}
                                                                </div>
                                                            </div>
                                                        ))
                                                    )}
                                                </div>
                                            </DialogContent>
                                        </Dialog>
                                    </TableCell>
                                    <TableCell className="text-right tabular-nums text-destructive">
                                        <div className="flex flex-col items-end">
                                            <span>-αº│{(emiDisabledUsers.has(emp.userId) ? 0 : emp.totalLoanDeduction).toLocaleString("en-BD")}</span>
                                            {emp.activeLoans.some(l => l.carryForward > 0) && (
                                                <span className="text-[9px] text-orange-600 font-bold uppercase">CF Active</span>
                                            )}
                                        </div>
                                    </TableCell>
                                    <TableCell className="text-right tabular-nums">
                                        <span className={emp.walletBalance >= 0 ? "text-blue-600" : "text-red-600"}>
                                            {emp.walletBalance >= 0 ? "+" : ""}αº│{emp.walletBalance.toLocaleString("en-BD")}
                                        </span>
                                    </TableCell>
                                    <TableCell>
                                        <div className="flex items-center justify-center">
                                            {emp.activeLoans.length > 0 ? (
                                                <div className="flex items-center gap-2">
                                                    <Switch
                                                        checked={!emiDisabledUsers.has(emp.userId)}
                                                        onCheckedChange={(checked) => handleToggleEmployeeEmi(emp.userId, checked)}
                                                    />
                                                    <span className={`text-[10px] font-medium ${
                                                        emiDisabledUsers.has(emp.userId) 
                                                            ? 'text-orange-600' 
                                                            : 'text-green-600'
                                                    }`}>
                                                        {emiDisabledUsers.has(emp.userId) ? 'OFF' : 'ON'}
                                                    </span>
                                                </div>
                                            ) : (
                                                <span className="text-[10px] text-muted-foreground italic">No Loans</span>
                                            )}
                                        </div>
                                    </TableCell>
                                    <TableCell className="text-right tabular-nums font-bold text-green-700 text-base">
                                        αº│{calculateUserNetPay(emp).toLocaleString("en-BD")}
                                    </TableCell>
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import { Search, Eye, Calendar, DollarSign, Users, TrendingUp } from "lucide-react";

type ProcessedPayroll = {
    id: string;
    month: string;
    baseSalary: number;
    totalBonuses: number;
    totalAllowances: number;
    medicalReimbursement: number;
    loanDeduction: number;
    walletAdjustment: number;
    netAmount: number;
    createdAt: Date;
    user: {
        id: string;
        firstName: string | null;
        lastName: string | null;
        email: string;
        bankAccountNumber: string | null;
        branch: { name: string } | null;
        department: { name: string } | null;
        designation: { name: string } | null;
    };
};

interface ProcessedPayrollClientProps {
    data: ProcessedPayroll[];
}

export function ProcessedPayrollClient({ data }: ProcessedPayrollClientProps) {
    const [searchTerm, setSearchTerm] = useState("");
    const [selectedMonth, setSelectedMonth] = useState<string>("all");
    const [selectedPayroll, setSelectedPayroll] = useState<ProcessedPayroll | null>(null);
    const [isDetailOpen, setIsDetailOpen] = useState(false);

    // Get unique months from data
    const uniqueMonths = Array.from(new Set(data.map(p => p.month))).sort().reverse();

    // Filter data
    const filteredData = data.filter(payroll => {
        const matchesSearch = 
            payroll.user.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            payroll.user.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            payroll.user.email.toLowerCase().includes(searchTerm.toLowerCase());
        
        const matchesMonth = selectedMonth === "all" || payroll.month === selectedMonth;

        return matchesSearch && matchesMonth;
    });

    // Calculate summary stats
    const totalPaid = filteredData.reduce((sum, p) => sum + p.netAmount, 0);
    const totalEmployees = new Set(filteredData.map(p => p.user.id)).size;

    const formatMonth = (monthStr: string) => {
        const [year, month] = monthStr.split('-');
        const date = new Date(parseInt(year), parseInt(month) - 1);
        return date.toLocaleDateString('en-US', { year: 'numeric', month: 'long' });
    };

    const handleViewDetails = (payroll: ProcessedPayroll) => {
        setSelectedPayroll(payroll);
        setIsDetailOpen(true);
    };

    return (
        <div className="space-y-6">
            {/* Summary Cards */}
            <div className="grid gap-4 md:grid-cols-3">
                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Total Payments</CardTitle>
                        <Calendar className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{filteredData.length}</div>
                        <p className="text-xs text-muted-foreground">Salary payments processed</p>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Total Amount Paid</CardTitle>
                        <DollarSign className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">αº│{totalPaid.toLocaleString("en-BD")}</div>
                        <p className="text-xs text-muted-foreground">Cumulative payroll</p>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Employees Paid</CardTitle>
                        <Users className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{totalEmployees}</div>
                        <p className="text-xs text-muted-foreground">Unique employees</p>
                    </CardContent>
                </Card>
            </div>

            {/* Filters */}
            <Card>
                <CardHeader>
                    <CardTitle>Filters</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="flex flex-col sm:flex-row gap-4">
                        <div className="flex-1 relative">
                            <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                            <Input
                                placeholder="Search by employee name or email..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="pl-9"
                            />
                        </div>
                        <Select value={selectedMonth} onValueChange={setSelectedMonth}>
                            <SelectTrigger className="w-full sm:w-[200px]">
                                <SelectValue placeholder="Select month" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">All Months</SelectItem>
                                {uniqueMonths.map((month) => (
                                    <SelectItem key={month} value={month}>
                                        {formatMonth(month)}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>
                </CardContent>
            </Card>

            {/* Payroll Table */}
            <Card>
                <CardHeader>
                    <CardTitle>Processed Payroll Records</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="border rounded-md overflow-hidden">
                        <Table>
                            <TableHeader>
                                <TableRow className="bg-muted/50">
                                    <TableHead>Employee</TableHead>
                                    <TableHead>Email</TableHead>
                                    <TableHead>Department</TableHead>
                                    <TableHead>Month</TableHead>
                                    <TableHead>Processed Date</TableHead>
                                    <TableHead className="text-right">Net Amount</TableHead>
                                    <TableHead className="text-center">Actions</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {filteredData.length === 0 ? (
                                    <TableRow>
                                        <TableCell colSpan={7} className="h-32 text-center text-muted-foreground">
                                            No processed payroll records found.
                                        </TableCell>
                                    </TableRow>
                                ) : (
                                    filteredData.map((payroll) => (
                                        <TableRow key={payroll.id} className="hover:bg-muted/30 transition-colors">
                                            <TableCell className="font-medium">
                                                {payroll.user.firstName && payroll.user.lastName
                                                    ? `${payroll.user.firstName} ${payroll.user.lastName}`
                                                    : "N/A"}
                                            </TableCell>
                                            <TableCell className="text-muted-foreground">
                                                {payroll.user.email}
                                            </TableCell>
                                            <TableCell>
                                                {payroll.user.department?.name || "N/A"}
                                            </TableCell>
                                            <TableCell className="font-medium">
                                                {formatMonth(payroll.month)}
                                            </TableCell>
                                            <TableCell className="text-muted-foreground">
                                                {new Date(payroll.createdAt).toLocaleDateString('en-US', {
                                                    year: 'numeric',
                                                    month: 'short',
                                                    day: 'numeric'
                                                })}
                                            </TableCell>
                                            <TableCell className="text-right font-bold">
                                                αº│{payroll.netAmount.toLocaleString("en-BD")}
                                            </TableCell>
                                            <TableCell className="text-center">
                                                <Button
                                                    variant="ghost"
                                                    size="sm"
                                                    onClick={() => handleViewDetails(payroll)}
                                                >
                                                    <Eye className="h-4 w-4 mr-1" />
                                                    Details
                                                </Button>
                                            </TableCell>
                                        </TableRow>
                                    ))
                                )}
                            </TableBody>
                        </Table>
                    </div>
                </CardContent>
            </Card>

            {/* Details Dialog */}
            <Dialog open={isDetailOpen} onOpenChange={setIsDetailOpen}>
                <DialogContent className="max-w-2xl">
                    <DialogHeader>
                        <DialogTitle>Payroll Details</DialogTitle>
                        <DialogDescription>
                            Complete breakdown for {selectedPayroll?.user.firstName} {selectedPayroll?.user.lastName}
                        </DialogDescription>
                    </DialogHeader>
                    
                    {selectedPayroll && (
                        <div className="space-y-6">
                            {/* Employee Info */}
                            <div className="grid grid-cols-2 gap-4 p-4 bg-muted/50 rounded-lg">
                                <div>
                                    <p className="text-sm text-muted-foreground">Employee</p>
                                    <p className="font-medium">
                                        {selectedPayroll.user.firstName} {selectedPayroll.user.lastName}
                                    </p>
                                </div>
                                <div>
                                    <p className="text-sm text-muted-foreground">Email</p>
                                    <p className="font-medium">{selectedPayroll.user.email}</p>
                                </div>
                                <div>
                                    <p className="text-sm text-muted-foreground">Department</p>
                                    <p className="font-medium">{selectedPayroll.user.department?.name || "N/A"}</p>
                                </div>
                                <div>
                                    <p className="text-sm text-muted-foreground">Designation</p>
                                    <p className="font-medium">{selectedPayroll.user.designation?.name || "N/A"}</p>
                                </div>
                                <div>
                                    <p className="text-sm text-muted-foreground">Branch</p>
                                    <p className="font-medium">{selectedPayroll.user.branch?.name || "N/A"}</p>
                                </div>
                                <div>
                                    <p className="text-sm text-muted-foreground">Bank Account</p>
                                    <p className="font-medium">{selectedPayroll.user.bankAccountNumber || "N/A"}</p>
                                </div>
                            </div>

                            {/* Payment Info */}
                            <div className="space-y-3">
                                <div className="flex justify-between items-center pb-2 border-b">
                                    <span className="text-sm text-muted-foreground">Month</span>
                                    <span className="font-medium">{formatMonth(selectedPayroll.month)}</span>
                                </div>
                                <div className="flex justify-between items-center pb-2 border-b">
                                    <span className="text-sm text-muted-foreground">Processed Date</span>
                                    <span className="font-medium">
                                        {new Date(selectedPayroll.createdAt).toLocaleDateString('en-US', {
                                            year: 'numeric',
                                            month: 'long',
                                            day: 'numeric',
                                            hour: '2-digit',
                                            minute: '2-digit'
                                        })}
                                    </span>
                                </div>
                            </div>

                            {/* Salary Breakdown */}
                            <div className="space-y-3">
                                <h4 className="font-semibold flex items-center gap-2">
                                    <TrendingUp className="h-4 w-4" />
                                    Salary Breakdown
                                </h4>
                                
                                <div className="space-y-2">
                                    <div className="flex justify-between items-center py-2">
                                        <span className="text-sm">Base Salary</span>
                                        <span className="font-medium">
                                            αº│{selectedPayroll.baseSalary.toLocaleString("en-BD")}
                                        </span>
                                    </div>
                                    
                                    <div className="flex justify-between items-center py-2 text-green-600">
                                        <span className="text-sm">+ Allowances</span>
                                        <span className="font-medium">
                                            αº│{selectedPayroll.totalAllowances.toLocaleString("en-BD")}
                                        </span>
                                    </div>
                                    
                                    <div className="flex justify-between items-center py-2 text-green-600">
                                        <span className="text-sm">+ Bonuses</span>
                                        <span className="font-medium">
                                            αº│{selectedPayroll.totalBonuses.toLocaleString("en-BD")}
                                        </span>
                                    </div>
                                    
                                    <div className="flex justify-between items-center py-2 text-green-600">
                                        <span className="text-sm">+ Medical Reimbursement</span>
                                        <span className="font-medium">
                                            αº│{selectedPayroll.medicalReimbursement.toLocaleString("en-BD")}
                                        </span>
                                    </div>
                                    
                                    <div className="flex justify-between items-center py-2 text-red-600">
                                        <span className="text-sm">ΓêÆ Loan Deduction</span>
                                        <span className="font-medium">
                                            αº│{selectedPayroll.loanDeduction.toLocaleString("en-BD")}
                                        </span>
                                    </div>
                                    
                                    {selectedPayroll.walletAdjustment !== 0 && (
                                        <div className={`flex justify-between items-center py-2 ${
                                            selectedPayroll.walletAdjustment > 0 ? 'text-green-600' : 'text-red-600'
                                        }`}>
                                            <span className="text-sm">
                                                {selectedPayroll.walletAdjustment > 0 ? '+' : 'ΓêÆ'} Wallet Adjustment
                                            </span>
                                            <span className="font-medium">
                                                αº│{Math.abs(selectedPayroll.walletAdjustment).toLocaleString("en-BD")}
                                            </span>
                                        </div>
                                    )}
                                    
                                    <div className="flex justify-between items-center py-3 border-t-2 border-gray-300 mt-2">
                                        <span className="font-bold">Net Amount</span>
                                        <span className="font-bold text-lg text-primary">
                                            αº│{selectedPayroll.netAmount.toLocaleString("en-BD")}
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    )}
                </DialogContent>
            </Dialog>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { approveProfileUpdateRequest, rejectProfileUpdateRequest } from "@/actions/profile.actions";
import { format } from "date-fns";
import { Check, X, Clock, User, Calendar, Loader2 } from "lucide-react";

interface ProfileUpdateRequestWithUser {
  id: string;
  userId: string;
  status: string;
  requestedChanges: any;
  previousValues: any;
  createdAt: Date;
  updatedAt: Date;
  user: {
    id: string;
    firstName: string | null;
    lastName: string | null;
    email: string;
    imageUrl: string | null;
    role: string;
  };
}

interface ProfileUpdateRequestsListProps {
  requests: ProfileUpdateRequestWithUser[];
  onUpdate: () => void;
}

export function ProfileUpdateRequestsList({ requests, onUpdate }: ProfileUpdateRequestsListProps) {
  const [selectedRequest, setSelectedRequest] = useState<ProfileUpdateRequestWithUser | null>(null);
  const [showApproveDialog, setShowApproveDialog] = useState(false);
  const [showRejectDialog, setShowRejectDialog] = useState(false);
  const [reviewNotes, setReviewNotes] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);

  const handleApprove = async () => {
    if (!selectedRequest) return;

    setIsProcessing(true);
    try {
      const result = await approveProfileUpdateRequest(selectedRequest.id, reviewNotes);
      if (result.success) {
        toast.success("Profile update request approved");
        setShowApproveDialog(false);
        setSelectedRequest(null);
        setReviewNotes("");
        onUpdate();
      } else {
        toast.error(result.error || "Failed to approve request");
      }
    } catch (error) {
      toast.error("An error occurred");
      console.error(error);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleReject = async () => {
    if (!selectedRequest || !reviewNotes.trim()) {
      toast.error("Please provide a reason for rejection");
      return;
    }

    setIsProcessing(true);
    try {
      const result = await rejectProfileUpdateRequest(selectedRequest.id, reviewNotes);
      if (result.success) {
        toast.success("Profile update request rejected");
        setShowRejectDialog(false);
        setSelectedRequest(null);
        setReviewNotes("");
        onUpdate();
      } else {
        toast.error(result.error || "Failed to reject request");
      }
    } catch (error) {
      toast.error("An error occurred");
      console.error(error);
    } finally {
      setIsProcessing(false);
    }
  };

  if (requests.length === 0) {
    return (
      <Card>
        <CardContent className="py-10">
          <div className="text-center text-muted-foreground">
            <Clock className="h-12 w-12 mx-auto mb-4 opacity-50" />
            <p>No pending profile update requests</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <>
      <div className="space-y-4">
        {requests.map((request) => (
          <Card key={request.id}>
            <CardHeader>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <div className="h-12 w-12 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center text-white font-bold">
                    {request.user.firstName?.[0]}{request.user.lastName?.[0]}
                  </div>
                  <div>
                    <CardTitle className="text-lg">
                      {request.user.firstName} {request.user.lastName}
                    </CardTitle>
                    <CardDescription>
                      <div className="flex items-center gap-2 mt-1">
                        <User className="h-3 w-3" />
                        {request.user.email}
                        <span className="mx-2">ΓÇó</span>
                        <Calendar className="h-3 w-3" />
                        {format(new Date(request.createdAt), "PPP")}
                      </div>
                    </CardDescription>
                  </div>
                </div>
                <div className="flex gap-2">
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => {
                      setSelectedRequest(request);
                      setShowApproveDialog(true);
                    }}
                  >
                    <Check className="h-4 w-4 mr-1" />
                    Approve
                  </Button>
                  <Button
                    size="sm"
                    variant="destructive"
                    onClick={() => {
                      setSelectedRequest(request);
                      setShowRejectDialog(true);
                    }}
                  >
                    <X className="h-4 w-4 mr-1" />
                    Reject
                  </Button>
                </div>
              </div>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                <div>
                  <h4 className="font-semibold mb-2 text-sm">Requested Changes:</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3 text-sm">
                    {Object.entries(request.requestedChanges as Record<string, any>).map(([key, value]) => {
                      if (!value) return null;
                      const previousValue = request.previousValues?.[key];
                      
                      return (
                        <div key={key} className="border rounded-lg p-3">
                          <p className="font-medium text-muted-foreground capitalize mb-1">
                            {key.replace(/([A-Z])/g, " $1").trim()}
                          </p>
                          <div className="space-y-1">
                            {previousValue && (
                              <p className="text-xs text-muted-foreground line-through">
                                {formatValue(previousValue)}
                              </p>
                            )}
                            <p className="font-medium text-green-600">
                              {formatValue(value)}
                            </p>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Approve Dialog */}
      <Dialog open={showApproveDialog} onOpenChange={setShowApproveDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Approve Profile Update</DialogTitle>
            <DialogDescription>
              Are you sure you want to approve this profile update request from{" "}
              {selectedRequest?.user.firstName} {selectedRequest?.user.lastName}?
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-2">
            <Label htmlFor="approve-notes">Review Notes (Optional)</Label>
            <Textarea
              id="approve-notes"
              placeholder="Add any notes about this approval..."
              value={reviewNotes}
              onChange={(e) => setReviewNotes(e.target.value)}
              rows={3}
            />
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setShowApproveDialog(false);
                setReviewNotes("");
              }}
              disabled={isProcessing}
            >
              Cancel
            </Button>
            <Button onClick={handleApprove} disabled={isProcessing}>
              {isProcessing && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Approve
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Reject Dialog */}
      <Dialog open={showRejectDialog} onOpenChange={setShowRejectDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Reject Profile Update</DialogTitle>
            <DialogDescription>
              Please provide a reason for rejecting this profile update request from{" "}
              {selectedRequest?.user.firstName} {selectedRequest?.user.lastName}.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-2">
            <Label htmlFor="reject-notes">Rejection Reason *</Label>
            <Textarea
              id="reject-notes"
              placeholder="Explain why this request is being rejected..."
              value={reviewNotes}
              onChange={(e) => setReviewNotes(e.target.value)}
              rows={4}
              required
            />
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setShowRejectDialog(false);
                setReviewNotes("");
              }}
              disabled={isProcessing}
            >
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={handleReject}
              disabled={isProcessing || !reviewNotes.trim()}
            >
              {isProcessing && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Reject
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

function formatValue(value: any): string {
  if (value === null || value === undefined) return "Not provided";
  if (typeof value === "boolean") return value ? "Yes" : "No";
  if (value instanceof Date || (typeof value === "string" && !isNaN(Date.parse(value)))) {
    try {
      return format(new Date(value), "PPP");
    } catch {
      return String(value);
    }
  }
  return String(value);
}

"use client";

import React, { useState, useMemo, useTransition } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
    Search,
    Crown,
    Shield,
    Users,
    Archive,
    MoreHorizontal,
    ArchiveRestore,
    CheckCircle,
    XCircle,
    Settings,
} from "lucide-react";
import { toast } from "sonner";
import { changeUserRole, toggleUserArchiveStatus, toggleManagerStatus } from "@/actions/user.actions";
import { Role, UserStatus } from "@prisma/client";

interface User {
    id: string;
    clerkId: string;
    email: string;
    firstName: string | null;
    lastName: string | null;
    name: string;
    imageUrl: string | null;
    role: Role;
    isManager: boolean;
    status: UserStatus;
    employeeStatus: string | null;
    isArchived: boolean;
    dateOfJoining: Date | null;
    createdAt: Date;
    updatedAt: Date;
    branch?: {
        id: string;
        name: string;
    } | null;
    department?: {
        id: string;
        name: string;
    } | null;
    designation?: {
        id: string;
        name: string;
    } | null;
}

interface RoleManagementClientProps {
    users: User[];
}

export function RoleManagementClient({ users }: RoleManagementClientProps) {
    const [searchTerm, setSearchTerm] = useState("");
    const [selectedRole, setSelectedRole] = useState<string>("all");
    const [selectedStatus, setSelectedStatus] = useState<string>("all");
    const [selectedUsers, setSelectedUsers] = useState<string[]>([]);
    const [bulkRole, setBulkRole] = useState<Role | "">("");
    const [showArchived, setShowArchived] = useState(false);
    const [isPending, startTransition] = useTransition();

    // Filter users
    const filteredUsers = useMemo(() => {
        return users.filter(user => {
            const matchesSearch = 
                user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                user.email.toLowerCase().includes(searchTerm.toLowerCase());
            const matchesRole = selectedRole === "all" || user.role === selectedRole;
            const matchesStatus = 
                selectedStatus === "all" || 
                (selectedStatus === "PENDING" && user.status === "PENDING") ||
                (selectedStatus === "ACTIVE" && user.status === "APPROVED");
            const matchesArchive = showArchived || !user.isArchived;
            return matchesSearch && matchesRole && matchesStatus && matchesArchive;
        });
    }, [users, searchTerm, selectedRole, selectedStatus, showArchived]);

    // Role statistics
    const roleStats = useMemo(() => {
        const stats = {
            SUPERADMIN: 0,
            HR: 0,
            EMPLOYEE: 0,
            MANAGERS: 0,
            total: users.filter(u => !u.isArchived).length,
            archived: users.filter(u => u.isArchived).length,
            pending: users.filter(u => u.status === "PENDING" && !u.isArchived).length,
        };
        
        users.filter(u => !u.isArchived).forEach(user => {
            if (['SUPERADMIN', 'HR', 'EMPLOYEE'].includes(user.role)) {
                stats[user.role]++;
            }
            if (user.role === "EMPLOYEE" && user.isManager) {
                stats.MANAGERS++;
            }
        });

        return stats;
    }, [users]);

    // Handle single role change
    const handleRoleChange = async (userId: string, newRole: Role) => {
        startTransition(async () => {
            try {
                const result = await changeUserRole(userId, newRole);
                if (result.success) {
                    toast.success(result.message || "User role changed successfully");
                } else {
                    toast.error(result.error || "Failed to change role");
                }
            } catch (error) {
                toast.error("An unexpected error occurred");
            }
        });
    };

    // Handle bulk role change
    const handleBulkRoleChange = async () => {
        if (!bulkRole || selectedUsers.length === 0) return;

        startTransition(async () => {
            try {
                const promises = selectedUsers.map(userId => 
                    changeUserRole(userId, bulkRole as Role)
                );
                await Promise.all(promises);
                
                toast.success(`${selectedUsers.length} users updated successfully`);
                setSelectedUsers([]);
                setBulkRole("");
            } catch (error) {
                toast.error("Failed to update users");
            }
        });
    };

    // Handle archive toggle
    const handleArchiveToggle = async (userId: string) => {
        startTransition(async () => {
            try {
                const result = await toggleUserArchiveStatus(userId);
                if (result.success) {
                    toast.success(result.message);
                } else {
                    toast.error(result.error || "Failed to update user");
                }
            } catch (error) {
                toast.error("An unexpected error occurred");
            }
        });
    };

    // Handle manager toggle
    const handleManagerToggle = async (userId: string) => {
        startTransition(async () => {
            try {
                const result = await toggleManagerStatus(userId);
                if (result.success) {
                    toast.success(result.message);
                } else {
                    toast.error(result.error || "Failed to update manager status");
                }
            } catch (error) {
                toast.error("An unexpected error occurred");
            }
        });
    };

    // Handle checkbox selection
    const handleUserSelection = (userId: string, checked: boolean) => {
        if (checked) {
            setSelectedUsers([...selectedUsers, userId]);
        } else {
            setSelectedUsers(selectedUsers.filter(id => id !== userId));
        }
    };

    // Role color and icon mapping
    const getRoleDisplay = (role: Role) => {
        const config = {
            SUPERADMIN: { color: "destructive", icon: Crown, label: "Super Admin" },
            HR: { color: "secondary", icon: Shield, label: "HR Specialist" },
            EMPLOYEE: { color: "outline", icon: Users, label: "Employee" },
        } as const;

        return config[role] || config.EMPLOYEE;
    };

    return (
        <div className="space-y-6 p-6">
            <h1 className="text-2xl font-bold">User Role Management</h1>
            
            {/* Role Statistics Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Total Users</CardTitle>
                        <Users className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{roleStats.total}</div>
                        <p className="text-xs text-muted-foreground">
                            Active users
                        </p>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Super Admins</CardTitle>
                        <Crown className="h-4 w-4 text-red-600" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{roleStats.SUPERADMIN}</div>
                        <p className="text-xs text-muted-foreground">
                            Full system access
                        </p>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">HR Specialists</CardTitle>
                        <Shield className="h-4 w-4 text-green-600" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{roleStats.HR}</div>
                        <p className="text-xs text-muted-foreground">
                            HR management access
                        </p>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Employees</CardTitle>
                        <Users className="h-4 w-4 text-blue-600" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{roleStats.EMPLOYEE}</div>
                        <p className="text-xs text-muted-foreground">
                            Regular access
                        </p>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Managers</CardTitle>
                        <Settings className="h-4 w-4 text-purple-600" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{roleStats.MANAGERS}</div>
                        <p className="text-xs text-muted-foreground">
                            Team management access
                        </p>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Archived</CardTitle>
                        <Archive className="h-4 w-4 text-orange-600" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{roleStats.archived}</div>
                        <p className="text-xs text-muted-foreground">
                            Archived users
                        </p>
                    </CardContent>
                </Card>
            </div>

            {/* Search and Filters */}
            <div className="flex flex-col lg:flex-row gap-4">
                <div className="flex-1">
                    <div className="relative">
                        <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                        <Input
                            placeholder="Search by name or email..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="pl-8"
                        />
                    </div>
                </div>
                
                <Select value={selectedRole} onValueChange={setSelectedRole}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Filter by role" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">All Roles</SelectItem>
                        <SelectItem value="SUPERADMIN">Super Admin</SelectItem>
                        <SelectItem value="HR">HR Specialist</SelectItem>
                        <SelectItem value="EMPLOYEE">Employee</SelectItem>
                    </SelectContent>
                </Select>

                <Select value={selectedStatus} onValueChange={setSelectedStatus}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Filter by status" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">All Status</SelectItem>
                        <SelectItem value="ACTIVE">Active</SelectItem>
                        <SelectItem value="PENDING">Pending</SelectItem>
                    </SelectContent>
                </Select>

                <Button
                    variant={showArchived ? "default" : "outline"}
                    onClick={() => setShowArchived(!showArchived)}
                    className="whitespace-nowrap"
                >
                    {showArchived ? "Hide Archived" : "Show Archived"}
                </Button>
            </div>

            {/* Bulk Actions */}
            {selectedUsers.length > 0 && (
                <div className="flex items-center gap-2 p-3 bg-blue-50 border border-blue-200 rounded-lg">
                    <span className="text-sm text-blue-700">
                        {selectedUsers.length} users selected
                    </span>
                    <Select 
                        value={bulkRole} 
                        onValueChange={(value: Role) => setBulkRole(value)}
                    >
                        <SelectTrigger className="w-[180px]">
                            <SelectValue placeholder="Change role to..." />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="SUPERADMIN">Super Admin</SelectItem>
                            <SelectItem value="HR">HR Specialist</SelectItem>
                            <SelectItem value="EMPLOYEE">Employee</SelectItem>
                        </SelectContent>
                    </Select>
                    <Button
                        onClick={handleBulkRoleChange}
                        disabled={!bulkRole || isPending}
                    >
                        Apply Changes
                    </Button>
                    <Button
                        variant="outline"
                        onClick={() => setSelectedUsers([])}
                    >
                        Clear Selection
                    </Button>
                </div>
            )}

            {/* Users Table */}
            <Card>
                <CardHeader>
                    <CardTitle>Users ({filteredUsers.length})</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="overflow-x-auto">
                        <table className="w-full border-collapse">
                            <thead>
                                <tr className="border-b">
                                    <th className="text-left p-2">
                                        <input
                                            type="checkbox"
                                            checked={selectedUsers.length === filteredUsers.length && filteredUsers.length > 0}
                                            onChange={(e) => {
                                                if (e.target.checked) {
                                                    setSelectedUsers(filteredUsers.map(u => u.id));
                                                } else {
                                                    setSelectedUsers([]);
                                                }
                                            }}
                                        />
                                    </th>
                                    <th className="text-left p-2">User</th>
                                    <th className="text-left p-2">Role</th>
                                    <th className="text-left p-2">Status</th>
                                    <th className="text-left p-2">Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredUsers.map((user) => {
                                    const roleDisplay = getRoleDisplay(user.role);
                                    const RoleIcon = roleDisplay.icon;
                                    
                                    return (
                                        <tr key={user.id} className={`border-b hover:bg-gray-50 ${user.isArchived ? 'opacity-50' : ''}`}>
                                            <td className="p-2">
                                                <input
                                                    type="checkbox"
                                                    checked={selectedUsers.includes(user.id)}
                                                    onChange={(e) => handleUserSelection(user.id, e.target.checked)}
                                                />
                                            </td>
                                            <td className="p-2">
                                                <div>
                                                    <div className="font-medium">{user.name}</div>
                                                    <div className="text-sm text-gray-500">{user.email}</div>
                                                </div>
                                            </td>
                                            <td className="p-2">
                                                <div className="flex items-center space-x-2">
                                                    <Badge variant={roleDisplay.color as any} className="gap-1">
                                                        <RoleIcon className="h-3 w-3" />
                                                        {roleDisplay.label}
                                                    </Badge>
                                                    {user.role === "EMPLOYEE" && user.isManager && (
                                                        <Badge variant="outline" className="gap-1 text-xs">
                                                            <Settings className="h-3 w-3" />
                                                            Manager
                                                        </Badge>
                                                    )}
                                                </div>
                                            </td>
                                            <td className="p-2">
                                                <Badge variant={user.status === "APPROVED" ? "default" : "secondary"}>
                                                    {user.status === "APPROVED" ? (
                                                        <>
                                                            <CheckCircle className="mr-1 h-3 w-3" />
                                                            Active
                                                        </>
                                                    ) : (
                                                        <>
                                                            <XCircle className="mr-1 h-3 w-3" />
                                                            Pending
                                                        </>
                                                    )}
                                                </Badge>
                                            </td>
                                            <td className="p-2">
                                                <DropdownMenu>
                                                    <DropdownMenuTrigger asChild>
                                                        <Button variant="ghost" size="sm">
                                                            <MoreHorizontal className="h-4 w-4" />
                                                        </Button>
                                                    </DropdownMenuTrigger>
                                                    <DropdownMenuContent align="end">
                                                        <DropdownMenuItem
                                                            onClick={() => handleRoleChange(user.id, "EMPLOYEE")}
                                                            disabled={user.role === "EMPLOYEE"}
                                                        >
                                                            <Users className="mr-2 h-4 w-4" />
                                                            Make Employee
                                                        </DropdownMenuItem>
                                                        <DropdownMenuItem
                                                            onClick={() => handleRoleChange(user.id, "HR")}
                                                            disabled={user.role === "HR"}
                                                        >
                                                            <Shield className="mr-2 h-4 w-4" />
                                                            Make HR Specialist
                                                        </DropdownMenuItem>
                                                        <DropdownMenuItem
                                                            onClick={() => handleRoleChange(user.id, "SUPERADMIN")}
                                                            disabled={user.role === "SUPERADMIN"}
                                                        >
                                                            <Crown className="mr-2 h-4 w-4" />
                                                            Make Super Admin
                                                        </DropdownMenuItem>
                                                        <DropdownMenuSeparator />
                                                        {user.role === "EMPLOYEE" && (
                                                            <DropdownMenuItem
                                                                onClick={() => handleManagerToggle(user.id)}
                                                            >
                                                                <Settings className="mr-2 h-4 w-4" />
                                                                {user.isManager ? "Remove Manager Status" : "Make Manager"}
                                                            </DropdownMenuItem>
                                                        )}
                                                        <DropdownMenuSeparator />
                                                        <DropdownMenuItem
                                                            onClick={() => handleArchiveToggle(user.id)}
                                                        >
                                                            {user.isArchived ? (
                                                                <>
                                                                    <ArchiveRestore className="mr-2 h-4 w-4" />
                                                                    Restore User
                                                                </>
                                                            ) : (
                                                                <>
                                                                    <Archive className="mr-2 h-4 w-4" />
                                                                    Archive User
                                                                </>
                                                            )}
                                                        </DropdownMenuItem>
                                                    </DropdownMenuContent>
                                                </DropdownMenu>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { CalendarDays, Clock, Users, Filter, Download, RefreshCw, RotateCcw } from "lucide-react";
import { format } from "date-fns";
import TimelineTableView from "@/components/admin/TimelineTableView";
import TimelineCalendarView from "@/components/admin/TimelineCalendarView";
import TimelineFilters from "@/components/admin/TimelineFilters";
import { getTimelineRecords } from "@/actions/timeline.actions";
import { getBranches } from "@/actions/branch.actions";
import { getUsers } from "@/actions/user.actions";
import { toast } from "sonner";

interface TimeRecord {
  id: string;
  date: Date;
  status: "PRESENT" | "ABSENT" | "ON_LEAVE" | "WEEKLY_OFF";
  requiredCheckIn: Date | null;
  requiredCheckOut: Date | null;
  requiredBreakTime: string | null;
  actualCheckIn: Date | null;
  actualCheckOut: Date | null;
  actualBreakTime: string | null;
  requiredActiveTime: string | null;
  actualActiveTime: string | null;
  overtimeUndertime: string | null;
  autoDeductedLeaveType: string | null;
  user: {
    id: string;
    firstName: string | null;
    lastName: string | null;
    email: string;
    branch: {
      name: string;
      weeklyOffDays: string[];
      checkInTime: string;
      checkOutTime: string;
    } | null;
  };
}

interface FilterOptions {
  branchId: string;
  userId: string;
  startDate: string;
  endDate: string;
}

export default function TimelineClient() {
  const [activeView, setActiveView] = useState<"table" | "calendar">("table");
  const [timeRecords, setTimeRecords] = useState<TimeRecord[]>([]);
  const [branches, setBranches] = useState<any[]>([]);
  const [users, setUsers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [leaveBackfillRunning, setLeaveBackfillRunning] = useState(false);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 50,
    total: 0,
    totalPages: 0
  });
  
  const [filters, setFilters] = useState<FilterOptions>({
    branchId: "",
    userId: "",
    startDate: "",
    endDate: ""
  });

  // Load initial data
  useEffect(() => {
    loadInitialData();
  }, []);

  // Load time records when filters change
  useEffect(() => {
    loadTimeRecords();
  }, [filters, pagination.page]);

  const loadInitialData = async () => {
    try {
      const [branchesResult, usersResult] = await Promise.all([
        getBranches(),
        getUsers()
      ]);
      
      setBranches(branchesResult || []);
      setUsers(usersResult || []);
      
      loadTimeRecords();
    } catch (error) {
      console.error('Error loading initial data:', error);
    }
  };

  const loadTimeRecords = async () => {
    setLoading(true);
    try {
      const result = await getTimelineRecords(
        filters.userId || undefined,
        filters.startDate ? new Date(filters.startDate) : undefined,
        filters.endDate ? new Date(filters.endDate) : undefined
      );

      if (result.success) {
        setTimeRecords(result.records || []);
        setPagination(prev => ({
          ...prev,
          total: result.records?.length || 0,
          totalPages: Math.ceil((result.records?.length || 0) / 10)
        }));
      }
    } catch (error) {
      console.error('Error loading time records:', error);
    } finally {
      setLoading(false);
    }
  };

  const clearFilters = () => {
    setFilters({
      branchId: "",
      userId: "",
      startDate: "",
      endDate: ""
    });
    setPagination(prev => ({
      ...prev,
      page: 1
    }));
  };

  const handleFilterChange = (key: keyof FilterOptions, value: string) => {
    setFilters(prev => ({
      ...prev,
      [key]: value
    }));
    setPagination(prev => ({
      ...prev,
      page: 1 // Reset to first page when filters change
    }));
  };
  const handleGenerateTimeline = async () => {
    setGenerating(true);
    try {
      const response = await fetch('/api/admin/generate-timeline', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        }
      });
      
      const result = await response.json();
      
      if (result.success) {
        alert(`Successfully generated ${result.recordsCreated} timeline records!`);
        loadTimeRecords(); // Refresh the data
      } else {
        alert(`Failed to generate timeline: ${result.error}`);
      }
    } catch (error) {
      console.error('Error generating timeline:', error);
      alert('Error generating timeline records');
    } finally {
      setGenerating(false);
    }
  };

  const handleLeaveAutomationBackfill = async () => {
    setLeaveBackfillRunning(true);
    try {
      const response = await fetch('/api/leave-automation?backfill=all', {
        method: 'POST'
      });

      const result = await response.json();

      if (result.success) {
        toast.success(`Leave automation backfill completed. Processed ${result.data.processedDates} dates.`);
        loadTimeRecords();
      } else {
        toast.error(result.error || 'Failed to process leave automation backfill');
      }
    } catch (error) {
      console.error('Error running leave automation backfill:', error);
      toast.error('Failed to process leave automation backfill');
    } finally {
      setLeaveBackfillRunning(false);
    }
  };
  // Calculate summary stats
  const summaryStats = {
    totalEmployees: new Set(timeRecords.map(r => r.user.id)).size,
    totalRecords: pagination.total,
    presentToday: timeRecords.filter(r => {
      const today = new Date();
      const recordDate = new Date(r.date);
      return recordDate.toDateString() === today.toDateString() && r.actualCheckIn;
    }).length,
    avgAttendance: timeRecords.length > 0 ? 
      (timeRecords.filter(r => r.actualCheckIn).length / timeRecords.length * 100).toFixed(1) : '0'
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Timeline Management</h1>
          <p className="text-muted-foreground">
            Track and manage employee attendance and working hours
          </p>
        </div>
        <div className="flex gap-2">
          <Button 
            variant="outline" 
            size="sm"
            onClick={handleLeaveAutomationBackfill}
            disabled={leaveBackfillRunning}
          >
            <RotateCcw className={`h-4 w-4 mr-2 ${leaveBackfillRunning ? 'animate-spin' : ''}`} />
            {leaveBackfillRunning ? 'Processing...' : 'Run Leave Automation (All)'}
          </Button>
          <Button 
            variant="outline" 
            size="sm"
            onClick={handleGenerateTimeline}
            disabled={generating}
          >
            <RefreshCw className={`h-4 w-4 mr-2 ${generating ? 'animate-spin' : ''}`} />
            {generating ? 'Generating...' : 'Generate Today\'s Timeline'}
          </Button>
          <Button variant="outline" size="sm">
            <Download className="h-4 w-4 mr-2" />
            Export
          </Button>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Employees</CardTitle>
            <Users className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{summaryStats.totalEmployees}</div>
          </CardContent>
        </Card>
        
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Records</CardTitle>
            <CalendarDays className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{summaryStats.totalRecords}</div>
          </CardContent>
        </Card>
        
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Present Today</CardTitle>
            <Clock className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{summaryStats.presentToday}</div>
          </CardContent>
        </Card>
        
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Avg Attendance</CardTitle>
            <Badge variant="secondary">{summaryStats.avgAttendance}%</Badge>
          </CardHeader>
          <CardContent>
            <div className="text-sm text-muted-foreground">Current Period</div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <TimelineFilters
        filters={filters}
        branches={branches}
        users={users}
        onFilterChange={handleFilterChange}
        onClearFilters={clearFilters}
      />

      {/* Main Content */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>Employee Timeline</CardTitle>
              <CardDescription>
                View and manage employee attendance records
              </CardDescription>
            </div>
            <Tabs value={activeView} onValueChange={(value) => setActiveView(value as "table" | "calendar")}>
              <TabsList>
                <TabsTrigger value="table">Table View</TabsTrigger>
                <TabsTrigger value="calendar">Calendar View</TabsTrigger>
              </TabsList>
            </Tabs>
          </div>
        </CardHeader>
        <CardContent>
          {activeView === "table" ? (
            <TimelineTableView
              records={timeRecords}
              loading={loading}
              pagination={pagination}
              onPageChange={(page: number) => setPagination(prev => ({ ...prev, page }))}
              onRecordUpdate={loadTimeRecords}
            />
          ) : (
            <TimelineCalendarView
              records={timeRecords}
              loading={loading}
            />
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Filter, X } from "lucide-react";

interface FilterOptions {
  branchId: string;
  userId: string;
  startDate: string;
  endDate: string;
}

interface TimelineFiltersProps {
  filters: FilterOptions;
  branches: any[];
  users: any[];
  onFilterChange: (key: keyof FilterOptions, value: string) => void;
  onClearFilters: () => void;
}

export default function TimelineFilters({
  filters,
  branches,
  users,
  onFilterChange,
  onClearFilters
}: TimelineFiltersProps) {
  // Filter users based on selected branch
  const filteredUsers = filters.branchId ? 
    users.filter(user => user.branchId === filters.branchId) : 
    users;

  const hasActiveFilters = Object.values(filters).some(value => value !== "");

  return (
    <Card>
      <CardHeader className="pb-4">
        <div className="flex items-center justify-between">
          <CardTitle className="text-lg flex items-center gap-2">
            <Filter className="h-5 w-5" />
            Filters
          </CardTitle>
          {hasActiveFilters && (
            <Button 
              onClick={onClearFilters} 
              variant="ghost" 
              size="sm"
              className="text-muted-foreground hover:text-foreground"
            >
              <X className="h-4 w-4 mr-1" />
              Clear All
            </Button>
          )}
        </div>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {/* Branch Filter */}
          <div className="space-y-2">
            <Label htmlFor="branch-filter">Branch</Label>
            <Select
              value={filters.branchId || "all-branches"}
              onValueChange={(value) => onFilterChange('branchId', value === "all-branches" ? "" : value)}
            >
              <SelectTrigger>
                <SelectValue placeholder="All Branches" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all-branches">All Branches</SelectItem>
                {branches.map((branch) => (
                  <SelectItem key={branch.id} value={branch.id}>
                    {branch.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Employee Filter */}
          <div className="space-y-2">
            <Label htmlFor="employee-filter">Employee</Label>
            <Select
              value={filters.userId || "all-employees"}
              onValueChange={(value) => onFilterChange('userId', value === "all-employees" ? "" : value)}
            >
              <SelectTrigger>
                <SelectValue placeholder="All Employees" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all-employees">All Employees</SelectItem>
                {filteredUsers.map((user) => (
                  <SelectItem key={user.id} value={user.id}>
                    {user.firstName && user.lastName ? 
                      `${user.firstName} ${user.lastName}` : 
                      user.email
                    }
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Start Date Filter */}
          <div className="space-y-2">
            <Label htmlFor="start-date">Start Date</Label>
            <Input
              id="start-date"
              type="date"
              value={filters.startDate}
              onChange={(e) => onFilterChange('startDate', e.target.value)}
            />
          </div>

          {/* End Date Filter */}
          <div className="space-y-2">
            <Label htmlFor="end-date">End Date</Label>
            <Input
              id="end-date"
              type="date"
              value={filters.endDate}
              onChange={(e) => onFilterChange('endDate', e.target.value)}
              min={filters.startDate} // Ensure end date is not before start date
            />
          </div>
        </div>

        {/* Active Filters Display */}
        {hasActiveFilters && (
          <div className="mt-4 pt-4 border-t">
            <div className="flex flex-wrap gap-2">
              <span className="text-sm text-muted-foreground">Active filters:</span>
              
              {filters.branchId && (
                <div className="inline-flex items-center gap-1 px-2 py-1 bg-primary/10 text-primary rounded-md text-sm">
                  Branch: {branches.find(b => b.id === filters.branchId)?.name}
                  <button
                    onClick={() => onFilterChange('branchId', '')}
                    className="ml-1 hover:bg-primary/20 rounded"
                  >
                    <X className="h-3 w-3" />
                  </button>
                </div>
              )}
              
              {filters.userId && (
                <div className="inline-flex items-center gap-1 px-2 py-1 bg-primary/10 text-primary rounded-md text-sm">
                  Employee: {(() => {
                    const user = users.find(u => u.id === filters.userId);
                    return user?.firstName && user?.lastName ? 
                      `${user.firstName} ${user.lastName}` : 
                      user?.email;
                  })()}
                  <button
                    onClick={() => onFilterChange('userId', '')}
                    className="ml-1 hover:bg-primary/20 rounded"
                  >
                    <X className="h-3 w-3" />
                  </button>
                </div>
              )}
              
              {filters.startDate && (
                <div className="inline-flex items-center gap-1 px-2 py-1 bg-primary/10 text-primary rounded-md text-sm">
                  From: {filters.startDate}
                  <button
                    onClick={() => onFilterChange('startDate', '')}
                    className="ml-1 hover:bg-primary/20 rounded"
                  >
                    <X className="h-3 w-3" />
                  </button>
                </div>
              )}
              
              {filters.endDate && (
                <div className="inline-flex items-center gap-1 px-2 py-1 bg-primary/10 text-primary rounded-md text-sm">
                  To: {filters.endDate}
                  <button
                    onClick={() => onFilterChange('endDate', '')}
                    className="ml-1 hover:bg-primary/20 rounded"
                  >
                    <X className="h-3 w-3" />
                  </button>
                </div>
              )}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { useState } from "react";
import { format } from "date-fns";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table";
import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle, 
  DialogTrigger 
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent } from "@/components/ui/card";
import { 
  ChevronLeft, 
  ChevronRight, 
  Edit, 
  Clock, 
  Calendar,
  User,
  Building2,
  RefreshCw
} from "lucide-react";
import { updateTimelineRecord } from "@/actions/timeline.actions";
import { manualSyncEmployee } from "@/actions/zkteco-sync.actions";

interface TimeRecord {
  id: string;
  date: Date;
  requiredCheckIn: Date | null;
  requiredCheckOut: Date | null;
  requiredBreakTime: string | null;
  actualCheckIn: Date | null;
  actualCheckOut: Date | null;
  actualBreakTime: string | null;
  requiredActiveTime: string | null;
  actualActiveTime: string | null;
  overtimeUndertime: string | null;
  user: {
    id: string;
    firstName: string | null;
    lastName: string | null;
    email: string;
    branch: {
      name: string;
      weeklyOffDays: string[];
      checkInTime: string;
      checkOutTime: string;
    } | null;
  };
}

interface TimelineTableViewProps {
  records: TimeRecord[];
  loading: boolean;
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
  onPageChange: (page: number) => void;
  onRecordUpdate: () => void;
}

export default function TimelineTableView({
  records,
  loading,
  pagination,
  onPageChange,
  onRecordUpdate
}: TimelineTableViewProps) {
  const [editingRecord, setEditingRecord] = useState<TimeRecord | null>(null);
  const [editForm, setEditForm] = useState({
    requiredCheckIn: '',
    requiredCheckOut: '',
    requiredBreakTime: '',
    actualCheckIn: '',
    actualCheckOut: '',
    actualBreakTime: ''
  });
  const [saving, setSaving] = useState(false);
  const [syncingUsers, setSyncingUsers] = useState<Set<string>>(new Set());

  const openEditDialog = (record: TimeRecord) => {
    setEditingRecord(record);
    setEditForm({
      requiredCheckIn: record.requiredCheckIn ? 
        format(new Date(record.requiredCheckIn), 'yyyy-MM-dd\'T\'HH:mm') : '',
      requiredCheckOut: record.requiredCheckOut ? 
        format(new Date(record.requiredCheckOut), 'yyyy-MM-dd\'T\'HH:mm') : '',
      requiredBreakTime: record.requiredBreakTime || '',
      actualCheckIn: record.actualCheckIn ? 
        format(new Date(record.actualCheckIn), 'yyyy-MM-dd\'T\'HH:mm') : '',
      actualCheckOut: record.actualCheckOut ? 
        format(new Date(record.actualCheckOut), 'yyyy-MM-dd\'T\'HH:mm') : '',
      actualBreakTime: record.actualBreakTime || ''
    });
  };

  const handleSave = async () => {
    if (!editingRecord) return;

    setSaving(true);
    try {
      const result = await updateTimelineRecord(editingRecord.id, {
        requiredCheckIn: editForm.requiredCheckIn ? new Date(editForm.requiredCheckIn) : null,
        requiredCheckOut: editForm.requiredCheckOut ? new Date(editForm.requiredCheckOut) : null,
        requiredBreakTime: editForm.requiredBreakTime || null,
        actualCheckIn: editForm.actualCheckIn ? new Date(editForm.actualCheckIn) : null,
        actualCheckOut: editForm.actualCheckOut ? new Date(editForm.actualCheckOut) : null,
        actualBreakTime: editForm.actualBreakTime || null
      });

      if (result.success) {
        setEditingRecord(null);
        onRecordUpdate();
      } else {
        alert('Failed to update record');
      }
    } catch (error) {
      console.error('Error updating record:', error);
      alert('Error updating record');
    } finally {
      setSaving(false);
    }
  };

  const handleSync = async (userId: string) => {
    setSyncingUsers(prev => new Set(prev).add(userId));
    try {
      console.log(`Starting manual sync for user: ${userId}`);
      const result = await manualSyncEmployee(userId);
      
      console.log(`Manual sync completed:`, result);
      
      if (result.success) {
        // Show success message
        if (result.syncedRecords > 0) {
          alert(`Γ£à Successfully synced ${result.syncedRecords} record(s)!\n\nThe timeline should now show updated check-in/out times.`);
        } else {
          alert(`Γä╣∩╕Å ${result.message}\n\nNote: Records may already be complete or no new data available.`);
        }
        
        // Force refresh the table data
        console.log('Refreshing table data after sync...');
        onRecordUpdate();
        
        // Force a small delay and refresh again to ensure UI updates
        setTimeout(() => {
          console.log('Secondary refresh after sync...');
          onRecordUpdate();
        }, 500);
      } else {
        alert(`Γ¥î Sync failed: ${result.message}${result.errors.length > 0 ? '\n\nErrors:\n' + result.errors.join('\n') : ''}`);
        if (result.errors.length > 0) {
          console.error('Sync errors:', result.errors);
        }
      }
    } catch (error) {
      console.error('Error syncing employee data:', error);
      alert(`Γ¥î Error syncing employee data: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setSyncingUsers(prev => {
        const newSet = new Set(prev);
        newSet.delete(userId);
        return newSet;
      });
    }
  };

  const getOvertimeBadge = (overtime: string | null) => {
    if (!overtime) return null;
    
    const isPositive = !overtime.startsWith('-');
    return (
      <Badge variant={isPositive ? "default" : "destructive"}>
        {isPositive ? '+' : ''}{overtime}
      </Badge>
    );
  };

  const getAttendanceStatus = (record: TimeRecord) => {
    if (!record.requiredCheckIn && !record.requiredCheckOut) {
      return <Badge variant="secondary">Off Day</Badge>;
    }
    
    if (record.actualCheckIn && record.actualCheckOut) {
      return <Badge variant="default">Present</Badge>;
    }
    
    if (record.actualCheckIn) {
      return <Badge variant="outline">Checked In</Badge>;
    }
    
    return <Badge variant="destructive">Absent</Badge>;
  };

  if (loading) {
    return (
      <div className="space-y-4">
        {[...Array(5)].map((_, i) => (
          <div key={i} className="animate-pulse bg-gray-200 h-16 rounded"></div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Table */}
      <div className="border rounded-lg overflow-hidden">
        <Table>
          <TableHeader>
            <TableRow className="bg-gray-50">
              <TableHead>Employee</TableHead>
              <TableHead>Branch</TableHead>
              <TableHead>Date</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Required</TableHead>
              <TableHead>Actual</TableHead>
              <TableHead>Active Time</TableHead>
              <TableHead>OT/UT</TableHead>
              <TableHead>Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {records.length === 0 ? (
              <TableRow>
                <TableCell colSpan={9} className="text-center py-8 text-muted-foreground">
                  No timeline records found
                </TableCell>
              </TableRow>
            ) : (
              records.map((record) => (
                <TableRow key={record.id} className="hover:bg-gray-50">
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <User className="h-4 w-4 text-muted-foreground" />
                      <div>
                        <div className="font-medium">
                          {record.user.firstName && record.user.lastName 
                            ? `${record.user.firstName} ${record.user.lastName}`
                            : record.user.email}
                        </div>
                        <div className="text-sm text-muted-foreground">
                          {record.user.email}
                        </div>
                      </div>
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <Building2 className="h-4 w-4 text-muted-foreground" />
                      {record.user.branch?.name || 'No Branch'}
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <Calendar className="h-4 w-4 text-muted-foreground" />
                      {format(new Date(record.date), 'MMM dd, yyyy')}
                      <Badge variant="outline" className="text-xs">
                        {format(new Date(record.date), 'EEE')}
                      </Badge>
                    </div>
                  </TableCell>
                  <TableCell>
                    {getAttendanceStatus(record)}
                  </TableCell>
                  <TableCell>
                    <div className="text-sm space-y-1">
                      {record.requiredCheckIn ? (
                        <>
                          <div>In: {format(new Date(record.requiredCheckIn), 'HH:mm')}</div>
                          <div>Out: {record.requiredCheckOut ? format(new Date(record.requiredCheckOut), 'HH:mm') : '--'}</div>
                          <div>Break: {record.requiredBreakTime || '--'}</div>
                        </>
                      ) : (
                        <span className="text-muted-foreground">--</span>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="text-sm space-y-1">
                      <div>In: {record.actualCheckIn ? format(new Date(record.actualCheckIn), 'HH:mm') : '--'}</div>
                      <div>Out: {record.actualCheckOut ? format(new Date(record.actualCheckOut), 'HH:mm') : '--'}</div>
                      <div>Break: {record.actualBreakTime || '--'}</div>
                    </div>
                  </TableCell>
                  <TableCell>
                    <div className="text-sm space-y-1">
                      <div>Req: {record.requiredActiveTime || '--'}</div>
                      <div>Act: {record.actualActiveTime || '--'}</div>
                    </div>
                  </TableCell>
                  <TableCell>
                    {getOvertimeBadge(record.overtimeUndertime)}
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleSync(record.user.id)}
                        disabled={syncingUsers.has(record.user.id)}
                        title="Sync attendance data from ZKTeco"
                      >
                        <RefreshCw 
                          className={`h-4 w-4 ${syncingUsers.has(record.user.id) ? 'animate-spin' : ''}`} 
                        />
                      </Button>
                      <Dialog>
                        <DialogTrigger asChild>
                          <Button 
                            variant="ghost" 
                            size="sm"
                            onClick={() => openEditDialog(record)}
                          >
                            <Edit className="h-4 w-4" />
                          </Button>
                        </DialogTrigger>
                      <DialogContent className="max-w-md">
                        <DialogHeader>
                          <DialogTitle>Edit Time Record</DialogTitle>
                        </DialogHeader>
                        <div className="space-y-4">
                          <div className="text-sm text-muted-foreground">
                            {record.user.firstName && record.user.lastName 
                              ? `${record.user.firstName} ${record.user.lastName}`
                              : record.user.email} - {format(new Date(record.date), 'MMM dd, yyyy')}
                          </div>
                          
                          <div className="grid gap-4">
                            {/* Required Times Section */}
                            <div className="border-b pb-4">
                              <h4 className="font-medium text-sm text-muted-foreground mb-3">Required Times</h4>
                              <div className="grid gap-3">
                                <div>
                                  <Label htmlFor="requiredCheckIn">Required Check In</Label>
                                  <Input
                                    id="requiredCheckIn"
                                    type="datetime-local"
                                    value={editForm.requiredCheckIn}
                                    onChange={(e) => setEditForm({
                                      ...editForm,
                                      requiredCheckIn: e.target.value
                                    })}
                                  />
                                </div>
                                
                                <div>
                                  <Label htmlFor="requiredCheckOut">Required Check Out</Label>
                                  <Input
                                    id="requiredCheckOut"
                                    type="datetime-local"
                                    value={editForm.requiredCheckOut}
                                    onChange={(e) => setEditForm({
                                      ...editForm,
                                      requiredCheckOut: e.target.value
                                    })}
                                  />
                                </div>
                                
                                <div>
                                  <Label htmlFor="requiredBreakTime">Required Break Time (HH:MM)</Label>
                                  <Input
                                    id="requiredBreakTime"
                                    type="text"
                                    placeholder="01:00"
                                    value={editForm.requiredBreakTime}
                                    onChange={(e) => setEditForm({
                                      ...editForm,
                                      requiredBreakTime: e.target.value
                                    })}
                                  />
                                </div>
                              </div>
                            </div>

                            {/* Actual Times Section */}
                            <div>
                              <h4 className="font-medium text-sm text-muted-foreground mb-3">Actual Times</h4>
                              <div className="grid gap-3">
                                <div>
                                  <Label htmlFor="actualCheckIn">Actual Check In</Label>
                                  <Input
                                    id="actualCheckIn"
                                    type="datetime-local"
                                    value={editForm.actualCheckIn}
                                    onChange={(e) => setEditForm({
                                      ...editForm,
                                      actualCheckIn: e.target.value
                                    })}
                                  />
                                </div>
                                
                                <div>
                                  <Label htmlFor="actualCheckOut">Actual Check Out</Label>
                                  <Input
                                    id="actualCheckOut"
                                    type="datetime-local"
                                    value={editForm.actualCheckOut}
                                    onChange={(e) => setEditForm({
                                      ...editForm,
                                      actualCheckOut: e.target.value
                                    })}
                                  />
                                </div>
                                
                                <div>
                                  <Label htmlFor="actualBreakTime">Actual Break Time (HH:MM)</Label>
                                  <Input
                                    id="actualBreakTime"
                                    type="text"
                                    placeholder="01:00"
                                    value={editForm.actualBreakTime}
                                    onChange={(e) => setEditForm({
                                      ...editForm,
                                      actualBreakTime: e.target.value
                                    })}
                                  />
                                </div>
                              </div>
                            </div>
                          </div>
                          
                          <div className="flex justify-end gap-2">
                            <Button 
                              onClick={handleSave} 
                              disabled={saving}
                            >
                              {saving ? 'Saving...' : 'Save Changes'}
                            </Button>
                          </div>
                        </div>
                      </DialogContent>
                    </Dialog>
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      {/* Pagination */}
      {pagination.totalPages > 1 && (
        <div className="flex items-center justify-between">
          <div className="text-sm text-muted-foreground">
            Showing {((pagination.page - 1) * pagination.limit) + 1} to{' '}
            {Math.min(pagination.page * pagination.limit, pagination.total)} of{' '}
            {pagination.total} results
          </div>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => onPageChange(pagination.page - 1)}
              disabled={pagination.page === 1}
            >
              <ChevronLeft className="h-4 w-4" />
              Previous
            </Button>
            
            <span className="px-4 py-2 text-sm">
              Page {pagination.page} of {pagination.totalPages}
            </span>
            
            <Button
              variant="outline"
              size="sm"
              onClick={() => onPageChange(pagination.page + 1)}
              disabled={pagination.page === pagination.totalPages}
            >
              Next
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { updateEmployeeSalary } from "@/actions/salary.actions";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
    DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Plus, TrendingUp } from "lucide-react";
import { SalaryChangeReason } from "@prisma/client";

export function UpdateSalaryDialog({ userId, onUpdate }: { userId: string, onUpdate?: () => void }) {
    const [isOpen, setIsOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [formData, setFormData] = useState({
        amount: "",
        reason: "INCREMENT" as SalaryChangeReason,
        effectiveFrom: new Date().toISOString().split('T')[0],
    });

    const handleSubmit = async () => {
        if (!formData.amount || Number(formData.amount) <= 0) {
            toast.error("Please enter a valid amount");
            return;
        }

        setLoading(true);
        try {
            const res = await updateEmployeeSalary({
                userId,
                amount: Number(formData.amount),
                reason: formData.reason,
                effectiveFrom: new Date(formData.effectiveFrom),
            });

            toast.success("Salary updated successfully");
            setIsOpen(false);
            setFormData({ amount: "", reason: "INCREMENT", effectiveFrom: new Date().toISOString().split('T')[0] });
            if (onUpdate) onUpdate();
        } catch (error: any) {
            toast.error(error.message || "Failed to update salary");
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={isOpen} onOpenChange={setIsOpen}>
            <DialogTrigger asChild>
                <Button>
                    <TrendingUp className="mr-2 h-4 w-4" /> Update Salary
                </Button>
            </DialogTrigger>
            <DialogContent className="sm:max-w-[425px]">
                <DialogHeader>
                    <DialogTitle>Revise Employee Salary</DialogTitle>
                </DialogHeader>
                <div className="grid gap-4 py-4">
                    <div className="grid gap-2">
                        <Label htmlFor="amount">New Base Salary (Monthly)</Label>
                        <Input
                            id="amount"
                            type="number"
                            placeholder="e.g. 50000"
                            value={formData.amount}
                            onChange={(e) => setFormData({ ...formData, amount: e.target.value })}
                        />
                    </div>
                    <div className="grid gap-2">
                        <Label htmlFor="reason">Revision Reason</Label>
                        <Select
                            value={formData.reason}
                            onValueChange={(value: SalaryChangeReason) => setFormData({ ...formData, reason: value })}
                        >
                            <SelectTrigger>
                                <SelectValue placeholder="Select reason" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="JOINING">Initial Joining</SelectItem>
                                <SelectItem value="PROMOTION">Promotion</SelectItem>
                                <SelectItem value="INCREMENT">Annual Increment</SelectItem>
                                <SelectItem value="ADJUSTMENT">Market Adjustment</SelectItem>
                            </SelectContent>
                        </Select>
                    </div>
                    <div className="grid gap-2">
                        <Label htmlFor="effectiveDate">Effective From</Label>
                        <Input
                            id="effectiveDate"
                            type="date"
                            value={formData.effectiveFrom}
                            onChange={(e) => setFormData({ ...formData, effectiveFrom: e.target.value })}
                        />
                    </div>
                </div>
                <DialogFooter>
                    <Button variant="outline" onClick={() => setIsOpen(false)}>Cancel</Button>
                    <Button onClick={handleSubmit} disabled={loading}>
                        {loading ? "Processing..." : "Commit Change"}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

