"use client";

import { useTransition } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { Button } from "@/components/ui/button";
import {
    Form,
    FormControl,
    FormDescription,
    FormField,
    FormItem,
    FormLabel,
    FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { adjustWalletBalance } from "@/actions/wallet.actions";
import { toast } from "sonner";
import { Loader2 } from "lucide-react";
import { User } from "@prisma/client";

interface ManualAdjustmentFormProps {
    users: User[];
}

const formSchema = z.object({
    userId: z.string().min(1, "User is required"),
    amount: z.coerce.number().refine((val) => val !== 0, "Amount cannot be zero"),
    description: z.string().min(5, "Description is required"),
});

export function ManualAdjustmentForm({ users }: ManualAdjustmentFormProps) {
    const [isPending, startTransition] = useTransition();

    const form = useForm<z.infer<typeof formSchema>>({
        resolver: zodResolver(formSchema) as any,
        defaultValues: {
            userId: "",
            amount: 0,
            description: "",
        },
    });

    function onSubmit(values: z.infer<typeof formSchema>) {
        startTransition(async () => {
            try {
                await adjustWalletBalance(values.userId, values.amount, values.description);
                toast.success("Wallet adjusted successfully");
                form.reset();
            } catch (error) {
                toast.error("Failed to adjust wallet");
                console.error(error);
            }
        });
    }

    return (
        <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6 max-w-lg">
                <FormField
                    control={form.control}
                    name="userId"
                    render={({ field }) => (
                        <FormItem>
                            <FormLabel>Employee</FormLabel>
                            <Select onValueChange={field.onChange} defaultValue={field.value}>
                                <FormControl>
                                    <SelectTrigger>
                                        <SelectValue placeholder="Select an employee" />
                                    </SelectTrigger>
                                </FormControl>
                                <SelectContent>
                                    {users.map((user) => (
                                        <SelectItem key={user.id} value={user.id}>
                                            {user.email} (Current: αº│{user.walletBalance.toLocaleString("en-BD")})
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                            <FormMessage />
                        </FormItem>
                    )}
                />

                <FormField
                    control={form.control}
                    name="amount"
                    render={({ field }) => (
                        <FormItem>
                            <FormLabel>Amount (Tk)</FormLabel>
                            <FormControl>
                                <Input type="number" placeholder="0.00" {...field} />
                            </FormControl>
                            <FormDescription>
                                Use negative value for deduction (e.g. -500).
                            </FormDescription>
                            <FormMessage />
                        </FormItem>
                    )}
                />

                <FormField
                    control={form.control}
                    name="description"
                    render={({ field }) => (
                        <FormItem>
                            <FormLabel>Description</FormLabel>
                            <FormControl>
                                <Input placeholder="Reason for adjustment" {...field} />
                            </FormControl>
                            <FormMessage />
                        </FormItem>
                    )}
                />

                <Button type="submit" disabled={isPending}>
                    {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                    Apply Adjustment
                </Button>
            </form>
        </Form>
    );
}

"use client";

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { BarChart3, TrendingUp, Clock, Calendar } from "lucide-react";
import { format, startOfMonth, endOfMonth, eachMonthOfInterval } from "date-fns";

interface TimeRecord {
  id: string;
  date: Date;
  requiredCheckIn: Date | null;
  requiredCheckOut: Date | null;
  requiredBreakTime: string | null;
  actualCheckIn: Date | null;
  actualCheckOut: Date | null;
  actualBreakTime: string | null;
  requiredActiveTime: string | null;
  actualActiveTime: string | null;
  overtimeUndertime: string | null;
}

interface TimelineSummary {
  workingDays: number;
  presentDays: number;
  totalRequiredTime: string;
  totalActualTime: string;
  totalOvertime: string;
  attendancePercentage: string;
}

interface EmployeeTimelineChartsProps {
  records: TimeRecord[];
  summary: TimelineSummary | null;
  year: number;
}

// Helper function to convert time string to minutes
const timeToMinutes = (timeStr: string): number => {
  if (!timeStr || timeStr === '00:00') return 0;
  const isNegative = timeStr.startsWith('-');
  const cleanTime = timeStr.replace('-', '');
  const [hours, minutes] = cleanTime.split(':').map(Number);
  const totalMinutes = hours * 60 + minutes;
  return isNegative ? -totalMinutes : totalMinutes;
};

// Helper function to convert minutes to hours for display
const minutesToHours = (minutes: number): string => {
  const hours = Math.abs(minutes) / 60;
  return `${minutes < 0 ? '-' : ''}${hours.toFixed(1)}h`;
};

export default function EmployeeTimelineCharts({ 
  records, 
  summary, 
  year 
}: EmployeeTimelineChartsProps) {
  // Group records by month for yearly view
  const getMonthlyData = () => {
    const yearStart = new Date(year, 0, 1);
    const yearEnd = new Date(year, 11, 31);
    const months = eachMonthOfInterval({ start: yearStart, end: yearEnd });

    return months.map(month => {
      const monthRecords = records.filter(record => {
        const recordDate = new Date(record.date);
        return recordDate.getMonth() === month.getMonth() && 
               recordDate.getFullYear() === month.getFullYear();
      });

      const workingDays = monthRecords.filter(r => r.requiredCheckIn || r.requiredCheckOut).length;
      const presentDays = monthRecords.filter(r => r.actualCheckIn && r.actualCheckOut).length;
      const attendanceRate = workingDays > 0 ? (presentDays / workingDays) * 100 : 0;

      // Calculate total overtime for the month
      const totalOvertimeMinutes = monthRecords.reduce((sum, record) => {
        if (record.overtimeUndertime) {
          return sum + timeToMinutes(record.overtimeUndertime);
        }
        return sum;
      }, 0);

      return {
        month: format(month, 'MMM'),
        fullMonth: format(month, 'MMMM yyyy'),
        workingDays,
        presentDays,
        attendanceRate,
        totalOvertimeMinutes
      };
    });
  };

  const monthlyData = getMonthlyData();

  // Calculate weekly patterns
  const getWeeklyPattern = () => {
    const weekDays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    
    return weekDays.map((day, index) => {
      const dayRecords = records.filter(record => {
        const recordDate = new Date(record.date);
        return recordDate.getDay() === index;
      });

      const workingDays = dayRecords.filter(r => r.requiredCheckIn || r.requiredCheckOut).length;
      const presentDays = dayRecords.filter(r => r.actualCheckIn && r.actualCheckOut).length;
      const attendanceRate = workingDays > 0 ? (presentDays / workingDays) * 100 : 0;

      return {
        day,
        workingDays,
        presentDays,
        attendanceRate
      };
    });
  };

  const weeklyPattern = getWeeklyPattern();

  // Get attendance trend (last 30 days)
  const getRecentTrend = () => {
    const sortedRecords = [...records]
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
      .slice(0, 30)
      .reverse();

    return sortedRecords.map(record => ({
      date: format(new Date(record.date), 'MMM dd'),
      present: (record.actualCheckIn && record.actualCheckOut) ? 1 : 0,
      required: (record.requiredCheckIn || record.requiredCheckOut) ? 1 : 0
    }));
  };

  const recentTrend = getRecentTrend();

  return (
    <div className="space-y-6">
      {/* Overview Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Attendance Rate</CardTitle>
            <TrendingUp className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{summary?.attendancePercentage}%</div>
            <Progress value={parseFloat(summary?.attendancePercentage || '0')} className="mt-2" />
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Working Days</CardTitle>
            <Calendar className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{summary?.workingDays}</div>
            <p className="text-xs text-muted-foreground">
              Present: {summary?.presentDays}
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Active Time</CardTitle>
            <Clock className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{summary?.totalActualTime}</div>
            <p className="text-xs text-muted-foreground">
              Required: {summary?.totalRequiredTime}
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Net Overtime</CardTitle>
            <BarChart3 className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{summary?.totalOvertime}</div>
            <Badge 
              variant={summary?.totalOvertime?.startsWith('-') ? "destructive" : "default"}
              className="mt-1"
            >
              {summary?.totalOvertime?.startsWith('-') ? 'Undertime' : 'Overtime'}
            </Badge>
          </CardContent>
        </Card>
      </div>

      {/* Monthly Attendance Chart */}
      <Card>
        <CardHeader>
          <CardTitle>Monthly Attendance - {year}</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {monthlyData.map((month, index) => (
              <div key={index} className="space-y-2">
                <div className="flex items-center justify-between text-sm">
                  <span className="font-medium">{month.fullMonth}</span>
                  <div className="flex gap-4 text-xs text-muted-foreground">
                    <span>Working: {month.workingDays}</span>
                    <span>Present: {month.presentDays}</span>
                    <span>{month.attendanceRate.toFixed(1)}%</span>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <Progress 
                    value={month.attendanceRate} 
                    className="flex-1" 
                  />
                  <Badge 
                    variant={month.totalOvertimeMinutes >= 0 ? "default" : "destructive"}
                    className="text-xs"
                  >
                    {minutesToHours(month.totalOvertimeMinutes)}
                  </Badge>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Weekly Pattern */}
      <Card>
        <CardHeader>
          <CardTitle>Weekly Attendance Pattern</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {weeklyPattern.map((day, index) => (
              <div key={index} className="space-y-2">
                <div className="flex items-center justify-between text-sm">
                  <span className="font-medium w-20">{day.day}</span>
                  <div className="flex gap-4 text-xs text-muted-foreground">
                    <span>Working: {day.workingDays}</span>
                    <span>Present: {day.presentDays}</span>
                    <span>{day.attendanceRate.toFixed(1)}%</span>
                  </div>
                </div>
                <Progress value={day.attendanceRate} />
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Recent Attendance Trend */}
      <Card>
        <CardHeader>
          <CardTitle>Recent Attendance Trend (Last 30 Days)</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-end gap-1 h-32">
            {recentTrend.map((item, index) => {
              const height = item.required > 0 ? (item.present > 0 ? 100 : 20) : 10;
              const color = item.required === 0 ? 'bg-gray-200' : 
                          item.present > 0 ? 'bg-green-500' : 'bg-red-500';
              
              return (
                <div
                  key={index}
                  className="flex flex-col items-center flex-1"
                  title={`${item.date}: ${item.required === 0 ? 'Off Day' : 
                    item.present > 0 ? 'Present' : 'Absent'}`}
                >
                  <div
                    className={`${color} w-full rounded-t transition-all hover:opacity-80`}
                    style={{ height: `${height}%` }}
                  />
                  <div className="text-xs text-muted-foreground mt-1 transform -rotate-45 origin-left">
                    {item.date}
                  </div>
                </div>
              );
            })}
          </div>
          <div className="flex justify-center gap-4 mt-4 text-xs">
            <div className="flex items-center gap-1">
              <div className="w-3 h-3 bg-green-500 rounded"></div>
              <span>Present</span>
            </div>
            <div className="flex items-center gap-1">
              <div className="w-3 h-3 bg-red-500 rounded"></div>
              <span>Absent</span>
            </div>
            <div className="flex items-center gap-1">
              <div className="w-3 h-3 bg-gray-200 rounded"></div>
              <span>Off Day</span>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Performance Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <Card>
          <CardHeader>
            <CardTitle>Performance Metrics</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex justify-between items-center">
              <span className="text-sm">Punctuality Score</span>
              <div className="text-right">
                <div className="font-medium">
                  {(() => {
                    const onTimeRecords = records.filter(r => {
                      if (!r.requiredCheckIn || !r.actualCheckIn) return false;
                      const requiredTime = new Date(r.requiredCheckIn).getTime();
                      const actualTime = new Date(r.actualCheckIn).getTime();
                      return actualTime <= requiredTime;
                    });
                    const workingRecords = records.filter(r => r.requiredCheckIn && r.actualCheckIn);
                    const score = workingRecords.length > 0 ? 
                      (onTimeRecords.length / workingRecords.length * 100) : 0;
                    return `${score.toFixed(1)}%`;
                  })()}
                </div>
              </div>
            </div>

            <div className="flex justify-between items-center">
              <span className="text-sm">Full Day Completion</span>
              <div className="text-right">
                <div className="font-medium">
                  {(() => {
                    const fullDayRecords = records.filter(r => 
                      r.actualCheckIn && r.actualCheckOut
                    );
                    const workingRecords = records.filter(r => 
                      r.requiredCheckIn || r.requiredCheckOut
                    );
                    const rate = workingRecords.length > 0 ? 
                      (fullDayRecords.length / workingRecords.length * 100) : 0;
                    return `${rate.toFixed(1)}%`;
                  })()}
                </div>
              </div>
            </div>

            <div className="flex justify-between items-center">
              <span className="text-sm">Average Daily Hours</span>
              <div className="text-right">
                <div className="font-medium">
                  {(() => {
                    const recordsWithTime = records.filter(r => r.actualActiveTime);
                    if (recordsWithTime.length === 0) return '0h';
                    
                    const totalMinutes = recordsWithTime.reduce((sum, record) => {
                      return sum + timeToMinutes(record.actualActiveTime!);
                    }, 0);
                    
                    const avgHours = totalMinutes / recordsWithTime.length / 60;
                    return `${avgHours.toFixed(1)}h`;
                  })()}
                </div>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Time Distribution</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex justify-between items-center">
              <span className="text-sm">Regular Hours</span>
              <div className="text-right">
                <div className="font-medium">{summary?.totalRequiredTime}</div>
              </div>
            </div>

            <div className="flex justify-between items-center">
              <span className="text-sm">Actual Hours</span>
              <div className="text-right">
                <div className="font-medium">{summary?.totalActualTime}</div>
              </div>
            </div>

            <div className="flex justify-between items-center border-t pt-2">
              <span className="text-sm">Extra/Missing Hours</span>
              <div className="text-right">
                <Badge 
                  variant={summary?.totalOvertime?.startsWith('-') ? "destructive" : "default"}
                >
                  {summary?.totalOvertime}
                </Badge>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { CalendarDays, Clock, TrendingUp, BarChart3, Calendar, Download } from "lucide-react";
import { format } from "date-fns";
import EmployeeTimelineCalendar from "@/components/employee/EmployeeTimelineCalendar";
import EmployeeTimelineTable from "@/components/employee/EmployeeTimelineTable";
import EmployeeTimelineCharts from "@/components/employee/EmployeeTimelineCharts";
import { getTimelineRecords } from "@/actions/timeline.actions";

/**
 * Convert time string (HH:MM) to minutes
 */
function timeStringToMinutes(timeStr: string): number {
  if (!timeStr) return 0;
  const isNegative = timeStr.startsWith('-');
  const cleanTime = timeStr.replace('-', '').replace('+', '');
  const [hours, minutes] = cleanTime.split(':').map(Number);
  const totalMinutes = (hours * 60) + minutes;
  return isNegative ? -totalMinutes : totalMinutes;
}

/**
 * Convert minutes to time string (HH:MM)
 */
function minutesToTimeString(minutes: number): string {
  if (minutes === 0) return '00:00';
  
  const absMinutes = Math.abs(minutes);
  const hours = Math.floor(absMinutes / 60);
  const mins = absMinutes % 60;
  
  const sign = minutes < 0 ? '-' : '';
  return `${sign}${hours.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}`;
}

/**
 * Calculate summary statistics from timeline records
 */
function calculateTimelineSummary(records: TimeRecord[]): TimelineSummary {
  let workingDays = 0;
  let presentDays = 0;
  let totalRequiredMinutes = 0;
  let totalRequiredBreakMinutes = 0;
  let totalActualMinutes = 0;
  let totalOvertimeMinutes = 0;

  records.forEach(record => {
    // Count working days (records with required times - not weekends/holidays)
    if (record.requiredCheckIn && record.requiredCheckOut) {
      workingDays++;
      
      // Add required time
      if (record.requiredActiveTime) {
        totalRequiredMinutes += timeStringToMinutes(record.requiredActiveTime);
      }

      if (record.requiredBreakTime) {
        totalRequiredBreakMinutes += timeStringToMinutes(record.requiredBreakTime);
      }
      
      // Count present days (records with actual check-in)
      if (record.actualCheckIn) {
        presentDays++;
        
        // Add actual time
        if (record.actualActiveTime) {
          totalActualMinutes += timeStringToMinutes(record.actualActiveTime);
        }
        
        // Add overtime/undertime
        if (record.overtimeUndertime) {
          totalOvertimeMinutes += timeStringToMinutes(record.overtimeUndertime);
        }
      }
    }
  });

  const attendancePercentage = workingDays > 0 
    ? ((presentDays / workingDays) * 100).toFixed(1)
    : '0.0';

  return {
    workingDays,
    presentDays,
    totalRequiredTime: minutesToTimeString(totalRequiredMinutes),
    totalRequiredBreakTime: minutesToTimeString(totalRequiredBreakMinutes),
    totalActualTime: minutesToTimeString(totalActualMinutes),
    totalOvertime: minutesToTimeString(totalOvertimeMinutes),
    attendancePercentage
  };
}

interface TimeRecord {
  id: string;
  date: Date;
  requiredCheckIn: Date | null;
  requiredCheckOut: Date | null;
  requiredBreakTime: string | null;
  actualCheckIn: Date | null;
  actualCheckOut: Date | null;
  actualBreakTime: string | null;
  requiredActiveTime: string | null;
  actualActiveTime: string | null;
  overtimeUndertime: string | null;
}

interface TimelineSummary {
  workingDays: number;
  presentDays: number;
  totalRequiredTime: string;
  totalRequiredBreakTime: string;
  totalActualTime: string;
  totalOvertime: string;
  attendancePercentage: string;
}

interface EmployeeTimelineClientProps {
  userId: string;
  baseSalary: number;
}

export default function EmployeeTimelineClient({ userId, baseSalary }: EmployeeTimelineClientProps) {
  const [activeView, setActiveView] = useState<"calendar" | "table" | "charts">("calendar");
  const [timeRecords, setTimeRecords] = useState<TimeRecord[]>([]);
  const [summary, setSummary] = useState<TimelineSummary | null>(null);
  const [loading, setLoading] = useState(true);
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState<number | undefined>(undefined);

  // Generate years (2026-2030)
  const years = Array.from({ length: 5 }, (_, i) => 2026 + i);
  const months = [
    { value: undefined, label: "All Months" },
    { value: 0, label: "January" },
    { value: 1, label: "February" },
    { value: 2, label: "March" },
    { value: 3, label: "April" },
    { value: 4, label: "May" },
    { value: 5, label: "June" },
    { value: 6, label: "July" },
    { value: 7, label: "August" },
    { value: 8, label: "September" },
    { value: 9, label: "October" },
    { value: 10, label: "November" },
    { value: 11, label: "December" }
  ];

  // Load timeline data
  useEffect(() => {
    loadTimelineData();
  }, [selectedYear, selectedMonth]);

  // Recalculate summary when records change
  useEffect(() => {
    if (timeRecords.length > 0) {
      const calculatedSummary = calculateTimelineSummary(timeRecords);
      setSummary(calculatedSummary);
    } else {
      setSummary({
        workingDays: 0,
        presentDays: 0,
        totalRequiredTime: '00:00',
        totalActualTime: '00:00',
        totalOvertime: '00:00',
        totalRequiredBreakTime: '00:00',
        attendancePercentage: '0.0'
      });
    }
  }, [timeRecords]);

  const loadTimelineData = async () => {
    setLoading(true);
    try {
      let startDate: Date | undefined;
      let endDate: Date | undefined;
      
      if (selectedMonth !== undefined) {
        // Specific month selected
        startDate = new Date(selectedYear, selectedMonth, 1);
        endDate = new Date(selectedYear, selectedMonth + 1, 0);
      } else {
        // Whole year selected
        startDate = new Date(selectedYear, 0, 1);
        endDate = new Date(selectedYear, 11, 31);
      }
      
      const result = await getTimelineRecords(userId, startDate, endDate);
      
      if (result.success) {
        const records = result.records || [];
        setTimeRecords(records);
        
        // Calculate dynamic summary from the loaded records
        const calculatedSummary = calculateTimelineSummary(records);
        setSummary(calculatedSummary);
      } else {
        console.error('Failed to load timeline data:', result.error);
      }
    } catch (error) {
      console.error('Error loading timeline data:', error);
    } finally {
      setLoading(false);
    }
  };

  const getSummaryCards = () => {
    const isLoading = loading || !summary;
    const safeValue = (value: any, fallback: any = 0) => isLoading ? fallback : value;
    
    return [
      {
        title: "Working Days",
        value: isLoading ? "--" : summary?.workingDays || 0,
        icon: CalendarDays,
        description: "Total working days"
      },
      {
        title: "Present Days",
        value: isLoading ? "--" : summary?.presentDays || 0,
        icon: Clock,
        description: "Days attended"
      },
      {
        title: "Attendance Rate",
        value: isLoading ? "--" : `${summary?.attendancePercentage || 0}%`,
        icon: TrendingUp,
        description: "Overall attendance"
      },
      {
        title: "Total Overtime",
        value: isLoading ? "--" : (() => {
          const overtime = summary?.totalOvertime || "00:00";
          if (overtime === '00:00') return 'On Time';
          return overtime.startsWith('-') ? overtime : `+${overtime}`;
        })(),
        icon: BarChart3,
        description: "Extra hours worked",
        variant: (() => {
          const overtime = summary?.totalOvertime || "00:00";
          if (overtime === '00:00') return 'secondary';
          return overtime.startsWith('-') ? 'destructive' : 'default';
        })()
      }
    ];
  };

  const getPeriodLabel = () => {
    if (selectedMonth !== undefined) {
      return `${months.find(m => m.value === selectedMonth)?.label} ${selectedYear}`;
    }
    return `Year ${selectedYear}`;
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">My Timeline</h1>
          <p className="text-muted-foreground">
            Track your attendance and working hours
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm">
            <Download className="h-4 w-4 mr-2" />
            Export
          </Button>
        </div>
      </div>

      {/* Period Selection */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle>Period Selection</CardTitle>
            <div className="flex gap-2">
              <Select
                value={selectedYear.toString()}
                onValueChange={(value) => setSelectedYear(parseInt(value))}
              >
                <SelectTrigger className="w-32">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {years.map((year) => (
                    <SelectItem key={year} value={year.toString()}>
                      {year}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              
              <Select
                value={selectedMonth?.toString() || "all"}
                onValueChange={(value) => setSelectedMonth(value === "all" ? undefined : parseInt(value))}
              >
                <SelectTrigger className="w-40">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {months.map((month) => (
                    <SelectItem 
                      key={month.value?.toString() || "all"} 
                      value={month.value?.toString() || "all"}
                    >
                      {month.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <CardDescription>
            Viewing data for {getPeriodLabel()}
          </CardDescription>
        </CardHeader>
      </Card>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {getSummaryCards().map((card, index) => (
          <Card key={index}>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">{card.title}</CardTitle>
              <card.icon className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{card.value}</div>
              <p className="text-xs text-muted-foreground">{card.description}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Main Content */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>Attendance Records</CardTitle>
              <CardDescription>
                {getPeriodLabel()} timeline view
              </CardDescription>
            </div>
            <Tabs 
              value={activeView} 
              onValueChange={(value) => setActiveView(value as "calendar" | "table" | "charts")}
            >
              <TabsList>
                <TabsTrigger value="calendar">Calendar</TabsTrigger>
                <TabsTrigger value="table">Table</TabsTrigger>
                <TabsTrigger value="charts">Charts</TabsTrigger>
              </TabsList>
            </Tabs>
          </div>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="space-y-4">
              {[...Array(3)].map((_, i) => (
                <div key={i} className="animate-pulse bg-gray-200 h-20 rounded"></div>
              ))}
            </div>
          ) : (
            <>
              {activeView === "calendar" && (
                <EmployeeTimelineCalendar
                  records={timeRecords}
                  year={selectedYear}
                  month={selectedMonth}
                />
              )}
              
              {activeView === "table" && (
                <EmployeeTimelineTable
                  records={timeRecords}
                />
              )}
              
              {activeView === "charts" && (
                <EmployeeTimelineCharts
                  records={timeRecords}
                  summary={summary}
                  year={selectedYear}
                />
              )}
            </>
          )}
        </CardContent>
      </Card>

      {/* Additional Summary Details */}
      {!loading && summary && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <Card>
            <CardHeader>
              <CardTitle>Time Summary</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="flex justify-between text-sm">
                <span>Total Required Time:</span>
                <span className="font-medium">{summary.totalRequiredTime}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span>Total Actual Time:</span>
                <span className="font-medium">{summary.totalActualTime}</span>
              </div>
              <div className="flex justify-between text-sm border-t pt-2">
                <span>Net Overtime/Undertime:</span>
                <Badge variant={
                  summary.totalOvertime === '00:00' ? 'secondary' : 
                  summary.totalOvertime.startsWith('-') ? 'destructive' : 'default'
                }>
                  {summary.totalOvertime === '00:00' ? 'On Time' :
                   summary.totalOvertime.startsWith('-') ? summary.totalOvertime : 
                   `+${summary.totalOvertime}`}
                </Badge>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Attendance Summary</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="flex justify-between text-sm">
                <span>Working Days:</span>
                <span className="font-medium">{summary.workingDays}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span>Present Days:</span>
                <span className="font-medium text-green-600">{summary.presentDays}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span>Absent Days:</span>
                <span className="font-medium text-red-600">{summary.workingDays - summary.presentDays}</span>
              </div>
              <div className="flex justify-between text-sm border-t pt-2">
                <span>Attendance Rate:</span>
                <Badge variant="secondary">
                  {summary.attendancePercentage}%
                </Badge>
              </div>
            </CardContent>
          </Card>
        </div>
      )}
      
      {/* Show loading state for summary details */}
      {loading && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {[...Array(2)].map((_, i) => (
            <Card key={i}>
              <CardHeader>
                <div className="animate-pulse bg-gray-200 h-6 w-32 rounded"></div>
              </CardHeader>
              <CardContent className="space-y-3">
                {[...Array(4)].map((_, j) => (
                  <div key={j} className="flex justify-between">
                    <div className="animate-pulse bg-gray-200 h-4 w-24 rounded"></div>
                    <div className="animate-pulse bg-gray-200 h-4 w-16 rounded"></div>
                  </div>
                ))}
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { format } from "date-fns";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { LoanStatus } from "@prisma/client";

interface Loan {
    id: string;
    issuedAmount: number;
    remainingPrincipal: number;
    remainingPrincipalRaw?: number; // Optional if you control the mapping
    status: LoanStatus;
    totalMonths: number;
    gracePeriodMonths: number;
    createdAt: Date;
    managerVerifiedAt?: Date | null;
    managerVerifiedBy?: {
        id: string;
        firstName: string | null;
        lastName: string | null;
    } | null;
    managerRejectionReason?: string | null;
    managerComments?: string | null;
    adminDeclinedReason?: string | null;
    emiState?: {
        currentEmi: number;
    } | null;
}

export function LoanList({ loans }: { loans: Loan[] }) {
    if (loans.length === 0) {
        return (
            <div className="text-center py-12 text-muted-foreground border rounded-lg bg-white/50">
                <p>No loan history found.</p>
            </div>
        );
    }

    return (
        <div className="border rounded-lg bg-card shadow-sm overflow-hidden">
            <Table>
                <TableHeader>
                    <TableRow className="bg-muted/50">
                        <TableHead>Date Issued</TableHead>
                        <TableHead className="text-right">Issued Amount</TableHead>
                        <TableHead className="text-right">Remaining</TableHead>
                        <TableHead className="text-center">Term</TableHead>
                        <TableHead className="text-right">Monthly EMI</TableHead>
                        <TableHead className="text-center">Status</TableHead>
                    </TableRow>
                </TableHeader>
                <TableBody>
                    {loans.map((loan) => (
                        <TableRow key={loan.id} className="hover:bg-muted/30">
                            <TableCell className="font-medium text-muted-foreground text-xs">
                                {format(new Date(loan.createdAt), "MMM dd, yyyy")}
                            </TableCell>
                            <TableCell className="text-right font-medium">
                                αº│{loan.issuedAmount.toLocaleString("en-BD")}
                            </TableCell>
                            <TableCell className="text-right text-destructive font-bold">
                                αº│{loan.remainingPrincipal.toLocaleString("en-BD")}
                            </TableCell>
                            <TableCell className="text-center text-xs">
                                {loan.totalMonths} months
                                <span className="block text-[10px] text-muted-foreground">
                                    (+{loan.gracePeriodMonths} grace)
                                </span>
                            </TableCell>
                            <TableCell className="text-right">
                                {loan.status === "ACTIVE" ? (
                                    <span className="text-green-600 font-semibold">
                                        αº│{(loan.emiState?.currentEmi || 0).toLocaleString("en-BD")}
                                    </span>
                                ) : (
                                    <span className="text-muted-foreground">-</span>
                                )}
                            </TableCell>
                            <TableCell className="text-center">
                                <div className="space-y-2">
                                    <LoanStatusBadge status={loan.status} />
                                    {loan.managerVerifiedBy && (
                                        <div className="text-[10px] text-muted-foreground">
                                            Checked by {loan.managerVerifiedBy.firstName} {loan.managerVerifiedBy.lastName}
                                        </div>
                                    )}
                                    {loan.status === "MANAGER_REJECTED" && loan.managerRejectionReason && (
                                        <div className="text-[10px] text-red-600 max-w-40 mx-auto">
                                            {loan.managerRejectionReason}
                                        </div>
                                    )}
                                    {loan.status === "DECLINED" && loan.adminDeclinedReason && (
                                        <div className="text-[10px] text-red-600 max-w-40 mx-auto">
                                            {loan.adminDeclinedReason}
                                        </div>
                                    )}
                                </div>
                            </TableCell>
                        </TableRow>
                    ))}
                </TableBody>
            </Table>
        </div>
    );
}

function LoanStatusBadge({ status }: { status: LoanStatus }) {
    const styles = {
        PENDING: "bg-yellow-100 text-yellow-800 border-yellow-200",
        APPROVED: "bg-blue-100 text-blue-800 border-blue-200",
        ACTIVE: "bg-green-100 text-green-800 border-green-200",
        CLOSED: "bg-gray-100 text-gray-800 border-gray-200",
        DECLINED: "bg-red-100 text-red-800 border-red-200",
        MANAGER_VERIFIED: "bg-blue-100 text-blue-800 border-blue-200",
        MANAGER_REJECTED: "bg-orange-100 text-orange-800 border-orange-200",
    };

    return (
        <Badge variant="outline" className={`${styles[status]} font-normal uppercase tracking-wider text-[10px]`}>
            {status}
        </Badge>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Bell, Calendar, Check, Clock } from "lucide-react";
import { format } from "date-fns";
import { getEmployeeNotifications, markNotificationAsRead } from "@/actions/leave-automation.actions";
import { toast } from "sonner";

interface Notification {
    id: string;
    type: string;
    title: string;
    message: string;
    relatedDate?: Date | null;
    isRead: boolean;
    createdAt: Date;
}

interface NotificationPanelProps {
    userId: string;
}

export function NotificationPanel({ userId }: NotificationPanelProps) {
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        loadNotifications();
    }, [userId]);

    const loadNotifications = async () => {
        try {
            const data = await getEmployeeNotifications(userId);
            setNotifications(data as Notification[]);
        } catch (error) {
            console.error("Failed to load notifications:", error);
            toast.error("Failed to load notifications");
        } finally {
            setLoading(false);
        }
    };

    const handleMarkAsRead = async (notificationId: string) => {
        try {
            await markNotificationAsRead(notificationId);
            setNotifications(prev => 
                prev.map(notif => 
                    notif.id === notificationId 
                        ? { ...notif, isRead: true }
                        : notif
                )
            );
        } catch (error) {
            console.error("Failed to mark notification as read:", error);
            toast.error("Failed to mark notification as read");
        }
    };

    const unreadCount = notifications.filter(n => !n.isRead).length;

    const getNotificationIcon = (type: string) => {
        switch (type) {
            case "AUTO_LEAVE_DEDUCTION":
                return <Calendar className="h-4 w-4 text-orange-500" />;
            case "WEEKLY_OFF_SET":
                return <Clock className="h-4 w-4 text-blue-500" />;
            case "ABSENT_WITHOUT_LEAVE":
                return <Bell className="h-4 w-4 text-red-500" />;
            default:
                return <Bell className="h-4 w-4 text-gray-500" />;
        }
    };

    const getNotificationColor = (type: string) => {
        switch (type) {
            case "AUTO_LEAVE_DEDUCTION":
                return "border-l-orange-500";
            case "WEEKLY_OFF_SET":
                return "border-l-blue-500";
            case "ABSENT_WITHOUT_LEAVE":
                return "border-l-red-500";
            default:
                return "border-l-gray-500";
        }
    };

    if (loading) {
        return (
            <Card>
                <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                        <Bell className="h-5 w-5" />
                        Notifications
                    </CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="flex items-center justify-center py-8">
                        <div className="text-muted-foreground">Loading notifications...</div>
                    </div>
                </CardContent>
            </Card>
        );
    }

    return (
        <Card>
            <CardHeader>
                <CardTitle className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        <Bell className="h-5 w-5" />
                        Notifications
                    </div>
                    {unreadCount > 0 && (
                        <Badge variant="destructive" className="ml-2">
                            {unreadCount} unread
                        </Badge>
                    )}
                </CardTitle>
            </CardHeader>
            <CardContent>
                {notifications.length === 0 ? (
                    <div className="text-center py-8 text-muted-foreground">
                        No notifications yet
                    </div>
                ) : (
                    <ScrollArea className="h-[400px]">
                        <div className="space-y-3">
                            {notifications.map((notification) => (
                                <div
                                    key={notification.id}
                                    className={`p-4 border rounded-lg border-l-4 ${getNotificationColor(notification.type)} ${
                                        !notification.isRead ? "bg-blue-50/50" : "bg-gray-50/50"
                                    }`}
                                >
                                    <div className="flex items-start justify-between">
                                        <div className="flex items-start gap-3 flex-1">
                                            {getNotificationIcon(notification.type)}
                                            <div className="flex-1 min-w-0">
                                                <div className="flex items-center gap-2">
                                                    <h4 className="font-medium text-sm">
                                                        {notification.title}
                                                    </h4>
                                                    {!notification.isRead && (
                                                        <div className="w-2 h-2 bg-blue-500 rounded-full"></div>
                                                    )}
                                                </div>
                                                <p className="text-sm text-muted-foreground mt-1">
                                                    {notification.message}
                                                </p>
                                                <div className="flex items-center gap-4 mt-2 text-xs text-muted-foreground">
                                                    <span>
                                                        {format(new Date(notification.createdAt), "MMM d, yyyy 'at' h:mm a")}
                                                    </span>
                                                    {notification.relatedDate && (
                                                        <span>
                                                            Related Date: {format(new Date(notification.relatedDate), "MMM d, yyyy")}
                                                        </span>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                        {!notification.isRead && (
                                            <Button
                                                variant="ghost"
                                                size="sm"
                                                onClick={() => handleMarkAsRead(notification.id)}
                                                className="ml-2"
                                            >
                                                <Check className="h-4 w-4" />
                                            </Button>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </ScrollArea>
                )}
            </CardContent>
        </Card>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { User, Role } from "@prisma/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { toast } from "sonner";
import { submitProfileUpdateRequest, updateUserProfileByAdmin } from "@/actions/profile.actions";
import { updateEmployeeProfile } from "@/actions/employee.actions";
import { getActiveDepartments } from "@/actions/department.actions";
import { getDesignationsByDepartment } from "@/actions/designation.actions";
import { Loader2, UserCog, CalendarDays, DollarSign, User as UserIcon, Briefcase, Calendar } from "lucide-react";

const profileFormSchema = z.object({
  // Personal Information
  gender: z.string().optional(),
  dateOfBirth: z.string().optional(),
  bloodGroup: z.string().optional(),
  nidNumber: z.string().optional(),

  // Contact Information
  phoneNumber: z.string().optional(),
  personalEmail: z.string().email().optional().or(z.literal("")),

  // Current Address
  currentStreet: z.string().optional(),
  currentCity: z.string().optional(),
  currentState: z.string().optional(),
  currentCountry: z.string().optional(),
  currentPostalCode: z.string().optional(),

  // Permanent Address
  permanentStreet: z.string().optional(),
  permanentCity: z.string().optional(),
  permanentState: z.string().optional(),
  permanentCountry: z.string().optional(),
  permanentPostalCode: z.string().optional(),

  // Employment Details
  dateOfJoining: z.string().optional(),
  attendanceId: z.string().optional(),
  workingDaysInMonth: z.string().optional(),

  // Emergency Contact
  emergencyContactName: z.string().optional(),
  emergencyContactRelationship: z.string().optional(),
  emergencyContactPhone: z.string().optional(),
  emergencyContactEmail: z.string().email().optional().or(z.literal("")),
  emergencyContactAddress: z.string().optional(),

  // Banking Information
  bankAccountNumber: z.string().optional(),

  // Professional Links
  portfolioLink: z.string().url().optional().or(z.literal("")),
  githubLink: z.string().url().optional().or(z.literal("")),
  linkedinLink: z.string().url().optional().or(z.literal("")),

  // Employment Details (Admin only)
  role: z.enum(["SUPERADMIN", "HR", "EMPLOYEE"]).optional(),
  branchId: z.string().optional(),
  departmentId: z.string().optional(),
  designationId: z.string().optional(),
});

type ProfileFormValues = z.infer<typeof profileFormSchema>;

interface Branch {
  id: string;
  name: string;
  location: string;
}

interface Department {
  id: string;
  name: string;
}

interface Designation {
  id: string;
  name: string;
}

interface ProfileEditFormProps {
  user: User & {
    branch?: { id: string; name: string; location: string } | null;
    department?: { id: string; name: string } | null;
    designation?: { id: string; name: string } | null;
  };
  branches?: Branch[];
  isAdmin?: boolean;
  onSuccess?: () => void;
  onCancel?: () => void;
}

export function ProfileEditForm({ user, branches = [], isAdmin = false, onSuccess, onCancel }: ProfileEditFormProps) {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeTab, setActiveTab] = useState("personal");
  const [departments, setDepartments] = useState<Department[]>([]);
  const [designations, setDesignations] = useState<Designation[]>([]);
  const [selectedDepartmentId, setSelectedDepartmentId] = useState<string>(
    user.departmentId || ""
  );

  // Load departments and designations for admin
  useEffect(() => {
    if (isAdmin) {
      const loadDepartments = async () => {
        try {
          const depts = await getActiveDepartments();
          setDepartments(depts);
        } catch (error) {
          console.error("Failed to load departments:", error);
        }
      };
      loadDepartments();
    }
  }, [isAdmin]);

  useEffect(() => {
    if (isAdmin && selectedDepartmentId) {
      const loadDesignations = async () => {
        try {
          const desigs = await getDesignationsByDepartment(selectedDepartmentId);
          setDesignations(desigs);
        } catch (error) {
          console.error("Failed to load designations:", error);
        }
      };
      loadDesignations();
    } else {
      setDesignations([]);
    }
  }, [selectedDepartmentId, isAdmin]);

  const form = useForm<ProfileFormValues>({
    resolver: zodResolver(profileFormSchema),
    defaultValues: {
      gender: user.gender || "",
      dateOfBirth: user.dateOfBirth ? new Date(user.dateOfBirth).toISOString().split("T")[0] : "",
      bloodGroup: user.bloodGroup || "",
      nidNumber: user.nidNumber || "",
      phoneNumber: user.phoneNumber || "",
      personalEmail: user.personalEmail || "",
      currentStreet: user.currentStreet || "",
      currentCity: user.currentCity || "",
      currentState: user.currentState || "",
      currentCountry: user.currentCountry || "",
      currentPostalCode: user.currentPostalCode || "",
      permanentStreet: user.permanentStreet || "",
      permanentCity: user.permanentCity || "",
      permanentState: user.permanentState || "",
      permanentCountry: user.permanentCountry || "",
      permanentPostalCode: user.permanentPostalCode || "",
      dateOfJoining: user.dateOfJoining ? new Date(user.dateOfJoining).toISOString().split("T")[0] : "",
      attendanceId: user.attendanceId || "",
      workingDaysInMonth: user.workingDaysInMonth?.toString() || "",
      emergencyContactName: user.emergencyContactName || "",
      emergencyContactRelationship: user.emergencyContactRelationship || "",
      emergencyContactPhone: user.emergencyContactPhone || "",
      emergencyContactEmail: user.emergencyContactEmail || "",
      emergencyContactAddress: user.emergencyContactAddress || "",
      bankAccountNumber: user.bankAccountNumber || "",
      portfolioLink: user.portfolioLink || "",
      githubLink: user.githubLink || "",
      linkedinLink: user.linkedinLink || "",
      // Employment details
      role: user.role as Role,
      branchId: user.branchId || "",
      departmentId: user.departmentId || "",
      designationId: user.designationId || "",
    },
  });

  async function onSubmit(data: ProfileFormValues) {
    setIsSubmitting(true);
    try {
      const workingDaysRaw = data.workingDaysInMonth?.trim();
      let workingDaysValue: number | null | undefined = undefined;

      if (isAdmin) {
        if (!workingDaysRaw) {
          workingDaysValue = null;
        } else {
          const parsed = Number(workingDaysRaw);
          if (!Number.isInteger(parsed) || parsed < 0 || parsed > 31) {
            toast.error("Working days must be a whole number between 0 and 31");
            setIsSubmitting(false);
            return;
          }
          workingDaysValue = parsed;
        }
      }

      // Convert date strings to Date objects
      const { workingDaysInMonth, role, branchId, departmentId, designationId, ...rest } = data;
      const formattedData = {
        ...rest,
        dateOfBirth: data.dateOfBirth ? new Date(data.dateOfBirth) : null,
        dateOfJoining: data.dateOfJoining ? new Date(data.dateOfJoining) : null,
        ...(isAdmin ? { workingDaysInMonth: workingDaysValue } : {}),
      };

      let result;
      if (isAdmin) {
        // Admin can update profile and employment details
        const profileResult = await updateUserProfileByAdmin(user.id, formattedData);
        
        // Update employment details if any have changed
        if (role || branchId || departmentId || designationId) {
          const employmentData = {
            role: role as Role,
            branchId: branchId || null,
            departmentId: departmentId || null,
            designationId: designationId || null,
          };
          const employmentResult = await updateEmployeeProfile(user.id, employmentData);
          
          if (!employmentResult.success) {
            toast.error(employmentResult.error || "Failed to update employment details");
            setIsSubmitting(false);
            return;
          }
        }
        result = profileResult;
      } else {
        // Employee submits update request
        result = await submitProfileUpdateRequest(formattedData);
      }

      if (result.success) {
        toast.success(
          isAdmin
            ? "Profile updated successfully"
            : "Profile update request submitted. Awaiting admin approval."
        );
        onSuccess?.();
      } else {
        toast.error(result.error || "Failed to update profile");
      }
    } catch (error) {
      toast.error("An error occurred while updating profile");
      console.error(error);
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="personal" className="flex items-center gap-2">
              <UserIcon className="h-4 w-4" />
              Personal Info
            </TabsTrigger>
            <TabsTrigger value="employment" className="flex items-center gap-2">
              <Briefcase className="h-4 w-4" />
              Employment
            </TabsTrigger>
            <TabsTrigger value="leave-allowance" className="flex items-center gap-2">
              <Calendar className="h-4 w-4" />
              Leave & Allowance
            </TabsTrigger>
          </TabsList>

          {/* Personal Info Tab */}
          <TabsContent value="personal" className="space-y-6">
            {/* Personal Information */}
            <Card>
          <CardHeader>
            <CardTitle>Personal Information</CardTitle>
            <CardDescription>Update your personal details</CardDescription>
          </CardHeader>
          <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <FormField
              control={form.control}
              name="gender"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Gender</FormLabel>
                  <Select onValueChange={field.onChange} defaultValue={field.value}>
                    <FormControl>
                      <SelectTrigger>
                        <SelectValue placeholder="Select gender" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      <SelectItem value="Male">Male</SelectItem>
                      <SelectItem value="Female">Female</SelectItem>
                      <SelectItem value="Other">Other</SelectItem>
                      <SelectItem value="Prefer not to say">Prefer not to say</SelectItem>
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="dateOfBirth"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Date of Birth</FormLabel>
                  <FormControl>
                    <Input type="date" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="bloodGroup"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Blood Group</FormLabel>
                  <Select onValueChange={field.onChange} defaultValue={field.value}>
                    <FormControl>
                      <SelectTrigger>
                        <SelectValue placeholder="Select blood group" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      <SelectItem value="A+">A+</SelectItem>
                      <SelectItem value="A-">A-</SelectItem>
                      <SelectItem value="B+">B+</SelectItem>
                      <SelectItem value="B-">B-</SelectItem>
                      <SelectItem value="AB+">AB+</SelectItem>
                      <SelectItem value="AB-">AB-</SelectItem>
                      <SelectItem value="O+">O+</SelectItem>
                      <SelectItem value="O-">O-</SelectItem>
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="nidNumber"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>NID Number</FormLabel>
                  <FormControl>
                    <Input placeholder="Enter NID number" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </CardContent>
        </Card>

        {/* Contact Information */}
        <Card>
          <CardHeader>
            <CardTitle>Contact Information</CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <FormField
              control={form.control}
              name="phoneNumber"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Phone Number</FormLabel>
                  <FormControl>
                    <Input placeholder="+1234567890" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="personalEmail"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Personal Email</FormLabel>
                  <FormControl>
                    <Input type="email" placeholder="personal@example.com" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </CardContent>
        </Card>

        {/* Current Address */}
        <Card>
          <CardHeader>
            <CardTitle>Current Address</CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="md:col-span-2">
              <FormField
                control={form.control}
                name="currentStreet"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Street Address</FormLabel>
                    <FormControl>
                      <Input placeholder="123 Main St, Apt 4B" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <FormField
              control={form.control}
              name="currentCity"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>City</FormLabel>
                  <FormControl>
                    <Input placeholder="City" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="currentState"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>State/Province</FormLabel>
                  <FormControl>
                    <Input placeholder="State" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="currentCountry"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Country</FormLabel>
                  <FormControl>
                    <Input placeholder="Country" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="currentPostalCode"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Postal Code</FormLabel>
                  <FormControl>
                    <Input placeholder="12345" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </CardContent>
        </Card>

        {/* Permanent Address */}
        <Card>
          <CardHeader>
            <CardTitle>Permanent Address</CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="md:col-span-2">
              <FormField
                control={form.control}
                name="permanentStreet"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Street Address</FormLabel>
                    <FormControl>
                      <Input placeholder="123 Main St, Apt 4B" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <FormField
              control={form.control}
              name="permanentCity"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>City</FormLabel>
                  <FormControl>
                    <Input placeholder="City" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="permanentState"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>State/Province</FormLabel>
                  <FormControl>
                    <Input placeholder="State" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="permanentCountry"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Country</FormLabel>
                  <FormControl>
                    <Input placeholder="Country" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="permanentPostalCode"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Postal Code</FormLabel>
                  <FormControl>
                    <Input placeholder="12345" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </CardContent>
        </Card>

        {/* Employment Details */}
        <Card>
          <CardHeader>
            <CardTitle>Employment Details</CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <FormField
              control={form.control}
              name="dateOfJoining"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Date of Joining</FormLabel>
                  <FormControl>
                    <Input type="date" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="attendanceId"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Attendance ID</FormLabel>
                  <FormControl>
                    <Input placeholder="EMP001" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            {isAdmin && (
              <FormField
                control={form.control}
                name="workingDaysInMonth"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Working Days (Monthly)</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        min={0}
                        max={31}
                        placeholder="22"
                        {...field}
                      />
                    </FormControl>
                    <FormDescription>Set the monthly working days for this employee.</FormDescription>
                    <FormMessage />
                  </FormItem>
                )}
              />
            )}
          </CardContent>
        </Card>

        {/* Emergency Contact */}
        <Card>
          <CardHeader>
            <CardTitle>Emergency Contact</CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <FormField
              control={form.control}
              name="emergencyContactName"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Name</FormLabel>
                  <FormControl>
                    <Input placeholder="John Doe" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="emergencyContactRelationship"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Relationship</FormLabel>
                  <FormControl>
                    <Input placeholder="Spouse, Parent, etc." {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="emergencyContactPhone"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Phone</FormLabel>
                  <FormControl>
                    <Input placeholder="+1234567890" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="emergencyContactEmail"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Email</FormLabel>
                  <FormControl>
                    <Input type="email" placeholder="emergency@example.com" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <div className="md:col-span-2">
              <FormField
                control={form.control}
                name="emergencyContactAddress"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Address</FormLabel>
                    <FormControl>
                      <Input placeholder="Full address" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>
          </CardContent>
        </Card>

        {/* Banking Information */}
        <Card>
          <CardHeader>
            <CardTitle>Banking Information</CardTitle>
          </CardHeader>
          <CardContent>
            <FormField
              control={form.control}
              name="bankAccountNumber"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Bank Account Number</FormLabel>
                  <FormControl>
                    <Input placeholder="Account number" {...field} />
                  </FormControl>
                  <FormDescription>This information is kept confidential</FormDescription>
                  <FormMessage />
                </FormItem>
              )}
            />
          </CardContent>
        </Card>

        {/* Professional Links */}
        <Card>
          <CardHeader>
            <CardTitle>Professional Links</CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <FormField
              control={form.control}
              name="portfolioLink"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Portfolio</FormLabel>
                  <FormControl>
                    <Input type="url" placeholder="https://myportfolio.com" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="githubLink"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>GitHub</FormLabel>
                  <FormControl>
                    <Input type="url" placeholder="https://github.com/username" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="linkedinLink"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>LinkedIn</FormLabel>
                  <FormControl>
                    <Input type="url" placeholder="https://linkedin.com/in/username" {...field} />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
          </CardContent>
        </Card>
          </TabsContent>

          {/* Employment Tab */}
          <TabsContent value="employment" className="space-y-6">
            {isAdmin && (
              <Card>
                <CardHeader>
                  <CardTitle>Employment Management</CardTitle>
                  <CardDescription>Administrative employment settings</CardDescription>
                </CardHeader>
                <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <FormField
                    control={form.control}
                    name="role"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Role</FormLabel>
                        <Select onValueChange={field.onChange} defaultValue={field.value}>
                          <FormControl>
                            <SelectTrigger>
                              <SelectValue placeholder="Select role" />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            <SelectItem value="EMPLOYEE">Employee</SelectItem>
                            <SelectItem value="HR">HR</SelectItem>
                            <SelectItem value="SUPERADMIN">Super Admin</SelectItem>
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="branchId"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Branch</FormLabel>
                        <Select onValueChange={field.onChange} defaultValue={field.value}>
                          <FormControl>
                            <SelectTrigger>
                              <SelectValue placeholder="Select branch" />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            {branches.map((branch) => (
                              <SelectItem key={branch.id} value={branch.id}>
                                {branch.name} - {branch.location}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="departmentId"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Department</FormLabel>
                        <Select onValueChange={(value) => {
                          field.onChange(value);
                          setSelectedDepartmentId(value);
                          // Reset designation when department changes
                          form.setValue("designationId", "");
                        }} defaultValue={field.value}>
                          <FormControl>
                            <SelectTrigger>
                              <SelectValue placeholder="Select department" />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            {departments.map((department) => (
                              <SelectItem key={department.id} value={department.id}>
                                {department.name}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="designationId"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Designation</FormLabel>
                        <Select onValueChange={field.onChange} defaultValue={field.value}>
                          <FormControl>
                            <SelectTrigger>
                              <SelectValue placeholder="Select designation" />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            {designations.map((designation) => (
                              <SelectItem key={designation.id} value={designation.id}>
                                {designation.name}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </CardContent>
              </Card>
            )}
          </TabsContent>

          {/* Leave & Allowance Tab */}
          <TabsContent value="leave-allowance" className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Leave & Allowance Information</CardTitle>
                <CardDescription>View your leave balance and allowance details</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="text-sm text-muted-foreground">
                  Leave and allowance information will be displayed here based on your employment records.
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>

        <div className="flex justify-end gap-4">
          {onCancel && (
            <Button type="button" variant="outline" onClick={onCancel} disabled={isSubmitting}>
              Cancel
            </Button>
          )}
          <Button type="submit" disabled={isSubmitting}>
            {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            {isAdmin ? "Update Profile" : "Submit for Approval"}
          </Button>
        </div>
      </form>
    </Form>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { User, Role } from "@prisma/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { 
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow
} from "@/components/ui/table";
import { toast } from "sonner";
import { submitProfileUpdateRequest, updateUserProfileByAdmin } from "@/actions/profile.actions";
import { updateEmployeeProfile } from "@/actions/employee.actions";
import { getActiveDepartments } from "@/actions/department.actions";
import { getDesignationsByDepartment } from "@/actions/designation.actions";
import { getActiveLeaveTypes, getUserLeaveEntitlements, assignLeaveToUser, removeLeaveFromUser } from "@/actions/leave.actions";
import { getAllowanceTypes, getEmployeeAllowances, assignEmployeeAllowance, removeEmployeeAllowance } from "@/actions/settings.actions";
import { Badge } from "@/components/ui/badge";
import { 
  Loader2, 
  User as UserIcon, 
  Briefcase, 
  Calendar,
  Clock,
  DollarSign,
  Plus,
  Minus
} from "lucide-react";

const profileFormSchema = z.object({
  // Personal Information
  gender: z.string().optional(),
  dateOfBirth: z.string().optional(),
  bloodGroup: z.string().optional(),
  nidNumber: z.string().optional(),

  // Contact Information
  phoneNumber: z.string().optional(),
  personalEmail: z.string().email().optional().or(z.literal("")),

  // Current Address
  currentStreet: z.string().optional(),
  currentCity: z.string().optional(),
  currentState: z.string().optional(),
  currentCountry: z.string().optional(),
  currentPostalCode: z.string().optional(),

  // Permanent Address
  permanentStreet: z.string().optional(),
  permanentCity: z.string().optional(),
  permanentState: z.string().optional(),
  permanentCountry: z.string().optional(),
  permanentPostalCode: z.string().optional(),

  // Employment Details
  dateOfJoining: z.string().optional(),
  attendanceId: z.string().optional(),
  workingDaysInMonth: z.string().optional(),

  // Emergency Contact
  emergencyContactName: z.string().optional(),
  emergencyContactRelationship: z.string().optional(),
  emergencyContactPhone: z.string().optional(),
  emergencyContactEmail: z.string().email().optional().or(z.literal("")),
  emergencyContactAddress: z.string().optional(),
  emergencyContactNid: z.string().optional(),

  // Nominee Details
  nomineeName: z.string().optional(),
  nomineeRelationship: z.string().optional(),
  nomineePhone: z.string().optional(),
  nomineeEmail: z.string().email().optional().or(z.literal("")),
  nomineeNid: z.string().optional(),
  nomineeAddress: z.string().optional(),

  // Banking Information
  bankAccountNumber: z.string().optional(),

  // Professional Links
  portfolioLink: z.string().url().optional().or(z.literal("")),
  githubLink: z.string().url().optional().or(z.literal("")),
  linkedinLink: z.string().url().optional().or(z.literal("")),

  // Employee Document Links
  loanPapersLink: z.string().url().optional().or(z.literal("")),
  nomineesPapersLink: z.string().url().optional().or(z.literal("")),
  emergencyContactLink: z.string().url().optional().or(z.literal("")),
  personalInfoLink: z.string().url().optional().or(z.literal("")),

  // Employment Details (Admin only)
  role: z.enum(["EMPLOYEE", "HR", "SUPERADMIN"]).optional(),
  branchId: z.string().optional(),
  departmentId: z.string().optional(),
  designationId: z.string().optional(),
});

type ProfileFormValues = z.infer<typeof profileFormSchema>;

interface Branch {
  id: string;
  name: string;
  location: string;
}

interface Department {
  id: string;
  name: string;
}

interface Designation {
  id: string;
  name: string;
}

interface LeaveType {
  id: string;
  name: string;
  allocatedDays: number;
  requiresApproval: boolean;
  isActive: boolean;
}

interface UserLeaveEntitlement {
  id: string;
  year: number;
  allocatedDays: number;
  usedDays: number;
  leaveType: LeaveType;
}

interface ProfileEditFormProps {
  user: User & {
    branch?: { id: string; name: string; location: string } | null;
    department?: { id: string; name: string } | null;
    designation?: { id: string; name: string } | null;
  };
  branches?: Branch[];
  isAdmin?: boolean;
  allowRoleEdit?: boolean;
  allowPersonalEdit?: boolean;
  onSuccess?: () => void;
  onCancel?: () => void;
}

export function ProfileEditFormTabbed({ user, branches = [], isAdmin = false, allowRoleEdit = true, allowPersonalEdit = true, onSuccess, onCancel }: ProfileEditFormProps) {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeTab, setActiveTab] = useState("personal");
  const [departments, setDepartments] = useState<Department[]>([]);
  const [designations, setDesignations] = useState<Designation[]>([]);
  const [leaveTypes, setLeaveTypes] = useState<LeaveType[]>([]);
  const [userLeaveEntitlements, setUserLeaveEntitlements] = useState<UserLeaveEntitlement[]>([]);
  const [selectedDepartmentId, setSelectedDepartmentId] = useState<string>(
    user.departmentId || ""
  );
  const [isLeaveDialogOpen, setIsLeaveDialogOpen] = useState(false);
  const [selectedLeaveTypeId, setSelectedLeaveTypeId] = useState<string>("");
  const [customLeaveDays, setCustomLeaveDays] = useState<string>("");
  
  // Allowance Management State
  const [allowanceTypes, setAllowanceTypes] = useState<any[]>([]);
  const [userAllowances, setUserAllowances] = useState<any[]>([]);
  const [isAllowanceDialogOpen, setIsAllowanceDialogOpen] = useState(false);
  const [selectedAllowanceId, setSelectedAllowanceId] = useState<string>("");

  // Load departments, designations, leave types, and allowances for admin
  useEffect(() => {
    if (isAdmin) {
      const loadData = async () => {
        try {
          const [depts, leaveTypesData, allowanceTypesData] = await Promise.all([
            getActiveDepartments(),
            getActiveLeaveTypes(),
            getAllowanceTypes()
          ]);
          setDepartments(depts);
          setLeaveTypes(leaveTypesData);
          setAllowanceTypes(allowanceTypesData);
        } catch (error) {
          console.error("Failed to load reference data:", error);
        }
      };
      loadData();
    }
  }, [isAdmin]);

  // Load user leave entitlements
  useEffect(() => {
    const loadLeaveEntitlements = async () => {
      try {
        const entitlements = await getUserLeaveEntitlements(user.id);
        setUserLeaveEntitlements(entitlements);
      } catch (error) {
        console.error("Failed to load leave entitlements:", error);
      }
    };
    loadLeaveEntitlements();
  }, [user.id]);

  // Load user allowances
  useEffect(() => {
    const loadUserAllowances = async () => {
      try {
        const allowances = await getEmployeeAllowances(user.id);
        setUserAllowances(allowances);
      } catch (error) {
        console.error("Failed to load user allowances:", error);
      }
    };
    loadUserAllowances();
  }, [user.id]);

  useEffect(() => {
    if (isAdmin && selectedDepartmentId) {
      const loadDesignations = async () => {
        try {
          const desigs = await getDesignationsByDepartment(selectedDepartmentId);
          setDesignations(desigs);
        } catch (error) {
          console.error("Failed to load designations:", error);
        }
      };
      loadDesignations();
    } else {
      setDesignations([]);
    }
  }, [selectedDepartmentId, isAdmin]);

  const form = useForm<ProfileFormValues>({
    resolver: zodResolver(profileFormSchema),
    defaultValues: {
      gender: user.gender || "",
      dateOfBirth: user.dateOfBirth ? new Date(user.dateOfBirth).toISOString().split("T")[0] : "",
      bloodGroup: user.bloodGroup || "",
      nidNumber: user.nidNumber || "",
      phoneNumber: user.phoneNumber || "",
      personalEmail: user.personalEmail || "",
      currentStreet: user.currentStreet || "",
      currentCity: user.currentCity || "",
      currentState: user.currentState || "",
      currentCountry: user.currentCountry || "",
      currentPostalCode: user.currentPostalCode || "",
      permanentStreet: user.permanentStreet || "",
      permanentCity: user.permanentCity || "",
      permanentState: user.permanentState || "",
      permanentCountry: user.permanentCountry || "",
      permanentPostalCode: user.permanentPostalCode || "",
      dateOfJoining: user.dateOfJoining ? new Date(user.dateOfJoining).toISOString().split("T")[0] : "",
      attendanceId: user.attendanceId || "",
      workingDaysInMonth: user.workingDaysInMonth?.toString() || "",
      emergencyContactName: user.emergencyContactName || "",
      emergencyContactRelationship: user.emergencyContactRelationship || "",
      emergencyContactPhone: user.emergencyContactPhone || "",
      emergencyContactEmail: user.emergencyContactEmail || "",
      emergencyContactAddress: user.emergencyContactAddress || "",
      emergencyContactNid: user.emergencyContactNid || "",
      nomineeName: user.nomineeName || "",
      nomineeRelationship: user.nomineeRelationship || "",
      nomineePhone: user.nomineePhone || "",
      nomineeEmail: user.nomineeEmail || "",
      nomineeNid: user.nomineeNid || "",
      nomineeAddress: user.nomineeAddress || "",
      bankAccountNumber: user.bankAccountNumber || "",
      portfolioLink: user.portfolioLink || "",
      githubLink: user.githubLink || "",
      linkedinLink: user.linkedinLink || "",
      loanPapersLink: user.loanPapersLink || "",
      nomineesPapersLink: user.nomineesPapersLink || "",
      emergencyContactLink: user.emergencyContactLink || "",
      personalInfoLink: user.personalInfoLink || "",
      // Employment details
      role: user.role || "EMPLOYEE",
      branchId: user.branchId || "",
      departmentId: user.departmentId || "",
      designationId: user.designationId || "",
    },
  });

  async function onSubmit(data: ProfileFormValues) {
    setIsSubmitting(true);
    try {
      const workingDaysRaw = data.workingDaysInMonth?.trim();
      let workingDaysValue: number | null | undefined = undefined;

      if (isAdmin) {
        if (!workingDaysRaw) {
          workingDaysValue = null;
        } else {
          const parsed = Number(workingDaysRaw);
          if (!Number.isInteger(parsed) || parsed < 0 || parsed > 31) {
            toast.error("Working days must be a whole number between 0 and 31");
            setIsSubmitting(false);
            return;
          }
          workingDaysValue = parsed;
        }
      }

      // Convert date strings to Date objects and construct proper data object
      const finalFormattedData = {
        // Personal Information
        gender: data.gender || null,
        dateOfBirth: data.dateOfBirth ? new Date(data.dateOfBirth) : null,
        bloodGroup: data.bloodGroup || null,
        nidNumber: data.nidNumber || null,

        // Contact Information
        phoneNumber: data.phoneNumber || null,
        personalEmail: data.personalEmail || null,

        // Current Address
        currentStreet: data.currentStreet || null,
        currentCity: data.currentCity || null,
        currentState: data.currentState || null,
        currentCountry: data.currentCountry || null,
        currentPostalCode: data.currentPostalCode || null,

        // Permanent Address
        permanentStreet: data.permanentStreet || null,
        permanentCity: data.permanentCity || null,
        permanentState: data.permanentState || null,
        permanentCountry: data.permanentCountry || null,
        permanentPostalCode: data.permanentPostalCode || null,

        // Employment Details
        dateOfJoining: data.dateOfJoining ? new Date(data.dateOfJoining) : null,
        attendanceId: data.attendanceId || null,
        ...(isAdmin ? { workingDaysInMonth: workingDaysValue } : {}),

        // Emergency Contact
        emergencyContactName: data.emergencyContactName || null,
        emergencyContactRelationship: data.emergencyContactRelationship || null,
        emergencyContactPhone: data.emergencyContactPhone || null,
        emergencyContactEmail: data.emergencyContactEmail || null,
        emergencyContactAddress: data.emergencyContactAddress || null,
        emergencyContactNid: data.emergencyContactNid || null,

        // Nominee Details
        nomineeName: data.nomineeName || null,
        nomineeRelationship: data.nomineeRelationship || null,
        nomineePhone: data.nomineePhone || null,
        nomineeEmail: data.nomineeEmail || null,
        nomineeNid: data.nomineeNid || null,
        nomineeAddress: data.nomineeAddress || null,

        // Banking Information
        bankAccountNumber: data.bankAccountNumber || null,

        // Professional Links
        portfolioLink: data.portfolioLink || null,
        githubLink: data.githubLink || null,
        linkedinLink: data.linkedinLink || null,
        loanPapersLink: data.loanPapersLink || null,
        nomineesPapersLink: data.nomineesPapersLink || null,
        emergencyContactLink: data.emergencyContactLink || null,
        personalInfoLink: data.personalInfoLink || null,
      };

      let result;
      if (isAdmin) {
        const managerRestrictedProfileData = {
          dateOfJoining: finalFormattedData.dateOfJoining,
          attendanceId: finalFormattedData.attendanceId,
          ...(isAdmin ? { workingDaysInMonth: workingDaysValue } : {}),
          loanPapersLink: finalFormattedData.loanPapersLink,
          nomineesPapersLink: finalFormattedData.nomineesPapersLink,
          emergencyContactLink: finalFormattedData.emergencyContactLink,
          personalInfoLink: finalFormattedData.personalInfoLink,
        };

        // Admin can update profile and employment details
        const profileResult = await updateUserProfileByAdmin(
          user.id,
          allowPersonalEdit ? finalFormattedData : managerRestrictedProfileData
        );
        
        // Update employment details if any have changed
        if (data.role || data.branchId || data.departmentId || data.designationId) {
          const employmentData = {
            ...(allowRoleEdit ? { role: data.role as Role } : {}),
            branchId: data.branchId || null,
            departmentId: data.departmentId || null,
            designationId: data.designationId || null,
          };
          const employmentResult = await updateEmployeeProfile(user.id, employmentData);
          
          if (!employmentResult.success) {
            toast.error(employmentResult.error || "Failed to update employment details");
            setIsSubmitting(false);
            return;
          }
        }
        result = profileResult;
      } else {
        // Employee submits update request
        result = await submitProfileUpdateRequest(finalFormattedData);
      }

      if (result.success) {
        toast.success(
          isAdmin
            ? "Profile updated successfully"
            : "Profile update request submitted. Awaiting admin approval."
        );
        if (onSuccess) onSuccess();
      } else {
        toast.error(result.error || "Failed to update profile");
      }
    } catch (error) {
      console.error("Error updating profile:", error);
      toast.error("An unexpected error occurred");
    } finally {
      setIsSubmitting(false);
    }
  }

  // Leave management functions
  const handleAssignLeave = async (leaveTypeId: string, customDays?: number) => {
    try {
      const result = await assignLeaveToUser(user.id, leaveTypeId, customDays);
      if (result.success) {
        toast.success("Leave type assigned successfully");
        // Reload leave entitlements
        const entitlements = await getUserLeaveEntitlements(user.id);
        setUserLeaveEntitlements(entitlements);
        setIsLeaveDialogOpen(false);
        setSelectedLeaveTypeId("");
        setCustomLeaveDays("");
      } else {
        toast.error(result.error || "Failed to assign leave type");
      }
    } catch (error) {
      console.error("Error assigning leave:", error);
      toast.error("Failed to assign leave type");
    }
  };

  const handleRemoveLeave = async (leaveTypeId: string) => {
    try {
      const result = await removeLeaveFromUser(user.id, leaveTypeId);
      if (result.success) {
        toast.success("Leave type removed successfully");
        // Reload leave entitlements
        const entitlements = await getUserLeaveEntitlements(user.id);
        setUserLeaveEntitlements(entitlements);
      } else {
        toast.error(result.error || "Failed to remove leave type");
      }
    } catch (error) {
      console.error("Error removing leave:", error);
      toast.error("Failed to remove leave type");
    }
  };

  const handleUpdateLeaveAllocation = async (leaveTypeId: string, newDays: number) => {
    await handleAssignLeave(leaveTypeId, newDays);
  };

  // Allowance management functions
  const handleAssignAllowance = async (allowanceId: string) => {
    try {
      const result = await assignEmployeeAllowance(user.id, allowanceId);
      if (result.success) {
        toast.success("Allowance assigned successfully");
        // Reload user allowances
        const allowances = await getEmployeeAllowances(user.id);
        setUserAllowances(allowances);
        setIsAllowanceDialogOpen(false);
        setSelectedAllowanceId("");
      } else {
        toast.error(result.error || "Failed to assign allowance");
      }
    } catch (error) {
      console.error("Error assigning allowance:", error);
      toast.error("Failed to assign allowance");
    }
  };

  const handleRemoveAllowance = async (allowanceId: string) => {
    try {
      const result = await removeEmployeeAllowance(user.id, allowanceId);
      if (result.success) {
        toast.success("Allowance removed successfully");
        // Reload user allowances
        const allowances = await getEmployeeAllowances(user.id);
        setUserAllowances(allowances);
      } else {
        toast.error(result.error || "Failed to remove allowance");
      }
    } catch (error) {
      console.error("Error removing allowance:", error);
      toast.error("Failed to remove allowance");
    }
  };

  const handleAddAllowance = () => {
    if (!selectedAllowanceId) {
      toast.error("Please select an allowance type");
      return;
    }
    
    handleAssignAllowance(selectedAllowanceId);
  };

  const handleAddLeaveType = () => {
    if (!selectedLeaveTypeId) {
      toast.error("Please select a leave type");
      return;
    }
    
    let customDaysNumber: number | undefined = undefined;
    if (customLeaveDays) {
      const parsedDays = parseInt(customLeaveDays);
      if (isNaN(parsedDays) || parsedDays < 0) {
        toast.error("Please enter a valid number of days");
        return;
      }
      customDaysNumber = parsedDays;
    }
    
    handleAssignLeave(selectedLeaveTypeId, customDaysNumber);
  };

  // Get available leave types (not yet assigned to user)
  const availableLeaveTypes = leaveTypes.filter(
    leaveType => !userLeaveEntitlements.some(
      entitlement => entitlement.leaveType.id === leaveType.id
    )
  );

  // Get available allowance types (not yet assigned to user and active)
  const availableAllowanceTypes = allowanceTypes.filter(
    allowanceType => allowanceType.isActive && !userAllowances.some(
      userAllowance => userAllowance.allowanceId === allowanceType.id && userAllowance.isActive
    )
  );

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="personal" className="flex items-center gap-2">
              <UserIcon className="h-4 w-4" />
              Personal Info
            </TabsTrigger>
            <TabsTrigger value="employment" className="flex items-center gap-2">
              <Briefcase className="h-4 w-4" />
              Employment
            </TabsTrigger>
            <TabsTrigger value="leave-allowance" className="flex items-center gap-2">
              <Calendar className="h-4 w-4" />
              Leave & Allowance
            </TabsTrigger>
          </TabsList>

          {/* Personal Info Tab */}
          <TabsContent value="personal" className="space-y-6">
            {!allowPersonalEdit && (
              <Card>
                <CardContent className="pt-6">
                  <p className="text-sm text-muted-foreground">
                    Personal information is read-only for managers.
                  </p>
                </CardContent>
              </Card>
            )}

            <fieldset disabled={!allowPersonalEdit} className={!allowPersonalEdit ? "opacity-70" : ""}>
            {/* Personal Information */}
            <Card>
              <CardHeader>
                <CardTitle>Personal Information</CardTitle>
                <CardDescription>Update your personal details</CardDescription>
              </CardHeader>
              <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <FormField
                  control={form.control}
                  name="gender"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Gender</FormLabel>
                      <Select onValueChange={field.onChange} value={field.value}>
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue placeholder="Select gender" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          <SelectItem value="Male">Male</SelectItem>
                          <SelectItem value="Female">Female</SelectItem>
                          <SelectItem value="Other">Other</SelectItem>
                          <SelectItem value="Prefer not to say">Prefer not to say</SelectItem>
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="dateOfBirth"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Date of Birth</FormLabel>
                      <FormControl>
                        <Input type="date" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="bloodGroup"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Blood Group</FormLabel>
                      <Select onValueChange={field.onChange} value={field.value}>
                        <FormControl>
                          <SelectTrigger>
                            <SelectValue placeholder="Select blood group" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          <SelectItem value="A+">A+</SelectItem>
                          <SelectItem value="A-">A-</SelectItem>
                          <SelectItem value="B+">B+</SelectItem>
                          <SelectItem value="B-">B-</SelectItem>
                          <SelectItem value="AB+">AB+</SelectItem>
                          <SelectItem value="AB-">AB-</SelectItem>
                          <SelectItem value="O+">O+</SelectItem>
                          <SelectItem value="O-">O-</SelectItem>
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="nidNumber"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>NID Number</FormLabel>
                      <FormControl>
                        <Input placeholder="Enter NID number" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </CardContent>
            </Card>

            {/* Contact Information */}
            <Card>
              <CardHeader>
                <CardTitle>Contact Information</CardTitle>
              </CardHeader>
              <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <FormField
                  control={form.control}
                  name="phoneNumber"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Phone Number</FormLabel>
                      <FormControl>
                        <Input placeholder="+1234567890" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="personalEmail"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Personal Email</FormLabel>
                      <FormControl>
                        <Input type="email" placeholder="personal@example.com" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </CardContent>
            </Card>

            {/* Address Information */}
            <Card>
              <CardHeader>
                <CardTitle>Address Information</CardTitle>
              </CardHeader>
              <CardContent className="space-y-6">
                {/* Current Address */}
                <div className="space-y-4">
                  <h4 className="font-medium">Current Address</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <FormField
                      control={form.control}
                      name="currentStreet"
                      render={({ field }) => (
                        <FormItem className="md:col-span-2">
                          <FormLabel>Street Address</FormLabel>
                          <FormControl>
                            <Input placeholder="Street address" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="currentCity"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>City</FormLabel>
                          <FormControl>
                            <Input placeholder="City" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="currentState"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>State/Province</FormLabel>
                          <FormControl>
                            <Input placeholder="State or Province" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="currentCountry"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Country</FormLabel>
                          <FormControl>
                            <Input placeholder="Country" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="currentPostalCode"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Postal Code</FormLabel>
                          <FormControl>
                            <Input placeholder="Postal code" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                </div>

                {/* Permanent Address */}
                <div className="space-y-4">
                  <h4 className="font-medium">Permanent Address</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <FormField
                      control={form.control}
                      name="permanentStreet"
                      render={({ field }) => (
                        <FormItem className="md:col-span-2">
                          <FormLabel>Street Address</FormLabel>
                          <FormControl>
                            <Input placeholder="Street address" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="permanentCity"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>City</FormLabel>
                          <FormControl>
                            <Input placeholder="City" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="permanentState"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>State/Province</FormLabel>
                          <FormControl>
                            <Input placeholder="State or Province" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="permanentCountry"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Country</FormLabel>
                          <FormControl>
                            <Input placeholder="Country" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="permanentPostalCode"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Postal Code</FormLabel>
                          <FormControl>
                            <Input placeholder="Postal code" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Emergency Contact */}
            <Card>
              <CardHeader>
                <CardTitle>Emergency Contact</CardTitle>
              </CardHeader>
              <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <FormField
                  control={form.control}
                  name="emergencyContactName"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Name</FormLabel>
                      <FormControl>
                        <Input placeholder="Emergency contact name" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="emergencyContactRelationship"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Relationship</FormLabel>
                      <FormControl>
                        <Input placeholder="e.g. Father, Mother, Spouse" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="emergencyContactPhone"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Phone Number</FormLabel>
                      <FormControl>
                        <Input placeholder="+1234567890" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="emergencyContactEmail"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Email (Optional)</FormLabel>
                      <FormControl>
                        <Input type="email" placeholder="emergency@example.com" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="emergencyContactAddress"
                  render={({ field }) => (
                    <FormItem className="md:col-span-2">
                      <FormLabel>Address</FormLabel>
                      <FormControl>
                        <Input placeholder="Emergency contact address" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="emergencyContactNid"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>NID Number</FormLabel>
                      <FormControl>
                        <Input placeholder="National ID number" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </CardContent>
            </Card>

            {/* Professional Links */}
            <Card>
              <CardHeader>
                <CardTitle>Professional Links</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <FormField
                  control={form.control}
                  name="portfolioLink"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Portfolio</FormLabel>
                      <FormControl>
                        <Input type="url" placeholder="https://myportfolio.com" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="githubLink"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>GitHub</FormLabel>
                      <FormControl>
                        <Input type="url" placeholder="https://github.com/username" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={form.control}
                  name="linkedinLink"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>LinkedIn</FormLabel>
                      <FormControl>
                        <Input type="url" placeholder="https://linkedin.com/in/username" {...field} />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </CardContent>
            </Card>
            </fieldset>
          </TabsContent>

          {/* Employment Details Tab */}
          <TabsContent value="employment" className="space-y-6">
            <Card>
              <CardHeader>
                <CardTitle>Employment Information</CardTitle>
                <CardDescription>
                  {isAdmin 
                    ? "Update employment details and organizational assignment" 
                    : "View your employment information"
                  }
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <FormField
                    control={form.control}
                    name="dateOfJoining"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Date of Joining</FormLabel>
                        <FormControl>
                          <Input type="date" disabled={!isAdmin} {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="attendanceId"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Attendance ID</FormLabel>
                        <FormControl>
                          <Input placeholder="Employee ID for attendance" disabled={!isAdmin} {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  {isAdmin && (
                    <FormField
                      control={form.control}
                      name="workingDaysInMonth"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Working Days in Month</FormLabel>
                          <FormControl>
                            <Input 
                              type="number" 
                              min="0" 
                              max="31" 
                              placeholder="22" 
                              {...field} 
                            />
                          </FormControl>
                          <FormDescription>Number of working days per month (0-31)</FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  )}
                </div>

                {/* Admin-only employment details */}
                {isAdmin && (
                  <div className="space-y-4 border-t pt-6">
                    <h4 className="font-medium">Organizational Assignment</h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {allowRoleEdit && (
                        <FormField
                          control={form.control}
                          name="role"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Role</FormLabel>
                              <Select 
                                onValueChange={field.onChange} 
                                value={field.value}
                              >
                                <FormControl>
                                  <SelectTrigger>
                                    <SelectValue placeholder="Select role" />
                                  </SelectTrigger>
                                </FormControl>
                                <SelectContent>
                                  <SelectItem value="EMPLOYEE">Employee</SelectItem>
                                  <SelectItem value="HR">HR</SelectItem>
                                  <SelectItem value="SUPERADMIN">Super Admin</SelectItem>
                                </SelectContent>
                              </Select>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      )}

                      <FormField
                        control={form.control}
                        name="branchId"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Branch</FormLabel>
                            <Select 
                              onValueChange={field.onChange} 
                              value={field.value}
                            >
                              <FormControl>
                                <SelectTrigger>
                                  <SelectValue placeholder="Select branch (optional)" />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                {branches.map((branch) => (
                                  <SelectItem key={branch.id} value={branch.id}>
                                    {branch.name} - {branch.location}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="departmentId"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Department</FormLabel>
                            <Select 
                              onValueChange={(value) => {
                                field.onChange(value);
                                setSelectedDepartmentId(value);
                                // Clear designation when department changes
                                form.setValue("designationId", "");
                              }}
                              value={field.value}
                            >
                              <FormControl>
                                <SelectTrigger>
                                  <SelectValue placeholder="Select department (optional)" />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                {departments.map((dept) => (
                                  <SelectItem key={dept.id} value={dept.id}>
                                    {dept.name}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="designationId"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Designation</FormLabel>
                            <Select 
                              onValueChange={field.onChange} 
                              value={field.value}
                              disabled={!selectedDepartmentId}
                            >
                              <FormControl>
                                <SelectTrigger>
                                  <SelectValue placeholder="Select designation (optional)" />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                {designations.map((designation) => (
                                  <SelectItem key={designation.id} value={designation.id}>
                                    {designation.name}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                            {!selectedDepartmentId && (
                              <FormDescription>Select a department first</FormDescription>
                            )}
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>
                  </div>
                )}

                {isAdmin && (
                  <div className="space-y-4 border-t pt-6">
                    <h4 className="font-medium">Employee Document Links</h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <FormField
                        control={form.control}
                        name="loanPapersLink"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Loan Papers Link</FormLabel>
                            <FormControl>
                              <Input type="url" placeholder="https://..." {...field} />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="nomineesPapersLink"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Nominees Papers Link</FormLabel>
                            <FormControl>
                              <Input type="url" placeholder="https://..." {...field} />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="emergencyContactLink"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Emergency Contact Link</FormLabel>
                            <FormControl>
                              <Input type="url" placeholder="https://..." {...field} />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      <FormField
                        control={form.control}
                        name="personalInfoLink"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>Personal Info Link</FormLabel>
                            <FormControl>
                              <Input type="url" placeholder="https://..." {...field} />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>
                  </div>
                )}

                {/* Display current employment info for non-admin users */}
                {!isAdmin && (
                  <div className="space-y-4 border-t pt-6">
                    <h4 className="font-medium">Current Assignment</h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <label className="text-sm font-medium">Role</label>
                        <Badge variant="secondary">{user.role}</Badge>
                      </div>
                      
                      {user.branch && (
                        <div className="space-y-2">
                          <label className="text-sm font-medium">Branch</label>
                          <p className="text-sm text-muted-foreground">{user.branch.name} - {user.branch.location}</p>
                        </div>
                      )}
                      
                      {user.department && (
                        <div className="space-y-2">
                          <label className="text-sm font-medium">Department</label>
                          <p className="text-sm text-muted-foreground">{user.department.name}</p>
                        </div>
                      )}
                      
                      {user.designation && (
                        <div className="space-y-2">
                          <label className="text-sm font-medium">Designation</label>
                          <p className="text-sm text-muted-foreground">{user.designation.name}</p>
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </CardContent>
            </Card>

            {allowPersonalEdit && (
              <>
                {/* Nominee Details */}
                <Card>
                  <CardHeader>
                    <CardTitle>Nominee Details</CardTitle>
                    <CardDescription>Person who will receive benefits in case of emergency</CardDescription>
                  </CardHeader>
                  <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <FormField
                      control={form.control}
                      name="nomineeName"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Name</FormLabel>
                          <FormControl>
                            <Input placeholder="Nominee name" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="nomineeRelationship"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Relationship</FormLabel>
                          <FormControl>
                            <Input placeholder="e.g. Father, Mother, Spouse, Child" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="nomineePhone"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Phone Number</FormLabel>
                          <FormControl>
                            <Input placeholder="+1234567890" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="nomineeEmail"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Email (Optional)</FormLabel>
                          <FormControl>
                            <Input type="email" placeholder="nominee@example.com" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="nomineeNid"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>NID Number</FormLabel>
                          <FormControl>
                            <Input placeholder="National ID number" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="nomineeAddress"
                      render={({ field }) => (
                        <FormItem className="md:col-span-2">
                          <FormLabel>Address</FormLabel>
                          <FormControl>
                            <Input placeholder="Nominee's complete address" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </CardContent>
                </Card>

                {/* Banking Information */}
                <Card>
                  <CardHeader>
                    <CardTitle>Banking Information</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <FormField
                      control={form.control}
                      name="bankAccountNumber"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Bank Account Number</FormLabel>
                          <FormControl>
                            <Input placeholder="Account number" {...field} />
                          </FormControl>
                          <FormDescription>This information is kept confidential</FormDescription>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </CardContent>
                </Card>
              </>
            )}
          </TabsContent>

          {/* Leave & Allowance Management Tab */}
          <TabsContent value="leave-allowance" className="space-y-6">
            {/* Leave Management */}
            <Card>
              <CardHeader className="flex flex-row items-center justify-between">
                <div>
                  <CardTitle className="flex items-center gap-2">
                    <Clock className="h-5 w-5" />
                    Leave Management
                  </CardTitle>
                  <CardDescription>
                    {isAdmin ? "Manage leave types and allocations for this employee" : "View your leave entitlements"}
                  </CardDescription>
                </div>
                {isAdmin && (
                  <Dialog open={isLeaveDialogOpen} onOpenChange={setIsLeaveDialogOpen}>
                    <DialogTrigger asChild>
                      <Button size="sm">
                        <Plus className="h-4 w-4 mr-2" />
                        Add Leave Type
                      </Button>
                    </DialogTrigger>
                    <DialogContent>
                      <DialogHeader>
                        <DialogTitle>Assign Leave Type</DialogTitle>
                      </DialogHeader>
                      <div className="space-y-4">
                        <div>
                          <label className="text-sm font-medium">Leave Type</label>
                          <Select value={selectedLeaveTypeId} onValueChange={setSelectedLeaveTypeId}>
                            <SelectTrigger>
                              <SelectValue placeholder="Select a leave type" />
                            </SelectTrigger>
                            <SelectContent>
                              {availableLeaveTypes.map(leaveType => (
                                <SelectItem key={leaveType.id} value={leaveType.id}>
                                  {leaveType.name} ({leaveType.allocatedDays} days default)
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </div>
                        <div>
                          <label className="text-sm font-medium">Custom Allocation (Optional)</label>
                          <Input
                            type="number"
                            placeholder="Leave empty to use default allocation"
                            value={customLeaveDays}
                            onChange={(e) => setCustomLeaveDays(e.target.value)}
                          />
                          {selectedLeaveTypeId && (
                            <p className="text-xs text-muted-foreground mt-1">
                              Default: {leaveTypes.find(lt => lt.id === selectedLeaveTypeId)?.allocatedDays || 0} days
                            </p>
                          )}
                        </div>
                        <div className="flex justify-end gap-2">
                          <Button variant="outline" onClick={() => setIsLeaveDialogOpen(false)}>
                            Cancel
                          </Button>
                          <Button onClick={handleAddLeaveType}>
                            Assign Leave Type
                          </Button>
                        </div>
                      </div>
                    </DialogContent>
                  </Dialog>
                )}
              </CardHeader>
              <CardContent>
                {userLeaveEntitlements.length === 0 ? (
                  <div className="text-center py-8 text-muted-foreground">
                    <Calendar className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
                    <p className="text-sm font-medium">No Leave Types Assigned</p>
                    <p className="text-xs">
                      {isAdmin 
                        ? "Click 'Add Leave Type' to assign leave types to this employee"
                        : "Contact your admin to get leave types assigned"
                      }
                    </p>
                  </div>
                ) : (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Leave Type</TableHead>
                        <TableHead>Allocated Days</TableHead>
                        <TableHead>Used Days</TableHead>
                        <TableHead>Remaining</TableHead>
                        <TableHead>Requires Approval</TableHead>
                        {isAdmin && <TableHead>Actions</TableHead>}
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {userLeaveEntitlements.map((entitlement) => (
                        <TableRow key={entitlement.id}>
                          <TableCell className="font-medium">
                            {entitlement.leaveType.name}
                          </TableCell>
                          <TableCell>
                            {isAdmin ? (
                              <Input
                                type="number"
                                value={entitlement.allocatedDays}
                                onChange={(e) => {
                                  const newDays = parseInt(e.target.value);
                                  if (!isNaN(newDays) && newDays >= 0) {
                                    handleUpdateLeaveAllocation(entitlement.leaveType.id, newDays);
                                  }
                                }}
                                className="w-20"
                                min="0"
                              />
                            ) : (
                              entitlement.allocatedDays
                            )}
                          </TableCell>
                          <TableCell>{entitlement.usedDays}</TableCell>
                          <TableCell>
                            <Badge variant={entitlement.allocatedDays - entitlement.usedDays <= 0 ? "destructive" : "secondary"}>
                              {entitlement.allocatedDays - entitlement.usedDays}
                            </Badge>
                          </TableCell>
                          <TableCell>
                            <Badge variant={entitlement.leaveType.requiresApproval ? "default" : "secondary"}>
                              {entitlement.leaveType.requiresApproval ? "Yes" : "No"}
                            </Badge>
                          </TableCell>
                          {isAdmin && (
                            <TableCell>
                              <Button
                                size="sm"
                                variant="destructive"
                                onClick={() => handleRemoveLeave(entitlement.leaveType.id)}
                              >
                                <Minus className="h-3 w-3" />
                              </Button>
                            </TableCell>
                          )}
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                )}
              </CardContent>
            </Card>

            {/* Allowance Management */}
            <Card>
              <CardHeader className="flex flex-row items-center justify-between">
                <div>
                  <CardTitle className="flex items-center gap-2">
                    <DollarSign className="h-5 w-5" />
                    Allowance Management
                  </CardTitle>
                  <CardDescription>
                    {isAdmin ? "Manage allowances for this employee" : "View your assigned allowances"}
                  </CardDescription>
                </div>
                {isAdmin && (
                  <Dialog open={isAllowanceDialogOpen} onOpenChange={setIsAllowanceDialogOpen}>
                    <DialogTrigger asChild>
                      <Button size="sm">
                        <Plus className="h-4 w-4 mr-2" />
                        Add Allowance
                      </Button>
                    </DialogTrigger>
                    <DialogContent>
                      <DialogHeader>
                        <DialogTitle>Assign Allowance</DialogTitle>
                      </DialogHeader>
                      <div className="space-y-4">
                        <div>
                          <label className="text-sm font-medium">Allowance Type</label>
                          <Select value={selectedAllowanceId} onValueChange={setSelectedAllowanceId}>
                            <SelectTrigger>
                              <SelectValue placeholder="Select an allowance type" />
                            </SelectTrigger>
                            <SelectContent>
                              {availableAllowanceTypes.map(allowanceType => (
                                <SelectItem key={allowanceType.id} value={allowanceType.id}>
                                  {allowanceType.name} - {allowanceType.valueType === 'PERCENTAGE' ? `${allowanceType.amount}%` : `$${allowanceType.amount}`}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </div>
                        <div className="flex justify-end gap-2">
                          <Button variant="outline" onClick={() => setIsAllowanceDialogOpen(false)}>
                            Cancel
                          </Button>
                          <Button onClick={handleAddAllowance}>
                            Assign Allowance
                          </Button>
                        </div>
                      </div>
                    </DialogContent>
                  </Dialog>
                )}
              </CardHeader>
              <CardContent>
                {userAllowances.filter(allowance => allowance.isActive).length === 0 ? (
                  <div className="text-center py-8 text-muted-foreground">
                    <DollarSign className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
                    <p className="text-sm font-medium">No Allowances Assigned</p>
                    <p className="text-xs">
                      {isAdmin 
                        ? "Click 'Add Allowance' to assign allowances to this employee"
                        : "Contact your admin to get allowances assigned"
                      }
                    </p>
                  </div>
                ) : (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Allowance Name</TableHead>
                        <TableHead>Amount</TableHead>
                        <TableHead>Type</TableHead>
                        <TableHead>Scope</TableHead>
                        <TableHead>Status</TableHead>
                        {isAdmin && <TableHead>Actions</TableHead>}
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {userAllowances.filter(userAllowance => userAllowance.isActive).map((userAllowance) => (
                        <TableRow key={userAllowance.id}>
                          <TableCell className="font-medium">
                            {userAllowance.allowance.name}
                          </TableCell>
                          <TableCell>
                            {userAllowance.allowance.valueType === 'PERCENTAGE' 
                              ? `${userAllowance.allowance.amount}%` 
                              : `$${userAllowance.allowance.amount}`
                            }
                          </TableCell>
                          <TableCell>
                            <Badge variant={userAllowance.allowance.valueType === 'PERCENTAGE' ? "default" : "secondary"}>
                              {userAllowance.allowance.valueType === 'PERCENTAGE' ? "Percentage" : "Fixed"}
                            </Badge>
                          </TableCell>
                          <TableCell>
                            <Badge variant="outline">
                              {userAllowance.allowance.scope}
                            </Badge>
                          </TableCell>
                          <TableCell>
                            <Badge variant="default">
                              Active
                            </Badge>
                          </TableCell>
                          {isAdmin && (
                            <TableCell>
                              <Button
                                size="sm"
                                variant="destructive"
                                onClick={() => handleRemoveAllowance(userAllowance.allowanceId)}
                              >
                                <Minus className="h-3 w-3" />
                              </Button>
                            </TableCell>
                          )}
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* Form Action Buttons */}
          <div className="flex justify-end gap-4 pt-6 border-t">
            {onCancel && (
              <Button type="button" variant="outline" onClick={onCancel} disabled={isSubmitting}>
                Cancel
              </Button>
            )}
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {isAdmin ? "Update Profile" : "Submit for Approval"}
            </Button>
          </div>
        </Tabs>
      </form>
    </Form>
  );
}

"use client";

import { Bar, BarChart, ResponsiveContainer, XAxis, YAxis, Tooltip, CartesianGrid } from "recharts";

export function SalaryChart({ data }: { data: { name: string; amount: number }[] }) {
    if (data.length === 0) {
        return (
            <div className="h-[300px] flex items-center justify-center text-muted-foreground italic border rounded-lg bg-muted/20">
                No salary payments recorded yet.
            </div>
        );
    }

    return (
        <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
                <BarChart data={data}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                    <XAxis
                        dataKey="name"
                        stroke="#64748b"
                        fontSize={12}
                        tickLine={false}
                        axisLine={false}
                    />
                    <YAxis
                        stroke="#64748b"
                        fontSize={12}
                        tickLine={false}
                        axisLine={false}
                        tickFormatter={(value) => `αº│${value}`}
                    />
                    <Tooltip
                        cursor={{ fill: '#f1f5f9' }}
                        contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                        formatter={(value: any) => [`αº│${(value as number).toLocaleString("en-BD")}`, "Net Pay"]}
                    />
                    <Bar
                        dataKey="amount"
                        fill="#4f46e5"
                        radius={[4, 4, 0, 0]}
                        barSize={40}
                    />
                </BarChart>
            </ResponsiveContainer>
        </div>
    );
}

"use client";

import { useTransition } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { Button } from "@/components/ui/button";
import {
    Form,
    FormControl,
    FormDescription,
    FormField,
    FormItem,
    FormLabel,
    FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { createWalletRequest } from "@/actions/wallet.actions";
import { toast } from "sonner";
import { Loader2 } from "lucide-react";

const formSchema = z.object({
    amount: z.coerce.number().min(1, "Amount must be at least 1"),
    description: z.string().min(5, "Description must be at least 5 characters"),
    attachmentUrl: z.string().optional(),
});

export function WalletRequestForm() {
    const [isPending, startTransition] = useTransition();

    const form = useForm<z.infer<typeof formSchema>>({
        resolver: zodResolver(formSchema) as any,
        defaultValues: {
            amount: 0,
            description: "",
            attachmentUrl: "",
        },
    });

    function onSubmit(values: z.infer<typeof formSchema>) {
        startTransition(async () => {
            try {
                await createWalletRequest(values);
                toast.success("Request submitted successfully");
                form.reset();
            } catch (error) {
                toast.error("Failed to submit request");
                console.error(error);
            }
        });
    }

    return (
        <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6 max-w-lg">
                <FormField
                    control={form.control}
                    name="amount"
                    render={({ field }) => (
                        <FormItem>
                            <FormLabel>Amount (Tk)</FormLabel>
                            <FormControl>
                                <Input type="number" placeholder="0.00" {...field} />
                            </FormControl>
                            <FormDescription>
                                The amount you are claiming for reimbursement.
                            </FormDescription>
                            <FormMessage />
                        </FormItem>
                    )}
                />
                <FormField
                    control={form.control}
                    name="description"
                    render={({ field }) => (
                        <FormItem>
                            <FormLabel>Description</FormLabel>
                            <FormControl>
                                <Textarea
                                    placeholder="Details about the expense..."
                                    className="resize-none"
                                    {...field}
                                />
                            </FormControl>
                            <FormMessage />
                        </FormItem>
                    )}
                />
                <FormField
                    control={form.control}
                    name="attachmentUrl"
                    render={({ field }) => (
                        <FormItem>
                            <FormLabel>Attachment URL (Optional)</FormLabel>
                            <FormControl>
                                <Input placeholder="https://..." {...field} />
                            </FormControl>
                            <FormDescription>
                                Link to receipt or document.
                            </FormDescription>
                            <FormMessage />
                        </FormItem>
                    )}
                />

                <Button type="submit" disabled={isPending}>
                    {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                    Submit Application
                </Button>
            </form>
        </Form>
    );
}

"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { CalendarIcon, Filter, TrendingUp, Users, Building, UserCheck, ClipboardList } from "lucide-react";
import { cn } from "@/lib/utils";
import { 
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
    PieChart, Pie, Cell
} from "recharts";

interface Branch {
    id: string;
    name: string;
    location: string;
}

interface ManagerDashboardData {
    overview: {
        totalEmployees: number;
        activeEmployees: number;
        totalBranches: number;
        pendingRequests: number;
    };
    requests: {
        pendingProfileRequests: number;
        pendingLeaveRequests: number;
    };
    attendance: {
        presentDays: number;
        absentDays: number;
        leaveDays: number;
        totalDays: number;
        attendanceRate: number;
    };
    recentActivity: Array<{
        id: string;
        employeeName: string;
        date: Date;
        status: string;
        checkIn: Date | null;
        checkOut: Date | null;
    }>;
}

interface ManagerDashboardProps {
    initialData: ManagerDashboardData;
    branches: Branch[];
}

const COLORS = ['#10b981', '#f59e0b', '#ef4444', '#6b7280'];

export function ManagerDashboard({ initialData, branches }: ManagerDashboardProps) {
    const [selectedBranch, setSelectedBranch] = useState<string>('all');
    const [fromDate, setFromDate] = useState<string>(new Date(new Date().getFullYear(), 0, 1).toISOString().split('T')[0]);
    const [toDate, setToDate] = useState<string>(new Date(new Date().getFullYear(), 11, 31).toISOString().split('T')[0]);
    const [data] = useState(initialData);
    const [loading, setLoading] = useState(false);

    const handleFilterChange = async () => {
        setLoading(true);
        try {
            const params = new URLSearchParams({
                branch: selectedBranch,
                from: fromDate,
                to: toDate
            });
            
            window.location.href = `/employee/manager?${params}`;
        } catch (error) {
            console.error('Filter change failed:', error);
        } finally {
            setLoading(false);
        }
    };

    const stats = [
        { 
            title: "Total Employees", 
            value: data.overview.totalEmployees.toString(), 
            icon: Users, 
            description: `${data.overview.activeEmployees} active employees`,
            change: "+5%",
            trend: "up" as const
        },
        { 
            title: "Pending Requests", 
            value: data.overview.pendingRequests.toString(), 
            icon: ClipboardList, 
            description: `${data.requests.pendingProfileRequests} profile, ${data.requests.pendingLeaveRequests} leave`,
            change: "-2%",
            trend: "down" as const
        },
        { 
            title: "Active Branches", 
            value: data.overview.totalBranches.toString(), 
            icon: Building, 
            description: "All operational",
            change: "0%",
            trend: "neutral" as const
        },
        { 
            title: "Attendance Rate", 
            value: `${data.attendance.attendanceRate}%`, 
            icon: UserCheck, 
            description: `${data.attendance.presentDays} present days`,
            change: "+3%",
            trend: "up" as const
        },
    ];

    // Prepare attendance chart data
    const attendanceChartData = [
        { name: "Present", value: data.attendance.presentDays, color: COLORS[0] },
        { name: "Leave", value: data.attendance.leaveDays, color: COLORS[1] },
        { name: "Absent", value: data.attendance.absentDays, color: COLORS[2] },
    ].filter(item => item.value > 0);

    return (
        <div className="space-y-6">
            {/* Page Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight">Dashboard</h1>
                    <p className="text-muted-foreground">
                        Team management overview and operational metrics
                    </p>
                </div>
            </div>

            {/* Filters */}
            <Card>
                <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                        <Filter className="h-4 w-4" />
                        Filters
                    </CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Branch</label>
                            <Select value={selectedBranch} onValueChange={setSelectedBranch}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Select branch" />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="all">All Branches</SelectItem>
                                    {branches.map((branch) => (
                                        <SelectItem key={branch.id} value={branch.id}>
                                            {branch.name}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium">From Date</label>
                            <div className="relative">
                                <Input
                                    type="date"
                                    value={fromDate}
                                    onChange={(e) => setFromDate(e.target.value)}
                                />
                                <CalendarIcon className="absolute right-3 top-3 h-4 w-4 text-gray-400" />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium">To Date</label>
                            <div className="relative">
                                <Input
                                    type="date"
                                    value={toDate}
                                    onChange={(e) => setToDate(e.target.value)}
                                />
                                <CalendarIcon className="absolute right-3 top-3 h-4 w-4 text-gray-400" />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium invisible">Apply</label>
                            <Button 
                                onClick={handleFilterChange} 
                                disabled={loading} 
                                className="w-full"
                            >
                                {loading ? "Loading..." : "Apply Filters"}
                            </Button>
                        </div>
                    </div>
                </CardContent>
            </Card>

            {/* Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {stats.map((stat) => {
                    const IconComponent = stat.icon;
                    return (
                        <Card key={stat.title}>
                            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                                <CardTitle className="text-sm font-medium">{stat.title}</CardTitle>
                                <IconComponent className="h-4 w-4 text-muted-foreground" />
                            </CardHeader>
                            <CardContent>
                                <div className="text-2xl font-bold">{stat.value}</div>
                                <p className="text-xs text-muted-foreground">{stat.description}</p>
                                <div className={cn(
                                    "flex items-center text-xs mt-1",
                                    stat.trend === "up" ? "text-green-600" : stat.trend === "down" ? "text-red-600" : "text-gray-500"
                                )}>
                                    <TrendingUp className={cn(
                                        "h-3 w-3 mr-1",
                                        stat.trend === "down" && "rotate-180"
                                    )} />
                                    {stat.change} from last month
                                </div>
                            </CardContent>
                        </Card>
                    );
                })}
            </div>

            {/* Charts Row */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Attendance Distribution */}
                <Card>
                    <CardHeader>
                        <CardTitle>Attendance Overview</CardTitle>
                    </CardHeader>
                    <CardContent>
                        {attendanceChartData.length > 0 ? (
                            <ResponsiveContainer width="100%" height={250}>
                                <PieChart>
                                    <Pie
                                        data={attendanceChartData}
                                        cx="50%"
                                        cy="50%"
                                        labelLine={false}
                                        label={({ name, value, percent }) => `${name}: ${value} (${((percent ?? 0) * 100).toFixed(0)}%)`}
                                        outerRadius={80}
                                        fill="#8884d8"
                                        dataKey="value"
                                    >
                                        {attendanceChartData.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={entry.color} />
                                        ))}
                                    </Pie>
                                    <Tooltip />
                                </PieChart>
                            </ResponsiveContainer>
                        ) : (
                            <div className="h-[250px] flex items-center justify-center text-muted-foreground">
                                No attendance data available
                            </div>
                        )}
                    </CardContent>
                </Card>

                {/* Recent Activity */}
                <Card>
                    <CardHeader>
                        <CardTitle>Recent Employee Activity</CardTitle>
                    </CardHeader>
                    <CardContent>
                        <div className="space-y-4">
                            {data.recentActivity.length > 0 ? (
                                data.recentActivity.slice(0, 5).map((activity) => (
                                    <div key={activity.id} className="flex items-center justify-between p-3 bg-gray-50 rounded">
                                        <div>
                                            <p className="font-medium">{activity.employeeName}</p>
                                            <p className="text-sm text-muted-foreground">
                                                {new Date(activity.date).toLocaleDateString()} - {activity.status}
                                            </p>
                                        </div>
                                        <div className="text-right">
                                            {activity.checkIn && (
                                                <p className="text-sm">
                                                    In: {new Date(activity.checkIn).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                </p>
                                            )}
                                            {activity.checkOut && (
                                                <p className="text-sm">
                                                    Out: {new Date(activity.checkOut).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                </p>
                                            )}
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <div className="text-center text-muted-foreground py-8">
                                    No recent activity available
                                </div>
                            )}
                        </div>
                    </CardContent>
                </Card>
            </div>

            {/* Quick Actions */}
            <Card>
                <CardHeader>
                    <CardTitle>Quick Actions</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <Button asChild className="h-20 flex-col space-y-2">
                            <a href="/employee/manager/profile-requests">
                                <ClipboardList className="h-6 w-6" />
                                <span>Review Profile Requests</span>
                                <span className="text-xs opacity-75">{data.requests.pendingProfileRequests} pending</span>
                            </a>
                        </Button>
                        <Button asChild variant="outline" className="h-20 flex-col space-y-2">
                            <a href="/employee/manager/employees">
                                <Users className="h-6 w-6" />
                                <span>Manage Employees</span>
                                <span className="text-xs opacity-75">{data.overview.totalEmployees} total</span>
                            </a>
                        </Button>
                        <Button asChild variant="outline" className="h-20 flex-col space-y-2">
                            <a href="/employee/manager/holidays">
                                <CalendarIcon className="h-6 w-6" />
                                <span>Holiday Management</span>
                                <span className="text-xs opacity-75">Manage holidays</span>
                            </a>
                        </Button>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { 
    Table, 
    TableBody, 
    TableCell, 
    TableHead, 
    TableHeader, 
    TableRow 
} from "@/components/ui/table";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Check, X, Clock, User, Calendar, FileText } from "lucide-react";
import { format, formatDistanceToNow } from "date-fns";
import { toast } from "sonner";

interface User {
    id: string;
    firstName: string;
    lastName: string;
    email: string;
    imageUrl: string | null;
    attendanceId: string | null;
    branch: {
        name: string;
    } | null;
}

interface LeaveType {
    name: string;
    allocatedDays: number;
}

interface LeaveRequest {
    id: string;
    reason: string;
    startDate: Date;
    endDate: Date;
    totalDays: number;
    status: "PENDING" | "APPROVED" | "REJECTED";
    approvedBy: string | null;
    rejectionReason: string | null;
    createdAt: Date;
    updatedAt: Date;
    user: User;
    leaveType: LeaveType;
}

interface ManagerLeaveRequestsListProps {
    initialRequests: LeaveRequest[];
    showAll?: boolean;
}

export function ManagerLeaveRequestsList({ 
    initialRequests, 
    showAll = false 
}: ManagerLeaveRequestsListProps) {
    const [requests, setRequests] = useState<LeaveRequest[]>(initialRequests);
    const [isLoading, setIsLoading] = useState(false);

    const getStatusBadge = (status: string) => {
        switch (status) {
            case "PENDING":
                return <Badge variant="default" className="bg-yellow-100 text-yellow-800">Pending</Badge>;
            case "APPROVED":
                return <Badge variant="default" className="bg-green-100 text-green-800">Approved</Badge>;
            case "REJECTED":
                return <Badge variant="destructive">Rejected</Badge>;
            default:
                return <Badge variant="secondary">{status}</Badge>;
        }
    };

    const handleApprove = async (requestId: string) => {
        setIsLoading(true);
        try {
            // TODO: Call approval action
            toast.success("Leave request approved successfully");
            // Update local state
            setRequests(prev => 
                prev.map(req => 
                    req.id === requestId 
                        ? { ...req, status: "APPROVED" as const }
                        : req
                )
            );
        } catch (error) {
            toast.error("Failed to approve leave request");
        } finally {
            setIsLoading(false);
        }
    };

    const handleReject = async (requestId: string) => {
        setIsLoading(true);
        try {
            // TODO: Call rejection action  
            toast.success("Leave request rejected");
            // Update local state
            setRequests(prev => 
                prev.map(req => 
                    req.id === requestId 
                        ? { ...req, status: "REJECTED" as const }
                        : req
                )
            );
        } catch (error) {
            toast.error("Failed to reject leave request");
        } finally {
            setIsLoading(false);
        }
    };

    const displayRequests = showAll ? requests : requests.filter(req => req.status === "PENDING");

    if (displayRequests.length === 0) {
        return (
            <div className="text-center py-8 text-gray-500">
                <FileText className="h-12 w-12 mx-auto mb-2 text-gray-300" />
                <p>{showAll ? "No leave requests found" : "No pending leave requests"}</p>
            </div>
        );
    }

    return (
        <div className="space-y-4">
            {!showAll && displayRequests.length <= 3 ? (
                // Card view for small number of pending requests
                <div className="space-y-3">
                    {displayRequests.map((request) => (
                        <Card key={request.id} className="hover:shadow-md transition-shadow">
                            <CardContent className="p-4">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-3 flex-1">
                                        <Avatar className="h-10 w-10">
                                            <AvatarImage src={request.user.imageUrl || ""} />
                                            <AvatarFallback>
                                                {request.user.firstName[0]}{request.user.lastName[0]}
                                            </AvatarFallback>
                                        </Avatar>
                                        <div className="flex-1">
                                            <h4 className="font-medium text-gray-900">
                                                {request.user.firstName} {request.user.lastName}
                                            </h4>
                                            <div className="flex items-center gap-4 text-sm text-gray-600 mt-1">
