                                        <span className="text-gray-400 mx-1">to</span>
                                        <span>{format(new Date(request.endDate), "MMM d")}</span>
                                    </div>
                                </TableCell>
                                <TableCell>
                                    <span className="text-sm font-medium">{request.totalDays}</span>
                                </TableCell>
                                <TableCell>
                                    {getStatusBadge(request.status)}
                                </TableCell>
