                        <Select value={selectedStatus} onValueChange={setSelectedStatus}>
                            <SelectTrigger className="w-[180px]">
                                <SelectValue placeholder="Filter by status" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">All Status</SelectItem>
                                <SelectItem value="APPROVED">Approved</SelectItem>
                                <SelectItem value="PENDING">Pending</SelectItem>
                            </SelectContent>
                        </Select>

                        <Button
                            variant="outline"
                            onClick={() => setShowArchived(!showArchived)}
                        >
                            <Archive className="mr-2 h-4 w-4" />
                            {showArchived ? "Hide" : "Show"} Archived
                        </Button>
                    </div>

                    {/* Bulk Actions */}
                    {selectedUsers.length > 0 && (
                        <div className="flex items-center gap-4 p-4 bg-muted rounded-lg">
                            <span className="text-sm font-medium">
                                {selectedUsers.length} users selected
                            </span>
                            <Select 
                                value={bulkRole} 
                                onValueChange={(value: Role) => setBulkRole(value)}
                            >
                                <SelectTrigger className="w-[180px]">
                                    <SelectValue placeholder="Change role to..." />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="SUPERADMIN">Super Admin</SelectItem>
                                    <SelectItem value=""></SelectItem>
                                    <SelectItem value="HR">HR Specialist</SelectItem>
                                    <SelectItem value="EMPLOYEE">Employee</SelectItem>
                                </SelectContent>
                            </Select>
                            <Button
                                onClick={handleBulkRoleChange}
                                disabled={!bulkRole || isPending}
                            >
                                Apply Changes
                            </Button>
                            <Button
                                variant="outline"
                                onClick={() => setSelectedUsers([])}
                            >
                                Clear Selection
                            </Button>
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Users Table */}
            <Card>
                <CardHeader>
                    <div className="flex justify-between items-center">
                        <CardTitle>
                            Users ({filteredUsers.length})
                        </CardTitle>
                        <div className="flex gap-2">
                            <Button variant="outline" size="sm">
                                <Download className="mr-2 h-4 w-4" />
                                Export
                            </Button>
                            <Button variant="outline" size="sm">
                                <RefreshCw className="mr-2 h-4 w-4" />
                                Refresh
                            </Button>
                        </div>
                    </div>
                </CardHeader>
                <CardContent>
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead className="w-[50px]">
                                    <Checkbox
                                        checked={
                                            filteredUsers.length > 0 && 
                                            selectedUsers.length === filteredUsers.length
                                        }
                                        onCheckedChange={handleSelectAll}
                                    />
                                </TableHead>
                                <TableHead>User</TableHead>
                                <TableHead>Role</TableHead>
                                <TableHead>Status</TableHead>
                                <TableHead>Department</TableHead>
                                <TableHead>Joined</TableHead>
                                <TableHead className="text-right">Actions</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {filteredUsers.map((user) => {
                                const roleDisplay = getRoleDisplay(user.role);
                                const IconComponent = roleDisplay.icon;

                                return (
                                    <TableRow key={user.id} className={user.isArchived ? "opacity-60" : ""}>
                                        <TableCell>
                                            <Checkbox
                                                checked={selectedUsers.includes(user.id)}
                                                onCheckedChange={(checked) => 
                                                    handleSelectUser(user.id, checked as boolean)
                                                }
                                            />
                                        </TableCell>
                                        <TableCell>
                                            <div className="flex items-center space-x-3">
                                                <Avatar className="h-8 w-8">
                                                    <AvatarImage src={user.imageUrl || undefined} />
                                                    <AvatarFallback>
                                                        {user.firstName?.charAt(0) || user.email.charAt(0)}
                                                    </AvatarFallback>
                                                </Avatar>
                                                <div>
                                                    <div className="font-medium">
                                                        {user.firstName} {user.lastName}
                                                    </div>
                                                    <div className="text-sm text-muted-foreground">
                                                        {user.email}
                                                    </div>
                                                </div>
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <Badge variant={roleDisplay.color} className="gap-1">
                                                <IconComponent className="h-3 w-3" />
                                                {roleDisplay.label}
                                            </Badge>
                                        </TableCell>
                                        <TableCell>
                                            <Badge 
                                                variant={user.status === "APPROVED" ? "default" : "secondary"}
                                            >
                                                {user.status}
                                            </Badge>
                                            {user.isArchived && (
                                                <Badge variant="outline" className="ml-2">
                                                    Archived
                                                </Badge>
                                            )}
                                        </TableCell>
                                        <TableCell>
                                            <div className="text-sm">
                                                {user.department?.name || "Not assigned"}
                                            </div>
                                            {user.branch && (
                                                <div className="text-xs text-muted-foreground">
                                                    {user.branch.name}
                                                </div>
                                            )}
                                        </TableCell>
                                        <TableCell>
                                            {user.dateOfJoining?.toLocaleDateString() || "Not set"}
                                        </TableCell>
                                        <TableCell className="text-right">
                                            <DropdownMenu>
                                                <DropdownMenuTrigger asChild>
                                                    <Button variant="ghost" className="h-8 w-8 p-0">
                                                        <MoreHorizontal className="h-4 w-4" />
                                                    </Button>
                                                </DropdownMenuTrigger>
                                                <DropdownMenuContent align="end">
                                                    <DropdownMenuItem
                                                        onClick={() => handleRoleChange(user.id, "EMPLOYEE")}
                                                        disabled={user.role === "EMPLOYEE"}
                                                    >
                                                        <Users className="mr-2 h-4 w-4" />
                                                        Make Employee
                                                    </DropdownMenuItem>
                                                    <DropdownMenuItem
                                                        onClick={() => handleRoleChange(user.id, "HR")}
                                                        disabled={user.role === "HR"}
                                                    >
                                                        <Shield className="mr-2 h-4 w-4" />
                                                        Make HR Specialist
                                                    </DropdownMenuItem>
                                                    <DropdownMenuItem
                                                        onClick={() => handleRoleChange(user.id, "SUPERADMIN")}
                                                        disabled={user.role === "SUPERADMIN"}
                                                    >
                                                        <Crown className="mr-2 h-4 w-4" />
                                                        Make Super Admin
                                                    </DropdownMenuItem>
                                                    <DropdownMenuSeparator />
                                                    <DropdownMenuItem
                                                        onClick={() => handleArchiveToggle(user.id)}
                                                    >
                                                        {user.isArchived ? (
                                                            <>
                                                                <ArchiveRestore className="mr-2 h-4 w-4" />
                                                                Restore User
                                                            </>
                                                        ) : (
                                                            <>
                                                                <Archive className="mr-2 h-4 w-4" />
                                                                Archive User
                                                            </>
                                                        )}
                                                    </DropdownMenuItem>
                                                </DropdownMenuContent>
                                            </DropdownMenu>
                                        </TableCell>
                                    </TableRow>
                                );
                            })}
                        </TableBody>
                    </Table>

                    {filteredUsers.length === 0 && (
                        <div className="text-center py-12">
                            <Users className="mx-auto h-12 w-12 text-muted-foreground mb-4" />
                            <h3 className="text-lg font-semibold">No users found</h3>
                            <p className="text-muted-foreground">
                                Try adjusting your search criteria or filters
                            </p>
                        </div>
                    )}
                </CardContent>
            </Card>
        </div>
    );
}

