async function testCorrectDateSync() {
    console.log('Testing Manual Sync with Correct Date Mapping');
    console.log('='.repeat(60));
    
    try {
        loadEnv();
        
        const userId = 'cml9hqym90001b3sc41akv4g7'; // Dulad Sen
        const attendanceId = '48';
        
        // The database has 2026-02-26T18:00:00.000Z which is Feb 27 in Bangladesh
        const dbDate = new Date('2026-02-26T18:00:00.000Z');
        
        // Convert to Bangladesh date for ZKTeco query
        const bangladeshDate = new Date(dbDate.getTime() + (6 * 60 * 60 * 1000)); // Add 6 hours for Bangladesh timezone
        
        console.log(`Database date: ${dbDate.toISOString()}`);
        console.log(`Bangladesh date: ${bangladeshDate.toISOString()}`);
        console.log(`Bangladesh local: ${bangladeshDate.getFullYear()}-${(bangladeshDate.getMonth()+1).toString().padStart(2,'0')}-${bangladeshDate.getDate().toString().padStart(2,'0')}`);
        console.log('');
        
        // 1. Check current state
        console.log('1. Current database state:');
        const currentRecord = await prisma.dailyTimeRecord.findUnique({
            where: {
                userId_date: {
                    userId: userId,
                    date: dbDate
                }
            }
        });
        
        if (!currentRecord) {
            console.log('Γ¥î No record found');
            return;
        }
        
        console.log(`Status: ${currentRecord.status}`);
        console.log(`CheckIn: ${currentRecord.actualCheckIn}`);
        console.log(`CheckOut: ${currentRecord.actualCheckOut}`);
        console.log(`BreakTime: ${currentRecord.actualBreakTime}`);
        console.log('');
        
        // 2. Fetch from ZKTeco for the correct Bangladesh date (Feb 27, 2026)
        console.log('2. Fetching from ZKTeco API for Feb 27, 2026:');
        const baseUrl = process.env.ZKTECO_BASE_URL;
        const username = process.env.ZKTECO_USERNAME;
        const password = process.env.ZKTECO_PASSWORD;
        
        // Authenticate
        const authResponse = await fetch(`${baseUrl}/api-token-auth/`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ username, password })
        });
        
        const authData = await authResponse.json();
        const token = authData.token;
        console.log('Γ£à Authentication successful');
        
        // Query for Feb 27, 2026 in ZKTeco (which has the data)
        const startTime = '2026-02-27 00:00:00';
        const endTime = '2026-02-27 23:59:59';
        
        console.log(`Fetching transactions for employee ${attendanceId} on ${startTime.split(' ')[0]}`);
        
        const url = `${baseUrl}/iclock/api/transactions/?emp_code=${attendanceId}&start_time=${encodeURIComponent(startTime)}&end_time=${encodeURIComponent(endTime)}`;
        
        const transactionResponse = await fetch(url, {
            headers: { 'Authorization': `Token ${token}` }
        });
        
        const transactionData = await transactionResponse.json();
        const transactions = transactionData.data || [];
        
        console.log(`Γ£à Found ${transactions.length} transactions`);
        
        if (transactions.length === 0) {
            console.log('Γ¥î No ZKTeco data available');
            return;
        }
        
        // 3. Process transactions
        console.log('');
        console.log('3. Processing ZKTeco data:');
        
        let actualCheckIn = null;
        let actualCheckOut = null;
        const breakSessions = [];
        
        const sortedTransactions = transactions.sort((a, b) => 
            new Date(a.punch_time) - new Date(b.punch_time)
        );
        
        for (const transaction of sortedTransactions) {
            const punchTime = new Date(transaction.punch_time);
            const punchState = transaction.punch_state;
            
            console.log(`- ${transaction.punch_time}: ${transaction.punch_state_display}`);
            
            switch (punchState) {
                case '0': // Check In
                    if (!actualCheckIn) actualCheckIn = punchTime;
                    break;
                case '1': // Check Out
                    actualCheckOut = punchTime;
                    break;
                case '2': // Break Out
                    breakSessions.push({ breakOut: punchTime, breakIn: null });
                    break;
                case '3': // Break In
                    const lastBreak = breakSessions.find(s => !s.breakIn);
                    if (lastBreak) lastBreak.breakIn = punchTime;
                    break;
            }
        }
        
        // Calculate break time
        let totalBreakMinutes = 0;
        for (const session of breakSessions) {
            if (session.breakIn) {
                const duration = session.breakIn - session.breakOut;
                totalBreakMinutes += Math.floor(duration / (1000 * 60));
            }
        }
        
        const actualBreakTime = totalBreakMinutes > 0 
            ? `${Math.floor(totalBreakMinutes / 60).toString().padStart(2, '0')}:${(totalBreakMinutes % 60).toString().padStart(2, '0')}`
            : '00:00';
        
        console.log('');
        console.log('Processed data:');
        console.log(`- Check In: ${actualCheckIn}`);
        console.log(`- Check Out: ${actualCheckOut}`);  
        console.log(`- Break Time: ${actualBreakTime}`);
        console.log('');
        
        // 4. Update database
        console.log('4. Updating database:');
        
        const updateData = {};
        if (!currentRecord.actualCheckIn && actualCheckIn) {
            updateData.actualCheckIn = actualCheckIn;
        }
        if (!currentRecord.actualCheckOut && actualCheckOut) {
            updateData.actualCheckOut = actualCheckOut;
        }
        if (!currentRecord.actualBreakTime && actualBreakTime) {
            updateData.actualBreakTime = actualBreakTime;
        }
        
        console.log('Update data:', updateData);
        
        await prisma.dailyTimeRecord.update({
            where: {
                userId_date: {
                    userId: userId,
                    date: dbDate
                }
            },
            data: updateData
        });
        
        console.log('Γ£à Database updated successfully!');
        
        // 5. Verify
        const updatedRecord = await prisma.dailyTimeRecord.findUnique({
            where: {
                userId_date: {
                    userId: userId,
                    date: dbDate
                }
            }
        });
        
        console.log('');
        console.log('5. Final verification:');
        console.log(`Status: ${updatedRecord.status}`);
        console.log(`CheckIn: ${updatedRecord.actualCheckIn}`);
        console.log(`CheckOut: ${updatedRecord.actualCheckOut}`);
        console.log(`BreakTime: ${updatedRecord.actualBreakTime}`);
        console.log('');
        console.log('≡ƒÄë FIXED MANUAL SYNC SUCCESSFUL!');
        console.log('The UI should now show the updated times!');
        
    } catch (error) {
        console.error('Γ¥î Error:', error.message);
        console.error('Stack:', error.stack);
    } finally {
        await prisma.$disconnect();
    }
}

